// GoldDesk Service Worker — PWA offline-first
const CACHE_NAME = "golddesk-v1";
const STATIC_CACHE = "golddesk-static-v1";
const RUNTIME_CACHE = "golddesk-runtime-v1";

const STATIC_ASSETS = [
  "/gold",
  "/gold/portfolio",
  "/gold/analytics",
  "/gold/alerts",
  "/gold/backtest",
  "/gold/chat",
  "/gold/tokens",
  "/gold/settings",
  "/golddesk-manifest.json",
];

// ── Install: cache static shell ─────────────────────────
self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(STATIC_CACHE).then((cache) => {
      return cache.addAll(STATIC_ASSETS).catch(() => {
        // ignore errors for not-yet-cached pages
      });
    })
  );
  self.skipWaiting();
});

// ── Activate: clean old caches ───────────────────────────
self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys
          .filter((key) => key !== STATIC_CACHE && key !== RUNTIME_CACHE)
          .map((key) => caches.delete(key))
      )
    )
  );
  self.clients.claim();
});

// ── Fetch: network-first for /api, cache-first for /gold ──
self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // API: network first, fallback to cache
  if (url.pathname.startsWith("/api/")) {
    event.respondWith(networkFirst(request));
    return;
  }

  // GoldDesk pages: cache-first
  if (url.pathname.startsWith("/gold")) {
    event.respondWith(cacheFirst(request, STATIC_CACHE));
    return;
  }

  // Static assets: cache-first
  if (request.method === "GET") {
    event.respondWith(cacheFirst(request, RUNTIME_CACHE));
  }
});

async function networkFirst(request) {
  try {
    const response = await fetch(request);
    if (response.ok) {
      const cache = await caches.open(RUNTIME_CACHE);
      cache.put(request, response.clone());
    }
    return response;
  } catch (err) {
    const cached = await caches.match(request);
    if (cached) return cached;
    return new Response(
      JSON.stringify({ success: false, error: { message: "offline" } }),
      { status: 503, headers: { "Content-Type": "application/json" } }
    );
  }
}

async function cacheFirst(request, cacheName) {
  const cached = await caches.match(request);
  if (cached) return cached;
  try {
    const response = await fetch(request);
    if (response.ok) {
      const cache = await caches.open(cacheName);
      cache.put(request, response.clone());
    }
    return response;
  } catch (err) {
    // fallback: return offline page if HTML
    if (request.headers.get("accept")?.includes("text/html")) {
      const cache = await caches.open(STATIC_CACHE);
      const offline = await cache.match("/gold");
      if (offline) return offline;
    }
    return new Response("Offline", { status: 503 });
  }
}

// ── Push notifications (future) ──────────────────────────
self.addEventListener("push", (event) => {
  if (!event.data) return;
  const data = event.data.json();
  event.waitUntil(
    self.registration.showNotification(data.title || "GoldDesk", {
      body: data.body || "",
      icon: "/icons/golddesk-192.png",
      badge: "/icons/golddesk-192.png",
      data: { url: data.url || "/gold" },
    })
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = event.notification.data?.url || "/gold";
  event.waitUntil(clients.openWindow(url));
});

"use client";

import { useState, useCallback, useRef, useEffect, useMemo } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import dynamic from "next/dynamic";
import Link from "next/link";
import AppLayout from "@/components/layout/AppLayout";
import { Card } from "@/components/ui/Card";
import Skeleton from "@/components/Skeleton";
import { apiGet, apiPost } from "@/lib/api";
import {
  saveSyncSettings, resetSyncSettings,
  DEFAULT_SYNC_SETTINGS, ALL_SECTION_KEYS, type SyncSettingsMap,
} from "@/lib/sync-settings";
import { useSyncSettings } from "@/hooks/useSyncSettings";
import DeadLetterWidget from "@/components/admin/DeadLetterWidget";

const AreaChartCard = dynamic(() => import("@/components/charts/AreaChartCard"), {
  ssr: false, loading: () => <div className="animate-pulse bg-surface-800/50 rounded-2xl h-[200px]" />,
});

// ── Types ─────────────────────────────────────────────────────────────────────

interface TableSyncInfo { last_fetched: string | null; record_count: number; age_minutes: number; status: "ok"|"stale"|"outdated"|"missing"|"unknown"|"error"; max_age_minutes: number; error?: string; }
interface SyncLogEntry { time: string; endpoint: string; category: string; status: string; items_count: number; duration_ms: number; completed_at: string | null; }
interface SchedulerJob { name: string; enabled: boolean; cron: string; description: string; endpoint: string; category: string; next_run_time: string | null; }
interface SchedulerResponse { jobs: SchedulerJob[]; total: number; enabled: number; disabled: number; }
interface ImportJob { id: string; job_type: string; status: string; started_at: string | null; completed_at: string | null; duration_seconds: number; error_message: string | null; }
interface ImportResult { total_files?: number; total_rows?: number; imported?: number; updated?: number; errors?: string[]; per_file?: Record<string, { symbol: string; rows: number; imported: number; updated: number }>; }
interface TemplateInfo { label: string; endpoint: string; method: string; accept: string; max_size_mb: number; columns: Array<{ column: string; type: string; required: boolean; desc: string }>; sample_endpoint: string | null; note?: string; }
interface ImportTemplates { instruments: TemplateInfo; quotes: TemplateInfo; codal: TemplateInfo; }
interface TableInfo { name: string; row_count: number; }
interface ColumnInfo { name: string; type: string; }
interface TableData { table: string; columns: ColumnInfo[]; rows: Record<string, unknown>[]; total: number; page: number; page_size: number; total_pages: number; }
interface SearchResult { table: string; total: number; columns: ColumnInfo[]; rows: Record<string, unknown>[]; }
interface DashboardResponse {
  metrics: { total_instruments: number; active_signals: number; total_volume: number; total_db_records: number; total_users: number; active_users: number; weekly_active_users: number; total_trades: number; total_news: number; today_records: number };
  job_stats: { total_runs: number; successful: number; failed: number; running: number; avg_duration: number };
  recent_jobs: Array<{ id: string; job_type: string; status: string; started_at: string | null; completed_at: string | null; duration_seconds: number; error_message: string | null }>;
  table_rows: Array<{ table: string; rows: number }>;
  ml_models: Array<{ id: string; name: string; task: string; framework: string; tags: string[]; versions: Array<{ version: string; stage: string; metrics: Record<string, number> }> }>;
  strategies: Array<{ name: string; type: string; class_name: string; params: Array<{ name: string; type: string; default: unknown }> }>;
  system_status: string; daily_records: Record<string, number>;
  user_stats: { total_users: number; active_users: number; weekly_active: number };
}

// ── Config ────────────────────────────────────────────────────────────────────

type TabKey = "overview"|"sync"|"freshness"|"scheduler"|"import"|"tables"|"deadletter";
const TABS: { key: TabKey; label: string; icon: string }[] = [
  { key: "overview", label: "نمای کلی", icon: "📊" },
  { key: "sync", label: "همگام‌سازی", icon: "🔄" },
  { key: "freshness", label: "تنظیمات", icon: "⚙️" },
  { key: "scheduler", label: "زمان‌بندی", icon: "⏱️" },
  { key: "import", label: "ورود داده", icon: "📥" },
  { key: "tables", label: "مرور جداول", icon: "🗃️" },
  { key: "deadletter", label: "Dead-Letter", icon: "💀" },
];

const TABLE_CONFIG: Record<string, { label: string; icon: string; order: number }> = {
  symbols: { label: "نمادها (بورس)", icon: "📊", order: 1 }, commodities: { label: "کامودیتی‌ها", icon: "🌍", order: 2 },
  gold_coin: { label: "طلا و سکه", icon: "🥇", order: 3 }, currency: { label: "نرخ ارز", icon: "💵", order: 4 },
  crypto: { label: "ارز دیجیتال", icon: "₿", order: 5 }, index: { label: "شاخص‌ها", icon: "📈", order: 6 },
  ime_futures: { label: "آتی کالا", icon: "🛢️", order: 7 }, ime_options: { label: "اختیار کالا", icon: "📋", order: 8 },
  options: { label: "آپشن‌ها", icon: "🎯", order: 9 }, codal: { label: "کدال", icon: "🏢", order: 10 },
};

const STATUS_META: Record<string, { label: string; color: string; bg: string }> = {
  ok: { label: "به‌روز", color: "text-accent-emerald", bg: "bg-accent-emerald/15" },
  stale: { label: "کمی قدیمی", color: "text-accent-amber", bg: "bg-accent-amber/15" },
  outdated: { label: "قدیمی", color: "text-accent-rose", bg: "bg-accent-rose/15" },
  missing: { label: "بدون داده", color: "text-surface-500", bg: "bg-surface-800" },
  unknown: { label: "نامشخص", color: "text-surface-400", bg: "bg-surface-800" },
  error: { label: "خطا", color: "text-accent-rose", bg: "bg-accent-rose/15" },
};

const CATEGORY_CONFIG: Record<string, { label: string; icon: string }> = {
  tsetmc: { label: "بورس", icon: "📈" }, ime: { label: "کالا", icon: "🛢️" },
  commodity: { label: "کامودیتی", icon: "🌍" }, crypto: { label: "کریپتو", icon: "₿" },
  gold: { label: "طلا و ارز", icon: "🥇" }, codal: { label: "کدال", icon: "🏢" },
};

const SECTION_ID_MAP: Record<string, string> = {
  symbols: "all-symbols", commodities: "commodity", gold_coin: "gold-coin",
  currency: "currency", crypto: "crypto", index: "index-tse",
  ime_futures: "ime-futures", ime_options: "ime-options", options: "option", codal: "codal",
};

const IMPORT_TABS = [{ key: "instruments", label: "📋 نمادها", accept: ".csv,.json,.xlsx" }, { key: "quotes", label: "📊 قیمت‌ها", accept: ".csv" }, { key: "codal", label: "🏢 کدال", accept: ".xlsx,.csv" }] as const;

const PRESET_VALUES = [1, 2, 5, 10, 15, 30, 60, 120, 240, 480];
const VALUE_LABELS: Record<number, string> = { 1: "۱ دقیقه", 2: "۲ دقیقه", 5: "۵ دقیقه", 10: "۱۰ دقیقه", 15: "۱۵ دقیقه", 30: "۳۰ دقیقه", 60: "۱ ساعت", 120: "۲ ساعت", 240: "۴ ساعت", 480: "۸ ساعت" };

const SEARCHABLE_TABLES = ["instruments","quotes","trades","signals","recommendations","indicators","news_articles","codal_reports","alerts","backtest_trades","portfolio_positions","orderbooks"];
const API_BASE = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000/api/v1";

// ── Helpers ───────────────────────────────────────────────────────────────────

const fmt = (n: number) => n.toLocaleString("fa-IR");
const fmtDur = (ms: number) => ms < 1000 ? `${ms.toFixed(0)}ms` : ms < 60000 ? `${(ms / 1000).toFixed(1)}s` : `${(ms / 60000).toFixed(1)}min`;
const fmtDurSec = (s: number) => s < 1 ? `${(s * 1000).toFixed(0)}ms` : s < 60 ? `${s.toFixed(1)}s` : `${Math.floor(s / 60)}m ${(s % 60).toFixed(0)}s`;
const fmtCron = (c: string) => { const n = Number(c); if (Number.isInteger(n)) { if (n < 60) return `هر ${n} ثانیه`; if (n < 3600) return `هر ${n / 60} دقیقه`; return `هر ${n / 3600} ساعت`; } if (c === "0 9 * * *") return "روزانه ۹:۰۰"; if (c === "0 18 * * *") return "روزانه ۱۸:۰۰"; return c; };
const fmtRel = (iso: string | null) => { if (!iso) return "—"; try { const d = Math.floor((Date.now() - new Date(iso).getTime()) / 1000); if (d < 60) return `${d} ثانیه پیش`; if (d < 3600) return `${Math.floor(d / 60)} دقیقه پیش`; if (d < 86400) return `${Math.floor(d / 3600)} ساعت پیش`; return `${Math.floor(d / 86400)} روز پیش`; } catch { return "—"; } };
const fmtTime = (iso: string | null) => { if (!iso) return "—"; try { return new Date(iso).toLocaleTimeString("fa-IR", { hour: "2-digit", minute: "2-digit" }); } catch { return "—"; } };
const statusBadge = (s: string) => s === "completed" ? "bg-accent-emerald/15 text-accent-emerald" : s === "failed" ? "bg-accent-rose/15 text-accent-rose" : s === "running" ? "bg-accent-amber/15 text-accent-amber" : "bg-surface-700 text-surface-400";
const statusLbl = (s: string) => s === "completed" ? "موفق" : s === "failed" ? "خطا" : s === "running" ? "در حال اجرا" : s;
const nearestPreset = (v: number) => PRESET_VALUES.reduce((p, c) => Math.abs(c - v) < Math.abs(p - v) ? c : p);

// ── Toast ─────────────────────────────────────────────────────────────────────

function Toast({ message, type, onClose }: { message: string; type: "success" | "error" | "warning"; onClose: () => void }) {
  const ref = useRef(onClose);
  useEffect(() => { ref.current = onClose; }, [onClose]);
  useEffect(() => { const t = setTimeout(() => ref.current(), 4000); return () => clearTimeout(t); }, []);
  const styles = { success: "bg-accent-emerald/15 text-accent-emerald border-accent-emerald/30", error: "bg-accent-rose/15 text-accent-rose border-accent-rose/30", warning: "bg-accent-amber/15 text-accent-amber border-accent-amber/30" };
  return (<div className={`fixed bottom-4 left-1/2 -translate-x-1/2 z-[100] flex items-center gap-2 px-5 py-3 rounded-xl shadow-2xl text-sm font-medium border ${styles[type]}`} style={{ animation: "slideUp 0.3s ease-out" }}><span>{message}</span><button onClick={onClose} className="mr-3 opacity-60 hover:opacity-100">✕</button><style>{`@keyframes slideUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}`}</style></div>);
}

// ── MAIN PAGE ─────────────────────────────────────────────────────────────────

export default function AdminUnifiedPage() {
  const qc = useQueryClient();
  const [tab, setTab] = useState<TabKey>("overview");
  const [toast, setToast] = useState<{ message: string; type: "success" | "error" | "warning" } | null>(null);

  // ══════════════════════════════════════════════════════════════════════════════
  // SHARED QUERIES
  // ══════════════════════════════════════════════════════════════════════════════

  const { data: dash } = useQuery({ queryKey: ["admin-dash"], queryFn: async () => apiGet<DashboardResponse>("/dashboard"), refetchInterval: 300_000, staleTime: 120_000 });

  const { data: syncStatus, isLoading: statusLoading } = useQuery({ queryKey: ["admin-sync-status"], queryFn: async (): Promise<Record<string, TableSyncInfo>> => { const r = await apiGet<{ success: boolean; data: Record<string, TableSyncInfo> }>("/brsapi/sync-status"); return r?.data ?? {}; }, refetchInterval: 60_000, staleTime: 30_000 });

  const { data: schedulerData } = useQuery({ queryKey: ["admin-scheduler"], queryFn: async (): Promise<SchedulerResponse> => { const r = await apiGet<{ success: boolean; data: SchedulerResponse }>("/jobs/scheduler"); return r?.data ?? { jobs: [], total: 0, enabled: 0, disabled: 0 }; }, refetchInterval: 30_000, staleTime: 15_000 });

  // Freshness settings
  const [freshnessSettings, setFreshnessSettings] = useSyncSettings();

  const effectiveStatus = useMemo(() => {
    if (!syncStatus) return undefined;
    const result: Record<string, TableSyncInfo> = {};
    for (const [key, info] of Object.entries(syncStatus)) {
      const custom = freshnessSettings[key]; const over = { ...info };
      if (custom && custom.maxAgeMinutes > 0) {
        over.max_age_minutes = custom.maxAgeMinutes;
        if (info.status !== "missing" && info.status !== "error" && info.status !== "unknown" && info.age_minutes != null) {
          over.status = info.age_minutes <= custom.maxAgeMinutes ? "ok" : info.age_minutes <= custom.maxAgeMinutes * 3 ? "stale" : "outdated";
        }
      }
      result[key] = over;
    }
    return result;
  }, [syncStatus, freshnessSettings]);

  // ══════════════════════════════════════════════════════════════════════════════
  // SHARED HELPERS
  // ══════════════════════════════════════════════════════════════════════════════

  const overviewEntries = useMemo(() => {
    if (!effectiveStatus) return [];
    return Object.entries(effectiveStatus).filter(([, i]) => i.record_count > 0 || i.status !== "missing").sort(([a], [b]) => (TABLE_CONFIG[a]?.order ?? 99) - (TABLE_CONFIG[b]?.order ?? 99));
  }, [effectiveStatus]);

  const okCount = overviewEntries.filter(([, i]) => i.status === "ok").length;
  const staleCount = overviewEntries.filter(([, i]) => i.status === "stale").length;
  const outdatedCount = overviewEntries.filter(([, i]) => i.status === "outdated").length;
  const healthScore = overviewEntries.length > 0 ? Math.round((okCount / overviewEntries.length) * 100) : 0;
  const healthColor = healthScore >= 80 ? "text-accent-emerald" : healthScore >= 50 ? "text-accent-amber" : "text-accent-rose";

  const m = dash?.metrics; const jobs = dash?.job_stats; const recentJobs = dash?.recent_jobs || [];
  const dailyEntries = dash?.daily_records ? Object.entries(dash.daily_records).filter(([, v]) => v > 0) : [];
  const schedJobs = schedulerData?.jobs ?? [];

  const handleRunJob = useCallback(async (name: string) => {
    setToast({ message: `🔄 اجرا: ${name}...`, type: "warning" });
    try { const r = await apiPost<{ success: boolean; data: { success: boolean; items_count?: number; duration_ms?: number; message?: string } }>(`/jobs/scheduler/${name}/run`); if (r?.success && r.data?.success) setToast({ message: `✅ ${name}: ${r.data.items_count ?? 0} آیتم در ${fmtDur(r.data.duration_ms ?? 0)}`, type: "success" }); else setToast({ message: `❌ ${r?.data?.message || "خطا"}`, type: "error" }); qc.invalidateQueries({ queryKey: ["admin-scheduler"] }); } catch { setToast({ message: `❌ خطا`, type: "error" }); }
  }, [qc]);

  const handleToggleJob = useCallback(async (name: string) => {
    try { const r = await apiPost<{ success: boolean; data: { enabled: boolean } }>(`/jobs/scheduler/${name}/toggle`); if (r?.success) { setToast({ message: `${r.data.enabled ? "✅ فعال" : "⏸️ غیرفعال"}: ${name}`, type: "success" }); qc.invalidateQueries({ queryKey: ["admin-scheduler"] }); } } catch { setToast({ message: `❌ خطا`, type: "error" }); }
  }, [qc]);

  const handleSyncNow = useCallback(async (key: string) => {
    const id = SECTION_ID_MAP[key]; if (!id) return;
    setToast({ message: `🔄 sync ${TABLE_CONFIG[key]?.label || key}...`, type: "warning" });
    try { const r = await apiPost<{ success: boolean; data: { items_count: number; duration_ms: number } }>(`/brsapi/manage/sync/${id}`); if (r?.success && r.data) setToast({ message: `✅ ${TABLE_CONFIG[key]?.label}: ${r.data.items_count} رکورد در ${fmtDur(r.data.duration_ms)}`, type: "success" }); else setToast({ message: `❌ خطا`, type: "error" }); qc.invalidateQueries({ queryKey: ["admin-sync-status"] }); } catch { setToast({ message: `❌ خطا`, type: "error" }); }
  }, [qc]);

  // ══════════════════════════════════════════════════════════════════════════════
  // TAB: OVERVIEW — from /admin + /sync-manager dashboard
  // ══════════════════════════════════════════════════════════════════════════════

  if (tab === "overview") return (
    <AppLayout title="🛡️ پنل مدیریت" subtitle="مدیریت یکپارچه سیستم، داده‌ها و زمان‌بندی">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      {/* Metrics */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3 mb-5">
        <div className="glass-card p-3 text-center"><p className={`text-xl font-black ${healthColor}`}>{healthScore}%</p><p className="text-[9px] text-surface-500">سلامت داده</p></div>
        <div className="glass-card p-3 text-center"><p className="text-xl font-black text-accent-emerald">{okCount}</p><p className="text-[9px] text-surface-500">به‌روز</p></div>
        <div className="glass-card p-3 text-center"><p className={`text-xl font-black ${staleCount > 0 ? "text-accent-amber" : "text-surface-600"}`}>{staleCount}</p><p className="text-[9px] text-surface-500">کمی قدیمی</p></div>
        <div className="glass-card p-3 text-center"><p className="text-xl font-black text-primary-400">{schedulerData?.enabled ?? 0}</p><p className="text-[9px] text-surface-500">Scheduler فعال</p></div>
        <div className="glass-card p-3 text-center"><p className="text-xl font-black text-surface-200">{m?.total_db_records !== undefined ? fmt(m.total_db_records) : "—"}</p><p className="text-[9px] text-surface-500">کل رکوردها</p></div>
        <div className="glass-card p-3 text-center"><p className={`text-xl font-bold ${dash?.system_status === "healthy" ? "text-accent-emerald" : dash?.system_status === "warning" ? "text-accent-amber" : "text-accent-rose"}`}>{dash?.system_status === "healthy" ? "سالم" : dash?.system_status === "warning" ? "هشدار" : "—"}</p><p className="text-[9px] text-surface-500">وضعیت</p></div>
      </div>
      {/* Tabs */}
      <div className="flex gap-1 mb-5 bg-surface-800/50 rounded-xl p-1 border border-surface-700/50 overflow-x-auto">
        {TABS.map(t => (<button key={t.key} onClick={() => setTab(t.key)} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${tab === t.key ? "bg-primary-600/30 text-primary-300 shadow-sm" : "text-surface-400 hover:text-surface-200"}`}>{t.icon} {t.label}</button>))}
      </div>
      {/* Job Stats + Daily */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 mb-4">
        <Card title="وضعیت Job‌ها (۷ روز)">{jobs ? (<div className="grid grid-cols-5 gap-3 text-center">
          <div><p className="text-lg font-bold text-surface-200">{fmt(jobs.total_runs)}</p><p className="text-[9px] text-surface-500">کل</p></div>
          <div><p className="text-lg font-bold text-accent-emerald">{fmt(jobs.successful)}</p><p className="text-[9px] text-surface-500">موفق</p></div>
          <div><p className={`text-lg font-bold ${jobs.failed > 0 ? "text-accent-rose" : "text-surface-400"}`}>{fmt(jobs.failed)}</p><p className="text-[9px] text-surface-500">خطا</p></div>
          <div><p className="text-lg font-bold text-accent-amber">{fmt(jobs.running)}</p><p className="text-[9px] text-surface-500">در حال اجرا</p></div>
          <div><p className="text-lg font-bold text-primary-400">{jobs.avg_duration > 0 ? `${jobs.avg_duration.toFixed(1)}s` : "—"}</p><p className="text-[9px] text-surface-500">میانگین</p></div>
        </div>) : <Skeleton className="h-14 w-full" />}</Card>
        <Card title="فعالیت امروز">{dailyEntries.length > 0 ? (<div className="flex flex-wrap gap-x-4 gap-y-1.5">{dailyEntries.map(([k, v]) => (<div key={k} className="flex items-center gap-1.5"><span className="text-xs font-mono text-surface-200 font-bold">{fmt(v)}</span><span className="text-[9px] text-surface-500">{k.replace("_today", "").replace("_", " ")}</span></div>))}</div>) : <p className="text-xs text-surface-600">هیچ رکوردی امروز ثبت نشده</p>}</Card>
      </div>
      {/* Recent Jobs */}
      {recentJobs.length > 0 && (<Card title="آخرین Job‌ها"><div className="overflow-x-auto"><table className="w-full text-xs"><thead><tr className="text-surface-500 border-b border-surface-700"><th className="text-right py-2 px-2">نوع</th><th className="text-right py-2 px-2">وضعیت</th><th className="text-right py-2 px-2">مدت</th><th className="text-right py-2 px-2">زمان</th><th className="text-right py-2 px-2">خطا</th></tr></thead><tbody>{recentJobs.slice(0, 8).map(job => (<tr key={job.id} className="border-b border-surface-800/50 hover:bg-surface-800/30"><td className="py-2 px-2 font-mono text-surface-300">{job.job_type}</td><td className="py-2 px-2"><span className={`px-2 py-0.5 rounded-full text-[10px] font-semibold ${statusBadge(job.status)}`}>{statusLbl(job.status)}</span></td><td className="py-2 px-2 text-surface-400">{job.duration_seconds > 0 ? fmtDurSec(job.duration_seconds) : "—"}</td><td className="py-2 px-2 text-surface-500">{fmtTime(job.completed_at || job.started_at)}</td><td className="py-2 px-2 text-accent-rose max-w-[120px] truncate" title={job.error_message || ""}>{job.error_message || "—"}</td></tr>))}</tbody></table></div></Card>)}
      {/* Data Freshness */}
      <Card title="وضعیت جداول"><div className="overflow-x-auto"><table className="w-full text-xs"><thead><tr className="text-surface-500 border-b border-surface-700"><th className="pb-2 text-right">بخش</th><th className="pb-2 text-center">وضعیت</th><th className="pb-2 text-center">رکوردها</th><th className="pb-2 text-center">سن</th><th className="pb-2 text-center">عملیات</th></tr></thead><tbody>{overviewEntries.slice(0, 10).map(([key, info]) => { const cfg = TABLE_CONFIG[key] || { label: key, icon: "📦" }; const meta = STATUS_META[info.status] || STATUS_META.unknown; return (<tr key={key} className="border-b border-surface-800/30 hover:bg-surface-800/20"><td className="py-2 px-2"><div className="flex items-center gap-2"><span>{cfg.icon}</span><span className="font-semibold text-surface-200">{cfg.label}</span></div></td><td className="py-2 px-2 text-center"><span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold ${meta.bg} ${meta.color}`}>{meta.label}</span></td><td className="py-2 px-2 text-center font-mono text-surface-300">{fmt(info.record_count)}</td><td className="py-2 px-2 text-center"><span className={`font-mono ${info.status === "ok" ? "text-accent-emerald" : info.status === "stale" ? "text-accent-amber" : info.status === "outdated" ? "text-accent-rose" : "text-surface-500"}`}>{info.age_minutes != null ? `${info.age_minutes.toFixed(0)} دقیقه` : "—"}</span></td><td className="py-2 px-2 text-center"><button onClick={() => handleSyncNow(key)} className={`px-2 py-1 rounded-lg text-[10px] font-medium border transition-all ${info.status === "outdated" ? "bg-accent-rose/15 text-accent-rose border-accent-rose/30 animate-pulse" : info.status === "stale" ? "bg-accent-amber/15 text-accent-amber border-accent-amber/30" : "bg-surface-800 text-surface-400 hover:text-primary-300 border-surface-700"}`}>Sync</button></td></tr>); })}</tbody></table></div></Card>
      {/* Quick Actions */}
      <Card title="اقدامات سریع"><div className="flex flex-wrap gap-2">
        <button onClick={() => handleRunJob("brsapi_all_symbols")} className="px-4 py-2 bg-primary-600/10 border border-primary-600/20 rounded-xl text-xs font-bold text-primary-400 hover:bg-primary-600/20 transition-all">🔄 Sync همه نمادها</button>
        <button onClick={() => handleRunJob("brsapi_gold_currency")} className="px-4 py-2 bg-accent-amber/10 border border-accent-amber/20 rounded-xl text-xs font-bold text-accent-amber hover:bg-accent-amber/20 transition-all">🥇 Sync طلا و ارز</button>
        <button onClick={() => handleRunJob("brsapi_commodities")} className="px-4 py-2 bg-accent-emerald/10 border border-accent-emerald/20 rounded-xl text-xs font-bold text-accent-emerald hover:bg-accent-emerald/20 transition-all">🌍 Sync کامودیتی‌ها</button>
        <button onClick={() => handleRunJob("brsapi_codal")} className="px-4 py-2 bg-surface-800 border border-surface-700 rounded-xl text-xs font-bold text-surface-400 hover:text-surface-200 transition-all">🏢 Sync کدال</button>
        <Link href="/brsapi" className="px-4 py-2 bg-surface-800 border border-surface-700 rounded-xl text-xs font-bold text-surface-400 hover:text-surface-200 transition-all">📡 مدیریت داده</Link>
        <Link href="/settings" className="px-4 py-2 bg-surface-800 border border-surface-700 rounded-xl text-xs font-bold text-surface-400 hover:text-surface-200 transition-all">⚙️ تنظیمات</Link>
      </div></Card>
      {/* ML Models */}
      {dash?.ml_models && dash.ml_models.length > 0 && (<Card title="مدل‌های یادگیری ماشین"><div className="grid grid-cols-1 lg:grid-cols-2 gap-3">{dash.ml_models.map(model => { const lv = model.versions?.[model.versions.length - 1]; const acc = lv?.metrics?.accuracy != null ? (lv.metrics.accuracy * 100).toFixed(1) : null; return (<div key={model.id} className="p-3 rounded-xl bg-surface-800/30 border border-surface-700/30"><div className="flex items-center gap-2 mb-1"><span className="font-bold text-surface-200 text-sm">{model.name}</span><span className="text-[10px] font-mono text-surface-500">{model.id}</span></div><div className="flex items-center gap-2 text-[10px] text-surface-500"><span>📋 {model.task}</span><span>🔧 {model.framework}</span></div>{acc && <p className="text-xs mt-1">دقت: <span className={`font-mono font-bold ${parseFloat(acc) >= 85 ? "text-accent-emerald" : parseFloat(acc) >= 75 ? "text-accent-amber" : "text-accent-rose"}`}>{acc}%</span></p>}</div>); })}</div></Card>)}
      {/* Strategies */}
      {dash?.strategies && dash.strategies.length > 0 && (<Card title="استراتژی‌های بک‌تست"><div className="grid grid-cols-1 lg:grid-cols-3 gap-3">{dash.strategies.map((s, i) => (<div key={`${s.name}-${i}`} className="p-3 rounded-xl bg-surface-800/30 border border-surface-700/30"><div className="flex items-center gap-2 mb-1"><span className="font-bold text-surface-200 text-sm">{s.name}</span><span className="text-[10px] px-1.5 py-0.5 rounded-full bg-accent-purple/15 text-accent-purple">{s.type}</span></div><p className="text-[10px] text-surface-500 font-mono">{s.class_name}</p></div>))}</div></Card>)}
      {/* System Info */}
      <Card title="اطلاعات سیستم"><div className="grid grid-cols-2 lg:grid-cols-3 gap-3 text-xs">
        <div><span className="text-surface-500">دیتابیس:</span><span className="text-surface-300 mr-1 font-mono">PostgreSQL</span></div>
        <div><span className="text-surface-500">API:</span><span className="text-surface-300 mr-1 font-mono">FastAPI + Python</span></div>
        <div><span className="text-surface-500">فرانت‌اند:</span><span className="text-surface-300 mr-1 font-mono">Next.js + React</span></div>
        <div><span className="text-surface-500">کاربران:</span><span className="text-surface-300 mr-1 font-mono">{m?.total_users ?? "—"} ({m?.active_users ?? 0} فعال)</span></div>
        <div><span className="text-surface-500">جدول‌ها:</span><span className="text-surface-300 mr-1 font-mono">{overviewEntries.length}</span></div>
        <div><span className="text-surface-500">وضعیت:</span><span className={`mr-1 font-semibold ${dash?.system_status === "healthy" ? "text-accent-emerald" : "text-accent-rose"}`}>{dash?.system_status === "healthy" ? "✅ سالم" : "—"}</span></div>
      </div></Card>
    </AppLayout>
  );

  // ══════════════════════════════════════════════════════════════════════════════
  // TAB: SYNC — from /sync + /sync-manager sync tab
  // ══════════════════════════════════════════════════════════════════════════════

  if (tab === "sync") return (
    <AppLayout title="🛡️ پنل مدیریت" subtitle="مدیریت یکپارچه سیستم، داده‌ها و زمان‌بندی">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <Tabs tab={tab} setTab={setTab} />
      <SyncChart />
      <div className="flex justify-end mb-3"><SyncAllButton /></div>
      <Card title="وضعیت بخش‌ها" actions={<div className="flex items-center gap-3 text-[10px]"><span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-accent-emerald" /> به‌روز</span><span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-accent-amber" /> کمی قدیمی</span><span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-accent-rose" /> قدیمی</span></div>}>
        {statusLoading ? <div className="space-y-3">{[1,2,3].map(i => <Skeleton key={i} className="h-14 w-full rounded-lg" />)}</div> : (
          <div className="overflow-x-auto"><table className="w-full text-right text-xs"><thead><tr className="text-surface-500 border-b border-surface-700">
            <th className="pb-3 px-3">بخش</th><th className="pb-3 px-3 text-center">وضعیت</th><th className="pb-3 px-3 text-center">رکوردها</th><th className="pb-3 px-3 text-center">آخرین بروزرسانی</th><th className="pb-3 px-3 text-center">سن</th><th className="pb-3 px-3 text-center">مهلت</th><th className="pb-3 px-3 text-center">عملیات</th>
          </tr></thead><tbody>{overviewEntries.map(([key, info]) => { const cfg = TABLE_CONFIG[key] || { label: key, icon: "📦" }; const meta = STATUS_META[info.status] || STATUS_META.unknown; return (
            <tr key={key} className="border-b border-surface-800/30 hover:bg-surface-800/20">
              <td className="py-3 px-3"><div className="flex items-center gap-2"><span className="text-base">{cfg.icon}</span><span className="font-semibold text-surface-200">{cfg.label}</span></div></td>
              <td className="py-3 px-3 text-center"><span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold ${meta.bg} ${meta.color}`}>{meta.label}</span></td>
              <td className="py-3 px-3 text-center font-mono text-surface-300">{fmt(info.record_count)}</td>
              <td className="py-3 px-3 text-center text-surface-400">{info.last_fetched ? fmtTime(info.last_fetched) : "—"}</td>
              <td className="py-3 px-3 text-center"><span className={`font-mono ${info.status === "ok" ? "text-accent-emerald" : info.status === "stale" ? "text-accent-amber" : info.status === "outdated" ? "text-accent-rose" : "text-surface-500"}`}>{info.age_minutes != null ? `${info.age_minutes.toFixed(0)} دقیقه` : "—"}</span></td>
              <td className="py-3 px-3 text-center text-surface-500 font-mono">{info.max_age_minutes} دقیقه</td>
              <td className="py-3 px-3 text-center"><button onClick={() => handleSyncNow(key)} className={`px-2.5 py-1.5 rounded-lg text-[10px] font-medium border transition-all ${info.status === "outdated" ? "bg-accent-rose/15 text-accent-rose border-accent-rose/30 animate-pulse" : info.status === "stale" ? "bg-accent-amber/15 text-accent-amber border-accent-amber/30" : "bg-surface-800 text-surface-400 hover:text-primary-300 border-surface-700"}`}>Sync</button></td>
            </tr>); })}</tbody></table></div>
        )}
      </Card>
      <SyncEvents />
    </AppLayout>
  );

  // ══════════════════════════════════════════════════════════════════════════════
  // TAB: FRESHNESS — from /sync-settings
  // ══════════════════════════════════════════════════════════════════════════════

  if (tab === "freshness") return (
    <AppLayout title="🛡️ پنل مدیریت" subtitle="مدیریت یکپارچه سیستم، داده‌ها و زمان‌بندی">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <Tabs tab={tab} setTab={setTab} />
      <FreshnessTab settings={freshnessSettings} setSettings={setFreshnessSettings} />
    </AppLayout>
  );

  // ══════════════════════════════════════════════════════════════════════════════
  // TAB: SCHEDULER — from /scheduler
  // ══════════════════════════════════════════════════════════════════════════════

  if (tab === "scheduler") return (
    <AppLayout title="🛡️ پنل مدیریت" subtitle="مدیریت یکپارچه سیستم، داده‌ها و زمان‌بندی">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <Tabs tab={tab} setTab={setTab} />
      <SchedulerTab jobs={schedJobs} enabled={schedulerData?.enabled ?? 0} disabled={schedulerData?.disabled ?? 0} />
    </AppLayout>
  );

  // ══════════════════════════════════════════════════════════════════════════════
  // TAB: DEAD-LETTER — from GET /jobs/queue/summary
  // ══════════════════════════════════════════════════════════════════════════════

  if (tab === "deadletter") return (
    <AppLayout title="🛡️ پنل مدیریت" subtitle="مدیریت یکپارچه سیستم، داده‌ها و زمان‌بندی">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <Tabs tab={tab} setTab={setTab} />
      <DeadLetterWidget />
    </AppLayout>
  );

  // ══════════════════════════════════════════════════════════════════════════════
  // TAB: IMPORT — from /data-import
  // ══════════════════════════════════════════════════════════════════════════════

  if (tab === "import") return (
    <AppLayout title="🛡️ پنل مدیریت" subtitle="مدیریت یکپارچه سیستم، داده‌ها و زمان‌بندی">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <Tabs tab={tab} setTab={setTab} />
      <ImportTab />
    </AppLayout>
  );

  // ══════════════════════════════════════════════════════════════════════════════
  // TAB: TABLES — from /tables
  // ══════════════════════════════════════════════════════════════════════════════

  return (
    <AppLayout title="🛡️ پنل مدیریت" subtitle="مدیریت یکپارچه سیستم، داده‌ها و زمان‌بندی">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <Tabs tab={tab} setTab={setTab} />
      <TablesTab />
    </AppLayout>
  );
}

// ════════════════════════════════════════════════════════════════════════════════
// SUB-COMPONENTS
// ════════════════════════════════════════════════════════════════════════════════

function Tabs({ tab, setTab }: { tab: TabKey; setTab: (t: TabKey) => void }) {
  return (<div className="flex gap-1 mb-5 bg-surface-800/50 rounded-xl p-1 border border-surface-700/50 overflow-x-auto">
    {TABS.map(t => (<button key={t.key} onClick={() => setTab(t.key)} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${tab === t.key ? "bg-primary-600/30 text-primary-300 shadow-sm" : "text-surface-400 hover:text-surface-200"}`}>{t.icon} {t.label}</button>))}
  </div>);
}

function SyncAllButton() {
  const qc = useQueryClient();
  const [syncing, setSyncing] = useState(false);
  const [toast, setToast] = useState<{ message: string; type: "success" | "error" | "warning" } | null>(null);
  const handle = useCallback(async () => {
    setSyncing(true); let ok = 0, fail = 0; const keys = Object.keys(SECTION_ID_MAP);
    for (let i = 0; i < keys.length; i++) { const id = SECTION_ID_MAP[keys[i]]; try { const r = await apiPost<{ success: boolean }>(`/brsapi/manage/sync/${id}`); if (r?.success) ok++; else fail++; } catch { fail++; } }
    qc.invalidateQueries({ queryKey: ["admin-sync-status"] }); setSyncing(false);
  }, [qc]);
  return (<><button onClick={handle} disabled={syncing} className={`inline-flex items-center gap-2 px-5 py-2.5 rounded-xl text-xs font-bold ${syncing ? "bg-primary-600/20 text-primary-300 animate-pulse" : "bg-primary-600/15 text-primary-400 border border-primary-600/30 hover:bg-primary-600/25"}`}><span className={`material-icons text-sm ${syncing ? "animate-spin" : ""}`}>sync</span>{syncing ? "در حال sync..." : "🔄 Sync All — همه بخش‌ها"}</button></>);
}

function SyncChart() {
  const [tr, setTr] = useState("48h");
  const hrs = tr === "24h" ? 24 : tr === "48h" ? 48 : tr === "7d" ? 168 : 720;
  const { data: hist, isLoading } = useQuery({ queryKey: ["admin-sync-hist", tr], queryFn: async (): Promise<SyncLogEntry[]> => { const r = await apiGet<{ success: boolean; data: SyncLogEntry[] }>(`/brsapi/sync-history?hours=${hrs}&limit=300`); return r?.data ?? []; }, refetchInterval: 120_000 });
  const chartData = useMemo(() => { if (!hist) return []; const b: Record<string, { time: string; success: number; error: number }> = {}; for (const e of hist) { if (!e.time) continue; const k = new Date(e.time).toISOString().slice(0, 13) + ":00"; if (!b[k]) b[k] = { time: k, success: 0, error: 0 }; if (e.status === "success") b[k].success++; else b[k].error++; } return Object.values(b).sort((a, c) => a.time.localeCompare(c.time)); }, [hist]);
  const tl = { "24h": "۲۴h", "48h": "۴۸h", "7d": "۷d", "30d": "۳۰d" }[tr];
  return (<Card title={`تاریخچه Freshness (${tl})`} actions={<div className="flex gap-1">{["24h","48h","7d","30d"].map(r => (<button key={r} onClick={() => setTr(r)} className={`text-[10px] px-2 py-1 rounded-lg font-bold ${tr === r ? "bg-primary-600/30 text-primary-300" : "text-surface-500 hover:text-surface-300"}`}>{tl}</button>))}</div>}>
    {isLoading ? <Skeleton className="h-[200px] w-full rounded-xl" /> : chartData.length === 0 ? <div className="flex items-center justify-center h-[180px] text-surface-500 text-sm">داده‌ای موجود نیست</div> : (
      <AreaChartCard title="" data={chartData.map(d => ({ date: d.time.slice(11, 16), time: d.time.slice(11, 16), value: d.success, error: d.error }))} dataKey="success" height={240} strokeColor="#10b981" gradientId="freshGrad" showAverage showMinMax crosshair animate primaryLabel="موفق" yAxisLabel="تعداد" additionalSeries={[{ dataKey: "error", strokeColor: "#FF5252", gradientId: "errGrad", label: "خطا", asBar: true, barFill: "#ef4444" }]} />
    )}
  </Card>);
}

function SyncEvents() {
  const { data: hist, isLoading } = useQuery({ queryKey: ["admin-sync-events"], queryFn: async (): Promise<SyncLogEntry[]> => { const r = await apiGet<{ success: boolean; data: SyncLogEntry[] }>(`/brsapi/sync-history?hours=48&limit=20`); return r?.data ?? []; }, refetchInterval: 120_000 });
  return (<Card title="آخرین رویدادهای Sync" actions={<span className="text-[10px] text-surface-600">{hist?.length ?? 0} رویداد</span>}>
    {isLoading ? <Skeleton className="h-40 w-full" /> : hist && hist.length > 0 ? (<div className="space-y-1 max-h-[300px] overflow-y-auto">{hist.map((ev, i) => (<div key={i} className="flex items-center justify-between py-1.5 px-3 rounded-lg hover:bg-surface-800/20"><div className="flex items-center gap-2.5 min-w-0"><span className={`w-2 h-2 rounded-full shrink-0 ${ev.status === "success" ? "bg-accent-emerald" : "bg-accent-rose"}`} /><span className="text-[10px] text-surface-400 font-mono truncate max-w-[180px]">{ev.endpoint}</span></div><div className="flex items-center gap-2 shrink-0 text-[9px]"><span className="text-surface-600">{ev.items_count} آیتم</span><span className="text-surface-600">{fmtDur(ev.duration_ms)}</span><span className="text-surface-500">{fmtRel(ev.time)}</span></div></div>))}</div>) : <p className="text-surface-500 text-sm text-center py-6">رویدادی ثبت نشده</p>}
  </Card>);
}

function FreshnessTab({ settings, setSettings }: { settings: SyncSettingsMap; setSettings: (s: SyncSettingsMap) => void }) {
  const [saved, setSaved] = useState(false); const [resetConfirm, setResetConfirm] = useState(false);
  const handleSave = useCallback(() => { saveSyncSettings(settings); setSaved(true); setTimeout(() => setSaved(false), 2500); }, [settings]);
  const handleReset = useCallback(() => { resetSyncSettings(); setSettings({ ...DEFAULT_SYNC_SETTINGS }); setResetConfirm(false); setSaved(true); setTimeout(() => setSaved(false), 2500); }, [setSettings]);
  const hasChanges = ALL_SECTION_KEYS.some(k => settings[k]?.maxAgeMinutes !== DEFAULT_SYNC_SETTINGS[k]?.maxAgeMinutes);
  return (<div className="max-w-2xl mx-auto space-y-4">
    <div className="p-3 rounded-xl bg-primary-600/10 border border-primary-500/20 text-[11px] text-surface-400 leading-relaxed"><span className="font-bold text-primary-300">💡 راهنما:</span> آستانه زمانی هر بخش را تنظیم کنید. تغییرات فقط در مرورگر شما اعمال می‌شوند (localStorage).</div>
    <Card title="تنظیمات Freshness">
      <div className="flex items-center gap-3 px-3 pb-2 mb-1 border-b border-surface-700/30 text-[10px] text-surface-500"><span className="w-40">بخش</span><span className="flex-1 text-center">آستانه</span><span className="w-20 text-center">مقدار</span></div>
      <div className="space-y-0.5">{ALL_SECTION_KEYS.map(key => { const s = settings[key] || DEFAULT_SYNC_SETTINGS[key]; const idx = PRESET_VALUES.indexOf(nearestPreset(s.maxAgeMinutes)); return (
        <div key={key} className="flex items-center gap-3 py-2.5 px-3 rounded-xl hover:bg-surface-800/40">
          <div className="flex items-center gap-2 w-40 shrink-0"><span className="text-lg">{s.icon}</span><span className="text-xs font-medium text-surface-300">{s.label}</span></div>
          <input type="range" min={0} max={PRESET_VALUES.length - 1} value={idx >= 0 ? idx : 3} onChange={e => { const i = parseInt(e.target.value); setSettings({ ...settings, [key]: { ...settings[key], maxAgeMinutes: PRESET_VALUES[i] } }); }} className="flex-1 h-1.5 rounded-full appearance-none cursor-pointer bg-surface-700 accent-primary-500 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-3.5 [&::-webkit-slider-thumb]:h-3.5 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-primary-500" />
          <span className="w-20 text-center text-[11px] font-mono text-surface-400 shrink-0">{VALUE_LABELS[nearestPreset(s.maxAgeMinutes)] || `${s.maxAgeMinutes} دقیقه`}</span>
        </div>); })}</div>
    </Card>
    <div className="flex items-center gap-3">
      <button onClick={handleSave} className="px-5 py-2.5 rounded-xl text-xs font-bold bg-primary-600 text-white hover:bg-primary-500">{saved ? "✓ ذخیره شد" : "💾 ذخیره"}</button>
      {hasChanges && <span className="text-[10px] text-accent-amber">⚠️ تغییرات ذخیره نشده</span>}
      <div className="flex-1" />
      {resetConfirm ? (<div className="flex items-center gap-2"><button onClick={handleReset} className="px-3 py-2 rounded-lg text-[10px] font-bold bg-accent-rose/15 text-accent-rose">بله، ریست</button><button onClick={() => setResetConfirm(false)} className="px-3 py-2 rounded-lg text-[10px] bg-surface-800 text-surface-400">انصراف</button></div>) : <button onClick={() => setResetConfirm(true)} className="text-[10px] text-surface-500 hover:text-accent-rose">🔄 بازگشت به پیش‌فرض</button>}
    </div>
  </div>);
}

function SchedulerTab({ jobs, enabled, disabled }: { jobs: SchedulerJob[]; enabled: number; disabled: number }) {
  const qc = useQueryClient();
  const [toast, setToast] = useState<{ message: string; type: "success" | "error" } | null>(null);
  const [search, setSearch] = useState(""); const [cat, setCat] = useState("all");
  const filtered = useMemo(() => jobs.filter(j => { if (cat !== "all" && j.category !== cat) return false; if (search.trim()) { const q = search.toLowerCase(); return j.name.toLowerCase().includes(q) || j.description.toLowerCase().includes(q); } return true; }).sort((a, b) => a.enabled === b.enabled ? a.name.localeCompare(b.name) : a.enabled ? -1 : 1), [jobs, search, cat]);
  const categories = useMemo(() => Array.from(new Set(jobs.map(j => j.category))).sort(), [jobs]);
  const handleRun = useCallback(async (name: string) => { setToast({ message: `🔄 ${name}...`, type: "success" }); try { const r = await apiPost<{ success: boolean }>(`/jobs/scheduler/${name}/run`); if (r?.success) { setToast({ message: `✅ ${name}`, type: "success" }); qc.invalidateQueries({ queryKey: ["admin-scheduler"] }); } } catch {} }, [qc]);
  const handleToggle = useCallback(async (name: string) => { try { const r = await apiPost<{ success: boolean }>(`/jobs/scheduler/${name}/toggle`); if (r?.success) { setToast({ message: `✅ ${name}`, type: "success" }); qc.invalidateQueries({ queryKey: ["admin-scheduler"] }); } } catch {} }, [qc]);
  return (<div className="space-y-4">
    {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    <div className="flex items-center gap-3 flex-wrap">
      <div className="flex items-center gap-2 bg-surface-800/50 rounded-xl px-3 py-2 border border-surface-700/50 flex-1 min-w-[200px]"><span className="text-surface-500">🔍</span><input type="text" value={search} onChange={e => setSearch(e.target.value)} placeholder="جستجو..." className="bg-transparent text-sm text-white placeholder-surface-500 outline-none flex-1 min-w-0" /></div>
      <select value={cat} onChange={e => setCat(e.target.value)} className="bg-surface-800/50 text-sm text-surface-300 border border-surface-700/50 rounded-xl px-3 py-2 outline-none"><option value="all">📂 همه</option>{categories.map(c => { const ci = CATEGORY_CONFIG[c] || { label: c, icon: "📦" }; return <option key={c} value={c}>{ci.icon} {ci.label}</option>; })}</select>
    </div>
    <Card title="Jobهای زمان‌بندی" actions={<span className="text-[10px] text-surface-600">{enabled} فعال / {disabled} غیرفعال</span>}>
      <div className="overflow-x-auto"><table className="w-full text-right text-xs"><thead><tr className="text-surface-500 border-b border-surface-700">
        <th className="pb-3 px-3">وضعیت</th><th className="pb-3 px-3">نام</th><th className="pb-3 px-3">دسته</th><th className="pb-3 px-3">برنامه</th><th className="pb-3 px-3 text-center">اجرای بعدی</th><th className="pb-3 px-3 text-center">عملیات</th>
      </tr></thead><tbody>{filtered.map(job => { const ci = CATEGORY_CONFIG[job.category] || { label: job.category, icon: "📦" }; return (
        <tr key={job.name} className={`border-b border-surface-800/30 hover:bg-surface-800/20 ${job.enabled ? "" : "opacity-60"}`}>
          <td className="py-3 px-3"><span className={`w-2.5 h-2.5 rounded-full inline-block ${job.enabled ? "bg-accent-emerald" : "bg-surface-600"}`} /></td>
          <td className="py-3 px-3 max-w-[220px]"><div className="flex flex-col gap-0.5"><span className="font-semibold text-surface-200 font-mono text-[11px]">{job.name}</span><span className="text-[9px] text-surface-500 line-clamp-1">{job.description}</span></div></td>
          <td className="py-3 px-3"><span className="px-2 py-0.5 rounded-lg bg-surface-800 text-surface-400 text-[10px]">{ci.icon} {ci.label}</span></td>
          <td className="py-3 px-3"><span className="font-mono text-surface-300 text-[10px]">{fmtCron(job.cron)}</span></td>
          <td className="py-3 px-3 text-center">{job.enabled && job.next_run_time ? <span className="text-[10px] text-surface-400">{fmtTime(job.next_run_time)}</span> : <span className="text-surface-600">—</span>}</td>
          <td className="py-3 px-3"><div className="flex items-center justify-center gap-1.5"><button onClick={() => handleRun(job.name)} className="px-2 py-1.5 rounded-lg text-[10px] bg-primary-600/10 text-primary-400 border border-primary-600/20 hover:bg-primary-600/20">▶</button><button onClick={() => handleToggle(job.name)} className={`px-2 py-1.5 rounded-lg text-[10px] border ${job.enabled ? "bg-accent-rose/10 text-accent-rose border-accent-rose/20" : "bg-accent-emerald/10 text-accent-emerald border-accent-emerald/20"}`}>{job.enabled ? "⏸" : "▶"}</button></div></td>
        </tr>); })}</tbody></table></div>
    </Card>
  </div>);
}

function ImportTab() {
  const [activeTab, setActiveTab] = useState<string>("instruments");
  const [files, setFiles] = useState<File[]>([]);
  const [result, setResult] = useState<ImportResult | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const ref = useRef<HTMLInputElement>(null);
  const { data: templates } = useQuery({ queryKey: ["import-templates"], queryFn: async () => { const r = await apiGet<{ success: boolean; data: ImportTemplates }>("/data-import/templates"); return r.data; }, staleTime: 300_000 });
  const { data: history } = useQuery({ queryKey: ["import-history"], queryFn: async () => { const r = await apiGet<{ success: boolean; data: { items: ImportJob[] } }>("/data-import/history"); return r.data?.items || []; }, refetchInterval: 30_000 });
  const tmpl = templates?.[activeTab as keyof ImportTemplates];
  const doUpload = useCallback(async (f: File[]) => {
    const ep = activeTab === "instruments" ? "/instruments/import" : activeTab === "quotes" ? "/quotes/import-bulk" : "/codal/import-bulk";
    const form = new FormData(); if (activeTab === "instruments") form.append("file", f[0]); else f.forEach(x => form.append("files", x));
    try { const r = await fetch(`${API_BASE}${ep}`, { method: "POST", body: form }); const d = await r.json(); setResult({ total_files: d?.data?.total_files ?? 0, total_rows: d?.data?.total_rows ?? 0, imported: d?.data?.imported ?? 0, updated: d?.data?.updated ?? 0, errors: d?.data?.errors ?? d?.data?.parse_errors ?? [], per_file: d?.data?.per_file }); setFiles([]); } catch { setResult({ errors: ["خطا در آپلود"] }); setFiles([]); }
  }, [activeTab]);
  return (<div className="space-y-4">
    <div className="flex gap-2 overflow-x-auto">{IMPORT_TABS.map(t => (<button key={t.key} onClick={() => setActiveTab(t.key)} className={`px-4 py-2 rounded-xl text-sm font-medium transition-all whitespace-nowrap ${activeTab === t.key ? "bg-primary-600/20 text-primary-300 border border-primary-600/30" : "bg-surface-800/50 text-surface-400 border border-surface-700 hover:text-surface-200"}`}>{t.label}</button>))}</div>
    <div onDragOver={e => { e.preventDefault(); setDragOver(true); }} onDragLeave={() => setDragOver(false)} onDrop={e => { e.preventDefault(); setDragOver(false); setFiles(Array.from(e.dataTransfer.files)); }} onClick={() => ref.current?.click()} className={`border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-all ${dragOver ? "border-primary-400 bg-primary-600/10" : "border-surface-700 hover:border-surface-500 bg-surface-800/30"}`}>
      <input ref={ref} type="file" multiple accept={tmpl?.accept} onChange={e => { if (e.target.files) setFiles(Array.from(e.target.files)); }} className="hidden" />
      <div className="text-4xl mb-3">{dragOver ? "📥" : "📂"}</div>
      <p className="text-sm text-surface-300">{files.length > 0 ? `${files.length} فایل انتخاب شده` : "فایل را بکشید و رها کنید"}</p>
      <p className="text-xs text-surface-500 mt-1">{tmpl?.accept} • حداکثر {tmpl?.max_size_mb}MB</p>
      {tmpl?.note && <p className="text-xs text-accent-amber mt-2">{tmpl.note}</p>}
      {files.length > 0 && <div className="mt-3 space-y-1">{files.map((f, i) => <p key={i} className="text-xs text-surface-400 font-mono">{f.name} ({(f.size / 1024).toFixed(0)}KB)</p>)}</div>}
    </div>
    <div className="flex gap-3">
      <button onClick={() => files.length > 0 && doUpload(files)} disabled={files.length === 0} className="flex-1 py-2.5 bg-primary-600 hover:bg-primary-500 disabled:bg-surface-700 disabled:text-surface-500 text-white rounded-xl text-sm font-semibold">📤 آپلود و Import</button>
      {tmpl?.sample_endpoint && <a href={`${API_BASE}${tmpl.sample_endpoint}`} className="px-4 py-2.5 bg-surface-800 hover:bg-surface-700 text-surface-300 rounded-xl text-xs">📄 نمونه CSV</a>}
    </div>
    {result && (<div className={`glass-card p-4 ${result.errors && result.errors.length > 0 ? "border-accent-rose/30" : "border-accent-emerald/30"}`}>
      <h4 className="text-sm font-bold text-surface-200 mb-3">نتایج Import</h4>
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-3">
        {result.total_files !== undefined && <div><span className="text-xs text-surface-500">فایل‌ها</span><p className="text-lg font-bold text-surface-200">{fmt(result.total_files)}</p></div>}
        {result.imported !== undefined && <div><span className="text-xs text-surface-500">جدید</span><p className="text-lg font-bold text-accent-emerald">{fmt(result.imported)}</p></div>}
        {result.updated !== undefined && <div><span className="text-xs text-surface-500">بروزرسانی</span><p className="text-lg font-bold text-accent-amber">{fmt(result.updated)}</p></div>}
        {result.total_rows !== undefined && <div><span className="text-xs text-surface-500">ردیف‌ها</span><p className="text-lg font-bold text-surface-200">{fmt(result.total_rows)}</p></div>}
      </div>
      {result.errors && result.errors.length > 0 && <div><p className="text-xs text-accent-rose mb-1">خطاها ({result.errors.length}):</p><div className="max-h-24 overflow-y-auto">{result.errors.slice(0, 10).map((e, i) => <p key={i} className="text-[10px] text-accent-rose/80 font-mono">{e}</p>)}</div></div>}
      {result.per_file && Object.keys(result.per_file).length > 0 && <div className="mt-2 pt-2 border-t border-surface-700"><p className="text-[10px] text-surface-500 mb-1">جزئیات:</p>{Object.entries(result.per_file).map(([name, info]) => <p key={name} className="text-[10px] text-surface-400 font-mono">{name}: {info.imported} جدید, {info.updated} بروز</p>)}</div>}
    </div>)}
    {tmpl && tmpl.columns.length > 0 && (<div className="glass-card p-4"><h4 className="text-xs font-bold text-surface-400 mb-2">📋 ستون‌های قابل قبول</h4><div className="overflow-x-auto"><table className="w-full text-[10px]"><thead><tr className="text-surface-600 border-b border-surface-700"><th className="text-right py-1.5 px-2">ستون</th><th className="text-right py-1.5 px-2">نوع</th><th className="text-right py-1.5 px-2">اجباری</th><th className="text-right py-1.5 px-2">توضیح</th></tr></thead><tbody>{tmpl.columns.map(col => (<tr key={col.column} className="border-b border-surface-800/50"><td className="py-1.5 px-2 font-mono text-surface-300">{col.column}</td><td className="py-1.5 px-2 text-surface-500">{col.type}</td><td className="py-1.5 px-2"><span className={`px-1.5 py-0.5 rounded ${col.required ? "bg-accent-rose/15 text-accent-rose" : "bg-surface-800 text-surface-500"}`}>{col.required ? "بله" : "خیر"}</span></td><td className="py-1.5 px-2 text-surface-500">{col.desc}</td></tr>))}</tbody></table></div></div>)}
    {history && history.length > 0 && (<Card title="تاریخچه Import"><div className="overflow-x-auto"><table className="w-full text-xs"><thead><tr className="text-surface-500 border-b border-surface-700"><th className="text-right py-2 px-2">نوع</th><th className="text-right py-2 px-2">وضعیت</th><th className="text-right py-2 px-2">مدت</th><th className="text-right py-2 px-2">زمان</th><th className="text-right py-2 px-2">خطا</th></tr></thead><tbody>{history.slice(0, 15).map((job: ImportJob) => (<tr key={job.id} className="border-b border-surface-800/50 hover:bg-surface-800/30"><td className="py-2 px-2 font-mono text-surface-300">{job.job_type}</td><td className="py-2 px-2"><span className={`px-2 py-0.5 rounded-full text-[10px] font-semibold ${statusBadge(job.status)}`}>{statusLbl(job.status)}</span></td><td className="py-2 px-2 text-surface-400">{job.duration_seconds > 0 ? fmtDurSec(job.duration_seconds) : "—"}</td><td className="py-2 px-2 text-surface-500">{fmtTime(job.completed_at || job.started_at)}</td><td className="py-2 px-2 text-accent-rose max-w-[160px] truncate">{job.error_message || "—"}</td></tr>))}</tbody></table></div></Card>)}
  </div>);
}

function TablesTab() {
  const [sel, setSel] = useState<string | null>(null);
  const [filter, setFilter] = useState("");
  const [globalQ, setGlobalQ] = useState("");
  const [activeGlobalQ, setActiveGlobalQ] = useState("");
  const [page, setPage] = useState(1);
  const { data: tblResp, isLoading } = useQuery({ queryKey: ["tables-list"], queryFn: async () => apiGet<unknown>("/tables") });
  const tables: TableInfo[] = (tblResp && typeof tblResp === "object" && "data" in tblResp) ? ((tblResp as { data?: { tables?: TableInfo[] } }).data?.tables ?? []) : [];
  const { data: dResp, isLoading: dLoading } = useQuery({ queryKey: ["table-data", sel], queryFn: async () => apiGet<unknown>(`/tables/${sel}?page=1&page_size=50`), enabled: !!sel });
  const tblData: TableData | null = (dResp && typeof dResp === "object" && "data" in dResp) ? ((dResp as { data?: TableData }).data ?? null) : null;

  return (<div className="space-y-4">
    {/* Global Search */}
    <div className="glass-card p-4">
      <form onSubmit={e => { e.preventDefault(); if (globalQ.trim()) setActiveGlobalQ(globalQ.trim()); }} className="flex items-center gap-3">
        <span className="text-surface-500 text-lg">🔍</span>
        <input type="text" value={globalQ} onChange={e => setGlobalQ(e.target.value)} placeholder="نام نماد را تایپ کنید (مثال: فولاد، شپنا، وبملت)" className="flex-1 px-4 py-2.5 bg-surface-800 border border-surface-700 rounded-xl text-sm text-surface-200 focus:outline-none focus:border-primary-500" />
        <button type="submit" className="px-4 py-2.5 bg-primary-600 text-white rounded-xl text-sm font-bold">جستجو</button>
        {activeGlobalQ && <button type="button" onClick={() => { setActiveGlobalQ(""); setGlobalQ(""); }} className="px-4 py-2.5 bg-surface-800 text-surface-300 rounded-xl text-sm">پاک کردن</button>}
      </form>
      {activeGlobalQ && <div className="mt-2 text-xs text-surface-400">جستجوی: <span className="font-mono text-primary-300">{activeGlobalQ}</span></div>}
    </div>
    {/* Content */}
    {activeGlobalQ ? <GlobalSearchResults query={activeGlobalQ} /> : (
      <div className="flex gap-6">
        {/* Sidebar */}
        <div className="w-64 shrink-0"><div className="glass-card p-4">
          <h3 className="font-bold text-sm text-surface-200 mb-3">جداول ({tables.length})</h3>
          <input type="text" value={filter} onChange={e => setFilter(e.target.value)} placeholder="فیلتر..." className="w-full px-3 py-2 bg-surface-800 border border-surface-700 rounded-lg text-sm text-surface-200 focus:outline-none focus:border-primary-500 mb-3" />
          <div className="space-y-1 max-h-[calc(100vh-320px)] overflow-y-auto">
            {(filter ? tables.filter(t => t.name.includes(filter)) : tables).map(t => (<button key={`${t.name}-${t.row_count}`} onClick={() => { setSel(t.name); setFilter(""); }} className={`w-full text-right px-3 py-2 rounded-lg text-xs font-mono transition-colors flex items-center justify-between ${sel === t.name ? "bg-primary-600/20 text-primary-300 border border-primary-600/30" : "text-surface-300 hover:bg-surface-800"}`}><span>{t.name}</span><span className="text-[10px] text-surface-500">{t.row_count.toLocaleString("en-US")}</span></button>))}
          </div>
        </div></div>
        {/* Main */}
        <div className="flex-1 min-w-0"><div className="glass-card p-4">
          {dLoading && !tblData ? <div className="space-y-3">{[1,2,3,4,5].map(i => <Skeleton key={i} className="h-11 w-full" />)}</div> : tblData ? (
            <div><div className="flex items-center justify-between mb-4"><h3 className="font-bold text-surface-200">{tblData.table}</h3><span className="text-xs text-surface-500 font-mono">{tblData.total.toLocaleString("en-US")} rows | Page {tblData.page}/{tblData.total_pages}</span></div>
              <div className="overflow-x-auto rounded-xl border border-surface-700/50"><table className="w-full text-right text-xs"><thead><tr className="bg-surface-800/80 border-b border-surface-700"><th className="py-2.5 px-3 text-surface-400 w-10">#</th>{tblData.columns.map((col, ci) => (<th key={`${col.name}-${ci}`} className="py-2.5 px-3 text-surface-400"><div>{col.name}</div><div className="text-[9px] text-surface-600 font-mono">{col.type}</div></th>))}</tr></thead>
                <tbody>{tblData.rows.map((row, i) => (<tr key={i} className="border-b border-surface-800/30 hover:bg-surface-800/20"><td className="py-2 px-3 text-surface-600 font-mono">{(tblData.page - 1) * tblData.page_size + i + 1}</td>{tblData.columns.map((col, ci) => { const val = row[col.name]; const sv = val == null ? "—" : typeof val === "object" ? JSON.stringify(val) : String(val); return <td key={`${col.name}-${ci}`} className="py-2 px-3 font-mono text-surface-200 max-w-[200px] truncate" title={sv.length > 50 ? sv : undefined}>{sv.length > 50 ? sv.slice(0, 50) + "..." : sv}</td>; })}</tr>))}</tbody></table></div>
              {tblData.total_pages > 1 && (<div className="flex justify-center gap-1 mt-4"><button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={tblData.page <= 1} className="px-3 py-1.5 rounded-lg bg-surface-800 text-surface-300 text-xs disabled:opacity-40">قبلی</button>{Array.from({ length: Math.min(5, tblData.total_pages) }, (_, i) => { const p = Math.max(1, Math.min(tblData.page - 2, tblData.total_pages - 4)) + i; if (p > tblData.total_pages) return null; return <button key={p} className={`px-3 py-1.5 rounded-lg text-xs ${p === tblData.page ? "bg-primary-600 text-white" : "bg-surface-800 text-surface-300"}`}>{p}</button>; })}<button onClick={() => setPage(p => Math.min(tblData.total_pages, p + 1))} disabled={tblData.page >= tblData.total_pages} className="px-3 py-1.5 rounded-lg bg-surface-800 text-surface-300 text-xs disabled:opacity-40">بعدی</button></div>)}
            </div>
          ) : <div className="text-center py-20 text-surface-500"><div className="text-4xl mb-3">🗃️</div><p className="text-sm">یک جدول را از لیست انتخاب کنید</p></div>}
        </div></div>
      </div>
    )}
  </div>);
}

function GlobalSearchResults({ query }: { query: string }) {
  const [open, setOpen] = useState<string | null>(null);
  const { data: resp, isLoading } = useQuery({ queryKey: ["global-search", query], queryFn: async () => {
    const ps = SEARCHABLE_TABLES.map(async tn => { try { const r = await apiGet<{ data?: { rows?: Record<string, unknown>[]; total?: number; columns?: ColumnInfo[] } }>(`/tables/${tn}?page=1&page_size=20&search=${encodeURIComponent(query)}`); const d = r?.data; if (d && Array.isArray(d.rows) && d.rows.length > 0) return { table: tn, total: d.total ?? 0, columns: d.columns ?? [], rows: d.rows } as SearchResult; } catch {} return null; });
    return (await Promise.all(ps)).filter(Boolean) as SearchResult[];
  }});
  const results = resp || [];
  if (isLoading) return <div className="space-y-4">{[1,2,3].map(i => <div key={i} className="glass-card p-4"><Skeleton className="h-7 w-36 mb-3" />{[1,2,3].map(j => <Skeleton key={j} className="h-9 w-full mb-1" />)}</div>)}</div>;
  if (results.length === 0) return <div className="text-center py-20 text-surface-500"><p className="text-lg mb-2">نتیجه‌ای برای «{query}» یافت نشد</p></div>;
  return (<div className="space-y-4">
    <div className="text-xs text-surface-400">{results.length} جدول — {results.reduce((s, r) => s + r.total, 0).toLocaleString("en-US")} ردیف یافت شد</div>
    {results.map(r => { const isOn = open === r.table; return (<div key={r.table} className="glass-card overflow-hidden">
      <button onClick={() => setOpen(isOn ? null : r.table)} className="w-full flex items-center justify-between p-4 text-surface-200">
        <div className="flex items-center gap-3"><span className="text-primary-400">📊</span><span className="font-mono font-bold">{r.table}</span><span className="text-[10px] px-2 py-0.5 rounded-full bg-primary-600/15 text-primary-300">{r.total.toLocaleString("en-US")} ردیف</span></div>
        <span className="text-surface-500">{isOn ? "▲" : "▼"}</span>
      </button>
      {isOn && (<div className="border-t border-surface-700/50 p-3 overflow-x-auto"><table className="w-full text-right text-xs"><thead><tr className="border-b border-surface-700">{r.columns.map((col, ci) => <th key={`${col.name}-${ci}`} className="py-1.5 px-2 text-surface-400">{col.name}</th>)}</tr></thead><tbody>{r.rows.map((row, i) => (<tr key={i} className="border-b border-surface-800/30">{r.columns.map((col, ci) => { const val = row[col.name]; const sv = val == null ? "—" : typeof val === "object" ? JSON.stringify(val) : String(val); return <td key={`${col.name}-${ci}`} className="py-1.5 px-2 font-mono text-surface-200 max-w-[180px] truncate" title={sv}>{sv.length > 40 ? sv.slice(0, 40) + "..." : sv}</td>; })}</tr>))}</tbody></table>{r.total > 20 && <p className="text-center text-[10px] text-surface-500 mt-2">نمایش ۲۰ از {r.total.toLocaleString("en-US")} ردیف</p>}</div>)}
    </div>); })}
  </div>);
}

"use client";

import { useState, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import Link from "next/link";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import { apiGet } from "@/lib/api";

// ── Types ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

interface AnomalyItem {
  symbol: string;
  type: "price_spike_up" | "price_spike_down" | "volume_spike";
  severity: "high" | "medium" | "low";
  date: string;
  value: number;
  expected: number;
  z_score: number;
  volume: number;
  price?: number;
  description: string;
}

interface AnomalySummary {
  total_symbols_scanned: number;
  symbols_with_data: number;
  symbols_with_anomalies: number;
  high_severity: number;
  medium_severity: number;
  price_anomalies: number;
  volume_anomalies: number;
}

interface AnomalyResponse {
  items: AnomalyItem[];
  total: number;
  summary: AnomalySummary;
  config: {
    price_threshold: number;
    volume_threshold: number;
    lookback_days: number;
  };
}

// ── Helpers ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

function formatNum(v: number): string {
  if (!v) return "—";
  if (v >= 1_000_000_000_000) return (v / 1_000_000_000_000).toFixed(2) + "T";
  if (v >= 1_000_000_000) return (v / 1_000_000_000).toFixed(2) + "B";
  if (v >= 1_000_000) return (v / 1_000_000).toFixed(1) + "M";
  if (v >= 1_000) return (v / 1_000).toFixed(0) + "K";
  return v.toLocaleString("fa-IR");
}

function typeIcon(type: string): string {
  switch (type) {
    case "price_spike_up": return "📈";
    case "price_spike_down": return "📉";
    case "volume_spike": return "📊";
    default: return "⚠️";
  }
}

function typeLabel(type: string): string {
  switch (type) {
    case "price_spike_up": return "جهش قیمت";
    case "price_spike_down": return "سقوط قیمت";
    case "volume_spike": return "جهش حجم";
    default: return type;
  }
}

function severityColor(severity: string): string {
  switch (severity) {
    case "high": return "bg-accent-rose/15 text-accent-rose border-accent-rose/30";
    case "medium": return "bg-accent-amber/15 text-accent-amber border-accent-amber/30";
    case "low": return "bg-surface-600/30 text-surface-400 border-surface-700";
    default: return "bg-surface-600/30 text-surface-400 border-surface-700";
  }
}

const SEVERITY_FILTERS = [
  { key: "all", label: "همه" },
  { key: "high", label: "شدید" },
  { key: "medium", label: "متوسط" },
  { key: "low", label: "ضعیف" },
];

const TYPE_FILTERS = [
  { key: "all", label: "همه انواع" },
  { key: "price", label: "قیمت" },
  { key: "volume", label: "حجم" },
];

// ── Main Page ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

export default function AnomaliesPage() {
  const [severityFilter, setSeverityFilter] = useState("all");
  const [typeFilter, setTypeFilter] = useState("all");
  const [search, setSearch] = useState("");

  const { data, isLoading, isError, refetch } = useQuery({
    queryKey: ["anomalies"],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: AnomalyResponse }>(
        "/anomalies?limit=60&price_threshold=2.5&volume_threshold=2.0"
      );
      if (!res?.success) throw new Error("Failed to fetch anomalies");
      return res.data;
    },
    refetchInterval: 120_000,
  });

  const items = data?.items ?? [];
  const summary = data?.summary;

  // ── Filters ──
  const filtered = useMemo(() => {
    let list = items;

    if (severityFilter !== "all") {
      list = list.filter((a) => a.severity === severityFilter);
    }
    if (typeFilter === "price") {
      list = list.filter((a) => a.type.includes("price"));
    } else if (typeFilter === "volume") {
      list = list.filter((a) => a.type === "volume_spike");
    }
    if (search.trim()) {
      const q = search.trim().toLowerCase();
      list = list.filter((a) => a.symbol.toLowerCase().includes(q));
    }

    return list;
  }, [items, severityFilter, typeFilter, search]);

  // ── Group by symbol ──
  const grouped = useMemo(() => {
    const map = new Map<string, AnomalyItem[]>();
    for (const item of filtered) {
      if (!map.has(item.symbol)) map.set(item.symbol, []);
      map.get(item.symbol)!.push(item);
    }
    return Array.from(map.entries()).sort(
      (a, b) => b[1].length - a[1].length
    );
  }, [filtered]);

  return (
    <AppLayout
      title="🚨 تشخیص ناهنجاری"
      subtitle="شناسایی جهش‌های قیمت و حجم با تحلیل Z-Score"
    >
      {/* ── Summary cards ── */}
      {summary && (
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-3 mb-5">
          <div className="glass-card p-3 text-center">
            <p className="text-xl font-black text-accent-rose">{summary.high_severity}</p>
            <p className="text-xs text-surface-500">شدید</p>
          </div>
          <div className="glass-card p-3 text-center">
            <p className="text-xl font-black text-accent-amber">{summary.medium_severity}</p>
            <p className="text-xs text-surface-500">متوسط</p>
          </div>
          <div className="glass-card p-3 text-center">
            <p className="text-xl font-black text-surface-100">{summary.price_anomalies}</p>
            <p className="text-xs text-surface-500">ناهنجاری قیمت</p>
          </div>
          <div className="glass-card p-3 text-center">
            <p className="text-xl font-black text-primary-300">{summary.volume_anomalies}</p>
            <p className="text-xs text-surface-500">ناهنجاری حجم</p>
          </div>
          <div className="glass-card p-3 text-center">
            <p className="text-xl font-black text-surface-200">{summary.symbols_with_anomalies}</p>
            <p className="text-xs text-surface-500">نمادهای دارای ناهنجاری</p>
          </div>
          <div className="glass-card p-3 text-center">
            <p className="text-xl font-black text-surface-400">{summary.total_symbols_scanned}</p>
            <p className="text-xs text-surface-500">بررسی شده</p>
          </div>
          <div className="glass-card p-3 text-center">
            <p className="text-lg font-black font-mono text-surface-500">{data?.config?.price_threshold}σ / {data?.config?.volume_threshold}σ</p>
            <p className="text-xs text-surface-500">آستانه Z-Score</p>
          </div>
        </div>
      )}

      {/* ── Filters ── */}
      <div className="flex flex-wrap items-center gap-3 mb-4">
        <input
          type="text"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="جستجوی نماد..."
          className="px-3 py-2 bg-surface-800 border border-surface-700 rounded-lg text-surface-200 text-sm focus:outline-none focus:border-primary-500 w-44"
        />

        <div className="flex gap-1 flex-wrap">
          {SEVERITY_FILTERS.map((f) => (
            <button
              key={f.key}
              onClick={() => setSeverityFilter(f.key)}
              className={`px-2.5 py-1 rounded-lg text-[10px] font-medium transition-all ${
                severityFilter === f.key
                  ? "bg-primary-600 text-white"
                  : "bg-surface-800 text-surface-400 hover:text-surface-200"
              }`}
            >
              {f.label}
            </button>
          ))}
        </div>

        <div className="flex gap-1 flex-wrap">
          {TYPE_FILTERS.map((f) => (
            <button
              key={f.key}
              onClick={() => setTypeFilter(f.key)}
              className={`px-2.5 py-1 rounded-lg text-[10px] font-medium transition-all ${
                typeFilter === f.key
                  ? "bg-primary-600 text-white"
                  : "bg-surface-800 text-surface-400 hover:text-surface-200"
              }`}
            >
              {f.label}
            </button>
          ))}
        </div>

        <button
          onClick={() => refetch()}
          className="p-1.5 rounded-lg bg-surface-800 text-surface-400 hover:text-surface-200 transition-colors"
          title="بروزرسانی"
        >
          <span className="material-icons text-sm">refresh</span>
        </button>

        <span className="text-xs text-surface-500">
          {filtered.length} ناهنجاری
        </span>
      </div>

      {/* ── Loading ── */}
      {isLoading && (
        <div className="space-y-3">
          {[1, 2, 3, 4, 5].map((i) => (
            <Skeleton key={i} className="h-16 w-full rounded-xl" />
          ))}
        </div>
      )}

      {/* ── Error ── */}
      {isError && !isLoading && (
        <div className="glass-card p-12 text-center text-accent-rose">
          <p className="text-5xl mb-3">⚠️</p>
          <p className="font-bold">خطا در تشخیص ناهنجاری</p>
          <p className="text-sm mt-1 text-surface-500">
            داده کافی در جدول quotes موجود نیست
          </p>
          <button
            onClick={() => refetch()}
            className="mt-4 px-4 py-2 bg-surface-800 hover:bg-surface-700 text-surface-200 rounded-lg text-sm transition-colors"
          >
            تلاش مجدد
          </button>
        </div>
      )}

      {/* ── Empty ── */}
      {!isLoading && !isError && filtered.length === 0 && (
        <div className="glass-card p-12 text-center text-surface-500">
          <p className="text-5xl mb-3">✅</p>
          <p className="font-bold">ناهنجاری‌ای یافت نشد</p>
          <p className="text-sm mt-1">
            {summary
              ? summary.total_symbols_scanned + " نماد بررسی شدند و ناهنجاری قابل توجهی یافت نشد"
              : "داده‌ای برای بررسی موجود نیست"}
          </p>
        </div>
      )}

      {/* ── Anomaly cards (grouped by symbol) ── */}
      {!isLoading && !isError && grouped.length > 0 && (
        <div className="space-y-3">
          {grouped.map(([symbol, anomalies]) => {
            const maxSeverity = anomalies.some((a) => a.severity === "high")
              ? "high"
              : anomalies.some((a) => a.severity === "medium")
              ? "medium"
              : "low";
            return (
              <div
                key={symbol}
                className="glass-card overflow-hidden"
              >
                {/* Header */}
                <Link
                  href={`/symbol/${encodeURIComponent(symbol)}`}
                  className="flex items-center justify-between p-3 bg-surface-800/50 hover:bg-surface-800/70 transition-colors"
                >
                  <div className="flex items-center gap-3">
                    <span className="font-bold text-surface-100">{symbol}</span>
                    <span className="text-xs text-surface-500">
                      {anomalies.length} ناهنجاری
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span
                      className={`text-[10px] px-2 py-0.5 rounded-full font-bold border ${
                        severityColor(maxSeverity)
                      }`}
                    >
                      {maxSeverity === "high"
                        ? "شدید"
                        : maxSeverity === "medium"
                        ? "متوسط"
                        : "ضعیف"}
                    </span>
                    <span className="material-icons text-surface-500 text-sm">
                      chevron_left
                    </span>
                  </div>
                </Link>

                {/* Anomaly list */}
                <div className="divide-y divide-surface-800/30">
                  {anomalies.map((a, i) => (
                    <div
                      key={`${a.date}-${a.type}-${i}`}
                      className="flex items-center gap-3 p-3 hover:bg-white/[0.02] transition-colors text-xs"
                    >
                      <span className="text-base shrink-0">{typeIcon(a.type)}</span>

                      <span
                        className={`text-[10px] px-1.5 py-0.5 rounded-full font-bold shrink-0 ${
                          severityColor(a.severity)
                        }`}
                      >
                        {a.severity === "high" ? "شدید" : a.severity === "medium" ? "متوسط" : "ضعیف"}
                      </span>

                      <span className="text-surface-400 shrink-0 font-mono w-[80px]">
                        {a.date?.slice(5) || "—"}
                      </span>

                      <span className="font-bold text-surface-300 shrink-0 w-[70px]">
                        {typeLabel(a.type)}
                      </span>

                      <span className="text-surface-200 font-mono shrink-0 w-[60px] text-right">
                        {a.type.includes("price") || a.type === "volume_spike"
                          ? formatNum(a.value)
                          : "—"}
                      </span>

                      <span className="text-surface-600 shrink-0">vs</span>

                      <span className="text-surface-500 font-mono shrink-0 w-[60px] text-right">
                        {formatNum(a.expected)}
                      </span>

                      <span
                        className={`font-mono font-bold shrink-0 w-[50px] text-right ${
                          a.z_score > 0 ? "text-accent-rose" : "text-accent-emerald"
                        }`}
                      >
                        {a.z_score > 0 ? "+" : ""}
                        {a.z_score?.toFixed(1)}σ
                      </span>

                      <span className="text-surface-500 flex-1 truncate hidden md:block">
                        {a.description}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </AppLayout>
  );
}

"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import {
  XAxis, YAxis, Tooltip, ResponsiveContainer,
  Area, AreaChart, CartesianGrid, ReferenceLine,
} from "recharts";
import {
  FlaskConical, Dices, FlaskRound, Cpu, Rocket, TrendingUp,
} from "lucide-react";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import { apiPost, apiGet } from "@/lib/api";
import { toJalali, gregorianToJalali, jalaliToGregorian } from "@/lib/dates";

interface CompareHistoryItem {
  id: string;
  symbol: string;
  total_strategies: number;
  successful: number;
  failed: number;
  best: string | null;
  worst: string | null;
  best_return_pct: number | null;
  worst_return_pct: number | null;
  avg_return_pct: number | null;
  notes: string | null;
  created_at: string | null;
}

interface BacktestResult {
  id: string;
  name: string;
  status: string;
  total_return_pct: number;
  annualized_return_pct: number;
  sharpe_ratio: number;
  max_drawdown_pct: number;
  win_rate: number;
  total_trades: number;
  winning_trades: number;
  losing_trades: number;
  initial_capital: number;
  final_value: number;
  equity_curve: { timestamp: string; nav: number }[];
  trades: { instrument_id: string; side: string; quantity: number; price: number; pnl: number }[];
  metrics: Record<string, number>;
  completed_at: string;
}

// ── Compare Strategies (shared types & constants — module scope so no
// components are created during render) ──
interface CompareResult {
  strategy: string;
  run_id: string;
  status: string;
  error?: string;
  metrics?: {
    total_return_pct?: number;
    sharpe_ratio?: number;
    win_rate?: number;
    max_drawdown_pct?: number;
    total_trades?: number;
    annualized_return_pct?: number;
  };
}

const ALL_RADAR_COLS = [
  { key: "total_return_pct" as const, label: "بازده", invert: false },
  { key: "annualized_return_pct" as const, label: "بازده سالانه", invert: false },
  { key: "sharpe_ratio" as const, label: "شارپ", invert: false },
  { key: "win_rate" as const, label: "Win Rate", invert: false },
  { key: "max_drawdown_pct" as const, label: "Max DD", invert: true },
];

const RADAR_COLORS_BT = [
  { fill: "rgba(0, 200, 255, 0.15)", stroke: "#00C8FF" },
  { fill: "rgba(0, 230, 118, 0.15)", stroke: "#00E676" },
  { fill: "rgba(255, 214, 0, 0.15)", stroke: "#FFD600" },
  { fill: "rgba(255, 82, 82, 0.15)", stroke: "#FF5252" },
  { fill: "rgba(224, 64, 251, 0.15)", stroke: "#E040FB" },
  { fill: "rgba(0, 230, 200, 0.15)", stroke: "#00E6C8" },
  { fill: "rgba(255, 168, 0, 0.15)", stroke: "#FFA800" },
  { fill: "rgba(100, 255, 218, 0.15)", stroke: "#64FFDA" },
];

function BacktestRadarChart({ results, selectedStrategies, onStrategyClick, enabledCols, hoveredStrategy, onHover, onClearSelection }: {
  results: CompareResult[];
  selectedStrategies: string[];
  onStrategyClick: (strategy: string, e?: React.MouseEvent) => void;
  enabledCols: string[];
  hoveredStrategy: string | null;
  onHover: (strategy: string | null) => void;
  onClearSelection?: () => void;
}) {
  const radarCols = ALL_RADAR_COLS.filter(c => enabledCols.includes(c.key));

  const validResults = results.filter(r => r.status !== "failed").slice(0, 8);
  if (validResults.length < 1) return null;
  if (radarCols.length < 3) {
    return <p className="text-xs text-surface-500 text-center py-4">حداقل ۳ متریک برای نمایش رادار انتخاب کنید</p>;
  }

  // Compute ranges for normalization
  const ranges: Record<string, { min: number; max: number }> = {};
  for (const col of radarCols) {
    const vals = validResults.map(r => r.metrics?.[col.key]).filter(v => v != null) as number[];
    if (vals.length === 0) continue;
    ranges[col.key] = { min: Math.min(...vals), max: Math.max(...vals) };
  }

  const normalize = (key: string, v: number | undefined): number => {
    if (v == null) return 0;
    const r = ranges[key];
    if (!r || r.max === r.min) return 0.5;
    const raw = (v - r.min) / (r.max - r.min);
    const col = radarCols.find(c => c.key === key);
    return col?.invert ? 1 - raw : raw;
  };

  const cx = 160, cy = 160, radius = 120;
  const angleStep = (2 * Math.PI) / radarCols.length;

  const polygons = validResults.map((r, mi) => {
    const pts = radarCols.map((col, i) => {
      const angle = -Math.PI / 2 + i * angleStep;
      const val = normalize(col.key, r.metrics?.[col.key]);
      const rad = val * radius;
      return `${cx + rad * Math.cos(angle)},${cy + rad * Math.sin(angle)}`;
    });
    return { points: pts.join(" "), color: RADAR_COLORS_BT[mi % RADAR_COLORS_BT.length], label: r.strategy };
  });

  return (
    <div className="mb-6">
      <p className="text-xs text-surface-400 font-bold mb-3 text-center">📡 نمودار راداری — مقایسه بصری استراتژی‌ها</p>
      <div className="flex flex-col items-center">
        <svg width={320} height={320} viewBox="0 0 320 320" className="max-w-full">
          {Array.from({ length: 5 }, (_, li) => {
            const r = ((li + 1) / 5) * radius;
            const pts = radarCols.map((_, i) => {
              const angle = -Math.PI / 2 + i * angleStep;
              return `${cx + r * Math.cos(angle)},${cy + r * Math.sin(angle)}`;
            });
            return <polygon key={li} points={pts.join(" ")} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth={1} />;
          })}
          {radarCols.map((col, i) => {
            const angle = -Math.PI / 2 + i * angleStep;
            const x2 = cx + radius * Math.cos(angle);
            const y2 = cy + radius * Math.sin(angle);
            const labelX = cx + (radius + 22) * Math.cos(angle);
            const labelY = cy + (radius + 22) * Math.sin(angle);
            const anchor = angle > -0.1 && angle < Math.PI - 0.1 ? "start" : angle > Math.PI - 0.1 ? "end" : "middle";
            return (
              <g key={col.key}>
                <line x1={cx} y1={cy} x2={x2} y2={y2} stroke="rgba(255,255,255,0.08)" strokeWidth={1} />
                <text x={labelX} y={labelY} textAnchor={anchor} dominantBaseline="middle"
                  fill="rgba(255,255,255,0.5)" fontSize={9} fontFamily="monospace">
                  {col.label}
                </text>
              </g>
            );
          })}
          {polygons.map((p, i) => {
            const isSelected = selectedStrategies.includes(p.label);
            const isHovered = hoveredStrategy === p.label;
            const hasSelection = selectedStrategies.length > 0;
            const isDimmed = hasSelection && !isSelected;
            const dimOpacity = isDimmed ? 0.15 : isHovered ? 1 : 0.85;
            const strokeColor = isSelected ? '#fff' : isHovered ? p.color.stroke : p.color.stroke;
            const strokeW = isSelected ? 3 : isHovered ? 2.5 : 2;
            return (
              <g key={i}
                onClick={(e) => onStrategyClick(p.label, e)}
                onMouseEnter={() => onHover(p.label)}
                onMouseLeave={() => onHover(null)}
                style={{ cursor: 'pointer' }}
              >
                <polygon
                  points={p.points}
                  fill={isSelected ? p.color.fill.replace('0.15', '0.35') : p.color.fill}
                  stroke={strokeColor}
                  strokeWidth={strokeW}
                  opacity={dimOpacity}
                  className="transition-all duration-200"
                />
                {p.points.split(" ").map((pt, pi) => {
                  const [x, y] = pt.split(",").map(Number);
                  return (
                    <circle key={pi} cx={x} cy={y}
                      r={isSelected ? 5 : isHovered ? 4 : 3}
                      fill={isSelected ? '#fff' : p.color.stroke}
                      opacity={isDimmed ? 0.2 : 0.95}
                      className="transition-all duration-200"
                    />
                  );
                })}
              </g>
            );
          })}
          <circle cx={cx} cy={cy} r={2} fill="rgba(255,255,255,0.2)" />
        </svg>
        <div className="flex flex-wrap gap-3 justify-center mt-2">
          {polygons.map((p, i) => {
            const isSelected = selectedStrategies.includes(p.label);
            return (
              <div key={i}
                onClick={(e) => onStrategyClick(p.label, e)}
                onMouseEnter={() => onHover(p.label)}
                onMouseLeave={() => onHover(null)}
                className={`flex items-center gap-1.5 cursor-pointer transition-all duration-200 px-1.5 py-0.5 rounded ${
                  isSelected ? 'bg-primary-600/20 ring-1 ring-primary-500/50' : 'hover:bg-surface-800/50'
                }`}
              >
                <div className="w-3 h-3 rounded-sm" style={{ backgroundColor: p.color.stroke }} />
                <span className={`text-[10px] ${isSelected ? 'text-surface-100 font-bold' : 'text-surface-400'}`}>
                  {p.label}
                </span>
              </div>
            );
          })}
          {selectedStrategies.length > 0 && onClearSelection && (
            <button onClick={onClearSelection}
              className="text-[9px] px-2 py-0.5 rounded bg-surface-700 hover:bg-surface-600 text-surface-400 hover:text-surface-200 transition-all">
              ✕ پاک کردن انتخاب
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

export default function BacktestPage() {
  const [selectedResult, setSelectedResult] = useState<BacktestResult | null>(null);
  const [symbolSearch, setSymbolSearch] = useState("");
  const [startDateJalali, setStartDateJalali] = useState(() => {
    const now = new Date();
    now.setFullYear(now.getFullYear() - 1);
    return toJalali(now.getFullYear(), now.getMonth() + 1, now.getDate());
  });
  const [endDateJalali, setEndDateJalali] = useState(() => {
    const now = new Date();
    return toJalali(now.getFullYear(), now.getMonth() + 1, now.getDate());
  });

  const [formData, setFormData] = useState({
    name: "بک‌تست جدید",
    symbols: ["فولاد"],
    strategyType: "moving_average_cross",
    strategyParams: {} as Record<string, unknown>,
    capital: 1000000000,
    commission_pct: 0.35,
    slippage_bps: 10,
    sizing_method: "fixed",
    sizing_value: 1000,
    stop_loss_pct: "" as string | number,
    take_profit_pct: "" as string | number,
    benchmark_symbol: "",
  });

  // Get default params for a strategy from the API data
  const getDefaultParams = (strategyName: string): Record<string, unknown> => {
    const selected = (strategies ?? []).find((s: Record<string, unknown>) => s.name === strategyName);
    if (!selected?.params || !Array.isArray(selected.params)) return {};
    const defaults: Record<string, unknown> = {};
    for (const p of selected.params as Array<{ name: string; default: unknown }>) {
      if (p.name !== "instrument_id") defaults[p.name] = p.default ?? "";
    }
    return defaults;
  };

  // When strategy changes, set default params from API
  const updateStrategyParams = (strategyName: string) => {
    const defaults = getDefaultParams(strategyName);
    setFormData(prev => ({ ...prev, strategyType: strategyName, strategyParams: defaults }));
  };

  // Reset strategy params to defaults
  const resetStrategyParams = () => {
    const defaults = getDefaultParams(formData.strategyType);
    setFormData(prev => ({ ...prev, strategyParams: defaults }));
  };

  // Load symbols from instruments table
  const { data: symbolsData } = useQuery({
    queryKey: ["backtest-symbols"],
    queryFn: async () => {
      try {
        const res = await apiGet<unknown>("/instruments?page=1&page_size=2000");
        const d = (res && typeof res === "object" && "data" in res) ? (res as { data?: { items?: { symbol: string; name: string }[] } }).data : null;
        return d?.items || [];
      } catch { return []; }
    },
  });

  const allSymbols: { symbol: string; name: string }[] = symbolsData || [];
  const filteredSymbols = symbolSearch
    ? allSymbols.filter(s => s.symbol.includes(symbolSearch) || s.name.includes(symbolSearch)).slice(0, 30)
    : allSymbols.slice(0, 30);

  const { data: strategies } = useQuery({
    queryKey: ["backtest-strategies"],
    queryFn: async () => {
      const res = await apiGet<unknown>('/backtests/strategies');
      const d = (res && typeof res === "object" && "data" in res) ? (res as { data?: { items?: Record<string, unknown>[] } }).data : null;
      return d?.items || [];
    },
  });

  // Load initial strategy params once strategies data arrives — useEffect to avoid setState during render
  const [prevStrategies, setPrevStrategies] = useState(strategies);
   
  useEffect(() => {
    if (strategies && strategies.length > 0 && strategies !== prevStrategies) {
      setPrevStrategies(strategies);
      setFormData(prev => ({ ...prev, strategyParams: getDefaultParams(prev.strategyType) }));
    }
  }, [strategies, prevStrategies]);

  const { data: runs, isLoading: loadingRuns } = useQuery({
    queryKey: ["backtest-runs"],
    queryFn: async () => {
      const res = await apiGet<unknown>('/backtests/runs');
      const d = (res && typeof res === "object" && "data" in res) ? (res as { data?: { items?: Record<string, unknown>[] } }).data : null;
      return d?.items || [];
    },
    refetchInterval: 5000,
  });

  const { data: result, isLoading: loadingResult } = useQuery({
    queryKey: ["backtest-result", selectedResult?.id],
    queryFn: async () => {
      if (!selectedResult?.id) return null;
      const res = await apiGet<unknown>(`/backtests/runs/${selectedResult.id}/result`);
      const d = (res && typeof res === "object" && "data" in res) ? (res as { data?: Record<string, unknown> }).data : null;
      return d;
    },
    enabled: !!selectedResult,
  });

  const queryClient = useQueryClient();
  const [showAllResults, setShowAllResults] = useState(false);

  const runMutation = useMutation({
    mutationFn: async (data: Record<string, unknown>) => {
      return await apiPost<Record<string, unknown>>('/backtests/run', data);
    },
    retry: false,
    onSuccess: () => {
      toast.success("بک‌تست با موفقیت شروع شد");
      queryClient.invalidateQueries({ queryKey: ["backtest-runs"] });
    },
    onError: (err: Error) => toast.error(err.message),
  });

  interface RunAllResult {
    symbol: string;
    run_id: string;
    status: string;
    metrics?: {
      total_return_pct?: number;
      sharpe_ratio?: number;
      win_rate?: number;
      max_drawdown_pct?: number;
      total_trades?: number;
      annualized_return_pct?: number;
    };
  }

  const [allResults, setAllResults] = useState<RunAllResult[]>([]);

  const runAllMutation = useMutation({
    mutationFn: async (data: Record<string, unknown>) => {
      return await apiPost<Record<string, unknown>>('/backtests/run-all', data);
    },
    retry: false,
    onSuccess: (res: unknown) => {
      const r = res as { data?: { total_symbols?: number; successful?: number; failed?: number; results?: RunAllResult[] } } | undefined;
      const total = r?.data?.total_symbols ?? 0;
      const ok = r?.data?.successful ?? 0;
      setAllResults(r?.data?.results ?? []);
      toast.success("بک‌تست روی " + ok + " از " + total + " نماد با موفقیت انجام شد");
      queryClient.invalidateQueries({ queryKey: ["backtest-runs"] });
      setShowAllResults(true);
    },
    onError: (err: Error) => toast.error(err.message),
  });

  // ── Compare Strategies ──
  const [showCompare, setShowCompare] = useState(false);
  const [compareResults, setCompareResults] = useState<CompareResult[]>([]);
  const [compareBest, setCompareBest] = useState<string | null>(null);
  const [compareWorst, setCompareWorst] = useState<string | null>(null);
  const [compareSymbol, setCompareSymbol] = useState("فولاد");
  const [compareSnapshotSymbol, setCompareSnapshotSymbol] = useState("فولاد");
  const [compareSnapshotDates, setCompareSnapshotDates] = useState({ start: "", end: "" });
  const [compareSortKey, setCompareSortKey] = useState<string | null>("total_return_pct");
  const [compareSortDir, setCompareSortDir] = useState<"asc" | "desc">("desc");
  const [highlightedStrategies, setHighlightedStrategies] = useState<string[]>([]);
  const [hoveredStrategy, setHoveredStrategy] = useState<string | null>(null);
  const defaultMetrics = ALL_RADAR_COLS.map(c => c.key);
  const getSavedMetrics = (): string[] => {
    try {
      const saved = localStorage.getItem("bt-radar-metrics");
      if (saved) {
        const parsed = JSON.parse(saved) as string[];
        // Only keep valid keys
        return parsed.filter(k => (defaultMetrics as string[]).includes(k));
      }
    } catch {}
    return defaultMetrics;
  };
  // SSR-safe initial state: `localStorage` doesn't exist during the server
  // render, so seeding state from getSavedMetrics() would produce different
  // HTML than the client → hydration mismatch. Start from deterministic
  // defaults and adopt the saved selection after mount.
  const [enabledRadarMetrics, setEnabledRadarMetrics] = useState<string[]>(
    defaultMetrics
  );
  useEffect(() => {
    setEnabledRadarMetrics(getSavedMetrics());
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  // Persist metric selection to localStorage
  useEffect(() => {
    try {
      localStorage.setItem("bt-radar-metrics", JSON.stringify(enabledRadarMetrics));
    } catch {}
  }, [enabledRadarMetrics]);

  const toggleCompareSort = (key: string) => {
    setCompareSortDir(prev => compareSortKey === key ? (prev === "asc" ? "desc" : "asc") : "desc");
    setCompareSortKey(key);
  };

  const sortedCompareResults = [...compareResults].sort((a, b) => {
    if (!compareSortKey || compareSortKey === "strategy") {
      const aVal = compareSortKey ? a.strategy : "";
      const bVal = compareSortKey ? b.strategy : "";
      const cmp = aVal.localeCompare(bVal, "fa");
      return compareSortDir === "asc" ? cmp : -cmp;
    }
    const aFailed = a.status === "failed";
    const bFailed = b.status === "failed";
    if (aFailed !== bFailed) return aFailed ? 1 : -1;
    const aVal = a.metrics?.[compareSortKey as keyof typeof a.metrics] ?? -Infinity;
    const bVal = b.metrics?.[compareSortKey as keyof typeof b.metrics] ?? -Infinity;
    return compareSortDir === "asc" ? (aVal as number) - (bVal as number) : (bVal as number) - (aVal as number);
  });

  // Track last clicked strategy for Shift+Click range selection
  const lastClickedRef = useRef<string | null>(null);

  // Multi-select click handler: Ctrl/Cmd toggles, Shift ranges, plain replaces
  const handleStrategyClick = useCallback((strategy: string, e?: React.MouseEvent) => {
    if (e?.shiftKey) {
      // Shift+Click: range select from last clicked to this one
      const last = lastClickedRef.current;
      if (!last || last === strategy) {
        // No anchor or same strategy: treat as toggle
        setHighlightedStrategies(prev =>
          prev.includes(strategy)
            ? prev.filter(s => s !== strategy)
            : [...prev, strategy]
        );
      } else {
        // Find positions in the sorted list the user sees
        const names = sortedCompareResults.map(r => r.strategy);
        const fromIdx = names.indexOf(last);
        const toIdx = names.indexOf(strategy);
        if (fromIdx !== -1 && toIdx !== -1) {
          const start = Math.min(fromIdx, toIdx);
          const end = Math.max(fromIdx, toIdx);
          const range = names.slice(start, end + 1);
          setHighlightedStrategies(prev => {
            const merged = new Set([...prev, ...range]);
            return Array.from(merged);
          });
        }
      }
      lastClickedRef.current = strategy;
    } else if (e?.ctrlKey || e?.metaKey) {
      // Toggle: Ctrl/Cmd+Click
      setHighlightedStrategies(prev =>
        prev.includes(strategy)
          ? prev.filter(s => s !== strategy)
          : [...prev, strategy]
      );
      lastClickedRef.current = strategy;
    } else {
      // Plain click: select only this one, or deselect if already the only one
      setHighlightedStrategies(prev => {
        if (prev.length === 1 && prev[0] === strategy) return [];
        return [strategy];
      });
      lastClickedRef.current = strategy;
    }
  }, [sortedCompareResults, setHighlightedStrategies]);

  // Column definitions for the compare table
  const compareColumns = [
    { key: "strategy", label: "استراتژی", numeric: false },
    { key: "total_return_pct", label: "بازده کل", numeric: true },
    { key: "annualized_return_pct", label: "بازده سالانه", numeric: true },
    { key: "sharpe_ratio", label: "شارپ", numeric: true },
    { key: "win_rate", label: "Win Rate", numeric: true },
    { key: "max_drawdown_pct", label: "Max DD", numeric: true },
    { key: "total_trades", label: "معاملات", numeric: true },
  ];

  const getSortArrow = (key: string) => {
    if (compareSortKey !== key) return " ⇅";
    return compareSortDir === "asc" ? " ▲" : " ▼";
  };

  const compareMutation = useMutation({
    mutationFn: async (data: Record<string, unknown>) => {
      return await apiPost<Record<string, unknown>>('/backtests/compare', data);
    },
    retry: false,
    onSuccess: (res: unknown) => {
      const r = res as { data?: { results?: CompareResult[]; best?: string; worst?: string; successful?: number; total_strategies?: number } } | undefined;
      setCompareResults(r?.data?.results ?? []);
      setCompareBest(r?.data?.best ?? null);
      setCompareWorst(r?.data?.worst ?? null);
      setCompareSnapshotSymbol(compareSymbol);
      setCompareSnapshotDates({
        start: jalaliToGregorian(startDateJalali) || "",
        end: jalaliToGregorian(endDateJalali) || "",
      });
      toast.success("مقایسه " + (r?.data?.successful ?? 0) + " استراتژی انجام شد");
      setShowCompare(true);
      // Invalidate history so it refreshes
      queryClient.invalidateQueries({ queryKey: ["compare-history"] });
    },
    onError: (err: Error) => toast.error(err.message),
  });

  // ── Compare History ──
  const { data: compareHistory } = useQuery({
    queryKey: ["compare-history"],
    queryFn: async () => {
      const res = await apiGet<unknown>('/backtests/compare/history?page_size=20');
      const d = (res && typeof res === "object" && "data" in res) ? (res as { data?: { items?: CompareHistoryItem[] } }).data : null;
      return d?.items || [];
    },
  });

  const saveCompareMutation = useMutation({
    mutationFn: async () => {
      const completed = compareResults.filter(r => r.status !== "failed" && r.metrics?.total_return_pct != null);
      const returns = completed.map(r => r.metrics?.total_return_pct ?? 0);
      const avgReturn = returns.length > 0 ? returns.reduce((a, b) => a + b, 0) / returns.length : 0;
      const bestReturn = completed.length > 0 ? Math.max(...returns) : 0;
      const worstReturn = completed.length > 0 ? Math.min(...returns) : 0;
      const startDate = compareSnapshotDates.start || jalaliToGregorian(startDateJalali) || "";
      const endDate = compareSnapshotDates.end || jalaliToGregorian(endDateJalali) || "";
      return await apiPost('/backtests/compare/save', {
        symbol: compareSnapshotSymbol,
        total_strategies: compareResults.length,
        successful: completed.length,
        failed: compareResults.length - completed.length,
        best: compareBest,
        worst: compareWorst,
        best_return_pct: bestReturn,
        worst_return_pct: worstReturn,
        avg_return_pct: avgReturn,
        start_date: startDate,
        end_date: endDate,
        capital: formData.capital,
        results: compareResults,
      });
    },
    onSuccess: () => {
      toast.success("نتیجه مقایسه ذخیره شد");
      queryClient.invalidateQueries({ queryKey: ["compare-history"] });
    },
    onError: (err: Error) => toast.error(err.message),
  });

  const loadCompareHistory = async (item: CompareHistoryItem) => {
    try {
      const res = await apiGet<{ success: boolean; data?: CompareHistoryDetail }>(`/backtests/compare/history/${item.id}`);
      const detail = (res as { data?: CompareHistoryDetail })?.data;
      if (detail?.results) {
        setCompareResults(detail.results as CompareResult[]);
        setCompareBest(detail.best ?? null);
        setCompareWorst(detail.worst ?? null);
        setCompareSnapshotSymbol(detail.symbol);
        setCompareSymbol(detail.symbol);
        setShowCompare(true);
        toast.success("نتایج مقایسه " + detail.symbol + " بارگذاری شد");
      }
    } catch {
      toast.error("خطا در بارگذاری تاریخچه");
    }
  };

  interface CompareHistoryDetail {
    id: string;
    symbol: string;
    results: CompareResult[];
    best: string | null;
    worst: string | null;
  }

  function formatRials(v: number) {
    return new Intl.NumberFormat("fa-IR").format(Math.round(v));
  }

  // ── Generate HTML Report for Compare Results ──
  const generateCompareReportHtml = (): string => {
    const reportSymbol = compareSnapshotSymbol;
    const completed = compareResults.filter(r => r.status !== "failed" && r.metrics?.total_return_pct != null);
    const failed = compareResults.filter(r => r.status === "failed");
    const sortedByReturn = [...completed].sort((a, b) => (b.metrics?.total_return_pct ?? 0) - (a.metrics?.total_return_pct ?? 0));

    const barMax = Math.max(...sortedByReturn.map(r => Math.abs(r.metrics?.total_return_pct ?? 0)), 1);
    const barChartBars = sortedByReturn.map((r, i) => {
      const val = r.metrics?.total_return_pct ?? 0;
      const pct = Math.abs(val) / barMax * 100;
      const color = val >= 0 ? "#22c55e" : "#ef4444";
      const isBest = r.strategy === compareBest;
      const isWorst = r.strategy === compareWorst;
      const bg = isBest ? "rgba(34,197,94,0.08)" : isWorst ? "rgba(239,68,68,0.08)" : i % 2 === 0 ? "rgba(255,255,255,0.02)" : "transparent";
      return `
        <tr style="background:${bg}">
          <td style="padding:8px 12px;font-weight:${isBest||isWorst?'700':'400'};color:${isBest?'#22c55e':isWorst?'#ef4444':'#e2e8f0'}">
            ${isBest ? '🏆 ' : isWorst ? '🫤 ' : ''}${r.strategy}
          </td>
          <td style="padding:8px 12px;text-align:right;direction:ltr">
            <div style="display:flex;align-items:center;gap:8px">
              <div style="flex:1;height:20px;background:rgba(255,255,255,0.06);border-radius:4px;overflow:hidden">
                <div style="height:100%;width:${pct}%;background:${color};border-radius:4px;transition:width 0.5s"></div>
              </div>
              <span style="font-family:monospace;color:${color};font-weight:700;min-width:70px;text-align:right">${val >= 0 ? '+' : ''}${val.toFixed(1)}%</span>
            </div>
          </td>
          <td style="padding:8px 12px;font-family:monospace;color:${(r.metrics?.sharpe_ratio ?? 0) >= 1 ? '#22c55e' : (r.metrics?.sharpe_ratio ?? 0) >= 0 ? '#eab308' : '#ef4444'};text-align:center">
            ${(r.metrics?.sharpe_ratio ?? 0).toFixed(2)}
          </td>
          <td style="padding:8px 12px;font-family:monospace;color:${(r.metrics?.win_rate ?? 0) >= 50 ? '#22c55e' : '#ef4444'};text-align:center">
            ${(r.metrics?.win_rate ?? 0).toFixed(1)}%
          </td>
          <td style="padding:8px 12px;font-family:monospace;color:#94a3b8;text-align:center">
            ${(r.metrics?.max_drawdown_pct ?? 0).toFixed(1)}%
          </td>
          <td style="padding:8px 12px;font-family:monospace;color:#94a3b8;text-align:center">
            ${r.metrics?.total_trades ?? 0}
          </td>
        </tr>`;
    }).join("\n");

    const failedRows = failed.map(r => `
      <tr style="opacity:0.5">
        <td style="padding:8px 12px;color:#94a3b8">${r.strategy}</td>
        <td colspan="5" style="padding:8px 12px;color:#ef4444;text-align:center">❌ ${r.error || "ناموفق"}</td>
      </tr>`
    ).join("\n");

    const now = new Date();
    const dateStr = now.toLocaleDateString("fa-IR", { year: "numeric", month: "long", day: "numeric" });

    return `<!DOCTYPE html>
<html dir="rtl" lang="fa">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>📊 گزارش مقایسه استراتژی‌ها — ${reportSymbol}</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;700;900&display=swap');
  *{margin:0;padding:0;box-sizing:border-box}
  body{font-family:'Vazirmatn',system-ui,sans-serif;background:#0f172a;color:#e2e8f0;padding:40px;line-height:1.6}
  @media print{body{padding:20px;background:#fff;color:#1e293b}.card,.table-wrap{background:#fff!important;border-color:#e2e8f0!important;box-shadow:none!important}th{color:#64748b!important}td{color:#1e293b!important}.badge{background:#f1f5f9!important;color:#1e293b!important}.metric{color:#1e293b!important}h1,h2{color:#0f172a!important}.bar-bg{background:#f1f5f9!important}.header-row{background:#f8fafc!important}.no-print{display:none!important}}
  h1{font-size:24px;font-weight:900;margin-bottom:4px;background:linear-gradient(135deg,#818cf8,#a78bfa);-webkit-background-clip:text;-webkit-text-fill-color:transparent}
  .subtitle{color:#64748b;font-size:13px;margin-bottom:24px}
  .header-row{display:flex;align-items:center;justify-content:space-between;margin-bottom:28px;background:rgba(255,255,255,0.03);border-radius:12px;padding:16px 20px;border:1px solid rgba(255,255,255,0.06)}
  .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-bottom:28px}
  .card{background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);border-radius:12px;padding:16px;text-align:center}
  .card .label{font-size:11px;color:#64748b;margin-bottom:4px}
  .card .value{font-size:22px;font-weight:700}
  .card .value.green{color:#22c55e}.card .value.red{color:#ef4444}.card .value.amber{color:#eab308}
  .table-wrap{background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.06);border-radius:12px;overflow:hidden;margin-bottom:28px}
  table{width:100%;border-collapse:collapse;font-size:13px}
  th{padding:10px 12px;text-align:center;color:#64748b;font-weight:700;font-size:11px;text-transform:uppercase;border-bottom:1px solid rgba(255,255,255,0.06)}
  th:first-child{text-align:right}
  td{padding:8px 12px;border-bottom:1px solid rgba(255,255,255,0.03)}
  .best-badge{display:inline-block;background:rgba(34,197,94,0.15);color:#22c55e;padding:2px 10px;border-radius:20px;font-size:11px;font-weight:700}
  .worst-badge{display:inline-block;background:rgba(239,68,68,0.15);color:#ef4444;padding:2px 10px;border-radius:20px;font-size:11px;font-weight:700}
  .footer{text-align:center;color:#475569;font-size:11px;margin-top:32px;padding-top:16px;border-top:1px solid rgba(255,255,255,0.06)}
  @page{size:A4;margin:15mm}
</style>
</head>
<body>
  <div class="header-row">
    <div>
      <h1>📊 گزارش مقایسه استراتژی‌ها</h1>
      <p class="subtitle">نماد: ${compareSymbol} • تاریخ: ${dateStr} • ${completed.length} استراتژی</p>
    </div>
    <div style="display:flex;gap:8px">
      ${compareBest ? "<span class=\"best-badge\">🏆 بهترین: " + compareBest + "</span>" : ''}
      ${compareWorst ? "<span class=\"worst-badge\">🫤 بدترین: " + compareWorst + "</span>" : ''}
    </div>
  </div>

  <div class="grid">
    <div class="card">
      <div class="label">کل استراتژی‌ها</div>
      <div class="value" style="color:#e2e8f0">${compareResults.length}</div>
    </div>
    <div class="card">
      <div class="label">موفق</div>
      <div class="value green">${completed.length}</div>
    </div>
    <div class="card">
      <div class="label">ناموفق</div>
      <div class="value red">${failed.length}</div>
    </div>
    <div class="card">
      <div class="label">بهترین بازده</div>
      <div class="value ${(sortedByReturn[0]?.metrics?.total_return_pct ?? 0) >= 0 ? 'green' : 'red'}">
        ${sortedByReturn.length > 0 ? `${sortedByReturn[0].metrics?.total_return_pct?.toFixed(1)}%` : '—'}
      </div>
    </div>
    <div class="card">
      <div class="label">بدترین بازده</div>
      <div class="value ${(sortedByReturn[sortedByReturn.length-1]?.metrics?.total_return_pct ?? 0) >= 0 ? 'green' : 'red'}">
        ${sortedByReturn.length > 0 ? `${sortedByReturn[sortedByReturn.length-1].metrics?.total_return_pct?.toFixed(1)}%` : '—'}
      </div>
    </div>
    <div class="card">
      <div class="label">میانگین بازده</div>
      <div class="value" style="color:#a78bfa">
        ${completed.length > 0 ? `${(completed.reduce((s,r) => s + (r.metrics?.total_return_pct ?? 0), 0) / completed.length).toFixed(1)}%` : '—'}
      </div>
    </div>
  </div>

  <div class="table-wrap">
    <table>
      <thead>
        <tr>
          <th style="text-align:right">استراتژی</th>
          <th style="text-align:right">بازده کل</th>
          <th>شارپ</th>
          <th>Win Rate</th>
          <th>Max DD</th>
          <th>معاملات</th>
        </tr>
      </thead>
      <tbody>
        ${barChartBars}
        ${failedRows}
      </tbody>
    </table>
  </div>

  <div style="margin-bottom:28px">
    <h2 style="font-size:16px;font-weight:700;margin-bottom:12px;color:#e2e8f0">📈 نمودار مقایسه بازده کل</h2>
    <div style="background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.06);border-radius:12px;padding:24px;direction:ltr">
      <svg viewBox="0 0 ${Math.max(700, sortedByReturn.length * 80)} ${sortedByReturn.length * 50 + 60}" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto">
        ${sortedByReturn.map((r, i) => {
          const val = r.metrics?.total_return_pct ?? 0;
          const absVal = Math.abs(val);
          const barMaxVal = Math.max(...sortedByReturn.map(x => Math.abs(x.metrics?.total_return_pct ?? 0)), 1);
          const barPct = (absVal / barMaxVal) * 100;
          const barColor = val >= 0 ? "#22c55e" : "#ef4444";
          const y = i * 50 + 10;
          const barHeight = 30;
          const zeroX = 100;
          const maxBarWidth = 520;
          const barWidth = (barPct / 100) * maxBarWidth;
          const isBest = r.strategy === compareBest;
          const isWorst = r.strategy === compareWorst;
          return `
            <g>
              ${isBest ? `<rect x="${zeroX - maxBarWidth - 10}" y="${y - 4}" width="${maxBarWidth + 140}" height="${barHeight + 8}" rx="6" fill="rgba(34,197,94,0.06)"/>` : ''}
              ${isWorst ? `<rect x="${zeroX - maxBarWidth - 10}" y="${y - 4}" width="${maxBarWidth + 140}" height="${barHeight + 8}" rx="6" fill="rgba(239,68,68,0.06)"/>` : ''}
              <text x="${Math.min(zeroX - 4, zeroX - 8)}" y="${y + barHeight / 2 + 4}" text-anchor="end" fill="#94a3b8" font-size="11" font-family="Vazirmatn">${r.strategy}</text>
              ${val >= 0
                ? `<rect x="${zeroX}" y="${y}" width="${barWidth}" height="${barHeight}" rx="4" fill="${barColor}" opacity="0.85"/>
                   <text x="${zeroX + barWidth + 6}" y="${y + barHeight / 2 + 4}" fill="${barColor}" font-size="11" font-family="monospace" font-weight="700">+${val.toFixed(1)}%</text>`
                : `<rect x="${zeroX - barWidth}" y="${y}" width="${barWidth}" height="${barHeight}" rx="4" fill="${barColor}" opacity="0.85"/>
                   <text x="${zeroX - barWidth - 6}" y="${y + barHeight / 2 + 4}" text-anchor="end" fill="${barColor}" font-size="11" font-family="monospace" font-weight="700">${val.toFixed(1)}%</text>`
              }
              ${i === 0 ? `<line x1="${zeroX}" y1="0" x2="${zeroX}" y2="${sortedByReturn.length * 50}" stroke="rgba(255,255,255,0.2)" stroke-width="1"/>
                          <text x="${zeroX}" y="-6" text-anchor="middle" fill="#64748b" font-size="10">صفر</text>` : ''}
            </g>`;
        }).join("\n")}
      </svg>
    </div>
  </div>

  <div class="footer">
    <p>تولید شده توسط سامانه تحلیل بازار • ${dateStr}</p>
    <p style="margin-top:4px;font-size:10px;color:#334155">این گزارش به صورت خودکار از نتایج مقایسه استراتژی‌ها تولید شده است</p>
  </div>

  <div class="no-print" style="text-align:center;margin-top:24px">
    <button onclick="window.print()" style="background:#818cf8;color:#fff;border:none;padding:10px 24px;border-radius:8px;font-size:14px;font-weight:700;cursor:pointer;font-family:Vazirmatn">
      🖨️ ذخیره به صورت PDF (چاپ)
    </button>
  </div>
</body>
</html>`;
  };

  const downloadCompareReport = () => {
    const html = generateCompareReportHtml();
    const blob = new Blob([html], { type: "text/html;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `compare-report-${compareSnapshotSymbol}-${Date.now()}.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <AppLayout
      title={
        <span className="flex items-center gap-2.5">
          <span className="grid size-10 place-items-center rounded-xl bg-primary-600/12 text-primary-700 dark:text-brand-300">
            <FlaskConical className="size-5" aria-hidden />
          </span>
          بک‌تست استراتژی
        </span>
      }
      subtitle="تست استراتژی روی تمام نمادها با داده‌های واقعی تاریخی"
    >
      {/* Quick Links to Advanced Tools */}
      <div className="mb-5 flex flex-wrap gap-2">
        <a href="/backtest/engine" className="flex items-center gap-1.5 rounded-xl bg-primary-600/12 px-3 py-1.5 text-xs font-bold text-primary-700 transition-colors hover:bg-primary-600/20 dark:text-brand-300">
          <Cpu className="size-3.5" aria-hidden /> موتور کشف استراتژی
        </a>
        <a href="/backtest/generate" className="flex items-center gap-1.5 rounded-xl bg-soft px-3 py-1.5 text-xs font-bold text-ink-2 transition-colors hover:bg-soft/80 hover:text-ink">
          <Rocket className="size-3.5" aria-hidden /> تولید خودکار استراتژی
        </a>
        <a href="/backtest/walk-forward" className="flex items-center gap-1.5 rounded-xl bg-warn/12 px-3 py-1.5 text-xs font-bold text-warn transition-colors hover:bg-warn/20">
          <TrendingUp className="size-3.5" aria-hidden /> Walk-Forward
        </a>
        <a href="/backtest/monte-carlo" className="flex items-center gap-1.5 rounded-xl bg-up/12 px-3 py-1.5 text-xs font-bold text-up transition-colors hover:bg-up/20">
          <Dices className="size-3.5" aria-hidden /> Monte Carlo
        </a>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1 glass-card p-5">
          <h2 className="text-base font-bold text-surface-200 mb-4">تنظیمات بک‌تست</h2>

          <label className="block mb-2 text-sm text-surface-400 font-bold">نام</label>
          <input className="w-full bg-surface-800 border border-surface-700 rounded-lg px-3 py-2 mb-3 text-sm text-surface-200 focus:outline-none focus:border-primary-500"
            value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />

          <label className="block mb-2 text-sm text-surface-400 font-bold">نمادها ({formData.symbols.length} انتخاب شده)</label>
          <input type="text" value={symbolSearch} onChange={e => setSymbolSearch(e.target.value)}
            placeholder="جستجوی نماد..." className="w-full bg-surface-800 border border-surface-700 rounded-lg px-3 py-2 mb-2 text-sm text-surface-200 focus:outline-none focus:border-primary-500" />
          <div className="flex flex-wrap gap-1 mb-3 max-h-32 overflow-y-auto">
            {filteredSymbols.map(s => (
              <button key={s.symbol} onClick={() => setFormData(prev => ({...prev, symbols: prev.symbols.includes(s.symbol) ? prev.symbols.filter(x => x !== s.symbol) : [...prev.symbols, s.symbol]}))}
                className={`px-2 py-1 text-xs rounded-full border font-bold ${formData.symbols.includes(s.symbol) ? "bg-primary-600 text-white border-primary-600" : "bg-surface-800 text-surface-300 border-surface-700 hover:border-surface-500"}`}>
                {s.symbol}
              </button>
            ))}
          </div>

          <label className="block mb-2 text-sm text-surface-400 font-bold">استراتژی</label>
          <select className="w-full bg-surface-800 border border-surface-700 rounded-lg px-3 py-2 text-sm text-surface-200 focus:outline-none focus:border-primary-500"
            value={formData.strategyType} onChange={e => updateStrategyParams(e.target.value)}>
            {strategies?.map((s: Record<string, unknown>, i: number) => (
              <option key={`${s.name}-${i}`} value={String(s.name ?? "")}>{String(s.name ?? "")}</option>
            ))}
          </select>
          {/* Strategy description tooltip */}
          {(() => {
            const selected = (strategies ?? []).find((s: Record<string, unknown>) => s.name === formData.strategyType);
            const desc = selected?.description as string | undefined;
            if (!desc) return null;
            return (
              <div className="mb-3 px-3 py-2 bg-surface-800/30 border border-surface-700/30 rounded-lg text-[11px] text-surface-400 leading-relaxed">
                📖 {desc}
              </div>
            );
          })()}

          {/* Strategy Params */}
          {(() => {
            const selected = (strategies ?? []).find((s: Record<string, unknown>) => s.name === formData.strategyType);
            const params = (selected?.params ?? []) as Array<{ name: string; type: string; default: unknown }>;
            const displayParams = params.filter(p => p.name !== "instrument_id");
            if (displayParams.length === 0) return null;
            return (
              <div className="mb-3 p-3 bg-surface-800/40 rounded-lg border border-surface-700/50">
                <div className="flex items-center justify-between mb-2">
                  <label className="text-xs text-surface-400 font-bold">⚙️ پارامترهای استراتژی</label>
                  <button onClick={resetStrategyParams}
                    className="text-[10px] px-2 py-0.5 rounded bg-surface-700 hover:bg-surface-600 text-surface-400 hover:text-surface-200 transition-all">
                    ↩ ریست
                  </button>
                </div>
                <div className="grid grid-cols-2 gap-2">
                  {displayParams.map((p, pi) => (
                    <div key={`${p.name}-${pi}`}>
                      <label className="block text-[10px] text-surface-500 mb-0.5">{p.name}</label>
                      <input type={p.type === "number" ? "number" : "text"} step={p.type === "number" ? "any" : undefined}
                        value={String(formData.strategyParams[p.name] ?? p.default ?? "")}
                        onChange={e => setFormData(prev => ({
                          ...prev,
                          strategyParams: { ...prev.strategyParams, [p.name]: p.type === "number" ? Number(e.target.value) : e.target.value },
                        }))}
                        className="w-full bg-surface-900 border border-surface-700 rounded px-2 py-1.5 text-xs text-surface-200 outline-none focus:border-primary-500" />
                    </div>
                  ))}
                </div>
              </div>
            );
          })()}

          <div className="grid grid-cols-2 gap-2 mb-3">
            <div>
              <label className="block mb-1 text-sm text-surface-400 font-bold">از تاریخ (شمسی)</label>
              <input type="text" dir="ltr" className="w-full bg-surface-800 border border-surface-700 rounded-lg px-3 py-2 text-sm text-surface-200 focus:outline-none focus:border-primary-500"
                value={startDateJalali} onChange={e => setStartDateJalali(e.target.value)} placeholder="1403/01/01" />
              <div className="text-[10px] text-surface-600 mt-1">{gregorianToJalali(jalaliToGregorian(startDateJalali))}</div>
            </div>
            <div>
              <label className="block mb-1 text-sm text-surface-400 font-bold">تا تاریخ (شمسی)</label>
              <input type="text" dir="ltr" className="w-full bg-surface-800 border border-surface-700 rounded-lg px-3 py-2 text-sm text-surface-200 focus:outline-none focus:border-primary-500"
                value={endDateJalali} onChange={e => setEndDateJalali(e.target.value)} placeholder="1404/04/01" />
              <div className="text-[10px] text-surface-600 mt-1">{gregorianToJalali(jalaliToGregorian(endDateJalali))}</div>
            </div>
          </div>

          {/* Quick Time Period Selector */}
          <div className="mb-3">
            <label className="block mb-1 text-xs text-surface-500 font-bold">بازه زمانی سریع</label>
            <div className="flex flex-wrap gap-1">
              {[
                { label: "۱ هفته", days: 7 },
                { label: "۱ ماه", days: 30 },
                { label: "۳ ماه", days: 90 },
                { label: "۶ ماه", days: 180 },
                { label: "۱ سال", days: 365 },
                { label: "۲ سال", days: 730 },
                { label: "۳ سال", days: 1095 },
              ].map(p => (
                <button key={p.days} onClick={() => {
                  const end = new Date();
                  const start = new Date();
                  start.setDate(start.getDate() - p.days);
                  setStartDateJalali(toJalali(start.getFullYear(), start.getMonth() + 1, start.getDate()));
                  setEndDateJalali(toJalali(end.getFullYear(), end.getMonth() + 1, end.getDate()));
                }} className="text-[10px] px-2 py-1 bg-surface-800 border border-surface-700 rounded text-surface-400 hover:text-surface-200 hover:border-surface-500 transition-colors">
                  {p.label}
                </button>
              ))}
            </div>
          </div>

          <div className="mb-3">
            <label className="block mb-2 text-sm text-surface-400 font-bold">سرمایه اولیه (ریال)</label>
            <input type="number" className="w-full bg-surface-800 border border-surface-700 rounded-lg px-3 py-2 text-sm text-surface-200 focus:outline-none focus:border-primary-500"
              value={formData.capital} onChange={e => setFormData({...formData, capital: Number(e.target.value)})} />
          </div>

          {/* Advanced Options */}
          <details className="mb-3 group">
            <summary className="text-xs text-surface-400 font-bold cursor-pointer hover:text-surface-200 transition-colors select-none">
              ⚙️ تنظیمات پیشرفته
            </summary>
            <div className="mt-2 p-3 bg-surface-800/40 rounded-lg border border-surface-700/50 space-y-2">
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="block text-[10px] text-surface-500 mb-0.5">کارمزد (%)</label>
                  <input type="number" step="0.01" className="w-full bg-surface-900 border border-surface-700 rounded px-2 py-1.5 text-xs text-surface-200 outline-none focus:border-primary-500"
                    value={formData.commission_pct} onChange={e => setFormData({...formData, commission_pct: Number(e.target.value)})} />
                </div>
                <div>
                  <label className="block text-[10px] text-surface-500 mb-0.5">Slippage (bps)</label>
                  <input type="number" step="0.5" className="w-full bg-surface-900 border border-surface-700 rounded px-2 py-1.5 text-xs text-surface-200 outline-none focus:border-primary-500"
                    value={formData.slippage_bps} onChange={e => setFormData({...formData, slippage_bps: Number(e.target.value)})} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3 mt-3">
                <div>
                  <label className="block text-[10px] text-surface-500 mb-0.5">روش محاسبه تعداد</label>
                  <select className="w-full bg-surface-900 border border-surface-700 rounded px-2 py-1.5 text-xs text-surface-200 outline-none focus:border-primary-500"
                    value={formData.sizing_method} onChange={e => setFormData({...formData, sizing_method: e.target.value})}>
                    <option value="fixed">ثابت (Fixed)</option>
                    <option value="percent">درصد سرمایه (Percent)</option>
                    <option value="kelly">کلی (Kelly)</option>
                    <option value="risk_based">بر اساس ریسک (Risk)</option>
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] text-surface-500 mb-0.5">مقدار محاسبه</label>
                  <input type="number" step="1" className="w-full bg-surface-900 border border-surface-700 rounded px-2 py-1.5 text-xs text-surface-200 outline-none focus:border-primary-500"
                    value={formData.sizing_value} onChange={e => setFormData({...formData, sizing_value: Number(e.target.value)})} />
                </div>
                <div>
                  <label className="block text-[10px] text-surface-500 mb-0.5">حد ضرر (٪)</label>
                  <input type="number" step="0.5" placeholder="اختیاری" className="w-full bg-surface-900 border border-surface-700 rounded px-2 py-1.5 text-xs text-surface-200 outline-none focus:border-primary-500"
                    value={formData.stop_loss_pct} onChange={e => setFormData({...formData, stop_loss_pct: e.target.value})} />
                </div>
                <div>
                  <label className="block text-[10px] text-surface-500 mb-0.5">حد سود (٪)</label>
                  <input type="number" step="0.5" placeholder="اختیاری" className="w-full bg-surface-900 border border-surface-700 rounded px-2 py-1.5 text-xs text-surface-200 outline-none focus:border-primary-500"
                    value={formData.take_profit_pct} onChange={e => setFormData({...formData, take_profit_pct: e.target.value})} />
                </div>
              </div>
              <div className="mt-3">
                <label className="block text-[10px] text-surface-500 mb-0.5">نماد مرجع (Benchmark)</label>
                <input type="text" placeholder="مثلاً شاخص كل" className="w-full bg-surface-900 border border-surface-700 rounded px-2 py-1.5 text-xs text-surface-200 outline-none focus:border-primary-500"
                  value={formData.benchmark_symbol} onChange={e => setFormData({...formData, benchmark_symbol: e.target.value})} />
              </div>
            </div>
          </details>

          <div className="flex gap-2">
            <button onClick={() => runMutation.mutate({
              name: formData.name,
              symbols: formData.symbols,
              strategy_type: formData.strategyType,
              strategy_params: formData.strategyParams,
              commission_pct: formData.commission_pct / 100,
              slippage_bps: formData.slippage_bps,
              sizing_method: formData.sizing_method,
              sizing_value: formData.sizing_value,
              stop_loss_pct: formData.stop_loss_pct !== "" ? Number(formData.stop_loss_pct) : null,
              take_profit_pct: formData.take_profit_pct !== "" ? Number(formData.take_profit_pct) : null,
              benchmark_symbol: formData.benchmark_symbol || null,
              start_date: jalaliToGregorian(startDateJalali) || undefined,
              end_date: jalaliToGregorian(endDateJalali) || undefined,
              initial_capital: formData.capital,
            })} disabled={runMutation.isPending || formData.symbols.length === 0}
              className="flex-1 bg-primary-600 text-white py-2.5 rounded-lg font-bold hover:bg-primary-500 disabled:opacity-50 transition-colors">
              {runMutation.isPending ? "در حال اجرا..." : "اجرای بک‌تست"}
            </button>

            <button onClick={() => runAllMutation.mutate({
              strategy_type: formData.strategyType,
              strategy_params: formData.strategyParams,
              commission_pct: formData.commission_pct / 100,
              slippage_bps: formData.slippage_bps,
              start_date: jalaliToGregorian(startDateJalali) || undefined,
              end_date: jalaliToGregorian(endDateJalali) || undefined,
              initial_capital: formData.capital,
            })} disabled={runAllMutation.isPending}
              className="flex cursor-pointer items-center gap-1.5 rounded-lg bg-primary-600 px-4 py-2.5 font-bold text-white shadow-[var(--shadow-card)] transition-all hover:bg-primary-500 disabled:cursor-not-allowed disabled:opacity-40">
              {runAllMutation.isPending ? (
                <><FlaskConical className="size-4 animate-spin" aria-hidden /> در حال اجرا...</>
              ) : (
                <><FlaskConical className="size-4" aria-hidden /> تست همه نمادها</>
              )}
            </button>
          </div>

          {/* ── Compare Section ── */}
          <div className="mt-4 p-3 bg-accent-purple/5 border border-accent-purple/20 rounded-lg">
            <label className="block mb-2 text-sm text-accent-purple font-bold">📊 مقایسه استراتژی‌ها</label>
            <div className="flex gap-2">
              <select
                value={compareSymbol}
                onChange={e => setCompareSymbol(e.target.value)}
                className="flex-1 bg-surface-800 border border-surface-700 rounded-lg px-3 py-2.5 text-sm text-surface-200 focus:outline-none focus:border-accent-purple"
              >
                {allSymbols.slice(0, 100).map(s => (
                  <option key={s.symbol} value={s.symbol}>{s.symbol}</option>
                ))}
              </select>
              <button onClick={() => compareMutation.mutate({
                symbol: compareSymbol,
                start_date: jalaliToGregorian(startDateJalali) || undefined,
                end_date: jalaliToGregorian(endDateJalali) || undefined,
                initial_capital: formData.capital,
              })} disabled={compareMutation.isPending}
                className="px-4 py-2.5 bg-accent-purple/30 hover:bg-accent-purple/40 border border-accent-purple/40 text-accent-purple rounded-lg font-bold transition-all whitespace-nowrap">
                {compareMutation.isPending ? (
                  <><span className="animate-spin text-sm">⚡</span>...</>
                ) : "اجرا"}
              </button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-2 space-y-4">
          <div className="glass-card p-5">
            <h2 className="text-base font-bold text-surface-200 mb-4">بک‌تست‌های انجام شده</h2>
            {loadingRuns ? (
              <div className="space-y-2">{[1,2,3].map(i => <Skeleton key={i} className="h-16 w-full rounded-lg" />)}</div>
            ) : runs?.length === 0 ? (
              <p className="text-surface-500 text-sm">هنوز بک‌تستی اجرا نشده</p>
            ) : (
              <div className="space-y-2">
                {runs?.map((run: Record<string, unknown>, i: number) => (
                  <div key={String(run.id ?? i)} className="flex items-center justify-between p-3 bg-surface-800/50 rounded-lg hover:bg-surface-800 transition-colors">
                    <div>
                      <p className="font-bold text-surface-200">{String(run.name ?? "")}</p>
                      <p className="text-xs text-surface-500">{String(run.status ?? "")} — {String(run.progress_pct ?? "")}%</p>
                    </div>
                    <button onClick={() => setSelectedResult({ id: String(run.id) } as BacktestResult)}
                      className="text-primary-400 text-sm font-bold hover:text-primary-300">مشاهده نتیجه</button>
                  </div>
                ))}
              </div>
            )}
          </div>

          {loadingResult ? (
            <Skeleton className="h-96 w-full rounded-2xl" />
          ) : result ? (
            <div className="space-y-4">
              {/* Metrics */}
              <div className="glass-card p-5">
                <h2 className="text-base font-bold text-surface-200 mb-4">نتیجه: {String(result.name ?? "")}</h2>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                  {[
                    { label: "بازده کل", value: `${String(result.total_return_pct ?? "")}%`, color: Number(result.total_return_pct) >= 0 ? "text-accent-emerald" : "text-accent-rose" },
                    { label: "بازده سالانه", value: `${String(result.annualized_return_pct ?? "")}%`, color: "text-surface-200" },
                    { label: "شارپ", value: Number(result.sharpe_ratio || 0).toFixed(2), color: Number(result.sharpe_ratio) >= 1 ? "text-accent-emerald" : "text-accent-amber" },
                    { label: "Max DD", value: `${String(result.max_drawdown_pct ?? "")}%`, color: "text-accent-rose" },
                    { label: "Win Rate", value: `${String(result.win_rate ?? "")}%`, color: Number(result.win_rate) >= 50 ? "text-accent-emerald" : "text-accent-rose" },
                    { label: "معاملات", value: String(result.total_trades ?? ""), color: "text-surface-200" },
                    { label: "سرمایه اولیه", value: `${formatRials(Number(result.initial_capital) || 0)}`, color: "text-surface-200" },
                    { label: "ارزش نهایی", value: `${formatRials(Number(result.final_value) || 0)}`, color: Number(result.final_value) >= Number(result.initial_capital) ? "text-accent-emerald" : "text-accent-rose" },
                    ...((result as Record<string, unknown>).data_quality ? [{
                      label: "کیفیت داده",
                      value: `${((result as Record<string, unknown>).data_quality as Record<string, unknown>)?.quality_score ?? 0}`,
                      color: Number(((result as Record<string, unknown>).data_quality as Record<string, unknown>)?.quality_score ?? 0) >= 0.8 ? "text-accent-emerald" : "text-accent-amber",
                    }] : []),
                    ...((result as Record<string, unknown>).alpha != null ? [{
                      label: "آلفا",
                      value: Number((result as Record<string, unknown>).alpha).toFixed(2),
                      color: Number((result as Record<string, unknown>).alpha) >= 0 ? "text-accent-emerald" : "text-accent-rose",
                    }] : []),
                    ...((result as Record<string, unknown>).beta != null ? [{
                      label: "بتا",
                      value: Number((result as Record<string, unknown>).beta).toFixed(2),
                      color: "text-surface-200",
                    }] : []),
                  ].map(item => (
                    <div key={item.label} className="bg-surface-800/50 rounded-lg p-3 text-center">
                      <p className="text-xs text-surface-500 mb-1">{item.label}</p>
                      <p className={`text-sm font-bold font-mono ${item.color}`}>{item.value}</p>
                    </div>
                  ))}
                </div>
              </div>

              {/* ── Equity Curve Chart ── */}
              {(() => {
                const raw = result as Record<string, unknown>;
                const equityCurve = raw.equity_curve as Array<{ timestamp: string; nav: number }> | undefined;
                if (!equityCurve || equityCurve.length < 2) return null;
                const equityData = equityCurve.map((ep, i) => ({
                  index: i,
                  nav: ep.nav,
                  date: typeof ep.timestamp === "string" ? ep.timestamp.slice(0, 10) : "",
                }));
                const initCapital = Number(raw.initial_capital) || 1;
                const minNav = Math.min(...equityData.map(d => d.nav));
                const maxNav = Math.max(...equityData.map(d => d.nav));
                const range = maxNav - minNav || 1;
                const yMin = minNav - range * 0.05;
                const yMax = maxNav + range * 0.05;
                const finalReturn = ((equityData[equityData.length - 1]?.nav ?? initCapital) / initCapital - 1) * 100;
                const isPositive = finalReturn >= 0;

                return (
                  <div className="glass-card p-5">
                    <div className="flex items-center justify-between mb-4">
                      <div>
                        <h3 className="text-base font-bold text-surface-200">📈 منحنی سرمایه</h3>
                        <p className="text-[11px] text-surface-500 mt-0.5">
                          {equityData.length} روز معاملاتی
                        </p>
                      </div>
                      <div className={`text-lg font-bold font-mono ${isPositive ? "text-accent-emerald" : "text-accent-rose"}`}>
                        {isPositive ? "+" : ""}{finalReturn.toFixed(1)}%
                      </div>
                    </div>
                    <div className="w-full h-[280px]" dir="ltr">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={equityData} margin={{ top: 10, right: 10, left: 10, bottom: 10 }}>
                          <defs>
                            <linearGradient id="equityGradient" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor={isPositive ? "#22c55e" : "#ef4444"} stopOpacity={0.3} />
                              <stop offset="95%" stopColor={isPositive ? "#22c55e" : "#ef4444"} stopOpacity={0.02} />
                            </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)" />
                          <XAxis
                            dataKey="index"
                            tick={false}
                            axisLine={{ stroke: "rgba(255,255,255,0.1)" }}
                          />
                          <YAxis
                            domain={[yMin, yMax]}
                            tick={{ fill: "#64748b", fontSize: 10, fontFamily: "monospace" }}
                            tickFormatter={(v: number) => Math.round(v).toLocaleString("en-US")}
                            axisLine={{ stroke: "rgba(255,255,255,0.1)" }}
                            width={80}
                          />
                          <Tooltip
                            contentStyle={{
                              background: "#1e293b",
                              border: "1px solid rgba(255,255,255,0.1)",
                              borderRadius: 8,
                              fontSize: 12,
                              color: "#e2e8f0",
                            }}
                            formatter={(value: unknown) => [formatRials(Number(value) || 0), "ارزش پرتفوی"]}
                            labelFormatter={(i: unknown) => {
                              const idx = Number(i);
                              const d = equityData[idx];
                              return d ? "روز " + (idx + 1) + " — " + d.date : "روز " + (idx + 1);
                            }}
                          />
                          <ReferenceLine
                            y={initCapital}
                            stroke="rgba(255,255,255,0.2)"
                            strokeDasharray="4 4"
                            label={{
                              value: "سرمایه اولیه",
                              fill: "#64748b",
                              fontSize: 10,
                              position: "right",
                            }}
                          />
                          <Area
                            type="monotone"
                            dataKey="nav"
                            stroke={isPositive ? "#22c55e" : "#ef4444"}
                            strokeWidth={2}
                            fill="url(#equityGradient)"
                            dot={false}
                            activeDot={{ r: 4, strokeWidth: 1, stroke: "#e2e8f0" }}
                          />
                        </AreaChart>
                      </ResponsiveContainer>
                    </div>
                    <div className="flex justify-between mt-3 text-[10px] text-surface-500 border-t border-surface-800/50 pt-3">
                      <span>🔵 ارزش اولیه: {formatRials(initCapital)}</span>
                      <span>🟣 حداکثر: {formatRials(maxNav)}</span>
                      <span>🔴 حداقل: {formatRials(minNav)}</span>
                      <span>🟢 ارزش نهایی: {formatRials(equityData[equityData.length - 1]?.nav ?? initCapital)}</span>
                    </div>
                  </div>
                );
              })()}

              {/* ── Drawdown Chart ── */}
              {(() => {
                const raw = result as Record<string, unknown>;
                const equityCurve = raw.equity_curve as Array<{ timestamp: string; nav: number }> | undefined;
                if (!equityCurve || equityCurve.length < 2) return null;
                let peak = equityCurve[0].nav;
                const drawdownData = equityCurve.map((ep, i) => {
                  if (ep.nav > peak) peak = ep.nav;
                  const dd = peak > 0 ? ((ep.nav - peak) / peak) * 100 : 0;
                  return {
                    index: i,
                    drawdown: dd,
                    date: typeof ep.timestamp === "string" ? ep.timestamp.slice(0, 10) : "",
                  };
                });
                const maxDD = Math.min(...drawdownData.map(d => d.drawdown));
                return (
                  <div className="glass-card p-5 mt-4">
                    <div className="flex items-center justify-between mb-4">
                      <div>
                        <h3 className="text-base font-bold text-surface-200">📉 افت سرمایه</h3>
                        <p className="text-[11px] text-surface-500 mt-0.5">حداکثر افت: {maxDD.toFixed(2)}%</p>
                      </div>
                    </div>
                    <div className="w-full h-[180px]" dir="ltr">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={drawdownData} margin={{ top: 10, right: 10, left: 10, bottom: 10 }}>
                          <defs>
                            <linearGradient id="ddGradient" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor="#ef4444" stopOpacity={0.4} />
                              <stop offset="95%" stopColor="#ef4444" stopOpacity={0} />
                            </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)" />
                          <XAxis dataKey="index" tick={false} axisLine={{ stroke: "rgba(255,255,255,0.1)" }} />
                          <YAxis
                            tick={{ fill: "#64748b", fontSize: 10, fontFamily: "monospace" }}
                            tickFormatter={(v: number) => `${v.toFixed(1)}%`}
                            axisLine={{ stroke: "rgba(255,255,255,0.1)" }}
                            width={50}
                          />
                          <Tooltip
                            contentStyle={{
                              background: "#1e293b",
                              border: "1px solid rgba(255,255,255,0.1)",
                              borderRadius: 8,
                              fontSize: 12,
                              color: "#e2e8f0",
                            }}
                            formatter={(value: unknown) => [`${Number(value).toFixed(2)}%`, "افت سرمایه"]}
                            labelFormatter={(i: unknown) => {
                              const idx = Number(i);
                              const d = drawdownData[idx];
                              return d ? "روز " + (idx + 1) + " — " + d.date : "روز " + (idx + 1);
                            }}
                          />
                          <Area
                            type="monotone"
                            dataKey="drawdown"
                            stroke="#ef4444"
                            strokeWidth={1.5}
                            fill="url(#ddGradient)"
                            dot={false}
                          />
                        </AreaChart>
                      </ResponsiveContainer>
                    </div>
                  </div>
                );
              })()}
            </div>
          ) : null}

          {/* ── Compare Strategies Results ── */}
          {showCompare && compareResults.length > 0 && (
            <div className="glass-card p-5">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-base font-bold text-surface-200">📊 مقایسه استراتژی‌ها</h2>
                <div className="flex items-center gap-3">
                  {compareBest && compareWorst && (
                    <div className="flex gap-3 text-[10px]">
                      <span className="px-2 py-0.5 rounded-full bg-accent-emerald/15 text-accent-emerald font-bold">
                        🏆 بهترین: {compareBest}
                      </span>
                      <span className="px-2 py-0.5 rounded-full bg-accent-rose/15 text-accent-rose font-bold">
                        🫤 بدترین: {compareWorst}
                      </span>
                    </div>
                  )}
                  <button onClick={downloadCompareReport}
                    className="px-3 py-1.5 text-[11px] bg-accent-purple/20 hover:bg-accent-purple/30 border border-accent-purple/30 text-accent-purple rounded-lg font-bold transition-all whitespace-nowrap flex items-center gap-1">
                    📄 گزارش
                  </button>
                  <button onClick={() => saveCompareMutation.mutate()} disabled={saveCompareMutation.isPending}
                    className="px-3 py-1.5 text-[11px] bg-accent-emerald/20 hover:bg-accent-emerald/30 border border-accent-emerald/30 text-accent-emerald rounded-lg font-bold transition-all whitespace-nowrap flex items-center gap-1">
                    {saveCompareMutation.isPending ? "..." : "💾 ذخیره"}
                  </button>
                </div>
              </div>
              <div className="grid grid-cols-3 gap-3 mb-4">
                <div className="bg-surface-800/50 rounded-lg p-3 text-center">
                  <p className="text-lg font-bold text-surface-200">{compareResults.length}</p>
                  <p className="text-xs text-surface-500">کل استراتژی‌ها</p>
                </div>
                <div className="bg-surface-800/50 rounded-lg p-3 text-center">
                  <p className="text-lg font-bold text-accent-emerald">
                    {compareResults.filter(r => r.status !== "failed").length}
                  </p>
                  <p className="text-xs text-surface-500">موفق</p>
                </div>
                <div className="bg-surface-800/50 rounded-lg p-3 text-center">
                  <p className="text-lg font-bold text-accent-rose">
                    {compareResults.filter(r => r.status === "failed").length}
                  </p>
                  <p className="text-xs text-surface-500">ناموفق</p>
                </div>
              </div>
              {/* Metric checkboxes */}
              <div className="mb-4">
                <p className="text-[10px] text-surface-500 font-bold mb-2">📐 انتخاب متریک‌های رادار</p>
                <div className="flex flex-wrap gap-2">
                  {ALL_RADAR_COLS.map(col => {
                    const enabled = enabledRadarMetrics.includes(col.key);
                    return (
                      <label key={col.key}
                        className={`flex items-center gap-1.5 px-2.5 py-1 rounded-lg cursor-pointer transition-all text-[10px] font-bold ${
                          enabled
                            ? 'bg-primary-600/20 text-primary-300 ring-1 ring-primary-500/40'
                            : 'bg-surface-800/50 text-surface-500 hover:bg-surface-700/50'
                        }`}>
                        <input type="checkbox" checked={enabled}
                          onChange={() => {
                            setEnabledRadarMetrics(prev =>
                              enabled
                                ? prev.filter(k => k !== col.key)
                                : [...prev, col.key]
                            );
                          }}
                          className="sr-only" />
                        <div className={`w-2.5 h-2.5 rounded border flex items-center justify-center transition-all ${
                          enabled ? 'bg-primary-500 border-primary-500' : 'border-surface-600 bg-transparent'
                        }`}>
                          {enabled && <span className="text-[7px] text-white leading-none">✓</span>}
                        </div>
                        {col.label}
                      </label>
                    );
                  })}
                </div>
              </div>
              {/* Radar chart */}
              <BacktestRadarChart
                results={compareResults}
                selectedStrategies={highlightedStrategies}
                onStrategyClick={handleStrategyClick}
                enabledCols={enabledRadarMetrics}
                hoveredStrategy={hoveredStrategy}
                onHover={setHoveredStrategy}
                onClearSelection={() => {
                  setHighlightedStrategies([]);
                  lastClickedRef.current = null;
                }}
              />

              <div className="overflow-x-auto">
                <table className="w-full text-right text-xs">
                  <thead>
                    <tr className="text-surface-500 border-b border-surface-700">
                      {compareColumns.map(col => (
                        <th key={col.key}
                          onClick={() => toggleCompareSort(col.key)}
                          className={`pb-2 px-2 select-none cursor-pointer hover:text-surface-200 transition-colors ${compareSortKey === col.key ? "text-primary-400" : ""}`}>
                          {col.label}<span className="text-[10px] opacity-50">{getSortArrow(col.key)}</span>
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {sortedCompareResults.map(r => {
                      const m = r.metrics;          const isBest = r.strategy === compareBest;
          const isWorst = r.strategy === compareWorst;
          const failed = r.status === "failed";                      const isRowSelected = highlightedStrategies.includes(r.strategy);
                      let rowBg = "";
                      if (isRowSelected) rowBg = "bg-primary-600/10";
                      else if (isBest) rowBg = "bg-accent-emerald/5";
                      else if (isWorst) rowBg = "bg-accent-rose/5";
                      return (
                        <tr key={r.strategy}
                          onClick={(e) => handleStrategyClick(r.strategy, e)}
                          className={`border-b transition-colors ${
                            isRowSelected ? 'border-primary-500/60' : 'border-surface-800/30 hover:bg-white/5'
                          } ${rowBg} ${failed ? "opacity-50" : ""} cursor-pointer`}>
                          <td className="py-2 px-2 font-bold relative group">
                            <span className={`${isBest ? "text-accent-emerald" : isWorst ? "text-accent-rose" : "text-surface-200"} cursor-help`}>
                              {isBest && "🏆 "}{isWorst && "🫤 "}{r.strategy}
                            </span>
                            {(() => {
                              const desc = (strategies ?? []).find((s: Record<string, unknown>) => s.name === r.strategy)?.description as string | undefined;
                              if (!desc) return null;
                              return (
                                <div className="absolute bottom-full left-0 mb-1 hidden group-hover:block z-10">
                                  <div className="bg-surface-700 text-surface-300 text-[10px] rounded-lg px-3 py-2 shadow-lg max-w-[260px] leading-relaxed whitespace-normal">
                                    📖 {desc}
                                  </div>
                                </div>
                              );
                            })()}
                          </td>
                          <td className={`py-2 px-2 font-mono ${!failed && m?.total_return_pct != null ? (m.total_return_pct >= 0 ? "text-accent-emerald" : "text-accent-rose") : "text-surface-500"}`}>
                            {!failed && m?.total_return_pct != null ? `${m.total_return_pct.toFixed(1)}%` : "—"}
                          </td>
                          <td className="py-2 px-2 font-mono text-surface-400">
                            {!failed && m?.annualized_return_pct != null ? `${m.annualized_return_pct.toFixed(1)}%` : "—"}
                          </td>
                          <td className={`py-2 px-2 font-mono ${!failed && m?.sharpe_ratio != null ? (m.sharpe_ratio >= 1 ? "text-accent-emerald" : m.sharpe_ratio >= 0 ? "text-accent-amber" : "text-accent-rose") : "text-surface-500"}`}>
                            {!failed && m?.sharpe_ratio != null ? m.sharpe_ratio.toFixed(2) : "—"}
                          </td>
                          <td className={`py-2 px-2 font-mono ${!failed && m?.win_rate != null ? (m.win_rate >= 50 ? "text-accent-emerald" : "text-accent-rose") : "text-surface-500"}`}>
                            {!failed && m?.win_rate != null ? `${m.win_rate.toFixed(1)}%` : "—"}
                          </td>
                          <td className="py-2 px-2 font-mono text-surface-400">
                            {!failed && m?.max_drawdown_pct != null ? `${m.max_drawdown_pct.toFixed(1)}%` : "—"}
                          </td>
                          <td className="py-2 px-2 font-mono text-surface-400">
                            {!failed && m?.total_trades != null ? m.total_trades : "—"}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* ── Compare History ── */}
          {compareHistory && compareHistory.length > 0 && (
            <div className="glass-card p-5">
              <h2 className="text-base font-bold text-surface-200 mb-4">📚 تاریخچه مقایسه‌ها</h2>
              <div className="space-y-2 max-h-72 overflow-y-auto">
                {(compareHistory as CompareHistoryItem[]).slice(0, 10).map(item => {
                  const hasReturn = item.avg_return_pct != null;
                  return (
                    <button key={item.id} onClick={() => loadCompareHistory(item)}
                      className="w-full flex items-center justify-between p-3 bg-surface-800/40 hover:bg-surface-800 rounded-lg transition-colors text-right">
                      <div className="flex items-center gap-3">
                        <span className="text-surface-500 text-lg">📊</span>
                        <div>
                          <p className="text-sm font-bold text-surface-200">{item.symbol}</p>
                          <p className="text-[10px] text-surface-500">
                            {item.total_strategies} استراتژی • {item.successful} موفق • {item.failed} ناموفق
                            {item.created_at && ` • ${new Date(item.created_at).toLocaleDateString("fa-IR")}`}
                          </p>
                        </div>
                      </div>
                      <div className="text-left">
                        {hasReturn ? (
                          <>
                            <p className={`text-xs font-bold font-mono ${item.avg_return_pct! >= 0 ? "text-accent-emerald" : "text-accent-rose"}`}>
                              {item.avg_return_pct!.toFixed(1)}%
                            </p>
                            <p className="text-[9px] text-surface-600">میانگین</p>
                          </>
                        ) : (
                          <span className="text-xs text-surface-600">—</span>
                        )}
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* ── Run All Results ── */}
          {showAllResults && (
            <div className="glass-card p-5">
              <h2 className="text-base font-bold text-surface-200 mb-4">📊 نتیجه تست همه نمادها</h2>

              {/* Summary Cards */}
              <div className="grid grid-cols-4 gap-3 mb-4">
                <div className="bg-surface-800/50 rounded-lg p-3 text-center">
                  <p className="text-lg font-bold text-surface-200">{allResults.length}</p>
                  <p className="text-xs text-surface-500">کل</p>
                </div>
                <div className="bg-surface-800/50 rounded-lg p-3 text-center">
                  <p className="text-lg font-bold text-accent-emerald">
                    {allResults.filter(r => r.status !== "failed").length}
                  </p>
                  <p className="text-xs text-surface-500">موفق</p>
                </div>
                <div className="bg-surface-800/50 rounded-lg p-3 text-center">
                  <p className="text-lg font-bold text-accent-rose">
                    {allResults.filter(r => r.status === "failed").length}
                  </p>
                  <p className="text-xs text-surface-500">ناموفق</p>
                </div>
                <div className="bg-surface-800/50 rounded-lg p-3 text-center">
                  <p className="text-lg font-bold text-accent-cyan">
                    {allResults.reduce((sum, r) => sum + (r.metrics?.total_trades ?? 0), 0)}
                  </p>
                  <p className="text-xs text-surface-500">کل معاملات</p>
                </div>
              </div>

              {/* Per-Symbol Results Table */}
              <div className="overflow-x-auto">
                <table className="w-full text-right text-xs">
                  <thead>
                    <tr className="text-surface-500 border-b border-surface-700">
                      <th className="pb-2 px-2">نماد</th>
                      <th className="pb-2 px-2">وضعیت</th>
                      <th className="pb-2 px-2">بازده کل</th>
                      <th className="pb-2 px-2">بازده سالانه</th>
                      <th className="pb-2 px-2">شارپ</th>
                      <th className="pb-2 px-2">Win Rate</th>
                      <th className="pb-2 px-2">Max DD</th>
                      <th className="pb-2 px-2">معاملات</th>
                    </tr>
                  </thead>
                  <tbody>
                    {allResults.map(r => {
                      const m = r.metrics;
                      const failed = r.status === "failed";
                      return (
                        <tr key={r.symbol} className={`border-b border-surface-800/30 hover:bg-white/5 ${failed ? "opacity-50" : ""}`}>
                          <td className="py-2 px-2 font-bold text-surface-200">{r.symbol}</td>
                          <td className="py-2 px-2">
                            {failed ? (
                              <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-accent-rose/15 text-accent-rose">خطا</span>
                            ) : (
                              <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-accent-emerald/15 text-accent-emerald">✓</span>
                            )}
                          </td>
                          <td className={`py-2 px-2 font-mono ${!failed && m?.total_return_pct != null ? (m.total_return_pct >= 0 ? "text-accent-emerald" : "text-accent-rose") : "text-surface-500"}`}>
                            {!failed && m?.total_return_pct != null ? `${m.total_return_pct.toFixed(1)}%` : "—"}
                          </td>
                          <td className="py-2 px-2 font-mono text-surface-400">
                            {!failed && m?.annualized_return_pct != null ? `${m.annualized_return_pct.toFixed(1)}%` : "—"}
                          </td>
                          <td className={`py-2 px-2 font-mono ${!failed && m?.sharpe_ratio != null ? (m.sharpe_ratio >= 1 ? "text-accent-emerald" : m.sharpe_ratio >= 0 ? "text-accent-amber" : "text-accent-rose") : "text-surface-500"}`}>
                            {!failed && m?.sharpe_ratio != null ? m.sharpe_ratio.toFixed(2) : "—"}
                          </td>
                          <td className={`py-2 px-2 font-mono ${!failed && m?.win_rate != null ? (m.win_rate >= 50 ? "text-accent-emerald" : "text-accent-rose") : "text-surface-500"}`}>
                            {!failed && m?.win_rate != null ? `${m.win_rate.toFixed(1)}%` : "—"}
                          </td>
                          <td className="py-2 px-2 font-mono text-surface-400">
                            {!failed && m?.max_drawdown_pct != null ? `${m.max_drawdown_pct.toFixed(1)}%` : "—"}
                          </td>
                          <td className="py-2 px-2 font-mono text-surface-400">
                            {!failed && m?.total_trades != null ? m.total_trades : "—"}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

"use client";

import { useState, useCallback } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import { apiGet, apiPost } from "@/lib/api";
import Link from "next/link";

// ------ Types -------------------------------------------------------------------------------------------------------

interface SyncInfo {
  status: string | null;
  items_count: number;
  duration_ms: number;
  completed_at: string | null;
  error_message: string | null;
}

interface SectionData {
  id: string;
  name: string;
  name_en: string;
  icon: string;
  category: string;
  has_date_range: boolean;
  record_count: number;
  last_data_date: string | null;
  last_sync: SyncInfo | null;
}

interface SyncResult {
  endpoint: string;
  section_id: string;
  success: boolean;
  items_count: number;
  duration_ms: number;
  skipped: number;
  error: string | null;
}

interface HealthData {
  status: string;
  commodity_prices: number;
  crypto_prices: number;
  symbol_snapshots: number;
  index_values: number;
  option_snapshots: number;
  ime_futures: number;
}

interface BatchSyncResult {
  total: number;
  success_count: number;
  fail_count: number;
  total_duration_ms: number;
  results: { symbol: string; success: boolean; items_count?: number; duration_ms?: number; error?: string }[];
}

// ------ Category Config ----------------------------------------------------------------------------------------------

const CATEGORY_META: Record<string, { label: string; color: string }> = {
  tsetmc: { label: "TSETMC (بورس)", color: "bg-accent-emerald/15 text-accent-emerald" },
  ime: { label: "IME (بورس کالا)", color: "bg-accent-amber/15 text-accent-amber" },
  commodity: { label: "Commodity (کامودیتی)", color: "bg-accent-rose/15 text-accent-rose" },
  cryptocurrency: { label: "Cryptocurrency (ارز دیجیتال)", color: "bg-accent-violet/15 text-accent-violet" },
  codal: { label: "Codal (کدال)", color: "bg-primary-600/15 text-primary-300" },
};

const CATEGORY_ORDER = ["tsetmc", "ime", "commodity", "cryptocurrency", "codal"];

// ------ Helpers -----------------------------------------------------------------------------------------------------

function formatNumber(n: number): string {
  if (n >= 1_000_000) return (n / 1_000_000).toFixed(1) + "M";
  if (n >= 1_000) return (n / 1_000).toFixed(1) + "K";
  return n.toLocaleString("en-US");
}

function formatDuration(ms: number): string {
  if (ms < 1000) return ms.toFixed(0) + "ms";
  if (ms < 60000) return (ms / 1000).toFixed(1) + "s";
  return (ms / 60000).toFixed(1) + "min";
}

function formatRelativeTime(dateStr: string | null): string {
  if (!dateStr) return "—";
  try {
    const d = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - d.getTime();
    const diffMin = Math.floor(diffMs / 60000);
    if (diffMin < 1) return "just now";
    if (diffMin < 60) return `${diffMin}m ago`;
    const diffHr = Math.floor(diffMin / 60);
    if (diffHr < 24) return `${diffHr}h ago`;
    const diffDays = Math.floor(diffHr / 24);
    return `${diffDays}d ago`;
  } catch {
    return dateStr.substring(0, 10);
  }
}

// ------ Components --------------------------------------------------------------------------------------------------

function StatusBadge({ status }: { status: string | null }) {
  if (!status) return <span className="text-xs text-surface-500">never synced</span>;
  if (status === "success")
    return <span className="text-xs bg-accent-emerald/15 text-accent-emerald px-2 py-0.5 rounded-full">success</span>;
  if (status === "failed" || status === "error")
    return <span className="text-xs bg-accent-rose/15 text-accent-rose px-2 py-0.5 rounded-full">failed</span>;
  if (status === "running" || status === "in_progress")
    return <span className="text-xs bg-accent-amber/15 text-accent-amber px-2 py-0.5 rounded-full animate-pulse">running...</span>;
  return <span className="text-xs text-surface-500 px-2 py-0.5 rounded-full bg-surface-800">{status}</span>;
}

function SectionIcon({ icon }: { icon: string }) {
  return <span className="text-lg">{icon}</span>;
}

// ── History Data Section (Crypto/Gold/Currency from BrsApi) ──────────────

interface HistoryStatus {
  [key: string]: {
    table: string;
    rows: number;
    min_date: string | null;
    max_date: string | null;
    symbols: number;
    error?: string;
  };
}

function HistoryDataSection() {
  const [importing, setImporting] = useState(false);
  const [lastResult, setLastResult] = useState<{ total_inserted: number; files_imported: number; duration_s: number } | null>(null);

  const { data: historyStatus, refetch: refetchHistory } = useQuery<HistoryStatus>({
    queryKey: ["brsapi-history-status"],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: HistoryStatus }>("/brsapi/manage/history-status");
      return res?.data ?? {};
    },
    refetchInterval: false,
  });

  const doImportJson = useCallback(async () => {
    setImporting(true);
    setLastResult(null);
    try {
      const res = await apiPost<{ success: boolean; data: { total_inserted: number; files_imported: number; duration_s: number } }>(
        "/brsapi/manage/import-json-history"
      );
      if (res?.success) {
        setLastResult(res.data);
        refetchHistory();
      }
    } catch (err) {
      console.error("Import error:", err);
    }
    setImporting(false);
  }, [refetchHistory]);

  return (
    <div className="glass-card p-4">
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-semibold text-surface-100">📊 تاریخچه داده‌ها</h3>
        <button onClick={() => refetchHistory()} className="text-xs text-surface-500 hover:text-surface-200 flex items-center gap-1">
          <span className="material-icons text-sm">refresh</span> بروزرسانی
        </button>
      </div>

      {/* Status Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mb-4">
        {historyStatus && Object.entries(historyStatus).map(([label, info]) => (
          <div key={label} className="bg-surface-800/50 rounded-xl p-3">
            <div className="text-xs text-surface-500 mb-1">{label}</div>
            <div className="text-lg font-bold font-mono text-surface-100">{formatNumber(info.rows)}</div>
            <div className="text-[10px] text-surface-500 mt-1">
              {info.symbols} نماد • {info.min_date || "—"} → {info.max_date || "—"}
            </div>
          </div>
        ))}
      </div>

      {/* Instructions */}
      <div className="bg-surface-800/30 rounded-lg p-3 mb-3 text-xs text-surface-400 space-y-1">
        <div className="font-medium text-surface-300">مراحل دریافت داده تاریخچه:</div>
        <div>۱. اسکریپت دریافت را از ترمینال اجرا کنید: <code className="bg-surface-700 px-1 rounded text-accent-emerald">python scripts/fetch_all_history.py</code></div>
        <div>۲. دکمه زیر را بزنید تا فایل‌ها وارد دیتابیس شوند</div>
      </div>

      {/* Import Button */}
      <div className="flex flex-wrap gap-2">
        <button
          onClick={doImportJson}
          disabled={importing}
          className={`flex items-center gap-1.5 px-5 py-2.5 rounded-lg text-sm font-medium transition-all ${
            importing
              ? "bg-accent-emerald/20 text-accent-emerald animate-pulse"
              : "bg-accent-emerald hover:bg-accent-emerald/80 text-white"
          } disabled:opacity-50`}
        >
          <span className={`material-icons text-sm ${importing ? "animate-spin" : ""}`}>
            {importing ? "sync" : "download"}
          </span>
          {importing ? "در حال وارد کردن..." : "وارد کردن از JSON فایل‌ها"}
        </button>
      </div>

      {/* Last Result */}
      {lastResult && (
        <div className="mt-3 bg-accent-emerald/10 border border-accent-emerald/20 rounded-lg p-3 text-xs text-accent-emerald">
          ✅ {lastResult.files_imported} فایل • {formatNumber(lastResult.total_inserted)} ردیف وارد شد • {lastResult.duration_s}s
        </div>
      )}
    </div>
  );
}

function SyncButton({
  sectionId,
  label,
  disabled,
  syncing,
  onSync,
}: {
  sectionId: string;
  label?: string;
  disabled?: boolean;
  syncing?: boolean;
  onSync: (id: string) => void;
}) {
  return (
    <button
      onClick={() => onSync(sectionId)}
      disabled={disabled || syncing}
      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
        syncing
          ? "bg-accent-amber/20 text-accent-amber animate-pulse cursor-wait"
          : "bg-primary-600 hover:bg-primary-500 text-white"
      } disabled:opacity-50 disabled:cursor-not-allowed`}
    >
      <span className={`material-icons text-sm ${syncing ? "animate-spin" : ""}`}>
        {syncing ? "sync" : "sync"}
      </span>
      {syncing ? "Syncing..." : label || "Sync"}
    </button>
  );
}

// ------ Main Page ---------------------------------------------------------------------------------------------------

export default function BrsapiManagementPage() {
  const queryClient = useQueryClient();
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [notification, setNotification] = useState<{ type: "success" | "error"; message: string } | null>(null);
  const [batchSyncing, setBatchSyncing] = useState<Record<string, boolean>>({});
  const [syncingSections, setSyncingSections] = useState<Record<string, boolean>>({});

  const showNotification = useCallback((type: "success" | "error", message: string) => {
    setNotification({ type, message });
    setTimeout(() => setNotification(null), 5000);
  }, []);

  // Fetch all sections
  const {
    data: sectionsData,
    isLoading,
    isError,
    refetch,
  } = useQuery({
    queryKey: ["brsapi-sections"],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: SectionData[] }>("/brsapi/manage/sections");
      return res?.data ?? [];
    },
    refetchInterval: 30_000,
  });

  // Fetch health
  const { data: healthData } = useQuery({
    queryKey: ["brsapi-health"],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: HealthData }>("/brsapi/health");
      return res?.data ?? null;
    },
    refetchInterval: 30_000,
  });

  // Sync individual section
  const doSyncSection = useCallback(
    async (sectionId: string) => {
      setSyncingSections((prev) => ({ ...prev, [sectionId]: true }));
      try {
        const res = await apiPost<{ success: boolean; data: SyncResult }>(
          `/brsapi/manage/sync/${sectionId}`
        );
        if (res?.success) {
          showNotification("success", `Sync completed: ${res.data.items_count} items in ${formatDuration(res.data.duration_ms)}`);
        } else {
          showNotification("error", `Sync failed: ${(res as { error?: string })?.error || "Unknown error"}`);
        }
      } catch (err) {
        showNotification("error", `Sync error: ${err instanceof Error ? err.message : "Unknown"}`);
      }
      setSyncingSections((prev) => ({ ...prev, [sectionId]: false }));
      refetch();
    },
    [refetch, showNotification]
  );

  // Sync top symbols
  const doSyncTopSymbols = useCallback(
    async (limit: number = 10) => {
      setBatchSyncing((prev) => ({ ...prev, topSymbols: true }));
      try {
        const res = await apiPost<{ success: boolean; data: BatchSyncResult }>(
          `/brsapi/manage/sync-top-symbols?limit=${limit}`
        );
        if (res?.success) {
          showNotification(
            "success",
            `Top ${limit} symbols synced: ${res.data.success_count} OK, ${res.data.fail_count} failed in ${formatDuration(res.data.total_duration_ms)}`
          );
        } else {
          showNotification("error", (res as { error?: string })?.error || "Sync failed");
        }
      } catch (err) {
        showNotification("error", `Sync error: ${err instanceof Error ? err.message : "Unknown"}`);
      }
      setBatchSyncing((prev) => ({ ...prev, topSymbols: false }));
      refetch();
    },
    [refetch, showNotification]
  );

  // Sync all history
  const doSyncAllHistory = useCallback(
    async (limit: number = 0) => {
      setBatchSyncing((prev) => ({ ...prev, allHistory: true }));
      try {
        const res = await apiPost<{ success: boolean; data: BatchSyncResult }>(
          `/brsapi/manage/sync-all-history?limit=${limit}`
        );
        if (res?.success) {
          showNotification(
            "success",
            `History sync completed: ${res.data.success_count}/${res.data.total} OK, ${formatDuration(res.data.total_duration_ms)}`
          );
        } else {
          showNotification("error", (res as { error?: string })?.error || "Sync failed");
        }
      } catch (err) {
        showNotification("error", `Sync error: ${err instanceof Error ? err.message : "Unknown"}`);
      }
      setBatchSyncing((prev) => ({ ...prev, allHistory: false }));
      refetch();
    },
    [refetch, showNotification]
  );

  // Group sections by category
  const grouped = sectionsData?.reduce(
    (acc, section) => {
      const cat = section.category || "other";
      if (!acc[cat]) acc[cat] = [];
      acc[cat].push(section);
      return acc;
    },
    {} as Record<string, SectionData[]>
  );

  // Calculate totals
  const totalRecords = sectionsData?.reduce((sum, s) => sum + s.record_count, 0) ?? 0;
  const totalSynced = sectionsData?.filter((s) => s.last_sync?.status === "success").length ?? 0;

  return (
    <AppLayout
      title="BrsApi Management Dashboard"
      subtitle={`${sectionsData?.length ?? 0} data sections • ${formatNumber(totalRecords)} total records • ${totalSynced} synced`}
    >
      <div className="max-w-7xl mx-auto space-y-5">
        {/* Notification toast */}
        {notification && (
          <div
            className={`fixed top-4 left-1/2 -translate-x-1/2 z-50 px-5 py-3 rounded-xl shadow-2xl text-sm font-medium transition-all ${
              notification.type === "success"
                ? "bg-accent-emerald/20 text-accent-emerald border border-accent-emerald/30"
                : "bg-accent-rose/20 text-accent-rose border border-accent-rose/30"
            }`}
          >
            <span className="material-icons text-sm ml-1 align-text-bottom">
              {notification.type === "success" ? "check_circle" : "error"}
            </span>
            {notification.message}
          </div>
        )}

        {/* Health Status */}
        {healthData && (
          <div className="glass-card p-4">
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-sm font-semibold text-surface-100">
                🔌 Connection Status
              </h3>
              <span
                className={`text-xs font-bold px-2 py-1 rounded-full ${
                  healthData.status === "connected"
                    ? "bg-accent-emerald/15 text-accent-emerald"
                    : "bg-accent-rose/15 text-accent-rose"
                }`}
              >
                {healthData.status === "connected" ? "● Connected" : "● Disconnected"}
              </span>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-3 text-center">
              {[
                { label: "Symbol Snapshots", value: healthData.symbol_snapshots, icon: "📊" },
                { label: "Index Values", value: healthData.index_values, icon: "📈" },
                { label: "Commodity Prices", value: healthData.commodity_prices, icon: "🌍" },
                { label: "Crypto Prices", value: healthData.crypto_prices, icon: "₿" },
                { label: "Option Snapshots", value: healthData.option_snapshots, icon: "🎯" },
                { label: "IME Futures", value: healthData.ime_futures, icon: "🛢️" },
              ].map((item, ii) => (
                <div key={`${item.label}-${ii}`} className="bg-surface-800/50 rounded-xl p-2.5">
                  <span className="text-xs text-surface-500 block">{item.icon} {item.label}</span>
                  <span className="text-lg font-bold font-mono text-surface-100">{formatNumber(item.value)}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Batch Actions */}
        <div className="glass-card p-4">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-semibold text-surface-100">⚡ Batch Operations</h3>
            <button
              onClick={() => refetch()}
              className="text-xs text-surface-500 hover:text-surface-200 transition-colors flex items-center gap-1"
            >
              <span className="material-icons text-sm">refresh</span>
              Refresh
            </button>
          </div>
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => doSyncTopSymbols(10)}
              disabled={batchSyncing.topSymbols}
              className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-xs font-medium transition-all ${
                batchSyncing.topSymbols
                  ? "bg-accent-amber/20 text-accent-amber animate-pulse"
                  : "bg-surface-700 hover:bg-surface-600 text-surface-200"
              } disabled:opacity-50 disabled:cursor-not-allowed`}
            >
              <span className={`material-icons text-sm ${batchSyncing.topSymbols ? "animate-spin" : ""}`}>
                {batchSyncing.topSymbols ? "sync" : "sync"}
              </span>
              {batchSyncing.topSymbols ? "Syncing..." : "Sync Top 10 Symbols (Detail)"}
            </button>

            <button
              onClick={() => doSyncAllHistory(0)}
              disabled={batchSyncing.allHistory}
              className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-xs font-medium transition-all ${
                batchSyncing.allHistory
                  ? "bg-accent-amber/20 text-accent-amber animate-pulse"
                  : "bg-surface-700 hover:bg-surface-600 text-surface-200"
              } disabled:opacity-50 disabled:cursor-not-allowed`}
            >
              <span className={`material-icons text-sm ${batchSyncing.allHistory ? "animate-spin" : ""}`}>
                {batchSyncing.allHistory ? "sync" : "sync"}
              </span>
              {batchSyncing.allHistory ? "Syncing..." : "Sync ALL History Prices"}
            </button>

            <button
              onClick={() => doSyncTopSymbols(50)}
              disabled={batchSyncing.topSymbols}
              className="flex items-center gap-1.5 px-4 py-2 rounded-lg text-xs font-medium bg-surface-700 hover:bg-surface-600 text-surface-200 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <span className="material-icons text-sm">sync</span>
              Sync Top 50 Symbols
            </button>

            <Link
              href="/brsapi/codal"
              className="flex items-center gap-1.5 px-4 py-2 rounded-lg text-xs font-medium bg-primary-600/20 text-primary-300 hover:bg-primary-600/30 transition-all"
            >
              <span className="material-icons text-sm">description</span>
              Codal Announcements
            </Link>

            <Link
              href="/brsapi/history/%D9%81%D9%88%D9%84%D8%A7%D8%AF"
              className="flex items-center gap-1.5 px-4 py-2 rounded-lg text-xs font-medium bg-surface-700 hover:bg-surface-600 text-surface-200 transition-all"
            >
              <span className="material-icons text-sm">history</span>
              View Sample History
            </Link>
          </div>
        </div>

        {/* History Data Status & Sync */}
        <HistoryDataSection />

        {/* Category Filters */}
        <div className="flex flex-wrap gap-2">
          <button
            onClick={() => setActiveCategory(null)}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
              activeCategory === null
                ? "bg-primary-600 text-white shadow-lg"
                : "bg-surface-800 text-surface-400 hover:text-surface-200"
            }`}
          >
            All ({sectionsData?.length ?? 0})
          </button>
          {CATEGORY_ORDER.map((cat) => {
            const count = grouped?.[cat]?.length ?? 0;
            if (count === 0) return null;
            const meta = CATEGORY_META[cat];
            return (
              <button
                key={cat}
                onClick={() => setActiveCategory(activeCategory === cat ? null : cat)}
                className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                  activeCategory === cat
                    ? "bg-primary-600 text-white shadow-lg"
                    : "bg-surface-800 text-surface-400 hover:text-surface-200"
                }`}
              >
                {meta?.label ?? cat} ({count})
              </button>
            );
          })}
        </div>

        {/* Summary Cards */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          <div className="glass-card p-3 text-center">
            <div className="text-2xl font-bold text-surface-100">{sectionsData?.length ?? 0}</div>
            <div className="text-xs text-surface-500">Data Sections</div>
          </div>
          <div className="glass-card p-3 text-center">
            <div className="text-2xl font-bold text-accent-emerald">{formatNumber(totalRecords)}</div>
            <div className="text-xs text-surface-500">Total Records</div>
          </div>
          <div className="glass-card p-3 text-center">
            <div className="text-2xl font-bold text-primary-300">{totalSynced}</div>
            <div className="text-xs text-surface-500">Synced Sections</div>
          </div>
          <div className="glass-card p-3 text-center">
            <div className="text-2xl font-bold text-surface-100">
              {totalSynced > 0 ? Math.round((totalSynced / (sectionsData?.length ?? 1)) * 100) : 0}%
            </div>
            <div className="text-xs text-surface-500">Sync Coverage</div>
          </div>
        </div>

        {/* Sections List */}
        {isLoading ? (
          <div className="space-y-3">
            {Array.from({ length: 6 }).map((_, i) => (
              <Skeleton key={i} className="h-24 w-full rounded-xl" />
            ))}
          </div>
        ) : isError ? (
          <div className="text-center py-16 text-accent-rose">
            <p className="text-5xl mb-4">⚠️</p>
            <p className="text-lg font-medium">Failed to load BrsApi sections</p>
            <p className="text-sm mt-1 text-surface-500">
              Make sure the backend API is running and accessible
            </p>
            <button
              onClick={() => refetch()}
              className="mt-4 px-4 py-2 bg-primary-600 hover:bg-primary-500 text-white rounded-lg text-sm transition-colors"
            >
              Retry
            </button>
          </div>
        ) : (
          CATEGORY_ORDER.map((cat) => {
            const sections = grouped?.[cat];
            if (!sections || sections.length === 0) return null;
            if (activeCategory && activeCategory !== cat) return null;

            const meta = CATEGORY_META[cat];
            const catTotal = sections.reduce((s, sec) => s + sec.record_count, 0);

            return (
              <div key={cat}>
                {/* Category Header */}
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <span className={`text-xs font-bold px-2.5 py-1 rounded-full ${meta?.color ?? "bg-surface-700 text-surface-300"}`}>
                      {meta?.label ?? cat}
                    </span>
                    <span className="text-xs text-surface-500">{sections.length} sections</span>
                  </div>
                  <span className="text-xs text-surface-500">{formatNumber(catTotal)} records</span>
                </div>

                {/* Section Cards */}
                <div className="space-y-2 mb-6">
                  {sections.map((section) => {
                    const sync = section.last_sync;
                    const needsSync = !sync || (section.record_count === 0);

                    return (
                      <div
                        key={section.id}
                        className={`glass-card p-4 hover:bg-surface-800/50 transition-colors ${
                          needsSync ? "border-r-2 border-accent-amber/50" : ""
                        }`}
                      >
                        <div className="flex items-center justify-between gap-4">
                          {/* Left: Icon + Info */}
                          <div className="flex items-center gap-3 min-w-0 flex-1">
                            <SectionIcon icon={section.icon} />
                            <div className="min-w-0">
                              <div className="flex items-center gap-2 flex-wrap">
                                <h4 className="text-sm font-semibold text-surface-100">
                                  {section.name}
                                </h4>
                                <span className="text-[10px] text-surface-500 font-mono">
                                  {section.id}
                                </span>
                                {section.has_date_range && (
                                  <span className="text-[10px] bg-primary-600/10 text-primary-300 px-1.5 py-0.5 rounded">
                                    date range
                                  </span>
                                )}
                              </div>
                              <div className="flex items-center gap-3 mt-1 text-xs text-surface-500">
                                <span className="font-mono font-bold text-surface-300">
                                  {formatNumber(section.record_count)}
                                </span>
                                <span>records</span>
                                {section.last_data_date && (
                                  <>
                                    <span>•</span>
                                    <span className="text-primary-300" title={`Last data date: ${section.last_data_date}`}>
                                      📅 {section.last_data_date.length > 10 ? section.last_data_date : section.last_data_date.substring(0, 10)}
                                    </span>
                                  </>
                                )}
                                {sync && (
                                  <>
                                    <span>•</span>
                                    <StatusBadge status={sync.status} />
                                    <span>•</span>
                                    <span>{formatRelativeTime(sync.completed_at)}</span>
                                    {sync.duration_ms > 0 && (
                                      <span className="text-surface-600">
                                        ({formatDuration(sync.duration_ms)})
                                      </span>
                                    )}
                                  </>
                                )}
                                {!sync && (
                                  <>
                                    <span>•</span>
                                    <span className="text-accent-amber">not synced yet</span>
                                  </>
                                )}
                              </div>
                              {sync?.error_message && (
                                <div className="mt-1 text-[10px] text-accent-rose/80 truncate max-w-md">
                                  Error: {sync.error_message}
                                </div>
                              )}
                              {needsSync && (
                                <div className="mt-1">
                                  <span className="text-[10px] bg-accent-amber/10 text-accent-amber px-1.5 py-0.5 rounded">
                                    Data may be incomplete
                                  </span>
                                </div>
                              )}
                            </div>
                          </div>

                          {/* Right: Actions */}
                          <div className="flex items-center gap-2 shrink-0">
                            {sync && (
                              <>
                                {/* Download button */}
                                <a
                                  href={`${process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000/api/v1"}/brsapi/manage/download/${section.id}?format=json`}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-xs bg-surface-800 text-surface-400 hover:text-surface-200 hover:bg-surface-700 transition-all"
                                  title="Download JSON"
                                >
                                  <span className="material-icons text-sm">download</span>
                                </a>
                                <a
                                  href={`${process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000/api/v1"}/brsapi/manage/download/${section.id}?format=csv`}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-xs bg-surface-800 text-surface-400 hover:text-surface-200 hover:bg-surface-700 transition-all"
                                  title="Download CSV"
                                >
                                  <span className="text-xs font-bold">CSV</span>
                                </a>
                              </>
                            )}
                            <SyncButton
                              sectionId={section.id}
                              label="Sync"
                              syncing={syncingSections[section.id]}
                              onSync={doSyncSection}
                            />
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })
        )}

        {/* Empty state */}
        {!isLoading && sectionsData?.length === 0 && (
          <div className="text-center py-16 text-surface-500">
            <p className="text-5xl mb-4">📭</p>
            <p className="text-lg">No data sections found</p>
            <p className="text-sm mt-1">Ensure the BrsApi integration is properly configured on the backend</p>
          </div>
        )}

        {/* Quick Links */}
        <div className="flex flex-wrap gap-2 text-xs">
          <Link href="/instruments" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            ← All Symbols
          </Link>
          <Link href="/commodities" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            Commodities
          </Link>
          <Link href="/crypto" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            Crypto
          </Link>
          <Link href="/codal" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            Codal
          </Link>
          <Link href="/markets" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            Markets
          </Link>
        </div>
      </div>
    </AppLayout>
  );
}

"use client";

import { useParams } from "next/navigation";
import { useMemo, useState } from "react";
import Link from "next/link";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import { Card } from "@/components/ui/Card";
import { apiGet } from "@/lib/api";

// ── Types ──────────────────────────────────────────────────────────

interface AccountingItem {
  label: string;
  values: Record<string, number>;
}

interface AccountingTable {
  table_index: number;
  headers: string[];
  row_count: number;
  items: AccountingItem[];
}

interface AccountingReport {
  symbol: string;
  filename: string;
  report_type: string;
  date: string;
  title: string;
  tables: AccountingTable[];
  table_count: number;
}

interface ReportMeta {
  symbol: string;
  report_type: string;
  report_type_label: string;
  date: string;
  filename: string;
}

interface AccountingSummary {
  symbol: string;
  total_reports: number;
  latest_reports: Record<string, {
    date: string;
    filename: string;
    label: string;
    items: Record<string, number>;
  }>;
}

interface RatioItem {
  key: string;
  label: string;
  formula: string;
  description: string;
  good_range: string;
  value: number;
  value_pct: number;
  numerator: number;
  denominator: number;
}

interface RatiosResponse {
  symbol: string;
  total_reports: number;
  classified_items: Record<string, number>;
  ratios: RatioItem[];
  ratio_count: number;
}

// ── Helpers ────────────────────────────────────────────────────────

function formatCurrency(val: number | null | undefined): string {
  if (val == null || val === 0) return "—";
  if (Math.abs(val) >= 1e12) return (val / 1e12).toFixed(1) + "T";
  if (Math.abs(val) >= 1e9) return (val / 1e9).toFixed(1) + "B";
  if (Math.abs(val) >= 1e6) return (val / 1e6).toFixed(1) + "M";
  if (Math.abs(val) >= 1e3) return (val / 1e3).toFixed(0) + "K";
  return val.toLocaleString("en-US");
}

function faNum(s: string): string {
  const digits: Record<string, string> = { "0": "۰", "1": "۱", "2": "۲", "3": "۳", "4": "۴", "5": "۵", "6": "۶", "7": "۷", "8": "۸", "9": "۹" };
  return s.replace(/[0-9]/g, (d) => digits[d] || d);
}

const REPORT_TYPE_COLORS: Record<string, string> = {
  "ن-۱۰": "bg-blue-500/20 text-blue-300 border-blue-500/30",
  "ن-۳۰": "bg-violet-500/20 text-violet-300 border-violet-500/30",
  "ن-۳۱": "bg-emerald-500/20 text-emerald-300 border-emerald-500/30",
};

const REPORT_TYPE_ICONS: Record<string, string> = {
  "ن-۱۰": "📆",
  "ن-۳۰": "📋",
  "ن-۳۱": "📊",
};

function ReportTypeBadge({ type, label }: { type: string; label?: string }) {
  const color = REPORT_TYPE_COLORS[type] || "bg-surface-700 text-surface-400 border-surface-600";
  const icon = REPORT_TYPE_ICONS[type] || "📄";
  return (
    <span className={`text-xs px-2 py-0.5 rounded-lg border ${color}`}>
      {icon} {label || type}
    </span>
  );
}

// ── Main Page ──────────────────────────────────────────────────────

export default function CodalAccountingPage() {
  const params = useParams();
  const symbol = (params?.symbol as string) || "";
  const decodedSymbol = decodeURIComponent(symbol);

  const [selectedType, setSelectedType] = useState<string>("");
  const [selectedReport, setSelectedReport] = useState<string>("");

  // Fetch summary
  const { data: summary, isLoading: summaryLoading } = useQuery({
    queryKey: ["codal-acct-summary", decodedSymbol],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: AccountingSummary }>(
        `/codal-accounting/${encodeURIComponent(decodedSymbol)}/financials`
      );
      return res?.data ?? null;
    },
    enabled: !!decodedSymbol,
  });

  // Fetch all reports for the symbol
  const { data: reports, isLoading: reportsLoading } = useQuery({
    queryKey: ["codal-acct-reports", decodedSymbol],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: ReportMeta[] }>(
        `/codal-accounting/${encodeURIComponent(decodedSymbol)}/reports`
      );
      return res?.data ?? [];
    },
    enabled: !!decodedSymbol,
  });

  // Group reports by type
  const reportTypes = useMemo(() => {
    if (!reports) return [];
    const typeMap: Record<string, { type: string; label: string; reports: ReportMeta[] }> = {};
    for (const r of reports) {
      const key = r.report_type || "سایر";
      if (!typeMap[key]) {
        typeMap[key] = { type: key, label: r.report_type_label || key, reports: [] };
      }
      typeMap[key].reports.push(r);
    }
    return Object.values(typeMap).sort((a, b) => b.reports.length - a.reports.length);
  }, [reports]);

  // Set default selected type
  const activeType = selectedType || (reportTypes[0]?.type ?? "");
  const activeTypeData = reportTypes.find((t) => t.type === activeType);

  // Set default selected report
  const activeReportName = selectedReport || (activeTypeData?.reports[0]?.filename ?? "");

  // Fetch detail for selected report
  const { data: reportDetail, isLoading: detailLoading } = useQuery({
    queryKey: ["codal-acct-detail", decodedSymbol, activeReportName],
    queryFn: async () => {
      if (!activeReportName) return null;
      const res = await apiGet<{ success: boolean; data: AccountingReport }>(
        `/codal-accounting/${encodeURIComponent(decodedSymbol)}/report/${encodeURIComponent(activeReportName)}`
      );
      return res?.data ?? null;
    },
    enabled: !!activeReportName && !!decodedSymbol,
  });

  // Fetch ratios
  const { data: ratiosData, isLoading: ratiosLoading } = useQuery({
    queryKey: ["codal-acct-ratios", decodedSymbol],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: RatiosResponse }>(
        `/codal-accounting/${encodeURIComponent(decodedSymbol)}/ratios`
      );
      return res?.data ?? null;
    },
    enabled: !!decodedSymbol,
  });

  // Summary stats
  const totalReports = summary?.total_reports ?? 0;
  const summaryEntries = summary?.latest_reports ? Object.entries(summary.latest_reports) : [];

  if (!decodedSymbol) {
    return (
      <AppLayout title="حسابداری کدال" subtitle="انتخاب نماد">
        <div className="max-w-6xl mx-auto py-20 text-center text-surface-500">
          <p className="text-5xl mb-4">📒</p>
          <p className="text-lg">لطفاً یک نماد وارد کنید</p>
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout
      title={`حسابداری ${decodedSymbol}`}
      subtitle="صورت‌های مالی و نسبت‌های حسابداری از گزارش‌های کدال"
    >
      <div className="max-w-6xl mx-auto space-y-5">

        {/* ── Header ────────────────────────────────────────────────────── */}
        <div className="glass-card p-5">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-primary-600/20 flex items-center justify-center text-lg">📒</div>
              <div>
                <h1 className="text-xl font-bold text-surface-100">گزارشات حسابداری {decodedSymbol}</h1>
                <p className="text-sm text-surface-500 mt-0.5">
                  {totalReports > 0
                    ? `${faNum(String(totalReports))} گزارش از ${faNum(String(reportTypes.length))} نوع گزارش`
                    : "صورت‌های مالی استخراج شده از فایل‌های کدال"}
                </p>
              </div>
            </div>
            <div className="flex gap-2">
              <Link href={`/codal/analysis/${encodeURIComponent(decodedSymbol)}`}
                className="text-xs bg-surface-700 hover:bg-surface-600 text-surface-300 px-3 py-2 rounded-lg transition-colors">
                📊 تحلیل بنیادی
              </Link>
              <Link href={`/symbol/${encodeURIComponent(decodedSymbol)}`}
                className="text-xs bg-surface-700 hover:bg-surface-600 text-surface-300 px-3 py-2 rounded-lg transition-colors">
                صفحه نماد
              </Link>
            </div>
          </div>
        </div>

        {summaryLoading || reportsLoading ? (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {[1,2,3].map(i => <Skeleton key={i} className="h-32 rounded-xl" />)}
          </div>
        ) : totalReports === 0 ? (
          <div className="text-center py-20 text-surface-500">
            <p className="text-5xl mb-4">📭</p>
            <p className="text-lg">هیچ گزارش حسابداری برای {decodedSymbol} یافت نشد</p>
            <p className="text-sm mt-2">داده‌های حسابداری فقط برای نمادهای موجود در دایرکتوری codal_excel_files قابل دسترسی است</p>
          </div>
        ) : (
          <>

            {/* ── Summary Cards ──────────────────────────────────────────── */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
              {summaryEntries.map(([type, data]) => (
                <button
                  key={type}
                  onClick={() => { setSelectedType(type); setSelectedReport(""); }}
                  className={`glass-card p-4 text-right hover:bg-surface-800/50 transition-all text-left ${
                    activeType === type ? "ring-2 ring-primary-500/50" : ""
                  }`}
                >
                  <div className="flex items-center gap-2 mb-2">
                    <ReportTypeBadge type={type} label={data.label} />
                  </div>
                  <p className="text-2xl font-bold text-surface-100 mt-2">
                    {faNum(String(Object.keys(data.items).length))}
                  </p>
                  <p className="text-xs text-surface-500 mt-1">آیتم مالی استخراج شده</p>
                  <p className="text-xs text-surface-600 mt-1 font-mono">{data.date}</p>
                </button>
              ))}
            </div>

            {/* ── Accounting Ratios Section ─────────────────────────────── */}
            {ratiosData && ratiosData.ratios.length > 0 && (
              <Card title="🧮 نسبت‌های حسابداری" subtitle="محاسبه شده از آخرین گزارش‌های مالی">
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
                  {ratiosData.ratios.map((ratio) => {
                    const isHealthy = ratio.key === "debt_to_equity"
                      ? ratio.value < 1
                      : ratio.key === "current_ratio"
                      ? ratio.value >= 1.5 && ratio.value <= 3
                      : ratio.value_pct > 10;
                    return (
                      <div
                        key={ratio.key}
                        className={`p-4 rounded-xl border transition-all ${
                          isHealthy
                            ? "bg-accent-emerald/5 border-accent-emerald/20"
                            : "bg-accent-amber/5 border-accent-amber/20"
                        }`}
                      >
                        <div className="flex items-center justify-between mb-2">
                          <span className="text-xs font-bold text-surface-300">{ratio.label}</span>
                          <span className={`text-xs px-1.5 py-0.5 rounded-full ${
                            isHealthy ? "bg-accent-emerald/15 text-accent-emerald" : "bg-accent-amber/15 text-accent-amber"
                          }`}>
                            {isHealthy ? "✓ مطلوب" : "⚠ نیاز به بررسی"}
                          </span>
                        </div>
                        <p className={`text-2xl font-black font-mono ${
                          isHealthy ? "text-accent-emerald" : "text-accent-amber"
                        }`}>
                          {ratio.key === "roe" || ratio.key === "roa" || ratio.key === "gross_margin" || ratio.key === "net_margin" || ratio.key === "operating_margin"
                            ? `${ratio.value_pct.toFixed(1)}%`
                            : ratio.value.toFixed(2)}
                        </p>
                        <p className="text-xs text-surface-500 mt-1">{ratio.description}</p>
                        <div className="mt-2 pt-2 border-t border-surface-700/50 flex items-center justify-between text-[10px] text-surface-600">
                          <span>محدوده مطلوب: {ratio.good_range}</span>
                        </div>
                      </div>
                    );
                  })}
                </div>
                {ratiosData.classified_items && Object.keys(ratiosData.classified_items).length > 0 && (
                  <details className="mt-4">
                    <summary className="text-xs text-surface-500 cursor-pointer hover:text-surface-300 transition-colors">
                      آیتم‌های شناسایی شده ({Object.keys(ratiosData.classified_items).length})
                    </summary>
                    <div className="mt-2 grid grid-cols-2 sm:grid-cols-3 gap-2">
                      {Object.entries(ratiosData.classified_items).map(([key, val]) => (
                        <div key={key} className="flex items-center justify-between p-2 rounded-lg bg-surface-800/50 text-xs">
                          <span className="text-surface-400">{key}</span>
                          <span className="font-mono text-surface-200 font-bold">{val.toLocaleString("en-US")}</span>
                        </div>
                      ))}
                    </div>
                  </details>
                )}
              </Card>
            )}

            {/* ── Report Type Tabs ──────────────────────────────────────── */}
            <div className="flex gap-2 overflow-x-auto pb-1">
              {reportTypes.map((rt) => (
                <button
                  key={rt.type}
                  onClick={() => { setSelectedType(rt.type); setSelectedReport(""); }}
                  className={`shrink-0 px-4 py-2 rounded-xl text-sm font-medium transition-all ${
                    activeType === rt.type
                      ? "bg-primary-600 text-white shadow-lg"
                      : "bg-surface-800 text-surface-400 hover:text-surface-200"
                  }`}
                >
                  {REPORT_TYPE_ICONS[rt.type] || "📄"} {rt.label || rt.type}
                  <span className="mr-1.5 text-xs opacity-70">({faNum(String(rt.reports.length))})</span>
                </button>
              ))}
            </div>

            {/* ── Report Selector ────────────────────────────────────────── */}
            {activeTypeData && (
              <div className="glass-card p-4">
                <div className="flex items-center gap-2 mb-3">
                  <span className="text-xs text-surface-500">انتخاب گزارش:</span>
                </div>
                <div className="flex flex-wrap gap-2 max-h-32 overflow-y-auto">
                  {activeTypeData.reports.map((r) => (
                    <button
                      key={r.filename}
                      onClick={() => setSelectedReport(r.filename)}
                      className={`text-xs px-3 py-1.5 rounded-lg transition-colors ${
                        activeReportName === r.filename
                          ? "bg-primary-600/20 text-primary-300 border border-primary-500/30"
                          : "bg-surface-800 text-surface-400 hover:text-surface-200 border border-surface-700"
                      }`}
                    >
                      {r.date.replace(/_/g, "/")}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* ── Report Detail ──────────────────────────────────────────── */}
            {detailLoading ? (
              <div className="space-y-4">
                <Skeleton className="h-10 w-1/3 rounded-lg" />
                <Skeleton className="h-64 w-full rounded-xl" />
              </div>
            ) : reportDetail ? (
              reportDetail.tables.map((table, ti) => (
                <Card key={ti} title={`📋 جدول ${faNum(String(ti + 1))}`} subtitle={`${faNum(String(table.row_count))} ردیف`}>
                  {table.items.length === 0 ? (
                    <p className="text-surface-500 text-sm text-center py-6">داده‌ای در این جدول وجود ندارد</p>
                  ) : (
                    <div className="overflow-x-auto">
                      <table className="w-full text-right text-sm">
                        <thead>
                          <tr className="text-surface-500 border-b border-surface-700 text-xs">
                            <th className="pb-2 px-3 font-medium">ردیف</th>
                            <th className="pb-2 px-3 font-medium">شرح</th>
                            {table.headers.slice(1).map((h, hi) => (
                              <th key={hi} className="pb-2 px-3 font-medium text-left">{h}</th>
                            ))}
                          </tr>
                        </thead>
                        <tbody>
                          {table.items.map((item, ri) => {
                            const valEntries = Object.entries(item.values);
                            return (
                              <tr key={ri} className={`border-b border-surface-800/50 hover:bg-white/5 transition-colors ${
                                item.label === "جمع" || item.label === "مجموع" ? "bg-primary-600/5 font-bold" : ""
                              }`}>
                                <td className="py-2.5 px-3 text-xs text-surface-500">{faNum(String(ri + 1))}</td>
                                <td className={`py-2.5 px-3 ${item.label === "جمع" || item.label === "مجموع" ? "text-primary-300 font-bold" : "text-surface-200"}`}>
                                  {item.label}
                                </td>
                                {table.headers.slice(1).map((h, hi) => {
                                  const val = valEntries.find(([k]) => k === h)?.[1];
                                  return (
                                    <td key={hi} className={`py-2.5 px-3 font-mono ${
                                      val && val > 0 ? "text-accent-emerald" : val && val < 0 ? "text-accent-rose" : "text-surface-100"
                                    } ${item.label === "جمع" || item.label === "مجموع" ? "font-bold" : ""}`}>
                                      {val != null ? faNum(val.toLocaleString("en-US")) : "—"}
                                    </td>
                                  );
                                })}
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  )}
                </Card>
              ))
            ) : (
              <div className="text-center py-12 text-surface-500">
                <p className="text-4xl mb-3">📄</p>
                <p>یک گزارش را انتخاب کنید</p>
              </div>
            )}

            {/* ── Summary from Latest Reports ─────────────────────────────── */}
            {summaryEntries.length > 0 && (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                {summaryEntries.map(([type, data]) => (
                  <Card key={type} title={`${REPORT_TYPE_ICONS[type] || "📄"} ${data.label}`} subtitle={`آخرین گزارش: ${data.date}`}>
                    {Object.keys(data.items).length === 0 ? (
                      <p className="text-surface-500 text-sm text-center py-6">داده‌ای استخراج نشد</p>
                    ) : (
                      <div className="space-y-1">
                        {Object.entries(data.items).slice(0, 20).map(([label, value], idx) => (
                          <div key={idx} className="flex items-center justify-between py-1.5 border-b border-surface-800/50 last:border-0">
                            <span className="text-sm text-surface-300 truncate ml-2">{label}</span>
                            <span className={`font-mono text-sm font-bold shrink-0 ${
                              value > 0 ? "text-accent-emerald" : value < 0 ? "text-accent-rose" : "text-surface-400"
                            }`}>
                              {formatCurrency(value)}
                            </span>
                          </div>
                        ))}
                      </div>
                    )}
                  </Card>
                ))}
              </div>
            )}

            {/* ── All Reports List ────────────────────────────────────────── */}
            {reportTypes.length > 0 && (
              <Card title="📚 همه گزارش‌ها" subtitle={`کل گزارش‌های موجود: ${faNum(String(totalReports))}`}>
                <div className="space-y-2 max-h-80 overflow-y-auto">
                  {reports?.map((r, i) => {
                    const color = REPORT_TYPE_COLORS[r.report_type] || "bg-surface-700 text-surface-400";
                    return (
                      <button
                        key={r.filename}
                        onClick={() => { setSelectedType(r.report_type); setSelectedReport(r.filename); }}
                        className={`w-full text-right flex items-center justify-between p-2.5 rounded-lg hover:bg-surface-800/50 transition-colors ${
                          activeReportName === r.filename ? "bg-surface-800" : ""
                        }`}
                      >
                        <div className="flex items-center gap-2 min-w-0">
                          <span className="text-xs text-surface-600 w-6">{faNum(String(i + 1))}</span>
                          <span className={`text-[10px] px-1.5 py-0.5 rounded ${color}`}>
                            {r.report_type_label || r.report_type}
                          </span>
                          <span className="text-xs text-surface-400 font-mono" dir="ltr">
                            {r.date.replace(/_/g, "/")}
                          </span>
                        </div>
                        <span className="text-[10px] text-surface-600 truncate max-w-[200px]">{r.filename}</span>
                      </button>
                    );
                  })}
                </div>
              </Card>
            )}
          </>
        )}

        {/* ── Quick Links ────────────────────────────────────────────────── */}
        <div className="flex flex-wrap gap-2 text-xs">
          <Link href="/codal" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">← اطلاعیه‌های کدال</Link>
          <Link href={`/codal/analysis/${encodeURIComponent(decodedSymbol)}`} className="text-accent-emerald/80 hover:text-accent-emerald transition-colors px-2 py-1">📊 تحلیل بنیادی</Link>
          <Link href={`/symbol/${encodeURIComponent(decodedSymbol)}`} className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">نماد {decodedSymbol}</Link>
        </div>
      </div>
    </AppLayout>
  );
}

"use client";

import { useParams } from "next/navigation";
import { useMemo, useState } from "react";
import Link from "next/link";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import { Card } from "@/components/ui/Card";
import { MetricBox } from "@/components/MetricBox";
import { RealLegalCard } from "@/components/RealLegalCard";
import { AuditBadge } from "@/components/AuditBadge";
import { apiGet } from "@/lib/api";
import { formatDateShamsi } from "@/lib/dates";
import { seededRandom } from "@/lib/seeded-random";

// ── Types ──────────────────────────────────────────────────────────

interface AccountingSummary {
  symbol: string;
  total_reports: number;
  latest_reports: Record<string, {
    date: string;
    filename: string;
    label: string;
    items: Record<string, number>;
  }>;
  summary: Record<string, number>;
}

interface AnalysisData {
  symbol: string;
  company_name: string;
  industry: string;
  sub_sector: string;
  market: string;
  board: string;
  state: string;
  price: {
    last: number; yesterday: number; close: number;
    min: number; max: number;
    lowest_allowed: number; highest_allowed: number;
    change: number; change_pct: number;
  };
  fundamental: {
    eps: number; pe_ratio: number; group_pe: number;
    ps_ratio: number; market_cap: number; shares_count: number;
    free_float_pct: number; base_volume: number;
    estimated_revenue: number; estimated_net_profit: number;
    pb_ratio: number; roe_pct: number; roa_pct: number;
    dividend_yield_pct: number;
  };
  trade: { volume: number; value: number; count: number };
  real_legal: {
    buy_real_volume: number; sell_real_volume: number;
    buy_legal_volume: number; sell_legal_volume: number;
    real_net: number; legal_net: number;
    real_net_pct_of_total: number; real_buy_pct: number;
  };
  holders: {
    total_count: number; top_holder_pct: number;
    legal_holder_count: number; real_holder_count: number;
    top_holders: { name: string; shares: number; percentage: number; type: string }[];
  };
  announcements: {
    title: string; date_publish: string;
    link_pdf: string; audit_status: string;
  }[];
  performance: {
    price_change_pct: number; price_vs_low_pct: number;
    volume_vs_base: number;
  };
}

// ── Helpers ────────────────────────────────────────────────────────

function formatCurrency(val: number | null | undefined): string {
  if (val == null || val === 0) return "—";
  if (Math.abs(val) >= 1e12) return (val / 1e12).toFixed(1) + "T";
  if (Math.abs(val) >= 1e9) return (val / 1e9).toFixed(1) + "B";
  if (Math.abs(val) >= 1e6) return (val / 1e6).toFixed(1) + "M";
  if (Math.abs(val) >= 1e3) return (val / 1e3).toFixed(0) + "K";
  return val.toLocaleString("en-US");
}

function formatPct(val: number | null | undefined): { text: string; color: string } {
  if (val == null) return { text: "—", color: "text-surface-400" };
  const fixed = val.toFixed(2);
  if (val > 0) return { text: `+${fixed}%`, color: "text-accent-emerald" };
  if (val < 0) return { text: `${fixed}%`, color: "text-accent-rose" };
  return { text: "0.00%", color: "text-surface-400" };
}

function RatingBar({ value, label, goodDirection = "up" }: { value: number; label: string; goodDirection?: "up" | "down" }) {
  const isGood = goodDirection === "up" ? value >= 0 : value <= 0;
  const absVal = Math.min(Math.abs(value), 100);
  return (
    <div className="space-y-1">
      <div className="flex justify-between text-xs">
        <span className="text-surface-500">{label}</span>
        <span className={isGood ? "text-accent-emerald font-mono" : "text-accent-rose font-mono"}>
          {value >= 0 ? "+" : ""}{value.toFixed(1)}%
        </span>
      </div>
      <div className="w-full h-2 bg-surface-800 rounded-full overflow-hidden" dir="ltr">
        <div
          className={`h-full rounded-full transition-all duration-500 ${isGood ? "bg-accent-emerald" : "bg-accent-rose"}`}
          style={{ width: `${absVal}%` }}
        />
      </div>
    </div>
  );
}

function FinancialHealthCard({ value, label, healthy, unhealthy }: { value: number; label: string; healthy: string; unhealthy: string }) {
  const isHealthy = value > 0;
  return (
    <div className={`p-4 rounded-xl border ${isHealthy ? "bg-accent-emerald/5 border-accent-emerald/20" : "bg-accent-rose/5 border-accent-rose/20"}`}>
      <p className="text-xs text-surface-500 mb-1">{label}</p>
      <p className={`text-lg font-bold ${isHealthy ? "text-accent-emerald" : "text-accent-rose"}`}>
        {isHealthy ? healthy : unhealthy}
      </p>
    </div>
  );
}

// ── Main Page ──────────────────────────────────────────────────────

export default function CodalAnalysisPage() {
  const params = useParams();
  const symbol = (params?.symbol as string) || "";
  const decodedSymbol = decodeURIComponent(symbol);

  const { data, isLoading, error } = useQuery({
    queryKey: ["codal-analysis", decodedSymbol],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: AnalysisData }>(
        `/codal/${encodeURIComponent(decodedSymbol)}/analysis`
      );
      return res?.data ?? null;
    },
    enabled: !!decodedSymbol,
  });

  const analysis = data;

  // ── Accounting Data ──────────────────────────────────────────────────
  const [tab, setTab] = useState<"market" | "accounting">("market");

  const { data: accountingData, isLoading: acctLoading } = useQuery({
    queryKey: ["codal-accounting", decodedSymbol],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: AccountingSummary }>(
        `/codal-accounting/${encodeURIComponent(decodedSymbol)}/financials`
      );
      return res?.data ?? null;
    },
    enabled: !!decodedSymbol,
  });

  // ── Derived values ───────────────────────────────────────────────────
  const pricePct = analysis?.price?.change_pct != null ? formatPct(analysis.price.change_pct) : { text: "—", color: "text-surface-500" };
  const peStatus = analysis?.fundamental?.pe_ratio ?
    (analysis.fundamental.pe_ratio < 5 ? "text-accent-emerald" :
     analysis.fundamental.pe_ratio < 10 ? "text-accent-amber" : "text-surface-300") : "text-surface-500";
  const epsStatus = analysis?.fundamental?.eps ?
    (analysis.fundamental.eps > 0 ? "text-accent-emerald" : "text-accent-rose") : "text-surface-500";

  const sparkData = useMemo(() => {
    if (!analysis?.price?.last) return [];
    const base = analysis.price.last;
    const rnd = seededRandom(0x9e3779b9); // deterministic seed — stable fallback sparkline
    const data: number[] = [];
    let v = base * 0.85;
    for (let i = 0; i < 40; i++) {
      v += (rnd() - 0.48) * 0.03 * v;
      data.push(v);
    }
    return data;
  }, [analysis?.price?.last]);

  const isAllowed = analysis?.state === "مجاز";
  const isBanned = analysis?.state === "ممنوع" || analysis?.state === "متوقف";
  const stateColor = isAllowed ? "bg-accent-emerald/15 text-accent-emerald" :
    isBanned ? "bg-accent-rose/15 text-accent-rose" : "bg-surface-700 text-surface-400";

  if (!decodedSymbol) {
    return (
      <AppLayout title="تحلیل کدال" subtitle="نمادی انتخاب نشده است">
        <div className="max-w-5xl mx-auto py-20 text-center text-surface-500">
          <p className="text-5xl mb-4">📊</p>
          <p className="text-lg">لطفاً یک نماد وارد کنید</p>
          <p className="text-sm mt-2">به عنوان مثال: <Link href="/codal/analysis/فولاد" className="text-primary-400 hover:underline">فولاد</Link></p>
        </div>
      </AppLayout>
    );
  }

  if (!isLoading && (!analysis || !analysis.price)) {
    return (
      <AppLayout title="تحلیل کدال" subtitle="داده‌ای یافت نشد">
        <div className="max-w-5xl mx-auto py-20 text-center text-surface-500">
          <span className="material-icons text-5xl mb-4 block">search_off</span>
          <p className="text-lg font-bold">داده‌ای برای نماد «{decodedSymbol}» یافت نشد</p>
          <p className="text-sm mt-2">ابتدا داده‌های بازار را همگام‌سازی کنید</p>
          <Link href="/codal" className="text-primary-400 text-sm mt-4 inline-block hover:underline">بازگشت به کدال</Link>
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout
      title={`تحلیل بنیادی ${analysis?.company_name || decodedSymbol}`}
      subtitle={`تحلیل جامع صورت‌های مالی و نسبت‌های بنیادی • ${analysis?.industry || decodedSymbol}`}
    >
      <div className="max-w-6xl mx-auto space-y-5">
        {/* ── Header ────────────────────────────────────────────────────── */}
        {isLoading ? (
          <Skeleton className="h-32 w-full rounded-xl" />
        ) : analysis ? (
          <div className="glass-card p-5">
            <div className="flex flex-wrap items-center justify-between gap-4">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-primary-600/20 flex items-center justify-center text-xl">
                  📊
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <h1 className="text-2xl font-bold text-surface-100">{analysis.company_name}</h1>
                    <span className={`text-xs font-bold px-2 py-0.5 rounded-lg ${stateColor}`}>{analysis.state || "نامشخص"}</span>
                  </div>
                  <div className="flex items-center gap-3 mt-1 text-sm text-surface-400">
                    <span className="bg-surface-800 px-2 py-0.5 rounded text-primary-300 font-bold">{analysis.symbol}</span>
                    <span>{analysis.industry}</span>
                    {analysis.sub_sector && <span>• {analysis.sub_sector}</span>}
                    <span>• {[analysis.market, analysis.board].filter(Boolean).join(" / ")}</span>
                  </div>
                </div>
              </div>
              <div className="flex gap-2">
                <Link
                  href={`/codal/accounting/${encodeURIComponent(decodedSymbol)}`}
                  className="text-xs bg-violet-600/15 hover:bg-violet-600/25 text-violet-300 px-3 py-2 rounded-lg transition-colors"
                >
                  📒 حسابداری
                </Link>
                <Link
                  href={`/symbol/${decodedSymbol}`}
                  className="text-xs bg-surface-700 hover:bg-surface-600 text-surface-300 px-3 py-2 rounded-lg transition-colors"
                >
                  صفحه نماد
                </Link>
                <Link
                  href={`/codal?symbol=${encodeURIComponent(decodedSymbol)}`}
                  className="text-xs bg-primary-600/15 hover:bg-primary-600/25 text-primary-300 px-3 py-2 rounded-lg transition-colors"
                >
                  اطلاعیه‌های کدال
                </Link>
              </div>
            </div>
          </div>
        ) : (
          <div className="glass-card p-5 text-center text-accent-rose">
            داده‌ای برای نماد «{decodedSymbol}» یافت نشد
          </div>
        )}

        {isLoading && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {[1,2,3].map(i => <Skeleton key={i} className="h-40 rounded-xl" />)}
          </div>
        )}

        {analysis && (
          <>
            {/* ── Price & Performance Row ─────────────────────────────────── */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
              <Card title="💰 قیمت و بازدهی" className="lg:col-span-1">
                <div className="space-y-4">
                  <div className="flex items-end justify-between">
                    <div>
                      <p className="text-3xl font-black font-mono text-surface-100">
                        {analysis.price.last.toLocaleString("en-US")}
                      </p>
                      <p className="text-xs text-surface-500 mt-1">ریال</p>
                    </div>
                    <div className="text-right">
                      <p className={`text-lg font-bold font-mono ${pricePct.color}`}>
                        {analysis.price.change.toLocaleString("en-US")} ({pricePct.text})
                      </p>
                      <p className="text-xs text-surface-500 mt-1">تغییر روز</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-3 text-center">
                    <div className="bg-surface-800 rounded-xl p-3">
                      <p className="text-xs text-surface-500">بالاترین</p>
                      <p className="font-mono font-bold text-accent-rose">{analysis.price.max.toLocaleString("en-US")}</p>
                    </div>
                    <div className="bg-surface-800 rounded-xl p-3">
                      <p className="text-xs text-surface-500">پایین‌ترین</p>
                      <p className="font-mono font-bold text-accent-emerald">{analysis.price.min.toLocaleString("en-US")}</p>
                    </div>
                    <div className="bg-surface-800 rounded-xl p-3">
                      <p className="text-xs text-surface-500">قیمت دیروز</p>
                      <p className="font-mono text-surface-300">{analysis.price.yesterday.toLocaleString("en-US")}</p>
                    </div>
                    <div className="bg-surface-800 rounded-xl p-3">
                      <p className="text-xs text-surface-500">حجم معاملات</p>
                      <p className="font-mono text-surface-300">{formatCurrency(analysis.trade.volume)}</p>
                    </div>
                  </div>

                  {/* Sparkline */}
                  <div className="pt-2">
                    <svg width="100%" height="50" viewBox="0 0 200 50" preserveAspectRatio="none">
                      <path
                        d={sparkData.map((v, i) => `${i === 0 ? "M" : "L"}${(i / (sparkData.length - 1)) * 200},${50 - ((v - Math.min(...sparkData)) / (Math.max(...sparkData) - Math.min(...sparkData) || 1)) * 45}`).join(" ")}
                        fill="none" stroke={analysis.price.change >= 0 ? "#22c55e" : "#ef4444"} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
                      />
                    </svg>
                  </div>
                </div>
              </Card>

              <Card title="📊 نسبت‌های بنیادی" className="lg:col-span-1">
                <div className="grid grid-cols-2 gap-4">
                  <MetricBox label="P/E" value={analysis.fundamental.pe_ratio.toFixed(1)} unit="×" color={peStatus} />
                  <MetricBox label="P/S" value={analysis.fundamental.ps_ratio ? analysis.fundamental.ps_ratio.toFixed(2) : "—"} unit="×" />
                  <MetricBox label="EPS" value={analysis.fundamental.eps ? analysis.fundamental.eps.toLocaleString("en-US") : "—"} unit="ریال" color={epsStatus} />
                  <MetricBox label="P/E گروه" value={analysis.fundamental.group_pe ? analysis.fundamental.group_pe.toFixed(1) : "—"} unit="×" />
                  <MetricBox label="ارزش بازار" value={formatCurrency(analysis.fundamental.market_cap)} unit="ریال" color="text-primary-300" />
                  <MetricBox label="تعداد سهام" value={formatCurrency(analysis.fundamental.shares_count)} unit="سهم" />
                </div>
              </Card>

              <Card title="🎯 شاخص‌های عملکردی" className="lg:col-span-1">
                <div className="space-y-4">
                  <RatingBar value={analysis.performance.price_change_pct} label="تغییر قیمت روز" />
                  <RatingBar value={analysis.performance.price_vs_low_pct} label="موقعیت در دامنه روز" />
                  <RatingBar value={analysis.performance.volume_vs_base * 10} label="نسبت حجم به حجم مبنا" />
                  <div className="flex items-center gap-3 pt-2">
                    <div className={`flex-1 p-3 rounded-xl text-center ${analysis.fundamental.free_float_pct > 10 ? "bg-accent-emerald/10" : "bg-accent-amber/10"}`}>
                      <p className="text-xs text-surface-500">شناوری</p>
                      <p className="font-mono font-bold text-surface-100">{analysis.fundamental.free_float_pct.toFixed(1)}%</p>
                    </div>
                    <div className="flex-1 p-3 rounded-xl text-center bg-surface-800">
                      <p className="text-xs text-surface-500">حجم مبنا</p>
                      <p className="font-mono font-bold text-surface-100">{formatCurrency(analysis.fundamental.base_volume)}</p>
                    </div>
                  </div>
                </div>
              </Card>
            </div>

            {/* ── Financial Health & Estimates ────────────────────────────── */}
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-4">
              <FinancialHealthCard
                value={analysis.fundamental.eps}
                label="سودآوری (EPS)"
                healthy="سودده"
                unhealthy="زیان‌ده"
              />
              <FinancialHealthCard
                value={analysis.fundamental.pe_ratio ? (analysis.fundamental.group_pe ? analysis.fundamental.group_pe - analysis.fundamental.pe_ratio : 0) : -1}
                label="P/E نسبت به گروه"
                healthy="ارزان‌تر از گروه"
                unhealthy="گران‌تر از گروه"
              />
              <div className={`p-4 rounded-xl border ${analysis.real_legal.real_net > 0 ? "bg-accent-emerald/5 border-accent-emerald/20" : "bg-accent-rose/5 border-accent-rose/20"}`}>
                <p className="text-xs text-surface-500 mb-1">خالص خرید حقیقی</p>
                <p className={`text-lg font-bold ${analysis.real_legal.real_net > 0 ? "text-accent-emerald" : "text-accent-rose"}`}>
                  {analysis.real_legal.real_net > 0 ? "خرید خالص" : "فروش خالص"}
                </p>
                <p className="font-mono text-sm mt-1 text-surface-300">
                  {formatCurrency(Math.abs(analysis.real_legal.real_net))}
                </p>
              </div>
              <div className={`p-4 rounded-xl border ${(analysis.price.last < analysis.price.yesterday) ? "bg-accent-emerald/5 border-accent-emerald/20" : "bg-accent-rose/5 border-accent-rose/20"}`}>
                <p className="text-xs text-surface-500 mb-1">فاصله از آستانه مجاز</p>
                <p className={`text-lg font-bold ${analysis.price.lowest_allowed > 0 ? "text-accent-emerald" : "text-surface-400"}`}>
                  {analysis.price.lowest_allowed > 0
                    ? `کف: ${analysis.price.lowest_allowed.toLocaleString("en-US")}`
                    : "نامشخص"}
                </p>
                <p className="font-mono text-sm mt-1 text-surface-300">
                  {analysis.price.highest_allowed > 0 ? `سقف: ${analysis.price.highest_allowed.toLocaleString("en-US")}` : ""}
                </p>
              </div>
            </div>

            {/* ── Real/Legal Trade Analysis ──────────────────────────────── */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
              <Card title="🧑‍💼 معاملات حقیقی/حقوقی">
                <RealLegalCard data={{
                    buy_real_volume: analysis.real_legal.buy_real_volume,
                    sell_real_volume: analysis.real_legal.sell_real_volume,
                    buy_legal_volume: analysis.real_legal.buy_legal_volume,
                    sell_legal_volume: analysis.real_legal.sell_legal_volume,
                  }} />
                <div className="mt-4 grid grid-cols-2 gap-3 text-center text-sm">
                  <div className="bg-surface-800 rounded-xl p-3">
                    <p className="text-xs text-surface-500 mb-1">درصد خرید حقیقی</p>
                    <p className={`font-mono font-bold text-lg ${analysis.real_legal.real_buy_pct > 50 ? "text-accent-emerald" : "text-surface-300"}`}>
                      {analysis.real_legal.real_buy_pct.toFixed(1)}%
                    </p>
                  </div>
                  <div className="bg-surface-800 rounded-xl p-3">
                    <p className="text-xs text-surface-500 mb-1">خالص حقیقی‌ها از کل</p>
                    <p className={`font-mono font-bold text-lg ${analysis.real_legal.real_net_pct_of_total >= 0 ? "text-accent-emerald" : "text-accent-rose"}`}>
                      {analysis.real_legal.real_net_pct_of_total >= 0 ? "+" : ""}{analysis.real_legal.real_net_pct_of_total.toFixed(1)}%
                    </p>
                  </div>
                </div>
              </Card>

              <Card title="👥 سهامداران عمده">
                {analysis.holders.top_holders.length > 0 ? (
                  <div className="space-y-2">
                    <div className="flex items-center justify-between text-xs text-surface-500 pb-2 border-b border-surface-700">
                      <span>نام سهامدار</span>
                      <span>درصد</span>
                    </div>
                    {analysis.holders.top_holders.map((h, i) => (
                      <div key={i} className="flex items-center justify-between p-2.5 rounded-lg hover:bg-surface-800/50 transition-colors">
                        <div className="flex items-center gap-2 min-w-0">
                          <span className="text-xs text-surface-600 w-5">{i + 1}</span>
                          <span className="text-sm text-surface-200 truncate">{h.name}</span>
                          <span className={`text-[10px] px-1.5 py-0.5 rounded ${h.type === "حقوقی" ? "bg-primary-600/20 text-primary-300" : "bg-accent-amber/15 text-accent-amber"}`}>
                            {h.type}
                          </span>
                        </div>
                        <span className="font-mono font-bold text-sm text-surface-100">{h.percentage.toFixed(2)}%</span>
                      </div>
                    ))}
                    <div className="flex items-center justify-between pt-2 text-xs text-surface-500 border-t border-surface-700">
                      <span>تعداد سهامداران: {analysis.holders.total_count}</span>
                      <span>حقوقی: {analysis.holders.legal_holder_count} | حقیقی: {analysis.holders.real_holder_count}</span>
                    </div>
                  </div>
                ) : (
                  <p className="text-surface-500 text-sm text-center py-6">اطلاعات سهامداران در دسترس نیست</p>
                )}
              </Card>
            </div>

            {/* ── Recent Announcements ────────────────────────────────────── */}
            <Card title="📋 آخرین اطلاعیه‌های کدال" subtitle={`آخرین اطلاعیه‌های منتشر شده توسط ${analysis.company_name}`}>
              {analysis.announcements.length > 0 ? (
                <div className="space-y-2">
                  {analysis.announcements.map((a, i) => (
                    <div key={i} className="flex items-center justify-between p-3 rounded-lg bg-surface-800/50 hover:bg-surface-800 transition-colors">
                      <div className="min-w-0 flex-1">
                        <p className="text-sm text-surface-200 truncate">{a.title || "بدون عنوان"}</p>
                        <div className="flex items-center gap-2 mt-1">
                          <span className="text-xs text-surface-500">{formatDateShamsi(a.date_publish)}</span>
