                      </div>
                      {a.link_pdf && (
                        <a
                          href={a.link_pdf}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="shrink-0 text-xs bg-accent-rose/10 text-accent-rose px-3 py-1.5 rounded-lg hover:bg-accent-rose/20 transition-colors"
