            {/* ── Detailed Metrics Table ──────────────────────────────────── */}
            <Card title="📊 جدول جزئیات بنیادی">
              <div className="overflow-x-auto">
                <table className="w-full text-right text-sm">
                  <thead>
                    <tr className="text-surface-500 border-b border-surface-700 text-xs">
                      <th className="pb-2 px-3 font-medium">معیار</th>
                      <th className="pb-2 px-3 font-medium">مقدار</th>
                      <th className="pb-2 px-3 font-medium">توضیحات</th>
                    </tr>
                  </thead>
                  <tbody>
                    {[
                      { label: "P/E", value: analysis.fundamental.pe_ratio.toFixed(2), desc: analysis.fundamental.pe_ratio < 5 ? "ارزشمند" : analysis.fundamental.pe_ratio < 10 ? "منطقی" : "بالا" },
                      { label: "P/S", value: analysis.fundamental.ps_ratio ? analysis.fundamental.ps_ratio.toFixed(2) : "—", desc: "نسبت قیمت به فروش" },
                      { label: "EPS", value: analysis.fundamental.eps ? analysis.fundamental.eps.toLocaleString("en-US") : "—", desc: analysis.fundamental.eps > 0 ? "سودآور" : "زیان‌ده" },
                      { label: "P/E گروه", value: analysis.fundamental.group_pe ? analysis.fundamental.group_pe.toFixed(2) : "—", desc: "میانگین P/E صنعت" },
                      { label: "ارزش بازار", value: formatCurrency(analysis.fundamental.market_cap) + " ریال", desc: "Market Cap" },
                      { label: "تعداد سهام", value: formatCurrency(analysis.fundamental.shares_count), desc: "کل سهام منتشر شده" },
                      { label: "شناوری", value: analysis.fundamental.free_float_pct ? `${analysis.fundamental.free_float_pct.toFixed(2)}%` : "—", desc: "درصد شناور آزاد" },
                      { label: "حجم مبنا", value: formatCurrency(analysis.fundamental.base_volume), desc: "حداقل حجم برای تأثیر بر قیمت" },
                      { label: "درآمد تخمینی", value: formatCurrency(analysis.fundamental.estimated_revenue) + " ریال", desc: "برآورد از P/S" },
                      { label: "سود خالص تخمینی", value: formatCurrency(analysis.fundamental.estimated_net_profit) + " ریال", desc: "برآورد از EPS × تعداد سهام" },
                      { label: "حجم معاملات", value: formatCurrency(analysis.trade.volume), desc: "حجم کل معاملات روز" },
                      { label: "ارزش معاملات", value: formatCurrency(analysis.trade.value) + " ریال", desc: "ارزش کل معاملات روز" },
                      { label: "تعداد معاملات", value: analysis.trade.count.toLocaleString("en-US"), desc: "تعداد دفعات معامله" },
                      { label: "بالاترین قیمت", value: analysis.price.max.toLocaleString("en-US"), desc: "قیمت حداکثر روز" },
                      { label: "پایین‌ترین قیمت", value: analysis.price.min.toLocaleString("en-US"), desc: "قیمت حداقل روز" },
                      { label: "کف مجاز", value: analysis.price.lowest_allowed ? analysis.price.lowest_allowed.toLocaleString("en-US") : "—", desc: "آستانه پایین مجاز" },
                      { label: "سقف مجاز", value: analysis.price.highest_allowed ? analysis.price.highest_allowed.toLocaleString("en-US") : "—", desc: "آستانه بالای مجاز" },
                      { label: "وضعیت نماد", value: analysis.state || "—", desc: "وضعیت معاملاتی" },
                    ].map((row, i) => (
                      <tr key={i} className="border-b border-surface-800/50 hover:bg-white/5">
                        <td className="py-2.5 px-3 text-surface-500">{row.label}</td>
                        <td className="py-2.5 px-3 font-mono text-surface-200 font-bold">{row.value}</td>
                        <td className="py-2.5 px-3 text-xs text-surface-500">{row.desc}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>

            {/* ── Accounting Section (Codal Excel Files) ──────────────────── */}
            <Card title="📒 اطلاعات حسابداری از صورت‌های مالی کدال" subtitle="داده‌های استخراج شده از فایل‌های اکسل کدال">
              {acctLoading ? (
                <div className="space-y-3">
                  <Skeleton className="h-8 w-full rounded" />
                  <Skeleton className="h-8 w-3/4 rounded" />
                  <Skeleton className="h-8 w-1/2 rounded" />
                </div>
              ) : accountingData && !("error" in accountingData) ? (
                <div className="space-y-4">
                  <div className="flex items-center justify-between text-xs text-surface-500">
                    <span>{accountingData.total_reports} گزارش موجود</span>
                  </div>

                  {Object.entries(accountingData.latest_reports).length === 0 ? (
                    <p className="text-surface-500 text-sm text-center py-6">هیچ گزارش حسابداری برای این نماد یافت نشد</p>
                  ) : (
                    Object.entries(accountingData.latest_reports).map(([rt, report]) => (
                      <div key={rt} className="border border-surface-700 rounded-xl overflow-hidden">
                        <div className="flex items-center justify-between px-4 py-3 bg-surface-800/80">
                          <div>
                            <span className="text-sm font-bold text-surface-200">{report.label}</span>
                            <span className="text-xs text-surface-500 mr-3">تاریخ: {report.date}</span>
                          </div>
                          <span className="text-xs text-surface-500 font-mono">{report.filename}</span>
                        </div>
                        {Object.keys(report.items).length > 0 ? (
                          <div className="overflow-x-auto">
                            <table className="w-full text-right text-sm">
                              <thead>
                                <tr className="text-surface-500 border-b border-surface-700 text-xs">
                                  <th className="pb-2 px-3 font-medium">ردیف</th>
                                  <th className="pb-2 px-3 font-medium">شرح</th>
                                  <th className="pb-2 px-3 font-medium">مبلغ (ریال)</th>
                                </tr>
                              </thead>
                              <tbody>
                                {Object.entries(report.items).map(([label, value], idx) => (
                                  <tr key={idx} className="border-b border-surface-800/50 hover:bg-white/5">
                                    <td className="py-2 px-3 text-xs text-surface-500">{idx + 1}</td>
                                    <td className="py-2 px-3 text-surface-200">{label}</td>
                                    <td className="py-2 px-3 font-mono text-surface-100 font-bold">
                                      {value.toLocaleString("en-US")}
                                    </td>
                                  </tr>
                                ))}
                              </tbody>
                            </table>
                          </div>
                        ) : (
                          <p className="text-surface-500 text-xs text-center py-4">داده‌ای استخراج نشد</p>
                        )}
                      </div>
                    ))
                  )}
                  <div className="text-center pt-2">
                    <Link
                      href={`/codal-accounting/${encodeURIComponent(decodedSymbol)}/reports`}
                      className="text-xs text-primary-400 hover:text-primary-300 transition-colors"
                    >
                      مشاهده همه گزارش‌ها ←
                    </Link>
                  </div>
                </div>
              ) : (
                <p className="text-surface-500 text-sm text-center py-6">داده‌های حسابداری کدال برای این نماد در دسترس نیست</p>
              )}
            </Card>
          </>
        )}

        {/* ── Error State ────────────────────────────────────────────────── */}
        {error && !isLoading && (
          <div className="text-center py-16 text-accent-rose">
            <p className="text-5xl mb-4">⚠️</p>
            <p className="text-lg">خطا در دریافت داده‌های تحلیل</p>
            <p className="text-sm mt-1 text-surface-500">لطفاً بعداً مراجعه کنید</p>
          </div>
        )}

        {/* ── Quick Links ────────────────────────────────────────────────── */}
        <div className="flex flex-wrap gap-2 text-xs">
          <Link href="/codal" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">← اطلاعیه‌های کدال</Link>
          <Link href={`/symbol/${decodedSymbol}`} className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">نماد {decodedSymbol}</Link>
          <Link href="/analysis" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">تحلیل بازار</Link>
          <Link href={`/smart-money?symbol=${decodedSymbol}`} className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">پول هوشمند</Link>
        </div>
      </div>
    </AppLayout>
  );
}

﻿"use client";
import { useState } from "react";
import AppLayout from "@/components/layout/AppLayout";
import { apiGet } from "@/lib/api";
import { useQuery } from "@tanstack/react-query";
import Skeleton from "@/components/Skeleton";

type AuditRow = {
  symbol: string; report_type: string | null; report_date: string | null;
  revenue: number | null; net_profit: number | null; total_assets: number | null; total_equity: number | null; eps: number | null;
  roe: number | null; roa: number | null; gross_margin: number | null; net_margin: number | null;
  current_ratio: number | null; debt_to_equity: number | null; asset_turnover: number | null;
  revenue_growth: number | null; net_profit_growth: number | null;
  health_score: number | null; health_classification: string | null;
  earnings_quality_score: number | null; forensic_risk: string | null;
  total_reports: number; analysis_status: string;
};

interface HealthDistRow { health_classification: string; cnt: number; avg_score: number; }
interface TopRoeRow { symbol: string; roe: number; net_margin: number; health_score: number; health_classification: string; }
interface AuditStatsData { health_distribution: HealthDistRow[]; top_roe: TopRoeRow[]; }

function fmt(v: number | null, pct = false): string {
  if (v === null || v === undefined) return "-";
  if (pct) return (v * 100).toFixed(1) + "%";
  if (Math.abs(v) >= 1e9) return (v / 1e9).toFixed(1) + "Mrd";
  if (Math.abs(v) >= 1e6) return (v / 1e6).toFixed(1) + "M";
  if (Math.abs(v) >= 1e3) return (v / 1e3).toFixed(1) + "K";
  return v.toFixed(2);
}

function hc(c: string | null): string {
  if (c === "Strong") return "text-green-400 bg-green-400/10";
  if (c === "Stable") return "text-blue-400 bg-blue-400/10";
  if (c === "Watchlist") return "text-yellow-400 bg-yellow-400/10";
  if (c === "Risky") return "text-red-400 bg-red-400/10";
  return "text-gray-400 bg-gray-400/10";
}

function hl(c: string | null): string {
  if (c === "Strong") return "قوي";
  if (c === "Stable") return "پايدار";
  if (c === "Watchlist") return "نگاه";
  if (c === "Risky") return "پرخطر";
  return c || "-";
}

export default function CodalAuditPage() {
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [health, setHealth] = useState("");
  const [sortBy, setSortBy] = useState("health_score");
  const [sortDir, setSortDir] = useState("desc");
  const [sel, setSel] = useState<string | null>(null);
  const [tab, setTab] = useState<"table" | "stats">("table");

  const { data: summary, isLoading: sLoad } = useQuery({
    queryKey: ["ca-sum", page, search, health, sortBy, sortDir],
    queryFn: () => apiGet<{ data?: { items?: AuditRow[]; total?: number; total_pages?: number } }>("/codal-audit/summary?page=" + page + "&page_size=50&search=" + search + "&health=" + health + "&sort_by=" + sortBy + "&sort_dir=" + sortDir),
  });

  const { data: stats, isLoading: stLoad } = useQuery({
    queryKey: ["ca-stats"],
    queryFn: () => apiGet<{ data?: AuditStatsData }>("/codal-audit/stats"),
  });

  const { data: sym, isLoading: symLoad } = useQuery({
    queryKey: ["ca-sym", sel],
    queryFn: () => apiGet<{ data?: AuditRow }>("/codal-audit/symbol/" + sel),
    enabled: !!sel,
  });

  const rows: AuditRow[] = summary?.data?.items || [];
  const total = summary?.data?.total || 0;
  const tp = summary?.data?.total_pages || 1;
  const sd = stats?.data || null;

  const th = (label: string, key: string) => (
    <th className="py-3 px-4 text-right font-medium cursor-pointer hover:text-white" onClick={() => { setSortBy(key); setSortDir(sortDir === "desc" ? "asc" : "desc"); }}>{label}</th>
  );

  return (
    <AppLayout title="حسابرسی کدال" subtitle="تحليل مالي تمام نمادها بر اساس گزارش‌هاي کدال">
      <div className="space-y-6">
        <div className="flex gap-2">
          <button onClick={() => setTab("table")} className={"px-4 py-2 rounded-lg text-sm font-medium transition " + (tab === "table" ? "bg-primary-600 text-white" : "bg-surface-800 text-surface-300 hover:bg-surface-700")}>جدول نمادها</button>
          <button onClick={() => setTab("stats")} className={"px-4 py-2 rounded-lg text-sm font-medium transition " + (tab === "stats" ? "bg-primary-600 text-white" : "bg-surface-800 text-surface-300 hover:bg-surface-700")}>آمار کلی</button>
        </div>

        {tab === "stats" && sd && (
          <div className="space-y-6">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {sd.health_distribution.map((h: HealthDistRow) => (
                <div key={h.health_classification} className="bg-surface-800 rounded-xl p-4 border border-surface-700">
                  <div className={"text-sm font-medium " + hc(h.health_classification).split(" ")[0]}>{hl(h.health_classification)}</div>
                  <div className="text-2xl font-bold text-white mt-1">{h.cnt}</div>
                  <div className="text-xs text-surface-400">ميانگين: {fmt(h.avg_score)}</div>
                </div>
              ))}
            </div>
            <div className="bg-surface-800 rounded-xl p-5 border border-surface-700">
              <h3 className="text-lg font-bold text-white mb-4">بيشترين بازده حقوق صاحبان سهام</h3>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead><tr className="text-surface-400 border-b border-surface-700">
                    <th className="py-2 text-right">نماد</th><th className="py-2 text-right">ROE</th><th className="py-2 text-right">حاشيه سود</th><th className="py-2 text-right">امتياز</th><th className="py-2 text-right">وضعيت</th>
                  </tr></thead>
                  <tbody>
                    {sd.top_roe.map((r: TopRoeRow) => (
                      <tr key={r.symbol} className="border-b border-surface-700/50 hover:bg-surface-700/30 cursor-pointer" onClick={() => setSel(r.symbol)}>
                        <td className="py-2 text-white font-medium">{r.symbol}</td>
                        <td className="py-2 text-green-400">{fmt(r.roe)}</td>
                        <td className="py-2 text-surface-300">{fmt(r.net_margin, true)}</td>
                        <td className="py-2 text-surface-300">{fmt(r.health_score)}</td>
                        <td className="py-2"><span className={"px-2 py-0.5 rounded text-xs " + hc(r.health_classification)}>{hl(r.health_classification)}</span></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {tab === "table" && (
          <>
            <div className="flex flex-wrap gap-3 items-center">
              <input type="text" placeholder="جستجوي نماد..." value={search} onChange={(e) => { setSearch(e.target.value); setPage(1); }} className="bg-surface-800 border border-surface-700 rounded-lg px-4 py-2 text-sm text-white placeholder:text-surface-500 focus:outline-none focus:ring-2 focus:ring-primary-500 w-48" />
              <select value={health} onChange={(e) => { setHealth(e.target.value); setPage(1); }} className="bg-surface-800 border border-surface-700 rounded-lg px-4 py-2 text-sm text-white focus:outline-none">
                <option value="">همه وضعيت‌ها</option>
                <option value="Strong">قوي</option>
                <option value="Stable">پايدار</option>
                <option value="Watchlist">نگاه</option>
                <option value="Risky">پرخطر</option>
              </select>
              <select value={sortBy} onChange={(e) => setSortBy(e.target.value)} className="bg-surface-800 border border-surface-700 rounded-lg px-4 py-2 text-sm text-white focus:outline-none">
                <option value="health_score">امتياز سلامت</option>
                <option value="roe">بازده حقوق</option>
                <option value="net_margin">حاشيه سود خالص</option>
                <option value="current_ratio">نسبت جاري</option>
                <option value="debt_to_equity">نسبت بدهي</option>
                <option value="revenue">درآمد</option>
              </select>
              <button onClick={() => setSortDir(sortDir === "desc" ? "asc" : "desc")} className="bg-surface-800 border border-surface-700 rounded-lg px-3 py-2 text-sm text-white hover:bg-surface-700">{sortDir === "desc" ? "↓" : "↑"}</button>
              <span className="text-surface-400 text-sm">{total} نماد</span>
            </div>
            {sLoad ? <Skeleton className="h-96" /> : (
              <div className="bg-surface-800 rounded-xl border border-surface-700 overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead><tr className="text-surface-400 bg-surface-900/50">
                      {th("نماد", "symbol")}{th("وضعيت", "health_score")}{th("ROE", "roe")}{th("حاشيه سود", "net_margin")}
                      <th className="py-3 px-4 text-right font-medium">نسبت جاري</th><th className="py-3 px-4 text-right font-medium">D/E</th>
                      {th("درآمد", "revenue")}{th("سود خالص", "net_profit")}{th("رشد", "revenue_growth")}
                    </tr></thead>
                    <tbody>
                      {rows.map((r) => (
                        <tr key={r.symbol} className="border-t border-surface-700/50 hover:bg-surface-700/30 cursor-pointer transition" onClick={() => setSel(r.symbol)}>
                          <td className="py-3 px-4 text-white font-medium">{r.symbol}</td>
                          <td className="py-3 px-4"><span className={"px-2 py-0.5 rounded text-xs font-medium " + hc(r.health_classification)}>{hl(r.health_classification)}</span></td>
                          <td className="py-3 px-4 text-green-400 font-mono">{fmt(r.roe)}</td>
                          <td className="py-3 px-4 text-surface-300 font-mono">{fmt(r.net_margin, true)}</td>
                          <td className="py-3 px-4 text-surface-300 font-mono">{fmt(r.current_ratio)}</td>
                          <td className="py-3 px-4 text-surface-300 font-mono">{fmt(r.debt_to_equity)}</td>
                          <td className="py-3 px-4 text-surface-300 font-mono">{fmt(r.revenue)}</td>
                          <td className="py-3 px-4 font-mono">{r.net_profit && r.net_profit > 0 ? <span className="text-green-400">{fmt(r.net_profit)}</span> : r.net_profit && r.net_profit < 0 ? <span className="text-red-400">{fmt(r.net_profit)}</span> : <span className="text-surface-500">-</span>}</td>
                          <td className="py-3 px-4 font-mono">{r.revenue_growth !== null ? <span className={r.revenue_growth > 0 ? "text-green-400" : "text-red-400"}>{fmt(r.revenue_growth, true)}</span> : <span className="text-surface-500">-</span>}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="flex justify-between items-center px-4 py-3 bg-surface-900/30 border-t border-surface-700">
                  <span className="text-surface-400 text-sm">صفحه {page} از {tp}</span>
                  <div className="flex gap-2">
                    <button disabled={page <= 1} onClick={() => setPage(page - 1)} className="px-3 py-1 rounded bg-surface-700 text-white text-sm disabled:opacity-50 hover:bg-surface-600">قبلی</button>
                    <button disabled={page >= tp} onClick={() => setPage(page + 1)} className="px-3 py-1 rounded bg-surface-700 text-white text-sm disabled:opacity-50 hover:bg-surface-600">بعدی</button>
                  </div>
                </div>
              </div>
            )}
          </>
        )}

        {sel && (
          <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4" onClick={() => setSel(null)}>
            <div className="bg-surface-800 rounded-2xl border border-surface-700 max-w-2xl w-full max-h-[80vh] overflow-y-auto p-6" onClick={(e) => e.stopPropagation()}>
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-xl font-bold text-white">{sel}</h2>
                <button onClick={() => setSel(null)} className="text-surface-400 hover:text-white text-2xl">&times;</button>
              </div>
              {symLoad ? <Skeleton className="h-48" /> : sym?.data && (
                <div className="space-y-4">
                  <div className="flex items-center gap-3">
                    <span className={"px-3 py-1 rounded-lg text-sm font-medium " + hc(sym.data.health_classification)}>{hl(sym.data.health_classification)}</span>
                    <span className="text-surface-400">امتياز: {fmt(sym.data.health_score)}</span>
                  </div>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                    {[["درآمد", fmt(sym.data.revenue)], ["سود خالص", fmt(sym.data.net_profit)], ["دارايي", fmt(sym.data.total_assets)], ["ROE", fmt(sym.data.roe)], ["ROA", fmt(sym.data.roa)], ["حاشيه سود", fmt(sym.data.net_margin, true)], ["حاشيه ناخالص", fmt(sym.data.gross_margin, true)], ["نسبت جاري", fmt(sym.data.current_ratio)], ["D/E", fmt(sym.data.debt_to_equity)], ["رشد درآمد", fmt(sym.data.revenue_growth, true)], ["رشد سود", fmt(sym.data.net_profit_growth, true)], ["تعداد گزارش", String(sym.data.total_reports || 0)]].map(([l, v]) => (
                      <div key={l} className="bg-surface-900/50 rounded-lg p-3">
                        <div className="text-xs text-surface-400">{l}</div>
                        <div className="text-sm font-medium text-white mt-1">{v}</div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { AuditBadge } from "@/components/AuditBadge";
import { DonutChart } from "@/components/DonutChart";
import AppLayout from "@/components/layout/AppLayout";
import RahavardMarketingBanner from "@/components/RahavardMarketingBanner";
import Skeleton from "@/components/Skeleton";
import { apiGet } from "@/lib/api";
import { formatDateShamsi, formatTime } from "@/lib/dates";
import Link from "next/link";

// ------ Types ------------------------------------------------------------------------------------------------------------------------------------------------

interface CodalAnnouncement {
  id: number;
  symbol: string;
  company_name: string;
  title: string;
  code: string;
  date_title: string;
  date_send: string;
  time_send: string;
  date_publish: string;
  time_publish: string;
  link: string;
  link_pdf: string;
  link_excel: string;
  link_attachment: string;
  audit_status: string;
  fetched_at: string;
  created_at: string;
}

interface PaginatedResult<T> {
  items: T[];
  total: number;
  page: number;
  page_size: number;
  total_pages: number;
}

function AnnouncementCard({ item }: { item: CodalAnnouncement }) {
  const hasPdf = !!item.link_pdf;
  const hasExcel = !!item.link_excel;
  const hasAttachment = !!item.link_attachment;
  const hasSymbol = !!item.symbol;

  return (
    <div className="glass-card p-4 hover:bg-surface-800/50 transition-colors">
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0 flex-1">
          {/* Symbol + Company + Audit Badge */}
          <div className="flex items-center gap-2 mb-1.5">
            <Link
              href={`/symbol/${item.symbol}`}
              className="text-xs font-bold bg-primary-600/15 text-primary-300 px-2 py-0.5 rounded-md hover:bg-primary-600/25 transition-colors"
            >
              {item.symbol || "—"}
            </Link>
            {hasSymbol && (
              <Link
                href={`/codal/analysis/${encodeURIComponent(item.symbol)}`}
                className="text-[10px] bg-accent-emerald/10 text-accent-emerald px-1.5 py-0.5 rounded-md hover:bg-accent-emerald/20 transition-colors"
                title="تحلیل بنیادی"
              >
                📊
              </Link>
            )}
            <span className="text-xs text-surface-400 truncate">
              {item.company_name || ""}
            </span>
            <AuditBadge status={item.audit_status} />
          </div>

          {/* Title */}
          <h3 className="text-sm font-medium text-surface-100 leading-relaxed line-clamp-2">
            {item.title || "بدون عنوان"}
          </h3>

          {/* Date + Time */}
          <div className="flex items-center gap-3 mt-2 text-xs text-surface-500">
            <span>📅 {formatDateShamsi(item.date_publish)}</span>
            {item.time_publish && <span>⏰ {formatTime(item.time_publish)}</span>}
          </div>
        </div>

        {/* Action buttons */}
        <div className="flex flex-col gap-1.5 shrink-0">
          {hasPdf && (
            <a
              href={item.link_pdf}
              target="_blank"
              rel="noopener noreferrer"
              className="text-xs bg-accent-rose/10 text-accent-rose px-2.5 py-1 rounded-lg hover:bg-accent-rose/20 transition-colors text-center whitespace-nowrap"
            >
              📄 PDF
            </a>
          )}
          {hasExcel && (
            <a
              href={item.link_excel}
              target="_blank"
              rel="noopener noreferrer"
              className="text-xs bg-accent-emerald/10 text-accent-emerald px-2.5 py-1 rounded-lg hover:bg-accent-emerald/20 transition-colors text-center whitespace-nowrap"
            >
              📊 Excel
            </a>
          )}
          {!hasPdf && !hasExcel && hasAttachment && (
            <a
              href={item.link_attachment}
              target="_blank"
              rel="noopener noreferrer"
              className="text-xs bg-primary-600/10 text-primary-300 px-2.5 py-1 rounded-lg hover:bg-primary-600/20 transition-colors text-center whitespace-nowrap"
            >
              🔗 مشاهده
            </a>
          )}
        </div>
      </div>
    </div>
  );
}

function AnnouncementSkeleton() {
  return (
    <div className="glass-card p-4">
      <div className="flex gap-2 mb-2">
        <Skeleton className="h-5 w-16 rounded-md" />
        <Skeleton className="h-5 w-32 rounded-md" />
      </div>
      <Skeleton className="h-4 w-full mb-2 rounded" />
      <Skeleton className="h-4 w-3/4 rounded" />
      <div className="flex gap-3 mt-2">
        <Skeleton className="h-3 w-24 rounded" />
        <Skeleton className="h-3 w-16 rounded" />
      </div>
    </div>
  );
}

const CATEGORIES = [
  { value: "", label: "همه دسته‌بندی‌ها" },
  { value: "1", label: "صورت مالی سالانه" },
  { value: "2", label: "افشای اطلاعات بااهمیت" },
  { value: "3", label: "گزارش عملکرد ماهانه" },
  { value: "4", label: "اساسنامه/امیدنامه" },
  { value: "5", label: "هیئت مدیره و کمیته حسابرسی" },
  { value: "6", label: "دعوت به مجامع و تصمیمات" },
  { value: "7", label: "افزایش سرمایه" },
  { value: "8", label: "شفاف‌سازی بورس/فرابورس" },
  { value: "9", label: "شفاف‌سازی سازمان" },
  { value: "10", label: "سایر" },
  { value: "11", label: "اوراق بدهی" },
];

interface BrsApiSearchResult {
  count_announcement: number;
  count_page: number;
  announcements: CodalAnnouncement[];
}

export default function CodalPage() {
  const [searchSymbol, setSearchSymbol] = useState("");
  const [category, setCategory] = useState("");
  const [auditFilter, setAuditFilter] = useState("");
  const [dateStart, setDateStart] = useState("");
  const [dateEnd, setDateEnd] = useState("");
  const [page, setPage] = useState(1);

  const hasAdvancedFilters = category !== "" || dateStart !== "" || dateEnd !== "";

  // Build query params for the API call
  const queryKey = ["codal-announcements", searchSymbol, category, auditFilter, dateStart, dateEnd, page];

  const { data, isLoading } = useQuery({
    queryKey,
    queryFn: async () => {
      // When advanced filters or audit filter is active, use BrsApi proxy
      if (hasAdvancedFilters || auditFilter) {
        const params = new URLSearchParams();
        if (searchSymbol.trim()) params.set("symbol", searchSymbol.trim());
        if (category) params.set("category", category);
        if (auditFilter === "audited") { params.set("audited", "true"); params.set("unaudited", "false"); }
        else if (auditFilter === "unaudited") { params.set("audited", "false"); params.set("unaudited", "true"); }
        if (dateStart) params.set("date_start", dateStart);
        if (dateEnd) params.set("date_end", dateEnd);
        params.set("page", String(page));

        const res = await apiGet<{ success: boolean; data: BrsApiSearchResult }>(
          `/codal/brsapi-search?${params.toString()}`
        );
        if (!res?.success || !res?.data) {
          return { items: [], total: 0, page: 1, page_size: 50, total_pages: 0 };
        }
        const items = res.data.announcements ?? [];
        const total = res.data.count_announcement ?? items.length;
        const totalPages = Math.max(1, res.data.count_page ?? 1);
        return { items, total, page, page_size: items.length, total_pages: totalPages };
      }

      // Default: search local database (codal_reports table with 236K+ records)
      const params = new URLSearchParams();
      if (searchSymbol.trim()) params.set("symbol", searchSymbol.trim());
      params.set("page", String(page));
      params.set("page_size", "50");

      const res = await apiGet<{ success: boolean; data: { items: CodalAnnouncement[]; total: number; page: number; page_size: number; total_pages: number } }>(
        `/codal?${params.toString()}`
      );
      return res?.data ?? { items: [], total: 0, page: 1, page_size: 50, total_pages: 0 };
    },
    placeholderData: (prev) => prev,
    refetchInterval: hasAdvancedFilters ? 60_000 : 120_000,
  });

  const announcements = data?.items ?? [];
  const total = data?.total ?? 0;
  const totalPages = Math.max(1, data?.total_pages ?? 1);

  // Audit stats
  const auditedCount = data?.items ? data.items.filter((a: CodalAnnouncement) => a.audit_status === "audited").length : 0;
  const unauditedCount = data?.items ? data.items.filter((a: CodalAnnouncement) => a.audit_status === "unaudited").length : 0;
  const unknownCount = data?.items ? data.items.length - auditedCount - unauditedCount : 0;

  // Trigger search on Enter
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      setPage(1);
    }
  };

  const handleCategoryChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setCategory(e.target.value);
    setPage(1);
  };

  const handleAuditFilterChange = (value: string) => {
    setAuditFilter(auditFilter === value ? "" : value);
    setPage(1);
  };

  return (
    <AppLayout title="اطلاعیه‌های کدال" subtitle="جستجو و مشاهده اطلاعیه‌های شرکت‌های پذیرفته شده در بورس">
      <div className="max-w-5xl mx-auto space-y-5">

        {/* ------ Header --------------------------------------------------------------------------------------------------------- */}
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h1 className="text-2xl font-bold text-surface-100">اطلاعیه‌های کدال</h1>
            <p className="text-sm text-surface-500 mt-1">جستجو و مشاهده اطلاعیه‌های شرکت‌ها</p>
          </div>
          <div className="flex gap-2">
            <Link
              href="/codal/analysis/فولاد"
              className="text-sm bg-accent-emerald/15 text-accent-emerald px-4 py-2 rounded-xl hover:bg-accent-emerald/25 transition-colors"
            >
              📊 تحلیل بنیادی
            </Link>
            <Link
              href="/codal/import"
              className="text-sm bg-primary-600/15 text-primary-300 px-4 py-2 rounded-xl hover:bg-primary-600/25 transition-colors"
            >
              + ورود اطلاعات کدال
            </Link>
          </div>
        </div>

        {/* Marketing Banner */}
        <RahavardMarketingBanner />

        {/* ------ Filters ------------------------------------------------------------------------------------------------------ */}
        <div className="glass-card p-4">
          <div className="flex flex-wrap items-end gap-3">
            {/* Symbol */}
            <div className="flex-1 min-w-[140px]">
              <label className="block text-xs text-surface-500 mb-1">نماد</label>
              <input
                type="text"
                value={searchSymbol}
                onChange={(e) => setSearchSymbol(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="مثال: فولاد"
                className="w-full bg-surface-800 border border-surface-700 rounded-lg px-3 py-2 text-sm text-surface-100 outline-none focus:border-primary-500"
              />
            </div>

            {/* Category */}
            <div className="min-w-[160px]">
              <label className="block text-xs text-surface-500 mb-1">دسته‌بندی</label>
              <select
                value={category}
                onChange={handleCategoryChange}
                className="w-full bg-surface-800 border border-surface-700 rounded-lg px-3 py-2 text-sm text-surface-100 outline-none focus:border-primary-500 appearance-none cursor-pointer"
              >
                {CATEGORIES.map((cat) => (
                  <option key={cat.value} value={cat.value}>{cat.label}</option>
                ))}
              </select>
            </div>

            {/* Audit Filter */}
            <div className="flex flex-col gap-1">
              <label className="block text-xs text-surface-500 mb-1">وضعیت حسابرسی</label>
              <div className="flex gap-1">
                <button
                  onClick={() => handleAuditFilterChange("audited")}
                  className={`px-2.5 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                    auditFilter === "audited"
                      ? "bg-accent-emerald/20 text-accent-emerald border border-accent-emerald/30"
                      : "bg-surface-800 text-surface-400 border border-surface-700 hover:text-surface-200"
                  }`}
                >
                  ✓ حسابرسی شده
                </button>
                <button
                  onClick={() => handleAuditFilterChange("unaudited")}
                  className={`px-2.5 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                    auditFilter === "unaudited"
                      ? "bg-accent-amber/20 text-accent-amber border border-accent-amber/30"
                      : "bg-surface-800 text-surface-400 border border-surface-700 hover:text-surface-200"
                  }`}
                >
                  ! حسابرسی نشده
                </button>
              </div>
            </div>

            {/* Date Start */}
            <div className="min-w-[130px]">
              <label className="block text-xs text-surface-500 mb-1">از تاریخ</label>
              <input
                type="text"
                value={dateStart}
                onChange={(e) => setDateStart(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="۱۴۰۳-۰۱-۰۱"
                className="w-full bg-surface-800 border border-surface-700 rounded-lg px-3 py-2 text-sm text-surface-100 font-mono outline-none focus:border-primary-500"
              />
            </div>

            {/* Date End */}
            <div className="min-w-[130px]">
              <label className="block text-xs text-surface-500 mb-1">تا تاریخ</label>
              <input
                type="text"
                value={dateEnd}
                onChange={(e) => setDateEnd(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="۱۴۰۳-۱۲-۲۹"
                className="w-full bg-surface-800 border border-surface-700 rounded-lg px-3 py-2 text-sm text-surface-100 font-mono outline-none focus:border-primary-500"
              />
            </div>

            {/* Search button */}
            <button
              onClick={() => setPage(1)}
              className="bg-primary-600 hover:bg-primary-500 text-white px-5 py-2 rounded-lg text-sm font-medium transition-colors"
            >
              🔍 جستجو
            </button>

            {/* Loading indicator */}
            {isLoading && (
              <span className="w-2 h-2 rounded-full bg-accent-amber animate-pulse" />
            )}
          </div>

          {/* Result count */}
          {!isLoading && total > 0 && (
            <div className="mt-3 text-xs text-surface-500">
              {total.toLocaleString("en-US")} اطلاعیه یافت شد
              {searchSymbol && " برای نماد \"" + searchSymbol + "\""}
            </div>
          )}
        </div>

        {/* ------ Audit Stats Donut ------------------------------------------------------------------ */}
        {!isLoading && announcements.length > 0 && (
          <div className="glass-card p-4">
            <DonutChart
              slices={[
                { label: "حسابرسی شده", value: auditedCount, color: "#22c55e" },
                { label: "حسابرسی نشده", value: unauditedCount, color: "#f59e0b" },
                ...(unknownCount > 0
                  ? [{ label: "نامشخص", value: unknownCount, color: "#6b7280" }]
                  : []
                ),
              ]}
              centerLabel="اطلاعیه"
            />
          </div>
        )}

        {/* ------ Results ------------------------------------------------------------------------------------------------------ */}
        {isLoading && announcements.length === 0 ? (
          <div className="space-y-3">
            {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
              <AnnouncementSkeleton key={i} />
            ))}
          </div>
        ) : announcements.length > 0 ? (
          <>
            <div className="space-y-3">
              {announcements.map((item, i) => (
                <AnnouncementCard key={item.id ?? i} item={item} />
              ))}
            </div>

            {/* ------ Pagination --------------------------------------------------------------------------------- */}
            {totalPages > 1 && (
              <div className="flex items-center justify-center gap-2 py-3">
                <button
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={page <= 1}
                  className="px-3 py-1.5 rounded-lg text-xs bg-surface-800 text-surface-400 hover:text-surface-200 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                >
                  ← قبلی
                </button>
                {Array.from({ length: Math.min(totalPages, 7) }, (_, i) => {
                  const pageNum = i + 1;
                  return (
                    <button
                      key={pageNum}
                      onClick={() => setPage(pageNum)}
                      className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                        page === pageNum
                          ? "bg-primary-600 text-white"
                          : "bg-surface-800 text-surface-400 hover:text-surface-200"
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                })}
                {totalPages > 7 && <span className="text-surface-500 text-xs">...</span>}
                <button
                  onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                  disabled={page >= totalPages}
                  className="px-3 py-1.5 rounded-lg text-xs bg-surface-800 text-surface-400 hover:text-surface-200 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                >
                  بعدی →
                </button>
              </div>
            )}
          </>
        ) : (
          <div className="text-center py-16 text-surface-500">
            <p className="text-5xl mb-4">📭</p>
            <p className="text-lg">هیچ اطلاعیه‌ای یافت نشد</p>
            <p className="text-sm mt-1">فیلترهای جستجو را تغییر دهید یا بعداً مراجعه کنید</p>
          </div>
        )}

        {/* ------ Quick Links ------------------------------------------------------------------------------------------ */}
        <div className="flex flex-wrap gap-2 text-xs">
          <Link href="/instruments" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            ← همه نمادها
          </Link>
          <Link href="/symbol/فولاد" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            نماد فولاد
          </Link>
          <Link href="/codal/analysis/فولاد" className="text-accent-emerald/80 hover:text-accent-emerald transition-colors px-2 py-1">
            📊 تحلیل بنیادی فولاد
          </Link>
          <Link href="/analysis" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            تحلیل بازار
          </Link>
        </div>
      </div>
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import { apiGet } from "@/lib/api";

interface CryptoPrice {
  name: string;
  symbol: string;
  price_usd: number;
  price_toman: number;
  change_percent: number;
  market_cap: number;
  volume_24h: number;
  icon_url: string;
  rank: number;
  high_24h: number;
  low_24h: number;
  ath: number;
  atl: number;
}

interface TimeframeData {
  timeframe: string;
  label: string;
  change: number;
  volume: number;
  high: number;
  low: number;
}

type Timeframe = "1H" | "4H" | "1D" | "1W" | "1M";

const timeframes: { key: Timeframe; label: string }[] = [
  { key: "1H", label: "۱ ساعته" },
  { key: "4H", label: "۴ ساعته" },
  { key: "1D", label: "روزانه" },
  { key: "1W", label: "هفتگی" },
  { key: "1M", label: "ماهانه" },
];

function PriceCard({ crypto, selectedTimeframe }: { crypto: CryptoPrice; selectedTimeframe: Timeframe }) {
  const isPositive = crypto.change_percent >= 0;

  const timeframeChanges: Record<Timeframe, number> = {
    "1H": crypto.change_percent * 0.15,
    "4H": crypto.change_percent * 0.4,
    "1D": crypto.change_percent,
    "1W": crypto.change_percent * 2.5,
    "1M": crypto.change_percent * 8.5,
  };

  const timeframeChange = timeframeChanges[selectedTimeframe];

  return (
    <div className="glass-card p-4 hover:border-primary-500/30 transition-all cursor-pointer group">
