            {crypto.volume_24h ? `$${(crypto.volume_24h / 1e9).toFixed(2)}B` : "—"}
          </div>
        </div>
        <div className="bg-surface-800/50 rounded-lg p-2">
          <div className="text-surface-500 mb-1">ارزش بازار</div>
          <div className="font-mono text-surface-300">
