import { apiGet } from "@/lib/api";
import { generateMockOrderBook } from "@/lib/types";
import type { OrderBookEntry } from "@/lib/types";
import { useClientData } from "@/hooks/useClientData";
import SSRSafe from "@/components/SSRSafe";

const HIGH_VOLUME_SYMBOLS = [
  { symbol: "فولاد", price: "۱۲,۴۵۰", bidVol: "۸۵,۰۰۰", askVol: "۲۵,۰۰۰", ratio: 3.40, positive: true },
  { symbol: "پترول", price: "۲۳,۸۹۰", bidVol: "۷۲,۰۰۰", askVol: "۳۸,۰۰۰", ratio: 1.89, positive: true },
  { symbol: "خودرو", price: "۸,۷۶۰", bidVol: "۴۵,۰۰۰", askVol: "۸۲,۰۰۰", ratio: 0.55, positive: false },
  { symbol: "مس", price: "۲۵,۶۸۰", bidVol: "۶۳,۰۰۰", askVol: "۲۸,۰۰۰", ratio: 2.25, positive: true },
  { symbol: "کالا", price: "۱۸,۲۳۰", bidVol: "۵۸,۰۰۰", askVol: "۳۵,۰۰۰", ratio: 1.66, positive: true },
  { symbol: "وغدیر", price: "۱۵,۳۴۰", bidVol: "۴۹,۰۰۰", askVol: "۳۲,۰۰۰", ratio: 1.53, positive: true },
];

export default function MarketDepthPage() {
  const [depthView, setDepthView] = useState<"count" | "volume" | "value">("count");
  const symbol = "فولاد";
  const [mockOrderBook] = useClientData(() => generateMockOrderBook(), {
    bids: [] as OrderBookEntry[],
    asks: [] as OrderBookEntry[],
    lastPrice: 0,
  });

  const { data: orderBook } = useQuery({
    queryKey: ["orderbook", symbol],
    queryFn: async () => {
      try {
        const res = await apiGet<{ success: boolean; data: { bids: OrderBookEntry[]; asks: OrderBookEntry[] } }>(`/orderbooks/${encodeURIComponent(symbol)}`);
        if (res?.data) {
          return { bids: res.data.bids || [], asks: res.data.asks || [], lastPrice: res.data.asks?.[0]?.price || 0 };
        }
      } catch {}
      return mockOrderBook;
    },
    staleTime: 15000,
  });

  const ob = orderBook || mockOrderBook;

  return (
    <AppLayout>
      <div className="dashboard-grid">
        <Card title={"دفتر سفارشات - " + symbol}>
          <SSRSafe className="order-book">
            <div className="order-side">
              <div className="order-header">
                <div className="order-title">تقاضا</div>
                <div className="order-title">حجم</div>
              </div>
              <div className="order-rows">
                {ob.bids.map((bid, i) => (
                  <div key={i} className="order-row bid-row" style={{ "--width": `${(bid.volume / ob.bids[0]?.volume || 1) * 100}%` } as React.CSSProperties}>
                    <span className="order-price bid-price">{bid.price.toLocaleString("en-US")}</span>
                    <span className="order-volume">{bid.volume.toLocaleString("en-US")}</span>
                  </div>
                ))}
              </div>
            </div>
            <div className="order-spread">
              <span>اسپرد: {ob.asks[0]?.price - ob.bids[0]?.price || 0}</span>
            </div>
            <div className="order-side">
              <div className="order-header">
                <div className="order-title">عرضه</div>
                <div className="order-title">حجم</div>
              </div>
              <div className="order-rows">
                {ob.asks.map((ask, i) => (
                  <div key={i} className="order-row ask-row" style={{ "--width": `${(ask.volume / ob.asks[0]?.volume || 1) * 100}%` } as React.CSSProperties}>
                    <span className="order-price ask-price">{ask.price.toLocaleString("en-US")}</span>
                    <span className="order-volume">{ask.volume.toLocaleString("en-US")}</span>
                  </div>
                ))}
              </div>
            </div>
          </SSRSafe>
        </Card>

        <Card title="نمادهای پرحجم">
          <SSRSafe>
            <table className="w-full text-right text-sm">
              <thead>
                <tr className="text-surface-500 border-b border-surface-700 text-xs">
                  <th className="pb-2 px-1">نماد</th>
                  <th className="pb-2 px-1">قیمت</th>
                  <th className="pb-2 px-1">حجم تقاضا</th>
                  <th className="pb-2 px-1">حجم عرضه</th>
                  <th className="pb-2 px-1">نسبت</th>
                </tr>
              </thead>
              <tbody>
                {HIGH_VOLUME_SYMBOLS.map((s, i) => (
                  <tr key={`${s.symbol}-${i}`} className="border-b border-surface-800/50 text-xs">
                    <td className="py-2 px-1 font-medium text-surface-200">{s.symbol}</td>
                    <td className="py-2 px-1 font-mono text-surface-200">{s.price}</td>
                    <td className="py-2 px-1 font-mono text-accent-emerald">{s.bidVol}</td>
                    <td className="py-2 px-1 font-mono text-accent-rose">{s.askVol}</td>
                    <td className="py-2 px-1 font-mono" style={{ color: s.positive ? "var(--positive)" : "var(--negative)" }}>{s.ratio.toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </SSRSafe>
        </Card>
      </div>
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import { Card } from "@/components/ui/Card";
import Skeleton from "@/components/Skeleton";
import AddAlertButton from "@/components/AddAlertButton";
import { apiGet } from "@/lib/api";

// ── Types ──────────────────────────────────────────────────────────────────

interface MarketSummary {
  index_value: number;
  index_change: number;
  index_change_pct: number;
  index_equal_weight: number;
  index_equal_weight_change: number;
  index_equal_weight_change_pct: number;
  total_trade_value: number;
  total_volume: number;
  net_real_money_flow: number;
  buy_queue_value: number;
  sell_queue_value: number;
  equity_fund_value: number;
  equity_fund_net: number;
  fixed_income_fund_value: number;
  fixed_income_fund_net: number;
}

interface SymbolStats {
  total: number;
  positive: number;
  negative: number;
  unchanged: number;
  above_closing: number;
  below_closing: number;
  buy_queue: number;
  sell_queue: number;
}

interface MoneyFlowItem {
  name: string;
  symbol?: string;
  value: number;
}

interface MarketWatchData {
  date: string;
  market: string;
  sector_filter: string | null;
  summary: MarketSummary;
  symbol_stats: SymbolStats;
  sector_money_flow: { inflow: MoneyFlowItem[]; outflow: MoneyFlowItem[] };
  stock_money_flow: { inflow: MoneyFlowItem[]; outflow: MoneyFlowItem[] };
  sector_trade_values: MoneyFlowItem[];
  sectors: string[];
}

// ── Tab Config ─────────────────────────────────────────────────────────────

const MARKET_TABS = [
  { key: "all", label: "کل بازار" },
  { key: "bourse", label: "بازار بورس" },
  { key: "farabourse", label: "بازار فرابورس" },
  { key: "top30", label: "30 شرکت بزرگ" },
  { key: "top50", label: "50 شرکت برتر" },
];

// ── Helper Components ──────────────────────────────────────────────────────

function StatCard({ label, value, change, unit, color }: {
  label: string;
  value: string | number;
  change?: number;
  unit?: string;
  color?: string;
}) {
  const changeColor = change != null
    ? change >= 0 ? "text-accent-emerald" : "text-accent-rose"
    : "";
  return (
    <div className="bg-surface-800/50 rounded-xl p-4 border border-surface-700/50">
      <div className="text-xs text-surface-500 mb-1">{label}</div>
      <div className={`text-lg font-bold font-mono ${color || "text-surface-100"}`}>
        {typeof value === "number" ? value.toLocaleString("en-US") : value}
        {unit && <span className="text-xs text-surface-500 mr-1">{unit}</span>}
      </div>
      {change != null && (
        <div className={`text-xs font-mono mt-0.5 ${changeColor}`}>
          {change >= 0 ? "+" : ""}{change.toLocaleString("en-US")} ({change >= 0 ? "+" : ""}{((change / (Math.abs(value as number) || 1)) * 100).toFixed(2)}%)
        </div>
      )}
    </div>
  );
}

function FlowList({ title, items, color }: {
  title: string;
  items: MoneyFlowItem[];
  color: "emerald" | "rose";
}) {
  const bg = color === "emerald" ? "bg-accent-emerald/10" : "bg-accent-rose/10";
  const text = color === "emerald" ? "text-accent-emerald" : "text-accent-rose";
  return (
    <div className="bg-surface-800/50 rounded-xl p-4 border border-surface-700/50">
      <div className="text-sm font-bold text-surface-200 mb-3">{title}</div>
      <div className="space-y-2 max-h-64 overflow-y-auto">
        {items.length === 0 ? (
          <div className="text-xs text-surface-500 text-center py-4">داده‌ای موجود نیست</div>
        ) : (
          items.map((item, i) => (
            <div key={i} className="flex items-center justify-between text-xs gap-2">
              <span className="text-surface-300 truncate max-w-[50%]">
                {item.symbol || item.name}
              </span>
              <span className={`font-mono font-bold ${text}`}>
                {item.value.toLocaleString("en-US")}
              </span>
              {(item.symbol || item.name) && (
                <AddAlertButton compact symbol={item.symbol || item.name || ""} market="stock" />
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
}

// ── Main Page ──────────────────────────────────────────────────────────────

export default function MarketWatchPage() {
  const [activeTab, setActiveTab] = useState("all");
  const [selectedSector, setSelectedSector] = useState<string>("");

  const { data, isLoading } = useQuery({
    queryKey: ["market-watch", activeTab, selectedSector],
    queryFn: async () => {
      const params = new URLSearchParams({ market: activeTab });
      if (selectedSector) params.set("sector", selectedSector);
      const res = await apiGet<{ success: boolean; data: MarketWatchData }>(
        `/market-watch?${params.toString()}`
      );
      return res?.data ?? null;
    },
    refetchInterval: 300_000,
    staleTime: 60_000,
  });

  const summary = data?.summary;
  const stats = data?.symbol_stats;

  return (
    <AppLayout title="📋 دیدبان بازار" subtitle="خلاصه معاملات بازار سرمایه">
      <div className="max-w-7xl mx-auto space-y-4">
        {/* ── Tabs ── */}
        <div className="flex items-center gap-2 flex-wrap">
          {MARKET_TABS.map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                activeTab === tab.key
                  ? "bg-primary-600 text-white shadow-lg shadow-primary-600/20"
                  : "bg-surface-800 text-surface-400 hover:text-surface-200 hover:bg-surface-700"
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* ── Sector Filter ── */}
        {data?.sectors && data.sectors.length > 0 && (
          <div className="flex items-center gap-3">
            <select
              value={selectedSector}
              onChange={(e) => setSelectedSector(e.target.value)}
              className="bg-surface-800 border border-surface-700 rounded-lg px-4 py-2 text-sm text-surface-200 outline-none focus:border-primary-500"
            >
              <option value="">--- انتخاب گروه ---</option>
              {data.sectors.map((s) => (
                <option key={s} value={s}>{s}</option>
              ))}
            </select>
            {selectedSector && (
              <button
                onClick={() => setSelectedSector("")}
                className="text-xs text-surface-500 hover:text-surface-300"
              >
                پاک کردن فیلتر
              </button>
            )}
          </div>
        )}

        {isLoading ? (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
              <Skeleton key={i} className="h-24 rounded-xl" />
            ))}
          </div>
        ) : data ? (
          <>
            {/* ── Date ── */}
            <div className="text-xs text-surface-500">
              تاریخ: {data.date}
            </div>

            {/* ── Summary Cards ── */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              <StatCard
                label="شاخص کل"
                value={summary?.index_value ?? 0}
                change={summary?.index_change ?? 0}
              />
              <StatCard
                label="شاخص هم وزن"
                value={summary?.index_equal_weight ?? 0}
                change={summary?.index_equal_weight_change ?? 0}
              />
              <StatCard
                label="ارزش کل معاملات"
                value={summary?.total_trade_value ?? 0}
                unit="میلیارد ریال"
              />
              <StatCard
                label="خالص پول حقیقی"
                value={summary?.net_real_money_flow ?? 0}
                unit="میلیارد ریال"
                color={(summary?.net_real_money_flow ?? 0) >= 0 ? "text-accent-emerald" : "text-accent-rose"}
              />
            </div>

            {/* ── Second Row ── */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              <StatCard
                label="ارزش صف خرید"
                value={summary?.buy_queue_value ?? 0}
                unit="میلیارد ریال"
                color="text-accent-emerald"
              />
              <StatCard
                label="ارزش صف فروش"
                value={summary?.sell_queue_value ?? 0}
                unit="میلیارد ریال"
                color="text-accent-rose"
              />
              <StatCard
                label="صندوق سهامی"
                value={summary?.equity_fund_value ?? 0}
                unit="میلیارد ریال"
              />
              <StatCard
                label="صندوق درآمد ثابت"
                value={summary?.fixed_income_fund_value ?? 0}
                unit="میلیارد ریال"
              />
            </div>

            {/* ── Symbol Stats ── */}
            <Card title="تعداد نمادها">
              <div className="grid grid-cols-4 md:grid-cols-8 gap-3">
                <div className="text-center">
                  <div className="text-2xl font-bold text-surface-100">{stats?.total ?? 0}</div>
                  <div className="text-xs text-surface-500">کل</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-accent-emerald">{stats?.positive ?? 0}</div>
                  <div className="text-xs text-surface-500">مثبت</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-accent-rose">{stats?.negative ?? 0}</div>
                  <div className="text-xs text-surface-500">منفی</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-surface-400">{stats?.unchanged ?? 0}</div>
                  <div className="text-xs text-surface-500">بدون تغییر</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-blue-400">{stats?.above_closing ?? 0}</div>
                  <div className="text-xs text-surface-500">بالاتر از پایانی</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-orange-400">{stats?.below_closing ?? 0}</div>
                  <div className="text-xs text-surface-500">پایین‌تر از پایانی</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-accent-emerald">{stats?.buy_queue ?? 0}</div>
                  <div className="text-xs text-surface-500">صف خرید</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-accent-rose">{stats?.sell_queue ?? 0}</div>
                  <div className="text-xs text-surface-500">صف فروش</div>
                </div>
              </div>
            </Card>

            {/* ── Money Flow ── */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FlowList
                title="ورود پول حقیقی به گروه"
                items={data.sector_money_flow.inflow}
                color="emerald"
              />
              <FlowList
                title="خروج پول حقیقی از گروه"
                items={data.sector_money_flow.outflow}
                color="rose"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FlowList
                title="ورود پول حقیقی به سهام"
                items={data.stock_money_flow.inflow}
                color="emerald"
              />
              <FlowList
                title="خروج پول حقیقی از سهام"
                items={data.stock_money_flow.outflow}
                color="rose"
              />
            </div>

            {/* ── Sector Trade Values ── */}
            {data.sector_trade_values.length > 0 && (
              <Card title="ارزش معاملات گروه‌ها - میلیارد ریال">
                <div className="space-y-2 max-h-80 overflow-y-auto">
                  {data.sector_trade_values.map((item, i) => {
                    const maxVal = data.sector_trade_values[0]?.value || 1;
                    const pct = (item.value / maxVal) * 100;
                    return (
                      <div key={i} className="flex items-center gap-3 text-xs">
                        <span className="text-surface-300 w-40 truncate">{item.name}</span>
                        <div className="flex-1 h-4 bg-surface-700 rounded overflow-hidden">
                          <div
                            className="h-full bg-primary-500/60 rounded"
                            style={{ width: `${pct}%` }}
                          />
                        </div>
                        <span className="text-surface-200 font-mono w-20 text-left">
                          {item.value.toLocaleString("en-US")}
                        </span>
                      </div>
                    );
                  })}
                </div>
              </Card>
            )}
          </>
        ) : (
          <div className="text-center py-12 text-surface-500">
            داده‌ای موجود نیست
          </div>
        )}
      </div>
    </AppLayout>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import { apiGet } from "@/lib/api";

interface Commodity {
  symbol: string;
  name: string;
  price: number;
  change_value: number;
  change_percent: number;
  unit: string;
  category: string;
  date: string;
  time: string;
}

const CATEGORIES = [
  { key: "all", label: "همه", icon: "🌐" },
  { key: "precious_metal", label: "فلزات گرانبها", icon: "💎" },
  { key: "base_metal", label: "فلزات پایه", icon: "⚙️" },
  { key: "energy", label: "انرژی", icon: "🛢️" },
];

const CATEGORY_LABEL: Record<string, string> = {
  precious_metal: "فلزات گرانبها",
  base_metal: "فلزات پایه",
  energy: "انرژی",
  agriculture: "کشاورزی",
};

const SYMBOL_ICONS: Record<string, string> = {
  XAUUSD: "🥇", XAGUSD: "🥈", XPTUSD: "💠", XPDUSD: "🔮",
  COPPER: "🪙", ALUMINUM: "🪶", ZINC: "⚡", LEAD: "🔋", NICKEL: "🧲",
  BRENT: "🛢️", WTI: "⛽", NATURAL_GAS: "🔥", GASOLINE: "⛽",
};

function getIcon(c: Commodity): string {
  if (c.category && CATEGORY_LABEL[c.category]) {
    return CATEGORIES.find((cat) => cat.key === c.category)?.icon || "📊";
  }
  return SYMBOL_ICONS[c.symbol] || "📊";
}

function fmtNum(n: number, digits = 2): string {
  if (n == null || !Number.isFinite(n)) return "—";
  return n.toLocaleString("fa-IR", { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

function CommodityCard({ c }: { c: Commodity }) {
  const positive = (c.change_percent ?? 0) >= 0;
  const icon = getIcon(c);

  return (
    <div className="glass-card p-4 hover:scale-[1.01] transition-all duration-200">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <span className="text-2xl">{icon}</span>
          <div>
            <h3 className="font-bold text-surface-200 text-sm">{c.name || c.symbol}</h3>
            <span className="text-[10px] text-surface-500 font-mono">{c.symbol}</span>
          </div>
        </div>
        <span className="text-[10px] px-2 py-0.5 rounded-full bg-surface-700 text-surface-300">
          {CATEGORY_LABEL[c.category] || c.category || "—"}
        </span>
      </div>

      <div className="flex items-end justify-between mb-3">
        <div>
          <div className="text-xl font-bold font-mono text-surface-100">{fmtNum(c.price)}</div>
          <div className="text-[10px] text-surface-500 font-mono">{c.unit || "USD"}</div>
        </div>
        <div className="text-right">
          <div className={`text-sm font-bold font-mono ${positive ? "text-accent-emerald" : "text-accent-rose"}`}>
            {positive ? "+" : ""}{fmtNum(c.change_percent)}%
          </div>
          <div className={`text-[10px] font-mono ${positive ? "text-accent-emerald/70" : "text-accent-rose/70"}`}>
            {positive ? "+" : ""}{fmtNum(c.change_value)}
          </div>
        </div>
      </div>

      {c.time && (
        <div className="text-[10px] text-surface-600 mt-2 flex items-center gap-1 border-t border-surface-800/50 pt-2">
          <span className="material-icons text-[10px]">schedule</span>
          <span className="font-mono">{c.date} {c.time}</span>
        </div>
      )}
    </div>
  );
}

export default function CommoditiesMarketPage() {
  const [category, setCategory] = useState("all");

  const { data, isLoading, error } = useQuery({
    queryKey: ["brsapi-commodities", category],
    queryFn: async () => {
      const endpoint = category === "all"
        ? "/brsapi/commodities"
        : `/brsapi/commodities?category=${category}`;
      const res = await apiGet<{ success: boolean; data: Commodity[] }>(endpoint);
      return res.data || [];
    },
    refetchInterval: 30_000,
  });

  const filtered = data ?? [];

  const summary = useMemo(() => {
    const total = filtered.length;
    const up = filtered.filter((c) => (c.change_percent ?? 0) >= 0).length;
    const down = total - up;
    const avgChange = total === 0 ? 0 : filtered.reduce((s, c) => s + (c.change_percent ?? 0), 0) / total;
    const sorted = [...filtered].sort((a, b) => (b.change_percent ?? 0) - (a.change_percent ?? 0));
    const topGainer = sorted[0];
    const topLoser = sorted[sorted.length - 1];
    return { total, up, down, avgChange, topGainer, topLoser };
  }, [filtered]);

  const date = filtered[0]?.date;
  const time = filtered[0]?.time;

  return (
    <AppLayout title="بازار کالا" subtitle="قیمت جهانی کامودیتی‌ها - فلزات، انرژی و محصولات کشاورزی">
      <div className="flex flex-wrap gap-2 mb-5">
        {CATEGORIES.map((cat) => (
          <button
            key={cat.key}
            onClick={() => setCategory(cat.key)}
            className={`px-4 py-2 rounded-lg text-xs font-medium transition-all flex items-center gap-1.5 ${
              category === cat.key
                ? "bg-primary-600 text-white shadow-lg shadow-primary-600/20"
                : "bg-surface-800 text-surface-400 hover:text-surface-200 hover:bg-surface-700"
            }`}
          >
            <span>{cat.icon}</span>
            {cat.label}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-5 gap-3 mb-5">
        <div className="glass-card p-3">
          <div className="text-[10px] text-surface-500">تعداد آیتم</div>
          <div className="text-lg font-bold font-mono text-surface-200">{summary.total}</div>
        </div>
        <div className="glass-card p-3">
          <div className="text-[10px] text-surface-500">صعودی</div>
          <div className="text-lg font-bold font-mono text-accent-emerald">{summary.up}</div>
        </div>
        <div className="glass-card p-3">
          <div className="text-[10px] text-surface-500">نزولی</div>
          <div className="text-lg font-bold font-mono text-accent-rose">{summary.down}</div>
        </div>
        <div className="glass-card p-3">
          <div className="text-[10px] text-surface-500">میانگین تغییر</div>
          <div className={`text-lg font-bold font-mono ${summary.avgChange >= 0 ? "text-accent-emerald" : "text-accent-rose"}`}>
            {summary.avgChange >= 0 ? "+" : ""}{fmtNum(summary.avgChange)}%
          </div>
        </div>
        <div className="glass-card p-3">
          <div className="text-[10px] text-surface-500">به‌روزرسانی</div>
          <div className="text-xs font-mono text-surface-200 mt-1">{date || "—"}</div>
          <div className="text-[10px] font-mono text-surface-400">{time || ""}</div>
        </div>
      </div>

      {summary.topGainer && summary.topLoser && summary.total > 1 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-5">
          <div className="glass-card p-3 border-r-4 border-accent-emerald flex items-center justify-between">
            <div>
              <div className="text-[10px] text-surface-500 mb-1">بیشترین رشد</div>
              <div className="text-sm font-bold text-surface-200">{summary.topGainer.name || summary.topGainer.symbol}</div>
              <div className="text-[10px] text-surface-500 font-mono">{summary.topGainer.symbol}</div>
            </div>
            <div className="text-xl font-bold font-mono text-accent-emerald">
              +{fmtNum(summary.topGainer.change_percent)}%
            </div>
          </div>
          <div className="glass-card p-3 border-r-4 border-accent-rose flex items-center justify-between">
            <div>
              <div className="text-[10px] text-surface-500 mb-1">بیشترین افت</div>
              <div className="text-sm font-bold text-surface-200">{summary.topLoser.name || summary.topLoser.symbol}</div>
              <div className="text-[10px] text-surface-500 font-mono">{summary.topLoser.symbol}</div>
            </div>
            <div className="text-xl font-bold font-mono text-accent-rose">
              {fmtNum(summary.topLoser.change_percent)}%
            </div>
          </div>
        </div>
      )}

      {error && (
        <div className="p-4 mb-4 bg-accent-rose/10 border border-accent-rose/20 rounded-lg text-accent-rose text-sm">
          خطا در دریافت داده‌ها. در حال نمایش داده‌های کش شده...
        </div>
      )}

      <div className="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
        {isLoading
          ? Array.from({ length: 8 }).map((_, i) => <Skeleton key={i} className="h-40 w-full" />)
          : filtered.map((c, i) => <CommodityCard key={`${c.symbol}-${i}`} c={c} />)
        }
      </div>

      {!isLoading && filtered.length === 0 && (
        <div className="text-center py-16 text-surface-600">
          <div className="text-4xl mb-3">📡</div>
          <p>داده‌ای برای نمایش وجود ندارد</p>
          <p className="text-xs mt-2">منتظر اولین همگام‌سازی داده باشید</p>
        </div>
      )}
    </AppLayout>
  );
}

