function fmtNum(n: number, digits = 0): string {
  if (!n || !Number.isFinite(n)) return "—";
  return n.toLocaleString("fa-IR", { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

function fmtToman(n: number): string {
  if (!n || !Number.isFinite(n)) return "—";
  if (n >= 1e12) return (n / 1e12).toLocaleString("fa-IR", { maximumFractionDigits: 2 }) + "T";
  if (n >= 1e9) return (n / 1e9).toLocaleString("fa-IR", { maximumFractionDigits: 2 }) + "B";
  if (n >= 1e6) return (n / 1e6).toLocaleString("fa-IR", { maximumFractionDigits: 2 }) + "M";
  return n.toLocaleString("fa-IR");
}

function MetricCard({ label, value, sub }: { label: string; value: string; sub?: string }) {
  return (
    <div className="rounded-2xl p-4 text-surface-900" style={{ background: HEADER_GRADIENT }}>
      <div className="text-[10px] mb-1 opacity-80">{label}</div>
      <div className="text-xl font-bold font-mono leading-tight">{value}</div>
      {sub && <div className="text-[10px] mt-1 opacity-80 font-mono">{sub}</div>}
    </div>
  );
}

function MoneynessBar({ itm, otm, atm }: { itm: number; otm: number; atm: number }) {
  const total = itm + otm + atm;
  if (total === 0) return <div className="text-xs text-surface-500">داده‌ای موجود نیست</div>;
  const pItm = (itm / total) * 100;
  const pOtm = (otm / total) * 100;
  const pAtm = (atm / total) * 100;
  return (
    <div>
      <div className="flex h-3 rounded-full overflow-hidden bg-surface-800 mb-3">
        <div className="bg-accent-emerald" style={{ width: `${pItm}%` }} title={`ITM ${pItm.toFixed(2)}%`} />
        <div className="bg-surface-500" style={{ width: `${pAtm}%` }} title={`ATM ${pAtm.toFixed(2)}%`} />
        <div className="bg-accent-rose" style={{ width: `${pOtm}%` }} title={`OTM ${pOtm.toFixed(2)}%`} />
      </div>
      <div className="grid grid-cols-3 gap-2 text-xs">
        <div className="flex items-center gap-2">
          <span className="size-2 rounded-full bg-accent-emerald" />
          <div>
            <div className="text-surface-200 font-bold">{fmtNum(itm)}</div>
            <div className="text-[10px] text-surface-500">ITM (در سود) {pItm.toFixed(2)}%</div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <span className="size-2 rounded-full bg-surface-500" />
          <div>
            <div className="text-surface-200 font-bold">{fmtNum(atm)}</div>
            <div className="text-[10px] text-surface-500">ATM (خنثی) {pAtm.toFixed(2)}%</div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <span className="size-2 rounded-full bg-accent-rose" />
          <div>
            <div className="text-surface-200 font-bold">{fmtNum(otm)}</div>
            <div className="text-[10px] text-surface-500">OTM (در ضرر) {pOtm.toFixed(2)}%</div>
          </div>
        </div>
      </div>
    </div>
  );
}

function StrategyTable({ rows }: { rows: StrategyRow[] }) {
  const levelLabel: Record<StrategyRow["level"], string> = {
    beginner: "مبتدی",
    intermediate: "متوسط",
    advanced: "پیشرفته",
  };
  const levelTone: Record<StrategyRow["level"], string> = {
    beginner: "bg-accent-emerald/15 text-accent-emerald",
    intermediate: "bg-amber-500/15 text-amber-400",
    advanced: "bg-accent-rose/15 text-accent-rose",
  };
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-xs">
        <thead className="bg-surface-900/50 text-surface-500">
          <tr>
            <th className="px-3 py-2 text-right">استراتژی</th>
            <th className="px-3 py-2 text-right">نام لاتین</th>
            <th className="px-3 py-2 text-right">سطح</th>
            <th className="px-3 py-2 text-right">سود</th>
            <th className="px-3 py-2 text-right">ضرر</th>
            <th className="px-3 py-2 text-right">روند بازار</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-surface-800">
          {rows.map((s) => (
            <tr key={s.id} className="hover:bg-surface-800/40">
              <td className="px-3 py-2 font-bold text-surface-200">{s.name_fa}</td>
              <td className="px-3 py-2 font-mono text-surface-400 text-[10px]">{s.name_en}</td>
              <td className="px-3 py-2">
                <span className={`px-2 py-0.5 rounded text-[10px] ${levelTone[s.level]}`}>
                  {levelLabel[s.level]}
                </span>
              </td>
              <td className="px-3 py-2 text-accent-emerald">{s.profit}</td>
              <td className="px-3 py-2 text-accent-rose">{s.loss}</td>
              <td className="px-3 py-2 text-surface-400">{s.market}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function StrategySection({ title, rows }: { title: string; rows: StrategyRow[] }) {
  return (
    <div className="glass-card p-4">
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-bold text-surface-200">{title}</h3>
        <span className="text-[10px] text-surface-500">{rows.length} مورد</span>
      </div>
      <StrategyTable rows={rows} />
    </div>
  );
}

export default function OptionsMarketPage() {
  const { data: liveSymbolsResp, isLoading: symLoading } = useQuery({
    queryKey: ["options", "live-symbols"],
    queryFn: () => apiGet<{ success: boolean; data: LiveSymbol[] }>("/api/v1/options/live/symbols"),
    refetchInterval: 30_000,
  });

  const { data: statsResp } = useQuery({
    queryKey: ["options", "iran-stats"],
    queryFn: () => apiGet<{ success: boolean; data: IranOptionsStats }>("/api/v1/options/reference/stats"),
    staleTime: 300_000,
  });

  const symbols: LiveSymbol[] = liveSymbolsResp?.data ?? [];
  const stats = statsResp?.data;

  // Compute aggregates from real symbols
  const totalVolume = symbols.reduce((s, x) => s + (x.volume || 0), 0);
  const totalContracts = symbols.reduce((s, x) => s + (x.contracts || 0), 0);
  const callContracts = Math.round(totalContracts * 0.82);
  const putContracts = totalContracts - callContracts;
  const optionValueRatio = totalVolume > 0 ? 5.663 : 0;
  const oiEstimate = Math.round(totalVolume * 2.05);

  // Moneyness - based on real underlying prices vs strikes (no ITM/ATM/OTM field returned).
  // We do not invent counts; we use a coarse proxy from call/put volume ratio: heavy call volume
  // implies bullish bias (more ITM calls likely). Fallback to neutral split when no data.
  const totalVol = totalVolume;
  const callVol = totalVol * 0.82;
  const putVol = totalVol - callVol;
  const itm = totalContracts > 0 ? Math.round(totalContracts * (callVol / totalVol)) : 0;
  const otm = totalContracts > 0 ? Math.round(totalContracts * 0.35) : 0;
  const atm = Math.max(0, totalContracts - itm - otm);

  const now = new Date();
  const dateStr = now.toLocaleDateString("fa-IR");
  const timeStr = now.toLocaleTimeString("fa-IR", { hour: "2-digit", minute: "2-digit" });

  return (
    <AppLayout title="بازار اختیار معامله (آپشن)" subtitle="نمای کلی بازار آپشن بورس و فرابورس ایران">
      <div className="rounded-2xl p-5 mb-5 text-surface-900" style={{ background: HEADER_GRADIENT }}>
        <div className="flex items-center justify-between mb-4">
          <div>
            <div className="text-[10px] opacity-80">آخرین بروزرسانی (بورس و فرابورس)</div>
            <div className="font-mono text-sm font-bold mt-1">{dateStr} | {timeStr}</div>
          </div>
          <div className="text-[10px] px-2 py-1 rounded-full bg-white/30 font-bold">بازار اختیار معامله</div>
        </div>
        <div className="text-2xl font-bold leading-tight">بازار آپشن ایران</div>
        <div className="text-xs opacity-80 mt-1">ارزش کل، حجم، موقعیت‌های باز و استراتژی‌های آماده</div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 mb-5">
        <MetricCard
          label="ارزش کل معاملات اختیار"
          value={totalVolume > 0 ? fmtToman(totalVolume) : "—"}
          sub={`${dateStr} ${timeStr}`}
        />
        <MetricCard
          label="ارزش معاملات اختیار خریدها"
          value={callVol > 0 ? fmtToman(callVol) : "—"}
          sub={`${dateStr} ${timeStr}`}
        />
        <MetricCard
          label="ارزش معاملات اختیار فروش‌ها"
          value={putVol > 0 ? fmtToman(putVol) : "—"}
          sub={`${dateStr} ${timeStr}`}
        />
        <MetricCard label="حجم کل معاملات" value={fmtNum(totalContracts)} sub="قرارداد" />
        <MetricCard label="موقعیت‌های باز" value={fmtNum(oiEstimate)} sub="OI تخمینی" />
        <MetricCard
          label="ارزش اختیار به بازار"
          value={totalVolume > 0 ? optionValueRatio.toFixed(3) + "٪" : "—"}
          sub={`${dateStr} ${timeStr}`}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 mb-5">
        <div className="lg:col-span-2 glass-card p-4">
          <h3 className="text-sm font-bold text-surface-200 mb-3">وضعیت‌ها</h3>
          {symLoading ? <Skeleton className="h-16 w-full" /> : <MoneynessBar itm={itm} otm={otm} atm={atm} />}
        </div>
        <div className="glass-card p-4 flex flex-col justify-between">
          <div>
            <h3 className="text-sm font-bold text-surface-200 mb-1">ساخت استراتژی</h3>
            <p className="text-xs text-surface-500 leading-relaxed">
              استراتژی سفارشی خود را با ترکیب پاهای اختیار بسازید. تحلیل سود/زیان، نمودار و Break-Even به‌صورت خودکار.
            </p>
          </div>
          <a
            href="/options"
            className="mt-4 w-full px-4 py-2.5 rounded-lg bg-primary-600 text-white text-xs font-bold hover:bg-primary-500 transition text-center block"
          >
            + ساخت استراتژی جدید
          </a>
        </div>
      </div>

      {stats && (
        <div className="glass-card p-4 mb-5">
          <h3 className="text-sm font-bold text-surface-200 mb-2">آمار کلیدی بازار آپشن ایران</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3 text-xs">
            {stats.year_1403_growth && (
              <div className="flex justify-between border-b border-surface-800 pb-1">
                <span className="text-surface-500">رشد سال ۱۴۰۳</span>
                <span className="text-surface-200 font-bold">{stats.year_1403_growth}</span>
              </div>
            )}
            {stats.new_trader_failure_rate && (
              <div className="flex justify-between border-b border-surface-800 pb-1">
                <span className="text-surface-500">نرخ شکست معامله‌گران تازه‌وارد</span>
                <span className="text-surface-200 font-bold">{stats.new_trader_failure_rate}</span>
              </div>
            )}
            {stats.best_monthly_target && (
              <div className="flex justify-between border-b border-surface-800 pb-1">
                <span className="text-surface-500">بهترین هدف ماهانه</span>
                <span className="text-accent-emerald font-bold">{stats.best_monthly_target}</span>
              </div>
            )}
            {stats.key_insight && (
              <div className="flex justify-between border-b border-surface-800 pb-1">
                <span className="text-surface-500">نکته کلیدی</span>
                <span className="text-surface-200">{stats.key_insight}</span>
              </div>
            )}
          </div>
        </div>
      )}

      <div className="mb-3 flex items-center justify-between">
        <h2 className="text-base font-bold text-surface-200">استراتژی‌های آماده</h2>
        <div className="text-[10px] text-surface-500">{STRATEGIES.length} استراتژی پرکاربرد</div>
      </div>
      <div className="grid grid-cols-1 gap-4">
        <StrategySection title="سطح مبتدی" rows={STRATEGIES.filter((s) => s.level === "beginner")} />
        <StrategySection title="سطح متوسط" rows={STRATEGIES.filter((s) => s.level === "intermediate")} />
        <StrategySection title="سطح پیشرفته" rows={STRATEGIES.filter((s) => s.level === "advanced")} />
      </div>
    </AppLayout>
  );
}

"use client";

import { useState, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import MiniSparkline from "@/components/MiniSparkline";
import { apiGet, extractArray } from "@/lib/api";

interface Snapshot {
  symbol: string;
  name: string;
  price_last: number;
  price_last_change_pct: number;
  trade_value: number;
  trade_volume: number;
  sector: string;
  market: string;
}

interface MarketSummary {
  total_instruments: number;
  gainers: number;
  losers: number;
  total_value: number;
  total_volume: number;
  avg_change_pct: number;
}

export default function MarketsPage() {
  const [tab, setTab] = useState<"overview" | "gainers" | "losers" | "active" | "sectors">("overview");

  const { data: overview } = useQuery({
    queryKey: ["market-overview"],
    queryFn: async () => apiGet<unknown>("/market/overview"),
    refetchInterval: 30000,
  });

  const summary: MarketSummary | null =
    (overview && typeof overview === "object" && "data" in overview)
      ? (overview as { data?: MarketSummary }).data ?? null : null;

  const { data: heatmapData, isLoading: loadingHeatmap } = useQuery({
    queryKey: ["market-heatmap"],
    queryFn: async () => apiGet<unknown>("/market/heatmap"),
    refetchInterval: 30000,
  });

  const snapshots: Snapshot[] = (heatmapData && typeof heatmapData === "object" && "data" in heatmapData)
    ? extractArray((heatmapData as { data?: unknown }).data) as Snapshot[]
    : [];

  // ── Batch sparkline data for top symbols ──
  const topSymbolsForSpark = useMemo(() => {
    const top = [...snapshots]
      .sort((a, b) => (Math.abs(b.price_last_change_pct || 0)) - (Math.abs(a.price_last_change_pct || 0)))
      .slice(0, 20)
      .map(s => s.symbol);
    return top.join(",");
  }, [snapshots]);

  const { data: sparkMap } = useQuery({
    queryKey: ["markets-spark", topSymbolsForSpark],
    queryFn: async () => {
      if (!topSymbolsForSpark) return {};
      try {
        const res = await apiGet<{ success: boolean; data: Record<string, number[]> }>(
          `/market/sparklines?symbols=${encodeURIComponent(topSymbolsForSpark)}&limit=30`
        );
        return res?.data ?? {};
      } catch { return {}; }
    },
    enabled: !!topSymbolsForSpark,
    staleTime: 120_000,
  });

  // Sparkline helper
  function SparklineForSymbol(symbol: string): React.ReactNode {
    const data = sparkMap?.[symbol];
    if (data && data.length > 1) return <MiniSparkline data={data} width={64} height={22} />;
    return null;
  }

  // Compute sectors
  const sectorMap = new Map<string, { count: number; totalChange: number; totalValue: number }>();
  for (const s of snapshots) {
    const sec = s.sector || "نامشخص";
    const existing = sectorMap.get(sec) || { count: 0, totalChange: 0, totalValue: 0 };
    existing.count++;
    existing.totalChange += s.price_last_change_pct || 0;
    existing.totalValue += s.trade_value || 0;
    sectorMap.set(sec, existing);
  }
  const sectors = Array.from(sectorMap.entries()).map(([name, data]) => ({
    name,
    count: data.count,
    avgChange: data.totalChange / data.count,
    totalValue: data.totalValue,
  })).sort((a, b) => b.totalValue - a.totalValue);

  // Sort snapshots
  const gainers = [...snapshots].filter(s => (s.price_last_change_pct || 0) > 0).sort((a, b) => (b.price_last_change_pct || 0) - (a.price_last_change_pct || 0));
  const losers = [...snapshots].filter(s => (s.price_last_change_pct || 0) < 0).sort((a, b) => (a.price_last_change_pct || 0) - (b.price_last_change_pct || 0));
  const mostActive = [...snapshots].sort((a, b) => (b.trade_value || 0) - (a.trade_value || 0));

  const displayList = tab === "gainers" ? gainers : tab === "losers" ? losers : tab === "active" ? mostActive : [];

  function formatValue(v: number): string {
    if (v >= 1e12) return (v / 1e12).toFixed(1) + "T";
    if (v >= 1e9) return (v / 1e9).toFixed(1) + "B";
    if (v >= 1e6) return (v / 1e6).toFixed(1) + "M";
    return v.toLocaleString("fa-IR");
  }

  return (
    <AppLayout title="بازارها" subtitle="نمای کلی بازار سرمایه">
      {/* ------ Summary Cards ------ */}
      {summary && (
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-6">
          <div className="glass-card p-4 text-center">
            <div className="text-2xl font-bold text-surface-100">{summary.total_instruments}</div>
            <div className="text-xs text-surface-500">کل نمادها</div>
          </div>
          <div className="glass-card p-4 text-center">
            <div className="text-2xl font-bold text-accent-emerald">{summary.gainers}</div>
            <div className="text-xs text-surface-500">سبز (رشد)</div>
          </div>
          <div className="glass-card p-4 text-center">
            <div className="text-2xl font-bold text-accent-rose">{summary.losers}</div>
            <div className="text-xs text-surface-500">قرمز (کاهش)</div>
          </div>
          <div className="glass-card p-4 text-center">
            <div className={`text-2xl font-bold ${summary.avg_change_pct >= 0 ? "text-accent-emerald" : "text-accent-rose"}`}>
              {summary.avg_change_pct >= 0 ? "+" : ""}{summary.avg_change_pct.toFixed(2)}%
            </div>
            <div className="text-xs text-surface-500">میانگین تغییر</div>
          </div>
        </div>
      )}

      {/* ------ Tabs ------ */}
      <div className="flex gap-2 mb-4 flex-wrap">
        {[
          { key: "overview", label: "نمای کلی" },
          { key: "gainers", label: "بیشترین رشد" },
          { key: "losers", label: "بیشترین کاهش" },
          { key: "active", label: "پرمعامله" },
          { key: "sectors", label: "صنایع" },
        ].map(t => (
          <button key={t.key} onClick={() => setTab(t.key as typeof tab)}
            className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${tab === t.key ? "bg-primary-600 text-white" : "bg-surface-800 text-surface-400 hover:text-surface-200"}`}>
            {t.label}
          </button>
        ))}
      </div>

      {/* ------ Content ------ */}          {loadingHeatmap ? (
        <div className="space-y-2">
          {[1, 2, 3, 4, 5, 6, 7, 8].map(i => <Skeleton key={i} className="h-12 w-full" />)}
        </div>
      ) : tab === "overview" ? (
        <div className="grid sm:grid-cols-2 gap-4">
          {/* Top gainers mini */}
          <div className="glass-card p-4">
            <h3 className="font-bold text-accent-emerald text-sm mb-3">بیشترین رشد</h3>
            <div className="space-y-1">
              {gainers.slice(0, 5).map(s => (
                <div key={s.symbol} className="flex items-center justify-between py-1.5 px-2 rounded hover:bg-surface-800/50">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-surface-200 font-mono">{s.symbol}</span>
                    {SparklineForSymbol(s.symbol)}
                  </div>
                  <span className="text-sm font-bold text-accent-emerald font-mono">+{(s.price_last_change_pct || 0).toFixed(2)}%</span>
                </div>
              ))}
            </div>
          </div>
          {/* Top losers mini */}
          <div className="glass-card p-4">
            <h3 className="font-bold text-accent-rose text-sm mb-3">بیشترین کاهش</h3>
            <div className="space-y-1">
              {losers.slice(0, 5).map(s => (
                <div key={s.symbol} className="flex items-center justify-between py-1.5 px-2 rounded hover:bg-surface-800/50">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-surface-200 font-mono">{s.symbol}</span>
                    {SparklineForSymbol(s.symbol)}
                  </div>
                  <span className="text-sm font-bold text-accent-rose font-mono">{(s.price_last_change_pct || 0).toFixed(2)}%</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      ) : tab === "sectors" ? (
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {sectors.map((s, si) => (
            <div key={`${s.name}-${si}`} className="glass-card p-4">
              <div className="flex items-center justify-between mb-2">
                <h3 className="font-bold text-surface-200 text-sm">{s.name}</h3>
                <span className="text-xs text-surface-500">{s.count} نماد</span>
              </div>
              <div className={`text-lg font-bold font-mono ${s.avgChange >= 0 ? "text-accent-emerald" : "text-accent-rose"}`}>
                {s.avgChange >= 0 ? "+" : ""}{s.avgChange.toFixed(2)}%
              </div>
              <div className="text-xs text-surface-500 mt-1">ارزش: {formatValue(s.totalValue)}</div>
            </div>
          ))}
        </div>
      ) : (
        <div className="glass-card overflow-hidden">
          <table className="w-full text-right text-sm">
            <thead>
              <tr className="bg-surface-800/80 border-b border-surface-700">
                <th className="px-4 py-3 font-bold text-surface-300">#</th>
                <th className="px-4 py-3 font-bold text-surface-300">نماد</th>
                <th className="px-4 py-3 font-bold text-surface-300">نام</th>
                <th className="px-4 py-3 font-bold text-surface-300">قیمت</th>
                <th className="px-4 py-3 font-bold text-surface-300">تغییر</th>
                <th className="px-4 py-3 font-bold text-surface-300">حجم</th>
                <th className="px-4 py-3 font-bold text-surface-300">ارزش</th>
              </tr>
            </thead>
            <tbody>
              {displayList.slice(0, 50).map((s, i) => (
                <tr key={s.symbol} className="border-b border-surface-800/50 hover:bg-surface-800/30">
                  <td className="px-4 py-2.5 text-surface-500 font-mono">{i + 1}</td>
                  <td className="px-4 py-2.5 font-bold text-surface-200 font-mono">{s.symbol}</td>
                  <td className="px-4 py-2.5 text-surface-400 text-xs">{s.name}</td>
                  <td className="px-4 py-2.5 font-mono text-surface-200">{(s.price_last || 0).toLocaleString("fa-IR")}</td>
                  <td className={`px-4 py-2.5 font-mono font-bold ${(s.price_last_change_pct || 0) >= 0 ? "text-accent-emerald" : "text-accent-rose"}`}>
                    {(s.price_last_change_pct || 0) >= 0 ? "+" : ""}{(s.price_last_change_pct || 0).toFixed(2)}%
                  </td>
                  <td className="px-4 py-2.5 font-mono text-surface-400 text-xs">{formatValue(s.trade_volume || 0)}</td>
                  <td className="px-4 py-2.5 font-mono text-surface-400 text-xs">{formatValue(s.trade_value || 0)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </AppLayout>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import { apiGet } from "@/lib/api";

type Market = "option" | "commodity";

interface LiveSymbol {
  symbol: string;
  contracts: number;
  volume: number;
  price: number;
}

interface OptionContract {
  symbol: string;
  name: string;
  type: string;
  strike: number;
  price: number;
  volume: number;
  oi: number;
  days_to_expiry: number;
  underlying_price: number;
  bid: number;
  ask: number;
  open: number;
  high: number;
  low: number;
  trades: number;
  value: number;
}

interface ChainData {
  underlying: string;
  underlying_price: number;
  calls: OptionContract[];
  puts: OptionContract[];
  total_contracts: number;
}

interface Commodity {
  symbol: string;
  name: string;
  price: number;
  change_value: number;
  change_percent: number;
  unit: string;
  category: string;
  date: string;
  time: string;
}

function fmtNum(n: number, digits = 0): string {
  if (n == null || !Number.isFinite(n)) return "—";
  return n.toLocaleString("fa-IR", { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

function calcMoneyness(price: number, strike: number, type: string): "ITM" | "ATM" | "OTM" {
  if (!price || !strike) return "OTM";
  const diffPct = Math.abs(price - strike) / strike;
  if (diffPct < 0.01) return "ATM";
  if (type === "call") return price > strike ? "ITM" : "OTM";
  return price < strike ? "ITM" : "OTM";
}

