        </div>
        <div className="flex items-center gap-2 text-xs">
          {gold != null && <span className="font-mono text-ink-2">{fa(gold)}</span>}
          <span className="text-ink-3">÷</span>
          {silver != null && <span className="font-mono text-ink-2">{fa(silver)}</span>}
        </div>
      </div>

      <div className="flex flex-col gap-4">
        <div className="rounded-xl bg-soft/60 p-4 text-center">
          <p className="text-[10px] text-ink-3">نسبت لحظه‌ای</p>
          <p className={`mt-1 font-mono text-3xl font-black ${ratioState.tone}`} dir="ltr">
            {ratioState.ratio == null ? "—" : ratioState.ratio.toFixed(2)}
          </p>
          <p className={`mt-1 text-xs font-bold ${ratioState.tone}`}>{ratioState.label}</p>
        </div>

        <div className="grid gap-2 text-xs">
          <div className="rounded-xl bg-soft px-3 py-2 flex items-center justify-between">
            <span className="flex items-center gap-2 text-ink-3"><Coins className="size-4" /> قیمت طلا</span>
            <b className="font-mono text-ink" dir="ltr">{gold == null ? "—" : `${fa(gold)} $`}</b>
          </div>
          <div className="rounded-xl bg-soft px-3 py-2 flex items-center justify-between">
            <span className="flex items-center gap-2 text-ink-3"><Coins className="size-4" /> قیمت نقره</span>
            <b className="font-mono text-ink" dir="ltr">{silver == null ? "—" : `${fa(silver)} $`}</b>
          </div>
          <div className="rounded-xl bg-soft px-3 py-2 flex items-center justify-between">
            <span className="flex items-center gap-2 text-ink-3"><Calculator className="size-4" /> نسبت</span>
            <b className="font-mono text-ink" dir="ltr">{ratioState.ratio == null ? "—" : ratioState.ratio.toFixed(2) + ":1"}</b>
          </div>
        </div>

        <div className="rounded-xl border border-line bg-soft/30 p-3">
          <div className="flex items-center gap-2 text-[11px] text-ink-2">
            <Activity className="size-4 text-primary-500" />
            راهنمای وضعیت تاریخی
          </div>
          <p className="mt-1 text-[11px] text-ink-3">{ratioState.note}</p>
        </div>
      </div>

      <div className="mt-3 flex flex-wrap gap-2 text-[10px]">
        {HISTORICAL_BANDS.map((b) => (
          <span key={b.from} className={`rounded-full border px-2 py-1 ${ratioState.ratio != null && ratioState.ratio >= b.from && ratioState.ratio < b.to ? "border-primary-500 bg-primary-600/10 text-primary-600" : "border-line bg-soft text-ink-3"}`}>
            {b.from}:{b.to} — {b.badge}
          </span>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useMemo } from "react";
import { Activity, TrendingUp, TrendingDown, Zap, Shield } from "lucide-react";
import { fa } from "./helpers";
import type { Candle } from "./PriceChart";

interface Props {
  candles: Candle[];
}

export default function TechnicalPanel({ candles }: Props) {
  const pivots = useMemo(() => {
    if (candles.length < 2) return null;
    const last = candles[candles.length - 1];
    const prev = candles[candles.length - 2];
    const h = last.high || 0;
    const l = last.low || 0;
    const c = last.close || 0;
    const pp = (h + l + c * 2) / 4; // pivot with close emphasis
    const r1 = 2 * pp - l;
    const s1 = 2 * pp - h;
    const r2 = pp + (h - l);
    const s2 = pp - (h - l);
    const r3 = h + 2 * (pp - l);
    const s3 = l - 2 * (h - pp);
    return { pp, r1, s1, r2, s2, r3, s3 };
  }, [candles]);

  const rsi = useMemo(() => {
    if (candles.length < 2) return null;
    const close = candles.map((c) => c.close);
    const gains: number[] = [];
    const losses: number[] = [];
    for (let i = 1; i < close.length; i++) {
      const diff = close[i] - close[i - 1];
      gains.push(Math.max(diff, 0));
      losses.push(Math.max(-diff, 0));
    }
    if (gains.length === 0) return null;
    const avgGain = gains.reduce((a, b) => a + b, 0) / gains.length;
    const avgLoss = losses.reduce((a, b) => a + b, 0) / losses.length;
    if (avgLoss === 0) return 70;
    const rs = avgGain / avgLoss;
    return 100 - 100 / (1 + rs);
  }, [candles]);

  const macdInterpretation = useMemo(() => {
    if (candles.length < 4) return null;
    const close = candles.map((c) => c.close);
    const ema = (series: number[], span: number) => {
      const k = 2 / (span + 1);
      const out = series.slice(0, span - 1).map(() => 0);
      let prev = series.slice(0, span).reduce((a, b) => a + b, 0) / span;
      out.push(prev);
      for (let i = span; i < series.length; i++) {
        const cur = series[i] * k + prev * (1 - k);
        out.push(cur);
        prev = cur;
      }
      return out;
    };
    const ema12 = ema(close, 12);
    const ema26 = ema(close, 26);
    const macd = ema12.map((v, i) => v - ema26[i]);
    const signal = ema(macd, 9);
    const hist = macd.map((v, i) => v - signal[i]);
    const lastHist = hist[hist.length - 1] || 0;
    const prevHist = hist[hist.length - 2] || 0;
    let tone = "text-ink-3";
    let note = "ندارد";
    if (lastHist > 0 && prevHist <= 0) {
      tone = "text-up";
      note = " MACD صعودی; سیگنال ضعیف صعودی";
    } else if (lastHist < 0 && prevHist >= 0) {
      tone = "text-down";
      note = " MACD نزولی; سیگنال ضعیف نزولی";
    } else if (lastHist > 0) {
      tone = "text-up";
      note = " MACD صعودی";
    } else {
      tone = "text-down";
      note = " MACD نزولی";
    }
    return { tone, note, lastHist };
  }, [candles]);

  const rsiStatus = rsi == null ? null : rsi >= 70 ? "اشباع فروش" : rsi <= 30 ? "اشباع خرید" : "طبیعی";
  const rsiTone = rsi == null ? "text-ink-3" : rsi >= 70 ? "text-down" : rsi <= 30 ? "text-up" : "text-ink";

  return (
    <div className="rounded-2xl border border-line bg-card p-4 shadow-[var(--shadow-card)]">
      <div className="mb-4 flex items-center gap-2">
        <Activity className="size-4 text-primary-500" />
        <h3 className="text-sm font-black text-ink">سطوح حمایت / مقاومت + اندیکاتورهای قدرت</h3>
      </div>

      {pivots ? (
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-2 text-xs">
            <div className="rounded-xl bg-soft px-3 py-2 flex items-center justify-between">
              <span className="flex items-center gap-2 text-ink-3"><TrendingUp className="size-4" /> مقاومت R3</span>
              <b className="font-mono text-down" dir="ltr">{fa(pivots.r3)}</b>
            </div>
            <div className="rounded-xl bg-soft px-3 py-2 flex items-center justify-between">
              <span className="flex items-center gap-2 text-ink-3"><TrendingUp className="size-4" /> مقاومت R2</span>
              <b className="font-mono text-down" dir="ltr">{fa(pivots.r2)}</b>
            </div>
            <div className="rounded-xl bg-soft px-3 py-2 flex items-center justify-between">
              <span className="flex items-center gap-2 text-ink-3"><Zap className="size-4" /> مقاومت R1</span>
              <b className="font-mono text-down" dir="ltr">{fa(pivots.r1)}</b>
            </div>
            <div className="rounded-xl bg-soft px-3 py-2 flex items-center justify-between">
              <span className="flex items-center gap-2 text-ink-3"><Activity className="size-4" /> لیدر پایه (Pivot)</span>
              <b className="font-mono text-ink" dir="ltr">{fa(pivots.pp)}</b>
            </div>
            <div className="rounded-xl bg-soft px-3 py-2 flex items-center justify-between">
              <span className="flex items-center gap-2 text-ink-3"><TrendingDown className="size-4" /> حمایت S1</span>
              <b className="font-mono text-up" dir="ltr">{fa(pivots.s1)}</b>
            </div>
            <div className="rounded-xl bg-soft px-3 py-2 flex items-center justify-between">
              <span className="flex items-center gap-2 text-ink-3"><TrendingDown className="size-4" /> حمایت S2</span>
              <b className="font-mono text-up" dir="ltr">{fa(pivots.s2)}</b>
            </div>
            <div className="rounded-xl bg-soft px-3 py-2 flex items-center justify-between">
              <span className="flex items-center gap-2 text-ink-3"><TrendingDown className="size-4" /> حمایت S3</span>
              <b className="font-mono text-up" dir="ltr">{fa(pivots.s3)}</b>
            </div>
            <div className="rounded-xl bg-soft px-3 py-2 flex items-center justify-between">
              <span className="flex items-center gap-2 text-ink-3"><Shield className="size-4" /> RSI</span>
              <b className={`font-mono ${rsiTone}`} dir="ltr">{rsi == null ? "—" : rsi.toFixed(1) + " — " + rsiStatus}</b>
            </div>
          </div>

          <div className="rounded-xl border border-line bg-soft/30 px-3 py-2 text-xs">
            <div className="flex items-center gap-2">
              <span className="text-ink-3">تفسیر MACD:</span>
              <span className={macdInterpretation?.tone ?? "text-ink-3"}>{macdInterpretation?.note ?? "—"}</span>
            </div>
            {macdInterpretation?.lastHist != null && (
              <div className="mt-1 font-mono text-[10px]" dir="ltr">
                هیستوگرام MACD: {macdInterpretation.lastHist >= 0 ? "+" : ""}{macdInterpretation.lastHist.toFixed(2)}
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="py-6 text-center text-xs text-ink-3">داده تاریخی کافی برای محاسبه پيوت وجود ندارد.</div>
      )}
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import { apiGet, extractArray } from "@/lib/api";
import {
  Activity,
  BrainCircuit,
  Coins,
  Calculator,
  DollarSign,
  Gem,
  History,
  LineChart,
  Newspaper,
  Sparkles,
  TrendingUp,
  TrendingDown,
  Zap,
} from "lucide-react";
import PriceChart, { type Candle } from "./components/PriceChart";
import ForecastTab from "./components/ForecastTab";
import BacktestTab from "./components/BacktestTab";
import MlTab from "./components/MlTab";
import GoldSilverRatioCard from "./components/GoldSilverRatioCard";
import TechnicalPanel from "./components/TechnicalPanel";
import FundamentalCard from "./components/FundamentalCard";
import TradingViewWidget from "./components/TradingViewWidget";
import { fa, faDateTime, faPct, fmtTr, isGoldText, isSilverText } from "./components/helpers";

interface PriceItem {
  symbol?: string;
  name?: string;
  title?: string;
  price?: number;
  price_close?: number;
  price_last?: number;
  price_change?: number;
  price_change_pct?: number;
  change_percent?: number;
  unit?: string;
  date?: string;
  time_unix?: number;
}

interface SilverFund {
  symbol?: string;
  name?: string;
  fund_type?: string;
  price_last?: number;
  nav?: number;
  nav_change_pct?: number;
  change_percent?: number;
  market_value?: number;
  base_volume?: number;
  trade_value?: number;
}

interface FutureRow {
  contract_code: string;
  contract_description?: string;
  contract_size?: number;
  contract_size_unit?: string;
  price_last?: number;
  price_last_change_pct?: number;
  trade_volume?: number;
  open_interest?: number;
  price_last_settlement?: number;
  date_end_text?: string;
  date_update?: string;
}

interface NewsItem {
  id?: string | number;
  title?: string;
  summary?: string;
  source?: string;
  url?: string;
  published_at?: string;
  sentiment?: string;
}

type Tab = "overview" | "forecast" | "funds" | "futures" | "backtest" | "ml" | "news";

const TABS: { id: Tab; label: string; icon: typeof Activity }[] = [
  { id: "overview", label: "نمای کلی", icon: LineChart },
  { id: "forecast", label: "پیش‌بینی", icon: Sparkles },
  { id: "funds", label: "صندوق‌ها", icon: Gem },
  { id: "futures", label: "آتی (IME)", icon: Activity },
  { id: "backtest", label: "بک‌تست", icon: History },
  { id: "ml", label: "هوش مصنوعی", icon: BrainCircuit },
  { id: "news", label: "اخبار", icon: Newspaper },
];

function latestBySymbol<T extends { symbol?: string }>(rows: T[], ts: (r: T) => number): Map<string, T> {
  const by = new Map<string, T>();
  for (const r of rows) {
    const k = r.symbol ?? "";
    if (!k) continue;
    const prev = by.get(k);
    if (!prev || ts(r) > ts(prev)) by.set(k, r);
  }
  return by;
}

function sentimentDot(s?: string): string {
  if (s === "bullish" || s === "positive") return "bg-up";
  if (s === "bearish" || s === "negative") return "bg-down";
  return "bg-ink-3";
}

export default function SilverMarketPage() {
  const [tab, setTab] = useState<Tab>("overview");
  const [grams, setGrams] = useState("1");

  const pricesQ = useQuery({
    queryKey: ["silver-spot"],
    queryFn: async () => {
      const r = await apiGet<{ success?: boolean; data?: PriceItem[] }>("/brsapi/commodities?category=precious_metal&limit=2000");
      const list: PriceItem[] = extractArray<PriceItem>(r?.data ?? r);
      const bySymbol = latestBySymbol(list, (x) => Number(x.time_unix ?? 0));
      return [...bySymbol.values()].filter(
        (x) => isSilverText(`${x.symbol ?? ""} ${x.name ?? x.title ?? ""}`) && !isGoldText(`${x.symbol ?? ""} ${x.name ?? ""}`),
      );
    },
    refetchInterval: 120_000,
  });

  const fxQ = useQuery({
    queryKey: ["fx-usd"],
    queryFn: async () => {
      const r = await apiGet<{ success?: boolean; data?: PriceItem[] }>("/brsapi/currency");
      const list: PriceItem[] = extractArray<PriceItem>(r?.data ?? r);
      return list.find((x) => (x.symbol ?? "").toUpperCase().includes("USD"))?.price ?? null;
    },
    refetchInterval: 120_000,
  });

  const fundsQ = useQuery({
    queryKey: ["silver-funds"],
    queryFn: async () => {
      const r = await apiGet<{ items?: SilverFund[]; data?: SilverFund[] }>("/funds?market=ime&limit=200");
      const items: SilverFund[] = extractArray<SilverFund>((r as { items?: SilverFund[] })?.items ?? (r as { data?: SilverFund[] })?.data ?? r);
      return items.filter((f) => {
        const n = `${f.name ?? ""} ${f.symbol ?? ""}`;
        const silver = isSilverText(n) || f.fund_type === "نقره";
        const commodity = f.fund_type === "کالایی" || /کالایی|کالا/.test(n);
        return (silver || commodity) && !isGoldText(n) && ((f.nav ?? 0) > 0 || (f.price_last ?? 0) > 0);
      });
    },
    refetchInterval: 60_000,
  });

  const futQ = useQuery({
    queryKey: ["silver-futures"],
    queryFn: async () => {
      const r = await apiGet<{ success?: boolean; data?: FutureRow[] }>("/brsapi/manage/download/ime-futures?live=true&limit=2000");
      const items: FutureRow[] = Array.isArray(r) ? (r as FutureRow[]) : extractArray<FutureRow>(r?.data ?? r);
      const silver = items.filter(
        (x) =>
          isSilverText(`${x.contract_code ?? ""} ${x.contract_description ?? ""}`) &&
          !isGoldText(`${x.contract_code ?? ""} ${x.contract_description ?? ""}`),
      );
      const byCode = new Map<string, FutureRow>();
      for (const x of silver) {
        const prev = byCode.get(x.contract_code);
        if (!prev || (x.date_update ?? "") > (prev.date_update ?? "")) byCode.set(x.contract_code, x);
      }
      return [...byCode.values()].filter((x) => (x.price_last ?? 0) > 0);
    },
    refetchInterval: 60_000,
  });

  const spotHistoryQ = useQuery({
    queryKey: ["silver-spot-history"],
    queryFn: async () => {
      const r = await apiGet<{ success?: boolean; data?: PriceItem[] }>("/brsapi/commodities?category=precious_metal&limit=2000");
      const list: PriceItem[] = extractArray<PriceItem>(r?.data ?? r);
      const byDate = new Map<string, PriceItem>();
      for (const x of list) {
        if (!/^XAG/i.test(x.symbol ?? "")) continue;
        const k = x.date ?? "";
        const prev = byDate.get(k);
        if (!prev || (x.time_unix ?? 0) > (prev.time_unix ?? 0)) byDate.set(k, x);
      }
      const dates = [...byDate.keys()].sort();
      const closes = dates.map((d) => byDate.get(d)?.price ?? 0).filter((p) => p > 0);
      return dates
        .map((d, i) => {
          const close = byDate.get(d)?.price ?? 0;
          if (close <= 0) return null;
          const open = i > 0 ? closes[i - 1] : close;
          return { time: d.replace(/\//g, "-"), open, high: Math.max(open, close), low: Math.min(open, close), close };
        })
        .filter(Boolean) as Candle[];
    },
    refetchInterval: 600_000,
    staleTime: 600_000,
  });

  const newsQ = useQuery({
    queryKey: ["silver-news"],
    queryFn: async () => {
      const r = await apiGet<{ data?: { items?: NewsItem[] }; items?: NewsItem[] }>("/news/search?q=نقره");
      const items: NewsItem[] = r?.data?.items ?? r?.items ?? [];
      return items.filter((x) => x.title && /نقره|سیلور|silver|xag/i.test(`${x.title} ${x.summary ?? ""}`));
    },
    refetchInterval: 300_000,
  });

  const ounce = useMemo(() => {
    const list = pricesQ.data ?? [];
    return list.find((p) => (p.symbol ?? "").toUpperCase().includes("XAG")) ?? list.find((p) => (p.symbol ?? "").toUpperCase().includes("AG")) ?? null;
  }, [pricesQ.data]);

  const gramFromFutures = useMemo(() => {
    const f = (futQ.data ?? []).find((x) => (x.price_last ?? 0) > 0 && (x.contract_size ?? 0) > 0);
    return f ? (f.price_last as number) / (f.contract_size as number) : null;
  }, [futQ.data]);

  const usd = fxQ.data ?? null;

  const goldQ = useQuery({
    queryKey: ["silver-gold-ratio"],
    queryFn: async () => {
      const r = await apiGet<{ success?: boolean; data?: PriceItem[] }>("/brsapi/commodities?category=precious_metal&limit=2000");
      const list: PriceItem[] = extractArray<PriceItem>(r?.data ?? r);
      const gold = list.find((x) => (x.symbol ?? "").toUpperCase().includes("XAU") && !(x.symbol ?? "").toUpperCase().includes("XAG"));
      const silver = list.find((x) => (x.symbol ?? "").toUpperCase().includes("XAG"));
      return { gold: gold?.price ?? null, silver: silver?.price ?? null };
    },
    refetchInterval: 120_000,
  });

  const { gold, silver } = goldQ.data ?? { gold: null, silver: null };

  const candles = spotHistoryQ.data ?? [];
  const lastCandle = candles[candles.length - 1] ?? null;
  const firstCandle = candles[0] ?? null;
  const rangeChange = lastCandle && firstCandle ? (lastCandle.close / firstCandle.close - 1) * 100 : null;
  const candleMin = candles.length ? Math.min(...candles.map((c) => c.low)) : null;
  const candleMax = candles.length ? Math.max(...candles.map((c) => c.high)) : null;

  const converter = useMemo(() => {
    const g = parseFloat(grams) || 0;
    const toUsd = ounce?.price == null ? null : (g / 31.1035) * ounce.price;
    const toIrr = toUsd == null || usd == null ? null : toUsd * usd;
    return { toUsd, toIrr };
  }, [grams, ounce, usd]);

  const ratioState = useMemo(() => {
    if (gold == null || silver == null || silver <= 0) {
      return { ratio: null, label: "نسبت ناکام", tone: "text-ink-3", note: "داده کافی برای محاسبه نسبت موجود نیست" };
    }
    const ratio = gold / silver;
    let label = "متعادل";
    let tone = "text-ink";
    let note = "طلا و نقره در بازه اندکی متعادل";
    if (ratio >= 80) { label = "نسبت غیرمعمول"; tone = "text-rose-400"; note = "نرخ تاریخی غالبی; ممکن است معامله‌های معکوس یا بررسیی نسبت به طلا توصیه شود"; }
    else if (ratio >= 60) { label = "طلا غالبی"; tone = "text-down"; note = "طلا بسیار غالبی; نقره ممکن است زیرارزش"; }
    else if (ratio >= 45) { label = "طلا ممکناً بیش‌ارزش"; tone = "text-down"; note = "طلا در حدود بالا; نسبت طلا/نقره بالا"; }
    else { label = "متعادل / پایین"; tone = "text-warn"; note = "طلا و نقره نسبتاً متعادل — نرخ تاریخی پایین"; }
    return { ratio, label, tone, note };
  }, [gold, silver]);

  const converterExplicit = useMemo(() => {
    const g = parseFloat(grams) || 0;
    const ouncePrice = ounce?.price ?? 0;
    const usdPerGram = ouncePrice / 31.1035;
    const toUsd = usdPerGram > 0 ? usdPerGram * g : null;
    const toIrr = toUsd == null || usd == null ? null : toUsd * usd;
    return { g, ouncePrice, usdPerGram, toUsd, toIrr };
  }, [grams, ounce, usd]);

  const heroCards = [
    { label: "انس جهانی نقره (XAG/USD)", value: ounce?.price != null ? ounce.price.toFixed(2) : "—", unit: "دلار / انس", change: ounce?.change_percent ?? ounce?.price_change_pct ?? null },
    { label: "نقره گرمی (آتی IME)", value: gramFromFutures != null ? fa(Math.round(gramFromFutures)) : "—", unit: "ریال / گرم", change: null },
    { label: "دلار آمریکا", value: usd != null ? fa(Math.round(usd)) : "—", unit: "ریال", change: null },
    { label: "صندوق‌های نقره / کالایی", value: fa(fundsQ.data?.length ?? 0), unit: "نماد", change: null },
    { label: "قراردادهای آتی نقره", value: fa(futQ.data?.length ?? 0), unit: "قرارداد", change: null },
  ];

  return (
    <AppLayout title="بازار نقره" subtitle="تحلیل یکپارچه نقره، صندوق‌ها، آتی، پیش‌بینی، بک‌تست و ML — داده واقعی BrsApi">
      <div className="space-y-5">
        <section className="rounded-3xl border border-primary-500/20 bg-gradient-to-br from-primary-950 via-card to-card p-5 text-white shadow-[var(--shadow-card-hover)] lg:p-6">
          <div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center">
            <div>
              <div className="mb-2 flex flex-wrap items-center gap-2 text-[10px] font-bold">
                <span className="rounded-full bg-white/10 px-2.5 py-1">داده زنده: BrsApi.ir</span>
                <span className="rounded-full bg-white/10 px-2.5 py-1">IME + TSETMC</span>
                <span className="rounded-full bg-warn/15 px-2.5 py-1 text-warn">صرفاً داده واقعی — بدون داده ساختگی</span>
              </div>
              <h2 className="text-xl font-black tracking-tight lg:text-2xl">نقره — پایش، تحلیل و بک‌تست</h2>
              <p className="mt-1 text-xs text-brand-200/80">
                آخرین به‌روزرسانی: {faDateTime(ounce?.date ?? null)} · تاریخچه نمودار: {fa(candles.length)} کندل
              </p>
            </div>
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-5">
              {heroCards.map((c) => (
                <div key={c.label} className="rounded-2xl border border-white/10 bg-white/5 p-3">
                  <p className="text-[10px] text-brand-200/70">{c.label}</p>
                  <p className="mt-1 font-mono text-sm font-black" dir="ltr">{c.value}</p>
                  <p className={`text-[10px] ${c.change == null ? "text-brand-200/50" : c.change >= 0 ? "text-up" : "text-down"}`}>{c.change == null ? c.unit : faPct(c.change)}</p>
                </div>
              ))}
            </div>
          </div>
        </section>

        <nav className="flex gap-2 overflow-x-auto rounded-2xl border border-line bg-card p-2">
          {TABS.map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setTab(id)}
              className={`flex min-w-[110px] flex-1 items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-xs font-bold transition ${tab === id ? "bg-primary-600 text-white shadow" : "text-ink-3 hover:bg-soft hover:text-ink"}`}
            >
