    apiGet<{ success: boolean; data: StrategyInfo[] }>("/options/strategies")
      .then((r) => setStrategies(r.success ? r.data ?? [] : []))
      .catch(() => setStrategies([]));
  }, []);

  const run = async () => {
    if (!symbol.trim()) return;
    setLoading(true);
