      try {
        const r = await apiGet<unknown>("/brsapi/commodities?category=precious_metal");
        return extractArray<LiveRow>(r);
      } catch { return []; }
    },
    staleTime: 120_000,
  });

  const goldList = goldQ.data ?? [];
  const fxList = fxQ.data ?? [];
  const commList = commoditiesQ.data ?? [];

  const anchors = useMemo(() => {
    const g18 = findLive(goldList, "۱۸")?.price ?? findLive(goldList, "18")?.price ?? null;
    const usd = (fxList.find((x) => (x.symbol ?? "").toLowerCase().includes("usd"))?.price) ?? null;
    const xau = findLive(commList, "XAU")?.price ?? findLive(commList, "نیکل")?.price ?? null;
    const xag = findLive(commList, "XAG")?.price ?? null;
    return { gold_18k: g18, xau_usd: xau, xag_usd: xag, usd_irr_free: usd };
  }, [goldList, fxList, commList]);

  const ready = goldQ.data !== undefined && fxQ.data !== undefined;

  /* Fetch all 4 symbols × 6 horizons in one query. */
  const forecastsQ = useQuery<{ symbol: string; forecasts: Forecast[] }[]>({
    queryKey: ["predictions-all", anchors.gold_18k, anchors.xau_usd, anchors.xag_usd, anchors.usd_irr_free],
    enabled: ready && Boolean(anchors.gold_18k || anchors.xau_usd || anchors.xag_usd || anchors.usd_irr_free),
    queryFn: async () => {
      const results = await Promise.allSettled(
        PREDICABLES.map(async ({ symbol }): Promise<{ symbol: string; forecasts: Forecast[] }> => {
          const last = String(anchors[symbol] ?? "");
          if (!last) return { symbol, forecasts: [] };
          const settled = await Promise.allSettled(
            HORIZONS.map((h) =>
              apiGet<{ data?: Forecast }>(`/forecast?symbol=${symbol}&horizon=${h}&last_close=${last}`).then((r) => r?.data ?? (r as unknown as Forecast)),
            ),
          );
          const forecasts = settled
            .filter((s): s is PromiseFulfilledResult<Forecast> => s.status === "fulfilled")
            .map((s) => s.value)
            .filter((f) => f?.forecast?.length)
            .sort((a, b) => a.horizon_days - b.horizon_days);
          return { symbol, forecasts };
        }),
      );
      return results.filter((r): r is PromiseFulfilledResult<{ symbol: string; forecasts: Forecast[] }> => r.status === "fulfilled").map((r) => r.value);
    },
    staleTime: 60_000,
  });

  const isLoading = goldQ.isLoading || fxQ.isLoading || forecastsQ.isLoading;

  return (
    <AppLayout title="پیشبینی قیمتها" subtitle="پیشبینی هوشمند برای قیمتهای کلیدی بازار">
      {/* ─── Hero ─── */}
      <div className="mb-6 rounded-[28px] border border-violet-500/20 bg-gradient-to-l from-violet-950/40 via-surface-900 to-surface-900 relative overflow-hidden">
        <div className="absolute -top-20 -left-20 w-80 h-80 bg-violet-400/10 rounded-full blur-[90px]" />
        <div className="relative p-6 sm:p-8">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-violet-500/10 border border-violet-500/20 text-violet-200 text-xs">
            <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
            دادههای واقعی • قیمت پایه از BrsApi
            <span className="opacity-60">•</span>
            <Sparkles className="w-3 h-3" />
            مدل xgboost_ensemble
          </div>
          <h1 className="mt-4 text-2xl sm:text-3xl font-black tracking-tight text-white">
            پیشبینی قیمتها <span className="text-violet-400">— همه بازارها</span>
          </h1>
          <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-400">
            پیشبینی p50 با بازه عدمقطعیت ۸۰٪ برای طلای ۱۸ عیار، اونس طلا، اونس نقره و دلار آزاد در افقهای ۱ تا ۹۰ روزه
          </p>
        </div>
      </div>

      <div className="mb-4 flex items-center gap-2 text-xs text-amber-300">
        <span className="rounded-full bg-amber-500/10 border border-amber-500/20 px-2.5 py-1">⚠️ پیشبینی صرفاً برای تحلیل است؛ تضمین بازده نیست.</span>
      </div>

      {isLoading ? (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-2">
          {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-64 w-full rounded-2xl" />)}
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2">
          {PREDICABLES.map(({ symbol, label, unit, type }) => {
            const item = forecastsQ.data?.find((f) => f.symbol === symbol);
            const f = item?.forecasts?.[item.forecasts.length - 1];
            const horizonEntry = f ? item?.forecasts.find((x) => x.horizon_days === 7) ?? f : null;
            const anchor = anchors[symbol];
            const last = f?.forecast?.[f.forecast.length - 1];
            const first = f?.forecast?.[0];
            const change = last && first ? ((last.p50 / first.p50) - 1) * 100 : 0;
            const up = change >= 0;
            const isOpen = open === symbol;
            return (
              <div key={symbol} className="rounded-2xl border border-surface-800 bg-surface-900/40 p-4 hover:bg-surface-800/40 transition" dir="rtl">
                <div className="flex items-start justify-between gap-2">
                  <div className="flex items-center gap-2.5">
                    <div className={`w-9 h-9 rounded-xl grid place-items-center ${type === "global" ? "bg-gradient-to-br from-cyan-400/30 to-blue-600/30 text-cyan-300" : "bg-gradient-to-br from-amber-400/30 to-yellow-600/30 text-amber-300"}`}>
                      {type === "global" ? <Globe className="w-4 h-4" /> : <Gem className="w-4 h-4" />}
                    </div>
                    <div>
                      <div className="text-sm font-bold text-surface-100">{label}</div>
                      <div className="font-mono text-[10px] text-surface-500">{symbol}</div>
                    </div>
                  </div>
                  <span className={`text-xs px-2 py-1 rounded-full font-mono ${up ? "bg-emerald-500/15 text-emerald-400" : "bg-rose-500/15 text-rose-400"}`}>
                    {up ? <TrendingUp className="w-3 h-3 inline" /> : <TrendingDown className="w-3 h-3 inline" />} {faPct(change)}
                  </span>
                </div>

                <div className="mt-3 flex items-end justify-between gap-2">
                  <div>
                    <div className="text-[10px] text-surface-500">قیمت فعلی ({unit})</div>
                    <div className="mt-1 text-xl font-black font-mono text-slate-200">{anchor ? fa(anchor) : "—"}</div>
                  </div>
                  <div className="text-left">
                    <div className="text-[10px] text-surface-500">پیشبینی روز پایانی</div>
                    <div className={`mt-1 text-xl font-black font-mono ${up ? "text-emerald-300" : "text-rose-300"}`} dir="ltr">
                      {last ? last.p50.toFixed(2) : "—"}
                    </div>
                  </div>
                </div>

                {/* ─── Horizon chips ─── */}
                <div className="mt-3 grid grid-cols-3 gap-1.5">
                  {(item?.forecasts ?? []).map((hf) => {
                    const hp = hf.forecast[hf.forecast.length - 1];
                    const pct = first?.p50 ? ((hp.p50 / first.p50) - 1) * 100 : 0;
                    const hu = pct >= 0;
                    return (
                      <div key={hf.horizon_days} className="rounded-lg border border-surface-800 bg-surface-950/40 px-2 py-1.5 text-center">
                        <div className="text-[9px] text-surface-500">{hf.horizon_days} روز</div>
                        <div className={`mt-0.5 text-[11px] font-mono font-bold ${hu ? "text-emerald-400" : "text-rose-400"}`} dir="ltr">
                          {hp.p50.toFixed(2)}
                        </div>
                      </div>
                    );
                  })}
                </div>

                {f && <div className="mt-3"><MiniCurve pts={f.forecast} up={up} /></div>}

                <button
                  onClick={() => setOpen(isOpen ? null : symbol)}
                  className="mt-4 w-full inline-flex items-center justify-center gap-1.5 rounded-xl border border-surface-700 bg-surface-800/60 px-3 py-2 text-xs font-bold text-surface-300 hover:bg-surface-800 transition"
                >
                  {isOpen ? <ChevronUp className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
                  {isOpen ? "بستن جزئیات" : "مشاهده جزئیات همه افقها"}
                </button>

                {isOpen && horizonEntry && (
                  <div className="mt-3 overflow-auto rounded-xl border border-surface-800">
                    <table className="w-full text-xs">
                      <thead className="bg-surface-800/60 text-surface-400">
                        <tr>
                          <th className="p-2 text-right">افق</th>
                          <th className="p-2 text-left">p50</th>
                          <th className="p-2 text-left">بازه</th>
                          <th className="p-2 text-left">احتمال رشد</th>
                        </tr>
                      </thead>
                      <tbody>
                        {horizonEntry.forecast.map((p, i) => (
                          <tr key={i} className="border-t border-surface-800">
                            <td className="p-2 font-mono text-surface-400">{p.date}</td>
                            <td className="p-2 font-mono font-bold text-surface-100" dir="ltr">{p.p50.toFixed(2)}</td>
                            <td className="p-2 font-mono text-surface-500" dir="ltr">{p.p_lower.toFixed(2)} – {p.p_upper.toFixed(2)}</td>
                            <td className={`p-2 font-mono font-bold ${p.direction_probability_up >= 0.5 ? "text-emerald-400" : "text-rose-400"}`}>
                              {(p.direction_probability_up * 100).toFixed(1)}٪
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {!isLoading && forecastsQ.data?.every((f) => f.forecasts.length === 0) && (
        <div className="rounded-2xl border border-amber-500/20 bg-amber-500/5 p-5 text-sm text-amber-200/80">
          پیشبینی برای هیچ نمادی در دسترس نیست. ابتدا دادهی BrsApi و مدل پیشبینی را بررسی کنید.
        </div>
      )}

      <div className="mt-6 p-4 rounded-2xl border border-amber-500/20 bg-amber-500/5 text-[12px] leading-6 text-amber-200/80">
        <BarChart3 className="w-4 h-4 inline ml-1" />
        پیشبینیها محصول مدل آماری xgboost_ensemble بر پایه قیمت آخرین معامله (last_close) و بازه عدمقطعیت منطقهمحور هستند. این خروجی ابزار تحلیل است نه توصیه معاملاتی.
      </div>
    </AppLayout>
  );
}

"use client";

import { useState, type FormEvent } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import { apiGet, apiPut, apiPost } from "@/lib/api";
import { useAuth } from "@/lib/auth-context";
import { useRouter } from "next/navigation";

interface UserProfile {
  id: string;
  username: string;
  email: string;
  full_name: string;
  phone: string;
  roles: string[];
  is_active: boolean;
  is_verified: boolean;
  last_login: string | null;
  created_at: string | null;
}

interface LoginHistoryItem {
  ip_address: string;
  user_agent: string;
  created_at: string;
}

const ROLE_LABELS: Record<string, { label: string; color: string }> = {
  admin: { label: "ادمین", color: "bg-rose-500/20 text-rose-400" },
  analyst: { label: "تحلیلگر", color: "bg-amber-500/20 text-amber-400" },
  user: { label: "کاربر", color: "bg-emerald-500/20 text-emerald-400" },
  viewer: { label: "بیننده", color: "bg-surface-600/20 text-surface-400" },
};

function formatDate(iso: string | null): string {
  if (!iso) return "—";
  try {
    return new Date(iso).toLocaleDateString("fa-IR", {
      year: "numeric",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  } catch {
    return "—";
  }
}

export default function ProfilePage() {
  const { user, logout } = useAuth();
  const router = useRouter();
  const queryClient = useQueryClient();

  // Profile form state
  const [fullName, setFullName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");

  // Password form state
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");

  // Messages
  const [profileMsg, setProfileMsg] = useState("");
  const [passwordMsg, setPasswordMsg] = useState("");

  // Fetch user profile
  const { data: profile, isLoading } = useQuery<UserProfile>({
    queryKey: ["user-profile"],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: UserProfile }>("/auth/me");
      return res.data || res;
    },
    staleTime: 60_000,
  });

  // Sync profile data to form fields once when loaded.
  // React-documented pattern: adjust state during render (guarded by a marker)
  // instead of an effect, to avoid cascading renders after data arrives.
  const [syncedProfileId, setSyncedProfileId] = useState<string | null>(null);
  if (profile && profile.id !== syncedProfileId) {
    setSyncedProfileId(profile.id);
    setFullName(profile.full_name || "");
    setPhone(profile.phone || "");
    setEmail(profile.email || "");
  }

  // Update profile mutation
  const updateProfileMutation = useMutation({
    mutationFn: async () => {
      return apiPut("/auth/profile", {
        full_name: fullName,
        phone: phone,
        email: email,
      });
    },
    onSuccess: () => {
      setProfileMsg("✅ پروفایل با موفقیت به‌روزرسانی شد");
      queryClient.invalidateQueries({ queryKey: ["user-profile"] });
      setTimeout(() => setProfileMsg(""), 3000);
    },
    onError: () => {
      setProfileMsg("❌ خطا در به‌روزرسانی پروفایل");
      setTimeout(() => setProfileMsg(""), 3000);
    },
  });

  // Change password mutation
  const changePasswordMutation = useMutation({
    mutationFn: async () => {
      return apiPost("/auth/change-password", {
        current_password: currentPassword,
        new_password: newPassword,
      });
    },
    onSuccess: () => {
      setPasswordMsg("✅ رمز عبور با موفقیت تغییر کرد. لطفاً مجدداً وارد شوید.");
      setTimeout(() => {
        logout();
        router.push("/auth/login");
      }, 2000);
    },
    onError: () => {
      setPasswordMsg("❌ خطا در تغییر رمز عبور. رمز فعلی صحیح نیست.");
      setTimeout(() => setPasswordMsg(""), 3000);
    },
  });

  const handleProfileSubmit = (e: FormEvent) => {
    e.preventDefault();
    updateProfileMutation.mutate();
  };

  const handlePasswordSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      setPasswordMsg("❌ رمز جدید و تکرار آن مطابقت ندارند");
      return;
    }
    if (newPassword.length < 8) {
      setPasswordMsg("❌ رمز جدید باید حداقل ۸ حرف باشد");
      return;
    }
    changePasswordMutation.mutate();
  };

  return (
    <AppLayout title="👤 پروفایل کاربری" subtitle="مشاهده و ویرایش اطلاعات شخصی">
      <div className="max-w-2xl mx-auto space-y-6">
        {/* ── User Info Card ── */}
        <div className="glass-card p-6">
          <div className="flex items-center gap-4 mb-6">
            <div className="w-16 h-16 rounded-full bg-surface-700 flex items-center justify-center text-2xl">
              {profile?.username?.[0]?.toUpperCase() || "👤"}
            </div>
            <div>
              {isLoading ? (
                <Skeleton className="h-6 w-32 mb-1" />
              ) : (
                <h2 className="text-xl font-bold text-surface-100">{profile?.username}</h2>
              )}
              {profile?.roles?.[0] && (
                <span className={`px-2 py-0.5 rounded-full text-[10px] font-medium ${ROLE_LABELS[profile.roles[0]]?.color || "bg-surface-600/20 text-surface-400"}`}>
                  {ROLE_LABELS[profile.roles[0]]?.label || profile.roles[0]}
                </span>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4 text-sm">
            <div>
              <span className="text-surface-500">شناسه:</span>
              <span className="text-surface-300 mr-2 font-mono text-xs">{profile?.id || "—"}</span>
            </div>
            <div>
              <span className="text-surface-500">نام کاربری:</span>
              <span className="text-surface-300 mr-2">{profile?.username || "—"}</span>
            </div>
            <div>
              <span className="text-surface-500">ایمیل:</span>
              <span className="text-surface-300 mr-2">{profile?.email || "—"}</span>
            </div>
            <div>
              <span className="text-surface-500">تلفن:</span>
              <span className="text-surface-300 mr-2">{profile?.phone || "—"}</span>
            </div>
            <div>
              <span className="text-surface-500">وضعیت:</span>
              <span className={`mr-2 ${profile?.is_active ? "text-accent-emerald" : "text-accent-rose"}`}>
                {profile?.is_active ? "✅ فعال" : "❌ غیرفعال"}
              </span>
            </div>
            <div>
              <span className="text-surface-500">تایید شده:</span>
              <span className={`mr-2 ${profile?.is_verified ? "text-accent-emerald" : "text-surface-500"}`}>
                {profile?.is_verified ? "✅ بله" : "— خیر"}
              </span>
            </div>
            <div>
              <span className="text-surface-500">آخرین ورود:</span>
              <span className="text-surface-300 mr-2 text-xs">{formatDate(profile?.last_login || null)}</span>
            </div>
            <div>
              <span className="text-surface-500">تاریخ عضویت:</span>
              <span className="text-surface-300 mr-2 text-xs">{formatDate(profile?.created_at || null)}</span>
            </div>
          </div>
        </div>

        {/* ── Edit Profile Form ── */}
        <div className="glass-card p-6">
          <h3 className="text-lg font-bold text-surface-200 mb-4">✏️ ویرایش اطلاعات</h3>
          {profileMsg && (
            <div className={`px-4 py-2 rounded-lg mb-4 text-sm ${profileMsg.startsWith("✅") ? "bg-accent-emerald/10 text-accent-emerald" : "bg-accent-rose/10 text-accent-rose"}`}>
              {profileMsg}
            </div>
          )}
          <form onSubmit={handleProfileSubmit} className="space-y-4">
            <div>
              <label className="block text-sm text-surface-500 mb-1">نام و نام خانوادگی</label>
              <input
                type="text"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                className="w-full bg-surface-800 border border-surface-700 rounded-lg px-4 py-2.5 text-white focus:outline-none focus:border-primary-500 transition"
                placeholder="نام کامل"
              />
            </div>
            <div>
              <label className="block text-sm text-surface-500 mb-1">تلفن</label>
              <input
                type="text"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                className="w-full bg-surface-800 border border-surface-700 rounded-lg px-4 py-2.5 text-white focus:outline-none focus:border-primary-500 transition"
                placeholder="شماره تلفن"
              />
            </div>
            <div>
              <label className="block text-sm text-surface-500 mb-1">ایمیل</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-surface-800 border border-surface-700 rounded-lg px-4 py-2.5 text-white focus:outline-none focus:border-primary-500 transition"
                placeholder="example@email.com"
              />
            </div>
            <button
              type="submit"
              disabled={updateProfileMutation.isPending}
              className="w-full bg-primary-600 hover:bg-primary-500 disabled:opacity-50 text-white rounded-lg py-2.5 font-medium transition"
            >
              {updateProfileMutation.isPending ? "در حال ذخیره..." : "ذخیره تغییرات"}
            </button>
          </form>
        </div>

        {/* ── Change Password Form ── */}
        <div className="glass-card p-6">
          <h3 className="text-lg font-bold text-surface-200 mb-4">🔒 تغییر رمز عبور</h3>
          {passwordMsg && (
            <div className={`px-4 py-2 rounded-lg mb-4 text-sm ${passwordMsg.startsWith("✅") ? "bg-accent-emerald/10 text-accent-emerald" : "bg-accent-rose/10 text-accent-rose"}`}>
              {passwordMsg}
            </div>
          )}
          <form onSubmit={handlePasswordSubmit} className="space-y-4">
            <div>
              <label className="block text-sm text-surface-500 mb-1">رمز عبور فعلی</label>
              <input
                type="password"
                value={currentPassword}
                onChange={(e) => setCurrentPassword(e.target.value)}
                className="w-full bg-surface-800 border border-surface-700 rounded-lg px-4 py-2.5 text-white focus:outline-none focus:border-primary-500 transition"
                placeholder="رمز عبور فعلی"
                required
              />
            </div>
            <div>
              <label className="block text-sm text-surface-500 mb-1">رمز عبور جدید</label>
              <input
                type="password"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                className="w-full bg-surface-800 border border-surface-700 rounded-lg px-4 py-2.5 text-white focus:outline-none focus:border-primary-500 transition"
                placeholder="حداقل ۸ حرف"
                required
                minLength={8}
              />
            </div>
            <div>
              <label className="block text-sm text-surface-500 mb-1">تکرار رمز عبور جدید</label>
              <input
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                className="w-full bg-surface-800 border border-surface-700 rounded-lg px-4 py-2.5 text-white focus:outline-none focus:border-primary-500 transition"
                placeholder="تکرار رمز عبور جدید"
                required
                minLength={8}
              />
            </div>
            <button
              type="submit"
              disabled={changePasswordMutation.isPending}
              className="w-full bg-accent-rose/80 hover:bg-accent-rose disabled:opacity-50 text-white rounded-lg py-2.5 font-medium transition"
            >
              {changePasswordMutation.isPending ? "در حال تغییر..." : "تغییر رمز عبور"}
            </button>
          </form>
        </div>

        {/* ── Login History ── */}
        <LoginHistorySection />
      </div>
    </AppLayout>
  );
}

function LoginHistorySection() {
  const { data: historyData, isLoading } = useQuery<{
    items: LoginHistoryItem[];
    total: number;
  }>({
    queryKey: ["login-history"],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: { items: LoginHistoryItem[]; total: number } }>(
        "/auth/login-history?limit=20"
      );
      return res.data || { items: [], total: 0 };
    },
    staleTime: 60_000,
  });

  const items = historyData?.items || [];

  function parseUA(ua: string): string {
    if (!ua) return "—";
    // Simplified user agent parsing
    if (ua.includes("Chrome")) return "Chrome";
    if (ua.includes("Firefox")) return "Firefox";
    if (ua.includes("Safari") && !ua.includes("Chrome")) return "Safari";
    if (ua.includes("Edge")) return "Edge";
    if (ua.includes("curl")) return "cURL";
    return ua.substring(0, 40);
  }

  return (
    <div className="glass-card p-6">
      <h3 className="text-lg font-bold text-surface-200 mb-4">🕐 تاریخچه ورودها</h3>
      {isLoading ? (
        <div className="space-y-3">
          <Skeleton className="h-10 w-full" />
          <Skeleton className="h-10 w-full" />
          <Skeleton className="h-10 w-full" />
        </div>
      ) : items.length === 0 ? (
        <p className="text-surface-500 text-sm text-center py-4">
          سابقه ورودی ثبت نشده است.
        </p>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-surface-700 text-surface-500">
                <th className="text-right py-2 px-3">تاریخ و ساعت</th>
                <th className="text-right py-2 px-3">آدرس IP</th>
                <th className="text-right py-2 px-3">مرورگر</th>
              </tr>
            </thead>
            <tbody>
              {items.map((item, idx) => (
                <tr
                  key={idx}
                  className="border-b border-surface-800 hover:bg-surface-800/50 transition-colors"
                >
                  <td className="py-2.5 px-3 text-surface-300 text-xs">
                    {formatDate(item.created_at)}
                  </td>
                  <td className="py-2.5 px-3 text-surface-400 font-mono text-xs">
                    {item.ip_address || "—"}
                  </td>
                  <td className="py-2.5 px-3 text-surface-400 text-xs">
                    {parseUA(item.user_agent)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import { apiGet } from "@/lib/api";
import { formatDateShamsi } from "@/lib/dates";
import Link from "next/link";

// ------ Types -------------------------------------------------------------------------------------------------------

interface Recommendation {
  id: string;
  instrument_id: string;
  symbol: string;
  action: string;
  target_price: number | null;
  current_price: number;
  potential_return_pct: number;
  confidence: number;
  horizon: string;
  source: string;
  analyst: string;
  rationale: string;
  tags: string[];
  stop_loss: number | null;
  strategy: string;
  risk_level: string;
  generated_at: string | null;
  expires_at: string | null;
  created_at: string | null;
}

interface PaginatedResult<T> {
  items: T[];
  total: number;
  page: number;
  page_size: number;
  total_pages: number;
}

// ------ Helpers -----------------------------------------------------------------------------------------------------

const ACTION_META: Record<string, { label: string; icon: string; color: string }> = {
  strong_buy: { label: "خرید قوی", icon: "🔥", color: "bg-accent-emerald text-white" },
  buy: { label: "خرید", icon: "📈", color: "bg-accent-emerald/15 text-accent-emerald border border-accent-emerald/30" },
  accumulate: { label: "انباشت", icon: "📊", color: "bg-accent-emerald/10 text-accent-emerald/70 border border-accent-emerald/20" },
  hold: { label: "نگهداری", icon: "⏸️", color: "bg-accent-amber/15 text-accent-amber border border-accent-amber/30" },
  reduce: { label: "کاهش", icon: "📉", color: "bg-accent-rose/10 text-accent-rose/70 border border-accent-rose/20" },
  sell: { label: "فروش", icon: "📉", color: "bg-accent-rose/15 text-accent-rose border border-accent-rose/30" },
  strong_sell: { label: "فروش قوی", icon: "🚨", color: "bg-accent-rose text-white" },
};

const HORIZON_LABELS: Record<string, string> = {
  short_term: "کوتاه‌مدت",
  medium_term: "میان‌مدت",
  long_term: "بلندمدت",
};

const RISK_LABELS: Record<string, { label: string; color: string }> = {
  low: { label: "کم", color: "text-accent-emerald" },
  medium: { label: "متوسط", color: "text-accent-amber" },
  high: { label: "زیاد", color: "text-accent-rose" },
  very_high: { label: "خیلی زیاد", color: "text-accent-rose font-bold" },
};

const STRATEGY_LABELS: Record<string, string> = {
  value: "ارزشی",
  growth: "رشدی",
  momentum: "مومنتوم",
  income: "سودآوری",
  technical: "تکنیکال",
  fundamental: "بنیادی",
  sentiment: "احساسات",
  ml_model: "مدل ML",
  hybrid: "ترکیبی",
  manual: "دستی",
};

function formatNumber(n: number | null | undefined): string {
  if (n == null) return "—";
  if (Math.abs(n) >= 1_000_000_000_000) return (n / 1_000_000_000_000).toFixed(2) + "T";
  if (Math.abs(n) >= 1_000_000_000) return (n / 1_000_000_000).toFixed(2) + "B";
  if (Math.abs(n) >= 1_000_000) return (n / 1_000_000).toFixed(2) + "M";
  if (Math.abs(n) >= 1_000) return (n / 1_000).toFixed(1) + "K";
  return n.toLocaleString("en-US");
}

function formatPct(val: number | null | undefined): { text: string; color: string } {
  if (val == null) return { text: "—", color: "text-surface-500" };
  if (val > 0) return { text: `+${val.toFixed(1)}%`, color: "text-accent-emerald" };
  if (val < 0) return { text: `${val.toFixed(1)}%`, color: "text-accent-rose" };
  return { text: "0.0%", color: "text-surface-400" };
}

function getActionLabel(action: string): string {
  return ACTION_META[action]?.label ?? action;
}

function getActionColor(action: string): string {
  return ACTION_META[action]?.color ?? "bg-surface-700 text-surface-300";
}

function getActionIcon(action: string): string {
  return ACTION_META[action]?.icon ?? "❓";
}

// ------ Components --------------------------------------------------------------------------------------------------

function ActionBadge({ action }: { action: string }) {
  const meta = ACTION_META[action];
  return (
    <span className={`inline-flex items-center gap-1 text-xs font-bold px-2.5 py-1 rounded-lg ${getActionColor(action)}`}>
      <span>{getActionIcon(action)}</span>
      <span>{getActionLabel(action)}</span>
    </span>
  );
}

function ConfidenceBar({ value }: { value: number }) {
  const pct = Math.min(100, Math.max(0, value * 100));
  const color = pct >= 70 ? "bg-accent-emerald" : pct >= 40 ? "bg-accent-amber" : "bg-accent-rose";
  return (
    <div className="flex items-center gap-2">
      <div className="flex-1 h-1.5 bg-surface-700 rounded-full overflow-hidden" dir="ltr">
        <div className={`h-full rounded-full transition-all ${color}`} style={{ width: `${pct}%` }} />
      </div>
      <span className="text-xs font-mono text-surface-300 w-8 text-right">{pct.toFixed(0)}%</span>
    </div>
  );
}

function ReturnBadge({ pct }: { pct: number | null | undefined }) {
  const fmt = formatPct(pct);
  return <span className={`text-sm font-bold font-mono ${fmt.color}`}>{fmt.text}</span>;
}

function UpliftSection({ current, target }: { current: number; target: number | null }) {
  if (!target || !current) return null;
  const uplift = ((target - current) / current) * 100;
  return (
    <div className="flex items-center gap-2 text-xs">
      <span className="text-surface-500">هدف:</span>
      <span className="font-mono font-bold text-surface-200">{formatNumber(target)}</span>
      <span className="font-mono text-xs">({(uplift > 0 ? "+" : "") + uplift.toFixed(1)}%)</span>
    </div>
  );
}

// ------ Stats Card Component ----------------------------------------------------------------------------------------

function StatCard({ icon, label, value, color }: { icon: string; label: string; value: string; color?: string }) {
  return (
    <div className="glass-card p-3 flex items-center gap-3">
      <span className="text-xl">{icon}</span>
      <div>
        <div className="text-xs text-surface-500">{label}</div>
        <div className={`text-lg font-bold ${color || "text-surface-100"}`}>{value}</div>
      </div>
    </div>
  );
}

// ------ Main Page ---------------------------------------------------------------------------------------------------

export default function RecommendationsPage() {
  const [actionFilter, setActionFilter] = useState<string | null>(null);
  const [horizonFilter, setHorizonFilter] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [searchSymbol, setSearchSymbol] = useState("");
  const pageSize = 25;

  // Fetch recommendations
  const { data, isLoading, isError, refetch } = useQuery({
    queryKey: ["recommendations", page, actionFilter, horizonFilter],
    queryFn: async () => {
      const params = new URLSearchParams({ page: String(page), page_size: String(pageSize) });
      const res = await apiGet<{ success: boolean; data: PaginatedResult<Recommendation> }>(
        `/recommendations?${params.toString()}`
      );
      return res?.data ?? { items: [], total: 0, page: 1, page_size: 25, total_pages: 1 };
    },
    refetchInterval: 60_000,
    staleTime: 30_000,
  });

  const recommendations = data?.items ?? [];
  const total = data?.total ?? 0;
  const totalPages = Math.max(1, data?.total_pages ?? 1);

  // Apply client-side filters
  let filtered = recommendations;
  if (actionFilter) {
    filtered = filtered.filter((r) => r.action === actionFilter);
  }
  if (horizonFilter) {
    filtered = filtered.filter((r) => r.horizon === horizonFilter);
  }
  if (searchSymbol) {
    const q = searchSymbol.toLowerCase();
    filtered = filtered.filter((r) => r.symbol.toLowerCase().includes(q));
  }

  // Compute stats
  const buyRecs = recommendations.filter((r) => r.action.includes("buy") || r.action === "accumulate" || r.action === "strong_buy");
  const sellRecs = recommendations.filter((r) => r.action.includes("sell") || r.action === "reduce" || r.action === "strong_sell");
  const holdRecs = recommendations.filter((r) => r.action === "hold");
  const avgConfidence = recommendations.length > 0
    ? recommendations.reduce((s, r) => s + (r.confidence ?? 0), 0) / recommendations.length
    : 0;

  const ACTION_TYPES = ["strong_buy", "buy", "accumulate", "hold", "reduce", "sell", "strong_sell"];

  return (
    <AppLayout
      title="توصیه‌ها"
      subtitle={total.toLocaleString("en-US") + " توصیه • " + buyRecs.length + " خرید • " + sellRecs.length + " فروش • " + holdRecs.length + " نگهداری"}
    >
      <div className="max-w-7xl mx-auto space-y-5">
        {/* Stats Row */}
        {!isLoading && recommendations.length > 0 && (
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <StatCard icon="💎" label="کل توصیه‌ها" value={total.toLocaleString("en-US")} />
            <StatCard icon="🟢" label="خرید" value={buyRecs.length.toLocaleString("en-US")} color="text-accent-emerald" />
            <StatCard icon="🔴" label="فروش" value={sellRecs.length.toLocaleString("en-US")} color="text-accent-rose" />
            <StatCard icon="⏸️" label="نگهداری" value={holdRecs.length.toLocaleString("en-US")} color="text-accent-amber" />
          </div>
        )}

        {/* Filters */}
        <div className="glass-card p-4">
          <div className="flex flex-wrap items-center gap-3">
            {/* Action Filter */}
            <div className="flex flex-wrap gap-1">
              <button
                onClick={() => setActionFilter(null)}
                className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                  !actionFilter
                    ? "bg-primary-600 text-white shadow-lg"
                    : "bg-surface-800 text-surface-400 hover:text-surface-200"
                }`}
              >
                همه
              </button>
              {[
                { key: "buy", label: "خرید", icon: "🟢" },
                { key: "sell", label: "فروش", icon: "🔴" },
                { key: "hold", label: "خنثی", icon: "⏸️" },
              ].map((opt) => (
                <button
                  key={opt.key}
                  onClick={() => setActionFilter(actionFilter === opt.key ? null : opt.key)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                    actionFilter === opt.key
                      ? "bg-primary-600 text-white shadow-lg"
                      : "bg-surface-800 text-surface-400 hover:text-surface-200"
                  }`}
                >
                  {opt.icon} {opt.label}
                </button>
              ))}
            </div>

            <div className="w-px h-6 bg-surface-700" />

            {/* Horizon Filter */}
            <div className="flex gap-1">
              {[
                { key: "short_term", label: "کوتاه‌مدت" },
                { key: "medium_term", label: "میان‌مدت" },
                { key: "long_term", label: "بلندمدت" },
              ].map((opt) => (
                <button
                  key={opt.key}
                  onClick={() => setHorizonFilter(horizonFilter === opt.key ? null : opt.key)}
                  className={`px-3 py-1.5 rounded-lg text-xs transition-all ${
                    horizonFilter === opt.key
                      ? "bg-surface-700 text-surface-100"
                      : "bg-surface-800 text-surface-400 hover:text-surface-200"
                  }`}
                >
                  {opt.label}
                </button>
              ))}
            </div>

            <div className="w-px h-6 bg-surface-700" />

            {/* Symbol Search */}
            <div className="flex items-center gap-2">
              <span className="material-icons text-sm text-surface-500">search</span>
              <input
                type="text"
                value={searchSymbol}
                onChange={(e) => setSearchSymbol(e.target.value)}
                placeholder="جستجوی نماد..."
                className="bg-surface-800 border border-surface-700 rounded-lg px-3 py-1.5 text-sm text-surface-100 w-28 outline-none focus:border-primary-500 font-mono"
              />
            </div>

            {/* Refresh */}
            <button
              onClick={() => refetch()}
              className="p-1.5 rounded-lg bg-surface-800 text-surface-400 hover:text-surface-200 transition-colors"
              title="Refresh"
            >
              <span className="material-icons text-sm">refresh</span>
            </button>
          </div>

          {/* Summary */}
          {recommendations.length > 0 && (
            <div className="mt-3 flex items-center gap-4 text-xs text-surface-500">
              <span>نمایش {filtered.length} از {total} توصیه</span>
              {actionFilter && <span>• فیلتر: {getActionLabel(actionFilter)}</span>}
              {horizonFilter && <span>• افق: {HORIZON_LABELS[horizonFilter] || horizonFilter}</span>}
              {searchSymbol && <span>• نماد: {searchSymbol}</span>}
              <span>• اطمینان میانگین: {(avgConfidence * 100).toFixed(0)}%</span>
            </div>
          )}
        </div>

        {/* Recommendations List */}
        {isLoading ? (
          <div className="space-y-3">
            {Array.from({ length: 5 }).map((_, i) => (
              <Skeleton key={i} className="h-28 w-full rounded-xl" />
            ))}
          </div>
        ) : isError ? (
          <div className="text-center py-16 text-accent-rose">
            <p className="text-5xl mb-4">⚠️</p>
            <p className="text-lg font-medium">خطا در دریافت توصیه‌ها</p>
            <p className="text-sm mt-1 text-surface-500">اتصال به سرور را بررسی کنید</p>
            <button
              onClick={() => refetch()}
              className="mt-4 px-4 py-2 bg-primary-600 hover:bg-primary-500 text-white rounded-lg text-sm transition-colors"
            >
              تلاش مجدد
            </button>
          </div>
        ) : recommendations.length === 0 ? (
          <div className="text-center py-16 text-surface-500">
            <p className="text-5xl mb-4">📋</p>
            <p className="text-lg">هیچ توصیه‌ای یافت نشد</p>
            <p className="text-sm mt-1">توصیه‌ها از طریق API یا پنل مدیریت ایجاد می‌شوند</p>
            <div className="flex justify-center gap-3 mt-6">
              <Link
                href="/fundamental"
                className="px-4 py-2 bg-surface-800 hover:bg-surface-700 text-surface-200 rounded-lg text-sm transition-colors"
              >
                تحلیل بنیادی
              </Link>
              <Link
                href="/signals"
                className="px-4 py-2 bg-surface-800 hover:bg-surface-700 text-surface-200 rounded-lg text-sm transition-colors"
              >
                سیگنال‌ها
              </Link>
            </div>
          </div>
        ) : (
          <>
            {/* Card-style list */}
            <div className="space-y-3">
              {filtered.map((rec) => {
                const upside = rec.potential_return_pct ?? (rec.target_price && rec.current_price
                  ? ((rec.target_price - rec.current_price) / rec.current_price) * 100
                  : 0);

                return (
                  <div
                    key={rec.id}
                    className="glass-card p-4 hover:bg-surface-800/50 transition-colors"
                  >
                    <div className="flex items-start justify-between gap-4">
                      {/* Left side: Symbol + Action */}
                      <div className="flex items-center gap-3 min-w-0 flex-1">
                        <ActionBadge action={rec.action} />
                        <div className="min-w-0">
                          <div className="flex items-center gap-2">
                            <Link
                              href={`/symbol/${encodeURIComponent(rec.symbol)}`}
                              className="text-base font-bold text-surface-100 hover:text-primary-300 transition-colors"
                            >
                              {rec.symbol}
                            </Link>
                            {rec.risk_level && (
                              <span className={`text-[10px] font-mono ${RISK_LABELS[rec.risk_level]?.color ?? "text-surface-500"}`}>
                                {RISK_LABELS[rec.risk_level]?.label ?? rec.risk_level}
                              </span>
                            )}
                          </div>
                          <div className="flex items-center gap-3 mt-1 text-xs text-surface-500 flex-wrap">
                            <span>💰 {formatNumber(rec.current_price)}</span>
                            {rec.target_price && <span>🎯 {formatNumber(rec.target_price)}</span>}
                            <ReturnBadge pct={upside} />
                            <span>•</span>
                            <span>{HORIZON_LABELS[rec.horizon] || rec.horizon || "—"}</span>
                            {rec.analyst && (
                              <>
                                <span>•</span>
                                <span>👤 {rec.analyst}</span>
                              </>
                            )}
                          </div>
                        </div>
                      </div>

                      {/* Right side: Confidence + Date */}
                      <div className="text-right shrink-0 min-w-[120px]">
                        <div className="text-xs text-surface-500 mb-1">اطمینان</div>
                        <ConfidenceBar value={rec.confidence ?? 0} />
                        <div className="flex items-center justify-between mt-1.5 text-[10px] text-surface-600">
                          <span>{formatDateShamsi(rec.generated_at)}</span>
                          {rec.strategy && <span>{STRATEGY_LABELS[rec.strategy] || rec.strategy}</span>}
                        </div>
                      </div>
                    </div>

                    {/* Rationale */}
                    {rec.rationale && (
                      <div className="mt-3 pt-3 border-t border-surface-700/50 text-sm text-surface-400 leading-relaxed">
                        {rec.rationale}
                        {rec.tags && rec.tags.length > 0 && (
                          <div className="flex flex-wrap gap-1.5 mt-2">
                            {rec.tags.map((tag, i) => (
                              <span
                                key={i}
                                className="text-[10px] bg-surface-800 text-surface-500 px-2 py-0.5 rounded"
                              >
                                #{tag}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            {/* Pagination */}
            {totalPages > 1 && (
              <div className="flex items-center justify-between pt-2">
                <p className="text-xs text-surface-500">
                  صفحه {page} از {totalPages} — {total.toLocaleString("en-US")} توصیه
                </p>
                <div className="flex gap-1">
                  <button
                    onClick={() => setPage(Math.max(1, page - 1))}
                    disabled={page <= 1}
                    className="px-3 py-1.5 rounded-lg text-xs bg-surface-800 text-surface-400 hover:text-surface-200 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                  >
                    ← قبلی
                  </button>

                  {Array.from({ length: Math.min(totalPages, 5) }, (_, i) => {
                    let pageNum: number;
                    if (totalPages <= 5) {
                      pageNum = i + 1;
                    } else if (page <= 3) {
                      pageNum = i + 1;
                    } else if (page >= totalPages - 2) {
                      pageNum = totalPages - 4 + i;
                    } else {
                      pageNum = page - 2 + i;
                    }
                    return (
                      <button
                        key={pageNum}
                        onClick={() => setPage(pageNum)}
                        className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                          page === pageNum
                            ? "bg-primary-600 text-white shadow-lg"
                            : "bg-surface-800 text-surface-400 hover:text-surface-200"
                        }`}
                      >
                        {pageNum}
                      </button>
                    );
                  })}

                  <button
                    onClick={() => setPage(Math.min(totalPages, page + 1))}
                    disabled={page >= totalPages}
                    className="px-3 py-1.5 rounded-lg text-xs bg-surface-800 text-surface-400 hover:text-surface-200 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                  >
                    بعدی →
                  </button>
                </div>
              </div>
            )}
          </>
        )}

        {/* Quick Links */}
        <div className="flex flex-wrap gap-2 text-xs">
          <Link href="/signals" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            ← سیگنال‌ها
          </Link>
          <Link href="/analysis" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            تحلیل بازار
          </Link>
          <Link href="/fundamental" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            تحلیل بنیادی
          </Link>
          <Link href="/backtest" className="text-surface-500 hover:text-surface-200 transition-colors px-2 py-1">
            بک‌تست
          </Link>
        </div>

        {/* Legend */}
        <div className="glass-card p-3 text-xs text-surface-500">
          <p className="font-medium text-surface-400 mb-1">راهنما</p>
          <div className="flex flex-wrap gap-4">
            {ACTION_TYPES.map((action) => (
              <span key={action} className={`inline-flex items-center gap-1 px-2 py-0.5 rounded ${getActionColor(action)}`}>
                <span>{getActionIcon(action)}</span>
                <span>{getActionLabel(action)}</span>
              </span>
            ))}
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import Link from "next/link";
import AppLayout from "@/components/layout/AppLayout";
import { apiGet } from "@/lib/api";

// ── Types ──────────────────────────────────────────────────────────────────

interface ProfileStats {
  total_profiles: number;
  with_eps: number;
  with_profit: number;
  with_margin: number;
  with_loss: number;
  with_capital: number;
  avg_eps: number;
  avg_gross_margin: number;
}

interface SignalStats {
  total_signals: number;
  buy_count: number;
  dont_buy_count: number;
  risk_reject_count: number;
  score_reject_count: number;
  avg_final_score: number;
  max_final_score: number;
  correct_outcomes: number;
  tracked_outcomes: number;
}

interface ScoreBucket {
  bucket: string;
  cnt: number;
}

interface RecentSignal {
  symbol: string;
  final_score: number;
  decision: string;
  current_price: number;
  stop_loss_price: number;
  generated_at: string;
  score_fundamental: number;
  score_valuation: number;
  score_institutional: number;
  score_technical: number;
  score_macro: number;
}

interface IndustryStat {
  industry: string;
  cnt: number;
}

interface SystemStatus {
  last_populate: string | null;
  last_cycle: string | null;
  last_buy_signals: number;
  last_error: string | null;
}

interface MonitorData {
  profiles: ProfileStats;
  signals: SignalStats;
  score_distribution: ScoreBucket[];
  recent_signals: RecentSignal[];
  top_industries: IndustryStat[];
  system: SystemStatus;
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function fmtNum(n: number): string {
  if (n >= 1_000_000_000) return (n / 1_000_000_000).toFixed(1) + "B";
  if (n >= 1_000_000) return (n / 1_000_000).toFixed(1) + "M";
  if (n >= 1_000) return (n / 1_000).toFixed(1) + "K";
  return n.toLocaleString("fa-IR");
}

function fmtPct(n: number): string {
  return (n * 100).toFixed(1) + "%";
}

function fmtDate(iso: string | null): string {
  if (!iso) return "—";
  try {
    return new Date(iso).toLocaleString("fa-IR", {
      month: "short", day: "numeric", hour: "2-digit", minute: "2-digit",
    });
  } catch {
    return iso;
  }
}

function scoreColor(score: number): string {
  if (score >= 80) return "text-accent-emerald";
  if (score >= 60) return "text-primary-300";
  if (score >= 40) return "text-accent-amber";
  if (score >= 20) return "text-accent-rose";
  return "text-surface-500";
}

function scoreBg(score: number): string {
  if (score >= 80) return "bg-accent-emerald/15";
  if (score >= 60) return "bg-primary-600/20";
  if (score >= 40) return "bg-accent-amber/15";
  if (score >= 20) return "bg-accent-rose/15";
  return "bg-surface-800/50";
}

function decisionBadge(dec: string): { label: string; cls: string } {
  switch (dec) {
    case "خرید": return { label: "BUY", cls: "bg-accent-emerald/15 text-accent-emerald" };
    case "نخرید": return { label: "NO", cls: "bg-surface-600/30 text-surface-400" };
    case "رد_ریسک": return { label: "RISK", cls: "bg-accent-rose/15 text-accent-rose" };
    case "رد_نمره": return { label: "SCORE", cls: "bg-accent-amber/15 text-accent-amber" };
    default: return { label: dec || "—", cls: "bg-surface-800/50 text-surface-500" };
  }
}

// ── Stat Card ───────────────────────────────────────────────────────────────

function StatCard({ title, value, sub, accent = false }: {
  title: string; value: string; sub?: string; accent?: boolean;
}) {
  return (
    <div className={`glass-card p-4 ${accent ? "border-primary-500/30" : "border-surface-700/50"}`}>
      <div className="text-[10px] text-surface-500 mb-1 tracking-wide">{title}</div>
      <div className={`text-2xl font-black ${accent ? "text-primary-300" : "text-surface-100"}`}>
        {value}
      </div>
      {sub && <div className="text-[10px] text-surface-600 mt-0.5">{sub}</div>}
    </div>
  );
}

// ── Score Bar ───────────────────────────────────────────────────────────────

function ScoreBar({ label, value, maxWidth = 120 }: { label: string; value: number; maxWidth?: number }) {
  const pct = Math.min(value, 100);
  return (
    <div className="flex items-center gap-2" style={{ maxWidth }}>
      <span className="text-[10px] text-surface-500 w-8 text-right shrink-0">{label}</span>
      <div className="flex-1 h-2 bg-surface-800 rounded-full overflow-hidden">
        <div
          className={`h-full rounded-full transition-all duration-700 ${value >= 80 ? "bg-accent-emerald" : value >= 60 ? "bg-primary-500" : value >= 40 ? "bg-accent-amber" : "bg-accent-rose"}`}
          style={{ width: `${pct}%` }}
        />
      </div>
      <span className="text-[10px] font-mono text-surface-400 w-8 text-left">{pct.toFixed(0)}</span>
    </div>
  );
}

// ── Industry Badge ──────────────────────────────────────────────────────────

function IndustryBadge({ name, count, max }: { name: string; count: number; max: number }) {
  const pct = (count / max) * 100;
  return (
    <div className="flex items-center gap-2">
      <div className="flex-1 h-1.5 bg-surface-800 rounded-full overflow-hidden">
        <div className="h-full rounded-full bg-primary-500/60" style={{ width: `${pct}%` }} />
      </div>
      <span className="text-xs text-surface-300 min-w-[80px] text-right">{name}</span>
      <span className="text-[10px] font-mono text-surface-500 w-6 text-left">{count}</span>
    </div>
  );
}

// ── Mini Donut ──────────────────────────────────────────────────────────────

function MiniDonut({ value, size = 40, stroke = 5 }: { value: number; size?: number; stroke?: number }) {
  const r = (size - stroke) / 2;
  const circ = 2 * Math.PI * r;
  const offset = circ * (1 - Math.min(value, 100) / 100);
  const color = value >= 80 ? "#10b981" : value >= 60 ? "#818cf8" : value >= 40 ? "#f59e0b" : "#f43f5e";
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="shrink-0">
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="#1e293b" strokeWidth={stroke} />
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={color} strokeWidth={stroke}
        strokeDasharray={circ} strokeDashoffset={offset} strokeLinecap="round"
        transform={`rotate(-90 ${size / 2} ${size / 2})`}
        style={{ transition: "stroke-dashoffset 1s ease" }}
      />
    </svg>
  );
}

// ── Score Distribution Chart ────────────────────────────────────────────────

function ScoreDistChart({ data }: { data: ScoreBucket[] }) {
  if (!data || data.length === 0) {
    return (
      <div className="text-center py-8 text-surface-500 text-xs">
        No signals generated yet
      </div>
    );
  }
  const maxCnt = Math.max(...data.map(d => d.cnt), 1);
  const colors: Record<string, string> = {
    "80-100": "bg-accent-emerald", "60-80": "bg-primary-500",
    "40-60": "bg-accent-amber", "20-40": "bg-accent-rose/70",
    "0-20": "bg-surface-600", no_score: "bg-surface-800",
  };
  return (
    <div className="flex items-end gap-3 h-40 pt-4">
      {data.map(d => {
        const h = (d.cnt / maxCnt) * 100;
        return (
          <div key={d.bucket} className="flex-1 flex flex-col items-center gap-1">
            <span className="text-[9px] font-mono text-surface-400">{d.cnt}</span>
            <div className="w-full rounded-t-md relative group" style={{ height: `${Math.max(h, 4)}%` }}>
              <div className={`absolute inset-0 rounded-t-md ${colors[d.bucket] || "bg-surface-700"} opacity-80 group-hover:opacity-100 transition-opacity`} />
            </div>
            <span className="text-[8px] text-surface-600">{d.bucket}</span>
          </div>
        );
      })}
    </div>
  );
}

// ── Main Page ───────────────────────────────────────────────────────────────

export default function Screener110MonitorPage() {
  const [refreshing, setRefreshing] = useState(false);

  const { data: raw, isLoading, error, refetch } = useQuery({
    queryKey: ["screener110-monitor"],
    queryFn: async () => {
      const res = await apiGet<{ success: boolean; data: MonitorData }>("/screener110/monitor");
      return res?.data ?? null;
    },
    refetchInterval: 60_000,
    staleTime: 30_000,
  });

  const data = raw;

  const handleRefresh = async () => {
    setRefreshing(true);
    await refetch();
    setTimeout(() => setRefreshing(false), 500);
  };

  // ── Accuracy calc ──
  const accuracy = useMemo(() => {
    if (!data?.signals) return null;
    const { correct_outcomes, tracked_outcomes } = data.signals;
    if (tracked_outcomes === 0) return null;
    return ((correct_outcomes / tracked_outcomes) * 100).toFixed(1);
  }, [data]);

  return (
    <AppLayout
      title="Screener110 — Monitoring Dashboard"
      subtitle="Manitoring and analytics for the 110-column CANSLIM screener model"
    >
      {/* ── Header actions ── */}
      <div className="flex items-center gap-3 mb-5">
        <button
          onClick={handleRefresh}
          disabled={isLoading || refreshing}
          className="px-4 py-2 bg-surface-800 border border-surface-700 rounded-xl text-xs font-bold text-surface-300 hover:bg-surface-700 hover:text-surface-100 transition-all disabled:opacity-50 flex items-center gap-2"
        >
          <span className={`material-icons text-sm ${refreshing ? "animate-spin" : ""}`}>
            refresh
          </span>
          Refresh
        </button>
        <Link
          href="/screener"
          className="px-4 py-2 bg-surface-800 border border-surface-700 rounded-xl text-xs font-bold text-surface-300 hover:bg-surface-700 hover:text-surface-100 transition-all"
        >
          Smart Money Screener
        </Link>
        <span className="text-[10px] text-surface-600 mr-auto">
          Auto-refresh every 60s
        </span>
      </div>

      {/* ── Loading ── */}
      {isLoading && (
        <div className="space-y-4 animate-pulse">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {[1, 2, 3, 4].map(i => <div key={i} className="glass-card h-24" />)}
          </div>
          <div className="glass-card h-48" />
          <div className="glass-card h-64" />
        </div>
      )}

      {/* ── Error ── */}
      {error && !isLoading && (
        <div className="glass-card p-8 text-center border border-accent-rose/30">
          <span className="material-icons text-4xl text-accent-rose mb-3 block">error_outline</span>
          <p className="text-sm text-accent-rose mb-1">Failed to load monitoring data</p>
          <p className="text-xs text-surface-500">Check API connection and try again.</p>
        </div>
      )}

      {!isLoading && !error && data && (
        <>
          {/* ═══════════════ SECTION 1: Profile Stats ═══════════════ */}
          <div className="mb-6">
            <div className="flex items-center gap-2 mb-3">
              <span className="material-icons text-primary-400 text-lg">storage</span>
              <span className="text-sm font-bold text-surface-300">Screener Profiles</span>
            </div>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              <StatCard title="TOTAL PROFILES" value={data.profiles.total_profiles.toLocaleString("en-US")} sub="from symbols table" />
              <StatCard title="WITH EPS" value={data.profiles.with_eps.toLocaleString("en-US")} sub={data.profiles.total_profiles > 0 ? `${((data.profiles.with_eps / data.profiles.total_profiles) * 100).toFixed(0)}% coverage` : undefined} />
              <StatCard title="WITH NET PROFIT" value={fmtNum(data.profiles.with_profit)} sub={`avg: ${fmtNum(data.profiles.avg_eps)}`} accent />
              <StatCard title="WITH GROSS MARGIN" value={data.profiles.with_margin.toLocaleString("en-US")} sub={data.profiles.avg_gross_margin > 0 ? `avg: ${fmtPct(data.profiles.avg_gross_margin)}` : undefined} />
            </div>
            {/* Profile fill bars */}
            <div className="mt-3 glass-card p-4">
              <div className="text-xs font-bold text-surface-400 mb-3">Data Coverage</div>
              <div className="space-y-2">
                {[
                  { label: "EPS", val: data.profiles.with_eps / Math.max(data.profiles.total_profiles, 1) * 100 },
                  { label: "Net Profit", val: data.profiles.with_profit / Math.max(data.profiles.total_profiles, 1) * 100 },
                  { label: "Gross Margin", val: data.profiles.with_margin / Math.max(data.profiles.total_profiles, 1) * 100 },
                  { label: "Registered Capital", val: data.profiles.with_capital / Math.max(data.profiles.total_profiles, 1) * 100 },
                ].map(item => (
                  <div key={item.label} className="flex items-center gap-3">
                    <span className="text-[10px] text-surface-500 w-24 shrink-0">{item.label}</span>
                    <div className="flex-1 h-2 bg-surface-800 rounded-full overflow-hidden">
                      <div
                        className={`h-full rounded-full transition-all duration-700 ${item.val >= 50 ? "bg-accent-emerald" : item.val >= 20 ? "bg-accent-amber" : "bg-surface-600"}`}
                        style={{ width: `${item.val}%` }}
                      />
                    </div>
                    <span className="text-[10px] font-mono text-surface-400 w-10 text-right">{item.val.toFixed(0)}%</span>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* ═══════════════ SECTION 2: Signals Stats ═══════════════ */}
          <div className="mb-6">
            <div className="flex items-center gap-2 mb-3">
              <span className="material-icons text-accent-cyan text-lg">signal_cellular_alt</span>
              <span className="text-sm font-bold text-surface-300">Signals & Decisions</span>
            </div>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              <StatCard title="TOTAL SIGNALS" value={data.signals.total_signals.toLocaleString("en-US")} sub="generated by model" />
              <StatCard title="BUY SIGNALS" value={data.signals.buy_count.toLocaleString("en-US")} sub={data.signals.total_signals > 0 ? `${((data.signals.buy_count / Math.max(data.signals.total_signals, 1)) * 100).toFixed(0)}% of total` : undefined} accent />
              <StatCard title="AVG FINAL SCORE" value={data.signals.avg_final_score.toFixed(1)} sub={`max: ${data.signals.max_final_score.toFixed(1)}`} />
              <StatCard title="ACCURACY" value={accuracy ? `${accuracy}%` : "—"} sub={data.signals.tracked_outcomes > 0 ? `${data.signals.tracked_outcomes} tracked` : "no tracking yet"} />
            </div>

            {/* Score Distribution */}
            <div className="mt-3 glass-card p-4">
              <div className="text-xs font-bold text-surface-400 mb-3">Final Score Distribution</div>
              <ScoreDistChart data={data.score_distribution} />
            </div>
          </div>

          {/* ═══════════════ SECTION 3: Recent Signals ═══════════════ */}
          <div className="mb-6">
            <div className="flex items-center gap-2 mb-3">
              <span className="material-icons text-accent-amber text-lg">history</span>
              <span className="text-sm font-bold text-surface-300">Recent Signals</span>
              <span className="text-[10px] text-surface-600 mr-auto">
                {data.recent_signals.length > 0 ? "Last 20 signals" : "No signals yet — run the model first"}
              </span>
            </div>

            {data.recent_signals.length === 0 ? (
              <div className="glass-card p-8 text-center">
                <span className="material-icons text-5xl text-surface-600 mb-2 block">signal_cellular_alt</span>
                <p className="text-sm text-surface-500">No signals have been generated yet</p>
                <p className="text-xs text-surface-600 mt-1">Execute a model cycle via POST /screener110/run-cycle</p>
              </div>
            ) : (
              <div className="glass-card overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-xs">
                    <thead>
                      <tr className="border-b border-surface-700/50">
                        <th className="text-right p-3 text-surface-500 font-bold">Symbol</th>
                        <th className="text-right p-3 text-surface-500 font-bold">Score</th>
                        <th className="text-right p-3 text-surface-500 font-bold">Decision</th>
                        <th className="text-right p-3 text-surface-500 font-bold">Price</th>
                        <th className="text-right p-3 text-surface-500 font-bold">Stop Loss</th>
                        <th className="text-right p-3 text-surface-500 font-bold">Scores (F/V/I/T/M)</th>
                        <th className="text-right p-3 text-surface-500 font-bold">Generated</th>
                      </tr>
                    </thead>
                    <tbody>
                      {data.recent_signals.map((s, i) => {
                        const badge = decisionBadge(s.decision);
                        return (
                          <tr key={`${s.symbol}-${i}`} className="border-b border-surface-800/50 hover:bg-surface-800/30 transition-colors">
                            <td className="p-3">
                              <Link href={`/symbol/${encodeURIComponent(s.symbol)}`} className="font-bold text-surface-200 hover:text-primary-300 transition-colors">
                                {s.symbol}
                              </Link>
                            </td>
                            <td className="p-3">
                              <span className={`font-black font-mono ${scoreColor(s.final_score || 0)}`}>
                                {s.final_score?.toFixed(1) ?? "—"}
                              </span>
                            </td>
                            <td className="p-3">
                              <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold ${badge.cls}`}>
                                {badge.label}
                              </span>
                            </td>
                            <td className="p-3 font-mono text-surface-300">
                              {s.current_price?.toLocaleString("fa-IR") ?? "—"}
                            </td>
                            <td className="p-3 font-mono text-accent-rose">
                              {s.stop_loss_price?.toLocaleString("fa-IR") ?? "—"}
                            </td>
                            <td className="p-3">
                              <div className="flex gap-1 text-[9px]">
                                <span className={s.score_fundamental ? "text-accent-amber" : "text-surface-600"}>
                                  {s.score_fundamental?.toFixed(0) ?? "—"}
                                </span>
                                <span className="text-surface-600">/</span>
                                <span className={s.score_valuation ? "text-primary-300" : "text-surface-600"}>
                                  {s.score_valuation?.toFixed(0) ?? "—"}
                                </span>
                                <span className="text-surface-600">/</span>
                                <span className={s.score_institutional ? "text-accent-emerald" : "text-surface-600"}>
                                  {s.score_institutional?.toFixed(0) ?? "—"}
                                </span>
                                <span className="text-surface-600">/</span>
                                <span className={s.score_technical ? "text-accent-cyan" : "text-surface-600"}>
                                  {s.score_technical?.toFixed(0) ?? "—"}
                                </span>
                                <span className="text-surface-600">/</span>
                                <span className={s.score_macro ? "text-accent-rose" : "text-surface-600"}>
                                  {s.score_macro?.toFixed(0) ?? "—"}
                                </span>
                              </div>
                            </td>
                            <td className="p-3 text-surface-500 text-[9px] whitespace-nowrap">
                              {fmtDate(s.generated_at)}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>

          {/* ═══════════════ SECTION 4: System Status ═══════════════ */}
          <div className="mb-6">
            <div className="flex items-center gap-2 mb-3">
              <span className="material-icons text-surface-500 text-lg">monitor_heart</span>
              <span className="text-sm font-bold text-surface-300">System Status</span>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              <div className="glass-card p-4 border border-surface-700/50">
                <div className="flex items-center gap-2 mb-2">
                  <span className={`w-2 h-2 rounded-full ${data.system.last_populate ? "bg-accent-emerald" : "bg-surface-600"}`} />
                  <span className="text-[10px] text-surface-500 font-bold">Last Populate</span>
                </div>
                <div className="text-sm text-surface-200 font-mono">
                  {fmtDate(data.system.last_populate)}
                </div>
                {!data.system.last_populate && (
                  <div className="text-[10px] text-surface-600 mt-1">Never run</div>
                )}
              </div>
              <div className="glass-card p-4 border border-surface-700/50">
                <div className="flex items-center gap-2 mb-2">
                  <span className={`w-2 h-2 rounded-full ${data.system.last_cycle ? "bg-accent-emerald" : "bg-surface-600"}`} />
                  <span className="text-[10px] text-surface-500 font-bold">Last Model Cycle</span>
                </div>
                <div className="text-sm text-surface-200 font-mono">
                  {fmtDate(data.system.last_cycle)}
                </div>
                {data.system.last_buy_signals > 0 && (
                  <div className="text-[10px] text-accent-emerald mt-1">
                    {data.system.last_buy_signals} buy signals
                  </div>
                )}
                {!data.system.last_cycle && (
                  <div className="text-[10px] text-surface-600 mt-1">Never run</div>
                )}
              </div>
              <div className="glass-card p-4 border border-surface-700/50">
                <div className="flex items-center gap-2 mb-2">
                  <span className={`w-2 h-2 rounded-full ${data.system.last_error ? "bg-accent-rose" : "bg-accent-emerald"}`} />
                  <span className="text-[10px] text-surface-500 font-bold">Last Error</span>
                </div>
                {data.system.last_error ? (
                  <div className="text-xs text-accent-rose font-mono break-all">{data.system.last_error}</div>
                ) : (
                  <div className="text-sm text-surface-400">No errors</div>
                )}
              </div>
            </div>
          </div>

          {/* ═══════════════ SECTION 5: Top Industries ═══════════════ */}
          {data.top_industries.length > 0 && (
            <div className="mb-6">
              <div className="flex items-center gap-2 mb-3">
                <span className="material-icons text-surface-500 text-lg">domain</span>
                <span className="text-sm font-bold text-surface-300">Top Industries by Coverage</span>
              </div>
              <div className="glass-card p-4">
                <div className="space-y-2">
                  {data.top_industries.map(ind => (
                    <IndustryBadge key={ind.industry} name={ind.industry} count={ind.cnt} max={data.top_industries[0]?.cnt || 1} />
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* ═══════════════ SECTION 6: Quick Actions ═══════════════ */}
          <div className="mb-6">
            <div className="flex items-center gap-2 mb-3">
              <span className="material-icons text-surface-500 text-lg">bolt</span>
              <span className="text-sm font-bold text-surface-300">Quick Actions</span>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <Link href="/signals" className="glass-card p-4 border border-surface-700/50 hover:border-primary-500/30 transition-all group flex items-center gap-3">
                <span className="material-icons text-3xl text-primary-400 group-hover:text-primary-300">list_alt</span>
                <div>
                  <div className="text-sm font-bold text-surface-200 group-hover:text-surface-100">All Signals</div>
                  <div className="text-[10px] text-surface-500">View multi-market signals dashboard</div>
                </div>
                <span className="material-icons text-surface-600 mr-auto">arrow_back</span>
              </Link>
              <Link href="/screener" className="glass-card p-4 border border-surface-700/50 hover:border-accent-emerald/30 transition-all group flex items-center gap-3">
                <span className="material-icons text-3xl text-accent-emerald group-hover:text-accent-emerald/80">search</span>
                <div>
                  <div className="text-sm font-bold text-surface-200 group-hover:text-surface-100">Screener</div>
                  <div className="text-[10px] text-surface-500">Smart Money 5-phase stock screener</div>
                </div>
                <span className="material-icons text-surface-600 mr-auto">arrow_back</span>
              </Link>
            </div>
          </div>

          {/* ── Footer ── */}
          <div className="text-[10px] text-surface-600 text-center py-4 border-t border-surface-800/50">
            Screener110 Monitoring v1.0 — Data refreshes automatically every 60 seconds
          </div>
        </>
      )}
    </AppLayout>
  );
}

"use client";

import Link from "next/link";
import { useState, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import Skeleton from "@/components/Skeleton";
import MiniSparkline from "@/components/MiniSparkline";
import { apiGet } from "@/lib/api";

// ── Types ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

interface ScreenedItem {
  symbol: string;
  name: string;
  market: string;
  industry: string;
  last_price: number;
  change_pct: number;
  volume: number;
  value: number;
  liquidity_score: number;
  power_score: number;
  structure_score: number;
  orderflow_score: number;
  trigger_score: number;
  smc_score: number;
  phase: string;
  rank: number;
  reason: string;
}

interface ScreenerResponse {
  items: ScreenedItem[];
  total: number;
}

// ── Helpers ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

function formatPrice(v: number): string {
  if (v >= 1_000_000_000_000) return (v / 1_000_000_000_000).toFixed(2) + "T";
  if (v >= 1_000_000_000) return (v / 1_000_000_000).toFixed(2) + "B";
  if (v >= 1_000_000) return (v / 1_000_000).toFixed(1) + "M";
  if (v >= 1_000) return (v / 1_000).toFixed(0) + "K";
  return v.toLocaleString("fa-IR");
}

function pctScore(score: number): number {
  return Math.round(score * 100);
}

function scoreBg(score: number): string {
  if (score >= 0.75) return "bg-accent-emerald";
  if (score >= 0.5) return "bg-accent-amber";
  if (score >= 0.25) return "bg-accent-rose/70";
  return "bg-surface-600";
}

function scoreBadgeBg(score: number): string {
  if (score >= 0.7) return "bg-accent-emerald/15 text-accent-emerald";
  if (score >= 0.5) return "bg-accent-amber/15 text-accent-amber";
  if (score >= 0.3) return "bg-accent-rose/15 text-accent-rose";
  return "bg-surface-600/30 text-surface-400";
}

function PhaseBadge({ phase, reason }: { phase: string; reason: string }) {
  const phaseColors: Record<string, string> = {
    confirmed_smart_money: "bg-accent-emerald/15 text-accent-emerald",
    breakout_ready: "bg-accent-cyan/15 text-accent-cyan",
    float_lock: "bg-accent-purple/15 text-accent-purple",
    active_absorption: "bg-accent-amber/15 text-accent-amber",
    early_accumulation: "bg-primary-600/20 text-primary-300",
    neutral: "bg-surface-600/30 text-surface-400",
  };
  const phaseLabels: Record<string, string> = {
    confirmed_smart_money: "پول هوشمند",
    breakout_ready: "آماده شکست",
    float_lock: "قفل شناور",
    active_absorption: "جذب فعال",
    early_accumulation: "تجمع اولیه",
    neutral: "خنثی",
  };
  return (
    <div className="flex items-center gap-2 flex-wrap">
      <span
        className={`text-[10px] px-1.5 py-0.5 rounded-full font-bold ${
          phaseColors[phase] || phaseColors.neutral
        }`}
      >
        {phaseLabels[phase] || phase}
      </span>
      {reason && <span className="text-[10px] text-surface-500">{reason}</span>}
    </div>
  );
}

function ScoreBar({ value, label, maxWidth = 60 }: { value: number; label: string; maxWidth?: number }) {
  const pct = Math.min(value * 100, 100);
  return (
    <div className="flex items-center gap-1.5 group relative" style={{ maxWidth }}>
      <span className="text-[9px] text-surface-500 w-4 text-left shrink-0">{label}</span>
      <div className="flex-1 h-1.5 bg-surface-800 rounded-full overflow-hidden">
        <div
          className={`h-full rounded-full transition-all duration-500 ${scoreBg(value)}`}
          style={{ width: `${pct}%` }}
        />
      </div>
    </div>
  );
}

// ── Scoring Visualization ────────────────────────────────────────────────────────────────────────────────────────────────────────────

function ScoreGrid({ item }: { item: ScreenedItem }) {
  return (
    <div className="flex flex-col gap-1 min-w-[200px]">
      <ScoreBar value={item.liquidity_score} label="Liq" />
      <ScoreBar value={item.power_score} label="Pow" />
      <ScoreBar value={item.structure_score} label="Str" />
      <ScoreBar value={item.orderflow_score} label="Flw" />
      <ScoreBar value={item.trigger_score} label="Trg" />
    </div>
  );
}

// ── Main Page ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────

const SORT_OPTIONS = [
  { key: "smc_score", label: "SMC Score" },
  { key: "change_pct", label: "تغییرات" },
  { key: "liquidity_score", label: "نقدشوندگی" },
  { key: "power_score", label: "قدرت خرید" },
  { key: "structure_score", label: "ساختار قیمت" },
  { key: "trigger_score", label: "تریگر" },
  { key: "volume", label: "حجم" },
  { key: "value", label: "ارزش" },
];

const MARKET_OPTIONS = [
  { key: "", label: "همه بازارها" },
  { key: "BOURS", label: "بورس" },
  { key: "FARA", label: "فرابورس" },
  { key: "ENERGY", label: "انرژی" },
  { key: "COMMODITY", label: "کالا" },
];

const PHASE_OPTIONS = [
  { key: "", label: "همه فازها", color: "" },
  { key: "confirmed_smart_money", label: "پول هوشمند", color: "#22c55e" },
  { key: "breakout_ready", label: "آماده شکست", color: "#06b6d4" },
  { key: "float_lock", label: "قفل شناور", color: "#8b5cf6" },
  { key: "active_absorption", label: "جذب فعال", color: "#f59e0b" },
  { key: "early_accumulation", label: "تجمع اولیه", color: "#3b82f6" },
  { key: "neutral", label: "خنثی", color: "#64748b" },
];

export default function ScreenerPage() {
  const [search, setSearch] = useState("");
  const [sortBy, setSortBy] = useState("smc_score");
  const [sortOrder, setSortOrder] = useState<"desc" | "asc">("desc");
  const [minScore, setMinScore] = useState(0);
  const [marketFilter, setMarketFilter] = useState("");
  const [phaseFilter, setPhaseFilter] = useState("");

  // ── Fetch screener data (get ALL available symbols, max 1000) ──
  const { data: rawData, isLoading } = useQuery({
    queryKey: ["screener", sortBy, sortOrder, minScore, marketFilter],
    queryFn: async () => {
      const params = new URLSearchParams();
      params.set("sort_by", sortBy);
      params.set("sort_order", sortOrder);
      params.set("limit", "1000");
      if (minScore > 0) params.set("min_score", String(minScore));
      if (marketFilter) params.set("market", marketFilter);

      const res = await apiGet<{ success: boolean; data: ScreenerResponse }>(
        `/screener?${params.toString()}`
      );
      return res?.data ?? { items: [], total: 0 };
    },
    refetchInterval: 120_000,
  });

  const items = rawData?.items ?? [];

  // ── Sparklines ──
  const sparkQuery = useMemo(() => {
    const syms = items.slice(0, 200).map((i) => i.symbol);
    return syms.join(",");
  }, [items]);

  const { data: sparkMap } = useQuery({
    queryKey: ["screener-spark", sparkQuery],
    queryFn: async () => {
      if (!sparkQuery) return {};
      try {
        const res = await apiGet<{ success: boolean; data: Record<string, number[]> }>(
          `/market/sparklines?symbols=${encodeURIComponent(sparkQuery)}&limit=30`
        );
        return res?.data ?? {};
      } catch {
        return {};
      }
    },
    enabled: !!sparkQuery,
    staleTime: 120_000,
  });

  // ── Search filter (client-side) ──
  const filtered = useMemo(() => {
    let result = items;

    // Phase filter
    if (phaseFilter) {
      result = result.filter((i) => i.phase === phaseFilter);
    }

    // Search filter
    if (search.trim()) {
      const q = search.trim().toLowerCase();
      result = result.filter(
        (i) =>
          i.symbol.toLowerCase().includes(q) ||
          i.name.toLowerCase().includes(q) ||
          i.industry.toLowerCase().includes(q)
      );
    }

    return result;
  }, [items, search, phaseFilter]);

  // ── Stats ──
  const stats = useMemo(() => {
    const total = filtered.length;
    const highScore = filtered.filter((i) => i.smc_score >= 0.6).length;
    const avgScore =
      total > 0
        ? filtered.reduce((sum, i) => sum + i.smc_score, 0) / total
        : 0;
    const avgLiq =
      total > 0
        ? filtered.reduce((sum, i) => sum + i.liquidity_score, 0) / total
        : 0;
    const bullishPhases = filtered.filter((i) =>
      ["confirmed_smart_money", "breakout_ready", "float_lock", "active_absorption"].includes(i.phase)
    ).length;
    return { total, highScore, avgScore, avgLiq, bullishPhases };
  }, [filtered]);

  // ── Render ──
  return (
    <AppLayout
      title="🔍 Stock Screener"
      subtitle="غربال‌گری هوشمند با ۵ فاز Smart Money"
    >
      {/* ── Stats cards ── */}
      <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 mb-5">
        <div className="glass-card p-3 text-center">
          <p className="text-xl font-black text-surface-100">{stats.total}</p>
          <p className="text-xs text-surface-500">نماد</p>
        </div>
        <div className="glass-card p-3 text-center">
          <p className="text-xl font-black text-accent-emerald">{stats.highScore}</p>
          <p className="text-xs text-surface-500">SMC ≥ 60%</p>
        </div>
        <div className="glass-card p-3 text-center">
          <p className="text-xl font-black text-accent-cyan">{stats.bullishPhases}</p>
          <p className="text-xs text-surface-500">فاز صعودی</p>
        </div>
        <div className="glass-card p-3 text-center">
          <p className="text-xl font-black text-surface-100">
            {(stats.avgScore * 100).toFixed(0)}%
          </p>
          <p className="text-xs text-surface-500">میانگین SMC</p>
        </div>
        <div className="glass-card p-3 text-center">
          <p className="text-xl font-black text-primary-300">
            {(stats.avgLiq * 100).toFixed(0)}%
          </p>
          <p className="text-xs text-surface-500">میانگین نقدشوندگی</p>
        </div>
      </div>

      {/* ── Filters ── */}
      <div className="flex flex-wrap items-center gap-3 mb-4">
        <input
          type="text"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="جستجوی نماد، نام، صنعت..."
          className="px-3 py-2 bg-surface-800 border border-surface-700 rounded-lg text-surface-200 text-sm focus:outline-none focus:border-primary-500 w-56"
        />

        <select
          value={sortBy}
          onChange={(e) => setSortBy(e.target.value)}
          className="px-3 py-2 bg-surface-800 border border-surface-700 rounded-lg text-surface-200 text-sm focus:outline-none focus:border-primary-500"
        >
          {SORT_OPTIONS.map((o) => (
            <option key={o.key} value={o.key}>
              {o.label}
            </option>
          ))}
        </select>

        <button
          onClick={() => setSortOrder(sortOrder === "desc" ? "asc" : "desc")}
          className="px-3 py-2 bg-surface-800 border border-surface-700 rounded-lg text-surface-200 text-sm hover:bg-surface-700 transition-colors"
        >
          {sortOrder === "desc" ? "⬇ نزولی" : "⬆ صعودی"}
        </button>

        <div className="flex items-center gap-2">
          <span className="text-xs text-surface-500">min SMC:</span>
          <input
            type="range"
            min={0}
            max={100}
            step={5}
            value={minScore * 100}
            onChange={(e) => setMinScore(Number(e.target.value) / 100)}
            className="w-20 accent-primary-500"
          />
          <span className="text-xs font-mono text-surface-300 w-8 text-left">
            {(minScore * 100).toFixed(0)}%
          </span>
        </div>

        <div className="flex gap-1 flex-wrap">
          {MARKET_OPTIONS.map((m) => (
            <button
              key={m.key}
              onClick={() => setMarketFilter(m.key)}
              className={`px-2.5 py-1 rounded-lg text-[10px] font-medium transition-all ${
                marketFilter === m.key
                  ? "bg-primary-600 text-white"
                  : "bg-surface-800 text-surface-400 hover:text-surface-200"
              }`}
            >
              {m.label}
            </button>
          ))}
        </div>

        <div className="flex gap-1 flex-wrap">
          {PHASE_OPTIONS.map((p) => (
            <button
              key={p.key}
              onClick={() => setPhaseFilter(p.key)}
              className={`px-2.5 py-1 rounded-lg text-[10px] font-medium transition-all ${
                phaseFilter === p.key
                  ? "text-white"
                  : "bg-surface-800 text-surface-400 hover:text-surface-200"
              }`}
              style={
                phaseFilter === p.key
                  ? { background: p.color || "var(--color-primary-600)" }
                  : undefined
              }
            >
              {p.label}
            </button>
          ))}
        </div>
      </div>

      {/* ── Loading ── */}
      {isLoading && (
        <div className="space-y-3">
          {[1, 2, 3, 4, 5].map((i) => (
            <Skeleton key={i} className="h-20 w-full rounded-xl" />
          ))}
        </div>
      )}

      {/* ── Empty ── */}
      {!isLoading && filtered.length === 0 && (
        <div className="glass-card p-12 text-center text-surface-500">
          <p className="text-5xl mb-3">🔍</p>
          <p className="font-bold">نمادی یافت نشد</p>
          <p className="text-sm mt-1">
            {search
              ? "نمادی با این نام وجود ندارد"
              : "داده‌ای برای غربال‌گری موجود نیست"}
          </p>
        </div>
      )}

      {/* ── Results ── */}
      {!isLoading && filtered.length > 0 && (
        <div className="space-y-2">
          {filtered.map((item) => {
            const sparkData = sparkMap?.[item.symbol];
            const smcNum = pctScore(item.smc_score);
            return (
              <Link
                key={`${item.rank}-${item.symbol}`}
                href={`/symbol/${encodeURIComponent(item.symbol)}`}
                className="glass-card p-4 flex items-center gap-4 hover:bg-white/[0.03] transition-colors group cursor-pointer"
              >
                {/* Sparkline */}
                <div className="shrink-0 w-[72px]">
                  {sparkData && sparkData.length > 1 ? (
                    <MiniSparkline data={sparkData} width={72} height={24} />
                  ) : (
                    <div className="h-6 flex items-center justify-center text-[9px] text-surface-600">
                      —
                    </div>
                  )}
                </div>

                {/* Symbol + name */}
                <div className="min-w-[120px] shrink-0">
                  <p className="font-bold text-surface-100 group-hover:text-primary-300 transition-colors">
                    {item.symbol}
                  </p>
                  <p className="text-[10px] text-surface-500 truncate max-w-[140px]">
                    {item.name}
                  </p>
                  {item.industry && (
                    <p className="text-[9px] text-surface-600 mt-0.5">
                      {item.industry}
                    </p>
                  )}
                </div>

                {/* Price + change */}
                <div className="min-w-[90px] shrink-0 text-right">
                  <p className="font-mono text-sm text-surface-200">
                    {item.last_price?.toLocaleString("fa-IR")}
                  </p>
                  <p
                    className={`font-mono text-xs ${
                      item.change_pct >= 0
                        ? "text-accent-emerald"
                        : "text-accent-rose"
                    }`}
                  >
                    {item.change_pct >= 0 ? "+" : ""}
                    {item.change_pct?.toFixed(2)}%
                  </p>
                </div>

                {/* Phase scores */}
                <div className="hidden md:flex flex-col gap-0.5 min-w-[180px]">
                  <ScoreGrid item={item} />
                </div>

                {/* SMC score */}
                <div className="min-w-[60px] shrink-0 text-center">
                  <div
                    className={`text-sm font-black px-2 py-1 rounded-lg ${
                      scoreBadgeBg(item.smc_score)
                    }`}
                  >
                    {smcNum}
                  </div>
                  <p className="text-[8px] text-surface-600 mt-0.5">SMC</p>
                </div>

                {/* Phase */}
                <div className="hidden lg:block min-w-[120px] shrink-0">
                  <PhaseBadge phase={item.phase} reason={item.reason} />
                </div>

                {/* Volume */}
                <div className="hidden sm:block min-w-[70px] shrink-0 text-right">
                  <p className="font-mono text-xs text-surface-400">
                    {formatPrice(item.volume)}
                  </p>
                  <p className="text-[8px] text-surface-600">حجم</p>
                </div>

                {/* Arrow */}
                <div className="mr-auto shrink-0 opacity-0 group-hover:opacity-100 transition-opacity">
                  <span className="material-icons text-surface-500 text-lg">
                    chevron_left
                  </span>
                </div>
              </Link>
            );
          })}
        </div>
      )}
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import { Card, CardAction } from "@/components/ui/Card";
import { apiGet } from "@/lib/api";
import SSRSafe from "@/components/SSRSafe";
import SignalCard from "@/components/signals/SignalCard";
import SignalDetailModal from "@/components/signals/SignalDetailModal";
import type { EnrichedSignal } from "@/lib/types";

interface MultiMarketResponse {
  success: boolean;
  data?: {
    signals: EnrichedSignal[];
    summary: {
      total_signals: number;
      buy_count: number;
      sell_count: number;
      hold_count: number;
      avg_confidence: number;
      markets: Record<string, { buy: number; sell: number; hold: number }>;
    };
    generated_at: string;
  };
}

const MARKET_LABELS: Record<string, string> = {
  stock: "سهام", gold: "طلا", currency: "ارز",
  crypto: "رمزارز", option: "آپشن", commodity: "کالا", ime: "بورس کالا",
};

const MARKET_COLORS: Record<string, string> = {
  stock: "#64FFDA", gold: "#FFD700", currency: "#FF6B6B",
  crypto: "#A78BFA", option: "#38BDF8", commodity: "#FB923C", ime: "#94A3B8",
};

function fmtPrice(n: number): string {
  if (n >= 1_000_000_000) return `${(n / 1_000_000_000).toFixed(1)}B`;
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return n.toLocaleString("fa-IR");
  return n.toFixed(2);
}

function fmtPct(n: number): string {
  return `${n >= 0 ? "+" : ""}${n.toFixed(1)}%`;
}

export default function SignalsAllPage() {
  const [marketFilter, setMarketFilter] = useState("all");
  const [signalFilter, setSignalFilter] = useState("all");
  const [timeframeFilter, setTimeframeFilter] = useState("all");
  const [minConfidence, setMinConfidence] = useState(0.25);
  const [sortBy, setSortBy] = useState<"boosted_score" | "confidence" | "rule_score">("boosted_score");
  const [selectedSignal, setSelectedSignal] = useState<EnrichedSignal | null>(null);

  const { data, isLoading, error } = useQuery({
    queryKey: ["signals-all", marketFilter, signalFilter, timeframeFilter, minConfidence, sortBy],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (marketFilter !== "all") params.set("market", marketFilter);
      if (signalFilter !== "all") params.set("signal", signalFilter);
      if (timeframeFilter !== "all") params.set("timeframe", timeframeFilter);
      params.set("min_confidence", String(minConfidence));
      params.set("sort_by", sortBy);
      params.set("limit", "200");

      const res = await apiGet<MultiMarketResponse>(`/multi-market-signals?${params.toString()}`);
      return res?.data ?? null;
    },
    refetchInterval: 60_000,
    staleTime: 30_000,
  });

  const signals = data?.signals ?? [];
  const summary = data?.summary;

  return (
    <AppLayout title="همه سیگنال‌ها" subtitle="سیگنال‌های خرید و فروش در تمام بازارها">
      {/* Filters */}
      <div className="flex flex-wrap items-center gap-3 mb-4">
        <select
          value={marketFilter}
          onChange={(e) => setMarketFilter(e.target.value)}
          className="bg-surface-800 border border-surface-700 text-surface-200 text-xs rounded-lg px-3 py-2 focus:border-primary-500 outline-none"
        >
          <option value="all">همه بازارها</option>
          {Object.entries(MARKET_LABELS).map(([k, v]) => (
            <option key={k} value={k}>{v}</option>
          ))}
        </select>

        <select
          value={signalFilter}
          onChange={(e) => setSignalFilter(e.target.value)}
          className="bg-surface-800 border border-surface-700 text-surface-200 text-xs rounded-lg px-3 py-2 focus:border-primary-500 outline-none"
        >
          <option value="all">همه سیگنال‌ها</option>
          <option value="buy">خرید</option>
          <option value="sell">فروش</option>
          <option value="hold">خنثی</option>
        </select>

        <select
          value={timeframeFilter}
          onChange={(e) => setTimeframeFilter(e.target.value)}
          className="bg-surface-800 border border-surface-700 text-surface-200 text-xs rounded-lg px-3 py-2 focus:border-primary-500 outline-none"
        >
          <option value="all">همه بازه‌ها</option>
          <option value="daily">روزانه</option>
          <option value="2day">۲ روزه</option>
          <option value="3day">۳ روزه</option>
          <option value="weekly">هفتگی</option>
          <option value="monthly">ماهانه</option>
        </select>

        <div className="flex items-center gap-2 bg-surface-800 border border-surface-700 rounded-lg px-3 py-1.5">
          <span className="text-[10px] text-surface-500">حداقل اطمینان:</span>
          <input
            type="range"
            min="0"
            max="0.8"
            step="0.05"
            value={minConfidence}
            onChange={(e) => setMinConfidence(parseFloat(e.target.value))}
            className="w-20 accent-primary-500"
          />
          <span className="text-xs font-mono text-surface-300">{(minConfidence * 100).toFixed(0)}%</span>
        </div>

        <select
          value={sortBy}
          onChange={(e) => setSortBy(e.target.value as typeof sortBy)}
          className="bg-surface-800 border border-surface-700 text-surface-200 text-xs rounded-lg px-3 py-2 focus:border-primary-500 outline-none"
        >
          <option value="boosted_score">امتیاز ترکیبی</option>
          <option value="confidence">اطمینان</option>
          <option value="rule_score">امتیاز تکنیکال</option>
        </select>

        {isLoading && (
          <span className="text-xs text-surface-500 animate-pulse">در حال بارگذاری...</span>
        )}
        {data?.generated_at && (
          <span className="text-[10px] text-surface-600 mr-auto">
            {new Date(data.generated_at).toLocaleTimeString("fa-IR")}
          </span>
        )}
      </div>

      {/* Summary Stats */}
      {!isLoading && summary && (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-2 mb-4">
          <div className="glass-card p-3 text-center">
            <div className="text-[10px] text-surface-500 mb-1">کل</div>
            <div className="text-lg font-black text-surface-100">{summary.total_signals}</div>
          </div>
          <div className="glass-card p-3 text-center">
            <div className="text-[10px] text-surface-500 mb-1">خرید</div>
            <div className="text-lg font-black text-accent-emerald">{summary.buy_count}</div>
          </div>
          <div className="glass-card p-3 text-center">
            <div className="text-[10px] text-surface-500 mb-1">فروش</div>
            <div className="text-lg font-black text-accent-rose">{summary.sell_count}</div>
          </div>
          <div className="glass-card p-3 text-center">
            <div className="text-[10px] text-surface-500 mb-1">خنثی</div>
            <div className="text-lg font-black text-surface-400">{summary.hold_count}</div>
          </div>
          <div className="glass-card p-3 text-center">
            <div className="text-[10px] text-surface-500 mb-1">بازارها</div>
            <div className="text-lg font-black text-surface-200">{Object.keys(summary.markets ?? {}).length}</div>
          </div>
        </div>
      )}

      {/* Error */}
      {error && !isLoading && (
        <div className="glass-card p-6 text-center border border-accent-rose/30">
          <span className="material-icons text-3xl text-accent-rose mb-2 block">error_outline</span>
          <p className="text-sm text-accent-rose">خطا در دریافت سیگنال‌ها</p>
        </div>
      )}

      {/* Signal List */}
      <Card
        title={`سیگنال‌ها (${signals.length})`}
        actions={
          <div className="flex gap-1">
            {(["all", "buy", "sell", "hold"] as const).map((f) => (
              <CardAction key={f} active={signalFilter === f} onClick={() => setSignalFilter(f)}>
                {f === "all" ? "همه" : f === "buy" ? "خرید" : f === "sell" ? "فروش" : "خنثی"}
              </CardAction>
            ))}
          </div>
        }
      >
        <SSRSafe style={{ overflowX: "auto" }}>
          {isLoading && (
            <div className="space-y-2 animate-pulse">
              {[1, 2, 3, 4, 5].map((i) => (
                <div key={i} className="h-16 bg-surface-800/30 rounded-lg" />
              ))}
            </div>
          )}

          {!isLoading && signals.length === 0 && (
            <div className="text-center py-12 text-surface-500">
              <span className="material-icons text-4xl mb-2 block">signal_cellular_alt</span>
              <p className="text-sm">هیچ سیگنالی با فیلترهای فعلی یافت نشد</p>
            </div>
          )}

          {!isLoading && signals.length > 0 && (
            <div className="space-y-2">
              {signals.map((s, i) => (
                <SignalCard
                  key={`${s.symbol}-${s.market}-${s.timeframe}-${i}`}
                  signal={s}
                  variant="full"
                  onClick={() => setSelectedSignal(s)}
                />
              ))}
            </div>
          )}
        </SSRSafe>
      </Card>

      {/* Detail Modal */}
      {selectedSignal && (
        <SignalDetailModal
          signal={selectedSignal}
          onClose={() => setSelectedSignal(null)}
        />
      )}
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import Link from "next/link";
import AppLayout from "@/components/layout/AppLayout";
import { apiGet } from "@/lib/api";
import SSRSafe from "@/components/SSRSafe";
import SignalCard from "@/components/signals/SignalCard";
import SignalDetailModal from "@/components/signals/SignalDetailModal";
import type { EnrichedSignal } from "@/lib/types";

interface MultiMarketResponse {
  success: boolean;
  data?: {
    signals: EnrichedSignal[];
    summary: {
      total_signals: number;
      buy_count: number;
      sell_count: number;
      hold_count: number;
      avg_confidence: number;
    };
    accuracy: Record<string, number>;
    generated_at: string;
  };
}

export default function SignalsPage() {
  const [selectedSignal, setSelectedSignal] = useState<EnrichedSignal | null>(null);

  const { data, isLoading, error } = useQuery({
    queryKey: ["signals-top"],
    queryFn: async () => {
      const res = await apiGet<MultiMarketResponse>(
        "/multi-market-signals?limit=4&sort_by=boosted_score&min_confidence=0.25"
      );
      return res?.data ?? null;
    },
    refetchInterval: 60_000,
    staleTime: 30_000,
  });

  const signals = data?.signals ?? [];
  const summary = data?.summary;
  const topSignal = signals[0] ?? null;
  const otherSignals = signals.slice(1);

  return (
    <AppLayout title="سیگنال‌ها" subtitle="بهترین سیگنال‌های خرید و فروش در تمام بازارها">
      {/* Loading */}
      {isLoading && (
        <div className="space-y-4 animate-pulse">
          <div className="glass-card h-64" />
          <div className="grid grid-cols-3 gap-3">
            {[1, 2, 3].map((i) => (
              <div key={i} className="glass-card h-20" />
            ))}
          </div>
        </div>
      )}

      {/* Error */}
      {error && !isLoading && (
        <div className="glass-card p-8 text-center border border-accent-rose/30">
          <span className="material-icons text-4xl text-accent-rose mb-3 block">error_outline</span>
          <p className="text-sm text-accent-rose mb-2">خطا در دریافت سیگنال‌ها</p>
          <p className="text-xs text-surface-500">لطفاً اتصال به سرور را بررسی کنید.</p>
        </div>
      )}

      {/* No signals */}
      {!isLoading && !error && signals.length === 0 && (
        <div className="glass-card p-12 text-center">
          <span className="material-icons text-5xl text-surface-600 mb-3 block">signal_cellular_alt</span>
          <p className="text-sm text-surface-400">هیچ سیگنالی یافت نشد</p>
          <p className="text-xs text-surface-600 mt-1">سیستم در حال تحلیل بازارها است...</p>
        </div>
      )}

      {!isLoading && !error && signals.length > 0 && (
        <>
          {/* Hero: Top Signal */}
          {topSignal && (
            <div className="mb-6">
              <div className="flex items-center gap-2 mb-3">
                <span className="material-icons text-accent-cyan text-lg">star</span>
                <span className="text-sm font-bold text-surface-300">بهترین سیگنال</span>
              </div>
              <SignalCard
                signal={topSignal}
                variant="hero"
                onClick={() => setSelectedSignal(topSignal)}
              />
            </div>
          )}

          {/* Quick Stats */}
          {summary && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
              <div className="glass-card p-4 text-center">
                <div className="text-[10px] text-surface-500 mb-1">کل سیگنال‌ها</div>
                <div className="text-2xl font-black text-surface-100">{summary.total_signals}</div>
              </div>
              <div className="glass-card p-4 text-center">
                <div className="text-[10px] text-surface-500 mb-1">خرید</div>
                <div className="text-2xl font-black text-accent-emerald">{summary.buy_count}</div>
              </div>
              <div className="glass-card p-4 text-center">
                <div className="text-[10px] text-surface-500 mb-1">فروش</div>
                <div className="text-2xl font-black text-accent-rose">{summary.sell_count}</div>
              </div>
              <div className="glass-card p-4 text-center">
                <div className="text-[10px] text-surface-500 mb-1">میانگین اطمینان</div>
                <div className="text-2xl font-black text-primary-300">{(summary.avg_confidence * 100).toFixed(0)}%</div>
              </div>
            </div>
          )}

          {/* Quick Links */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-6">
            <Link href="/signals/all" className="glass-card p-5 border border-surface-700/50 hover:border-primary-500/30 transition-all group">
              <div className="flex items-center gap-3">
                <span className="material-icons text-3xl text-primary-400 group-hover:text-primary-300">list</span>
                <div>
                  <div className="text-sm font-bold text-surface-200 group-hover:text-surface-100">همه سیگنال‌ها</div>
                  <div className="text-xs text-surface-500">سیگنال‌های تمام بازارها با ۱۱ ستون کامل</div>
                </div>
                <span className="material-icons text-surface-600 mr-auto">arrow_back</span>
              </div>
            </Link>
            <Link href="/signals/stocks" className="glass-card p-5 border border-surface-700/50 hover:border-accent-emerald/30 transition-all group">
              <div className="flex items-center gap-3">
                <span className="material-icons text-3xl text-accent-emerald group-hover:text-accent-emerald/80">show_chart</span>
                <div>
                  <div className="text-sm font-bold text-surface-200 group-hover:text-surface-100">سیگنال سهام</div>
                  <div className="text-xs text-surface-500">سیگنال‌های سهام با تمرکز بر day-trading</div>
                </div>
                <span className="material-icons text-surface-600 mr-auto">arrow_back</span>
              </div>
            </Link>
          </div>

          {/* Next Best Signals */}
          {otherSignals.length > 0 && (
            <div>
              <div className="text-xs font-bold text-surface-400 mb-3">سیگنال‌های بعدی</div>
              <div className="space-y-2">
                {otherSignals.map((s, i) => (
                  <SignalCard
                    key={`${s.symbol}-${s.market}-${i}`}
                    signal={s}
                    variant="compact"
                    onClick={() => setSelectedSignal(s)}
                  />
                ))}
              </div>
            </div>
          )}

          {data?.generated_at && (
            <div className="mt-4 text-[10px] text-surface-600 text-center">
              آخرین به‌روزرسانی: {new Date(data.generated_at).toLocaleString("fa-IR")}
            </div>
          )}
        </>
      )}

      {/* Detail Modal */}
      {selectedSignal && (
        <SignalDetailModal
          signal={selectedSignal}
          onClose={() => setSelectedSignal(null)}
        />
      )}
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import { apiGet } from "@/lib/api";
import SSRSafe from "@/components/SSRSafe";
import SignalCard from "@/components/signals/SignalCard";
import SignalDetailModal from "@/components/signals/SignalDetailModal";
import type { EnrichedSignal } from "@/lib/types";

interface MultiMarketResponse {
  success: boolean;
  data?: {
    signals: EnrichedSignal[];
    summary: {
      total_signals: number;
      buy_count: number;
      sell_count: number;
      hold_count: number;
      avg_confidence: number;
    };
    accuracy: Record<string, number>;
    generated_at: string;
  };
}

function fmtPrice(n: number): string {
  if (n >= 1_000_000_000) return `${(n / 1_000_000_000).toFixed(1)}B`;
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return n.toLocaleString("fa-IR");
  return n.toFixed(2);
}

function fmtPct(n: number): string {
  return `${n >= 0 ? "+" : ""}${n.toFixed(1)}%`;
}

export default function SignalsStocksPage() {
  const [timeframe, setTimeframe] = useState<"daily" | "2day" | "all">("daily");
  const [signalFilter, setSignalFilter] = useState<"all" | "buy" | "sell" | "hold">("buy");
  const [selectedSignal, setSelectedSignal] = useState<EnrichedSignal | null>(null);

  const { data, isLoading, error } = useQuery({
    queryKey: ["signals-stocks", timeframe, signalFilter],
    queryFn: async () => {
      const params = new URLSearchParams();
      params.set("market", "stock");
      params.set("min_confidence", "0.2");
      params.set("sort_by", "boosted_score");
      params.set("limit", "100");
      if (timeframe !== "all") params.set("timeframe", timeframe);
      if (signalFilter !== "all") params.set("signal", signalFilter);

      const res = await apiGet<MultiMarketResponse>(`/multi-market-signals?${params.toString()}`);
      return res?.data ?? null;
    },
    refetchInterval: 60_000,
    staleTime: 30_000,
  });

  const signals = data?.signals ?? [];
  const summary = data?.summary;
  const accuracy = data?.accuracy ?? {};

  // Group signals by symbol for stock-specific display
  const signalsBySymbol = signals.reduce<Record<string, EnrichedSignal[]>>((acc, s) => {
    if (!acc[s.symbol]) acc[s.symbol] = [];
    acc[s.symbol].push(s);
    return acc;
  }, {});

  return (
    <AppLayout title="سیگنال سهام" subtitle="سیگنال‌های سهام با تمرکز بر معاملات کوتاه‌مدت (day-trading)">
      {/* Filters */}
      <div className="flex flex-wrap items-center gap-3 mb-4">
        <div className="flex bg-surface-800 border border-surface-700 rounded-lg overflow-hidden">
          {(["daily", "2day", "all"] as const).map((tf) => (
            <button
              key={tf}
              onClick={() => setTimeframe(tf)}
              className={`px-4 py-2 text-xs font-medium transition-colors ${
                timeframe === tf
                  ? "bg-primary-600/30 text-primary-300"
                  : "text-surface-400 hover:text-surface-200 hover:bg-surface-700/50"
              }`}
            >
              {tf === "daily" ? "روزانه" : tf === "2day" ? "۲ روزه" : "همه"}
            </button>
          ))}
        </div>

        <div className="flex bg-surface-800 border border-surface-700 rounded-lg overflow-hidden">
          {(["all", "buy", "sell", "hold"] as const).map((f) => (
            <button
              key={f}
              onClick={() => setSignalFilter(f)}
              className={`px-3 py-2 text-xs font-medium transition-colors ${
                signalFilter === f
                  ? "bg-primary-600/30 text-primary-300"
                  : "text-surface-400 hover:text-surface-200 hover:bg-surface-700/50"
              }`}
            >
              {f === "all" ? "همه" : f === "buy" ? "خرید" : f === "sell" ? "فروش" : "خنثی"}
            </button>
          ))}
        </div>

        {isLoading && (
          <span className="text-xs text-surface-500 animate-pulse">در حال بارگذاری...</span>
        )}
        {data?.generated_at && (
          <span className="text-[10px] text-surface-600 mr-auto">
            {new Date(data.generated_at).toLocaleTimeString("fa-IR")}
          </span>
        )}
      </div>

      {/* Stock Accuracy */}
      {!isLoading && accuracy.stock != null && (
        <div className="glass-card p-3 mb-4 flex items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="material-icons text-accent-emerald">verified</span>
            <span className="text-xs text-surface-400">دقت سیگنال سهام:</span>
            <span className="text-sm font-black text-accent-emerald">{accuracy.stock.toFixed(0)}%</span>
          </div>
          {summary && (
            <>
              <span className="text-surface-700">|</span>
              <span className="text-xs text-surface-400">
                کل: <span className="text-surface-200 font-mono">{summary.total_signals}</span>
              </span>
              <span className="text-xs text-accent-emerald">
                خرید: <span className="font-mono">{summary.buy_count}</span>
              </span>
              <span className="text-xs text-accent-rose">
                فروش: <span className="font-mono">{summary.sell_count}</span>
              </span>
            </>
          )}
        </div>
      )}

      {/* Error */}
      {error && !isLoading && (
        <div className="glass-card p-6 text-center border border-accent-rose/30">
          <span className="material-icons text-3xl text-accent-rose mb-2 block">error_outline</span>
          <p className="text-sm text-accent-rose">خطا در دریافت سیگنال‌های سهام</p>
        </div>
      )}

      {/* Stock Signals */}
      {!isLoading && signals.length === 0 && !error && (
        <div className="glass-card p-12 text-center">
          <span className="material-icons text-5xl text-surface-600 mb-3 block">show_chart</span>
          <p className="text-sm text-surface-400">هیچ سیگنال سهامی یافت نشد</p>
          <p className="text-xs text-surface-600 mt-1">فیلترها را تغییر دهید یا منتظر به‌روزرسانی باشید.</p>
        </div>
      )}

      {!isLoading && signals.length > 0 && (
        <div className="space-y-4">
          {Object.entries(signalsBySymbol).map(([symbol, symbolSignals]) => {
            const mainSignal = symbolSignals[0];
            const daySignal = symbolSignals.find((s) => s.timeframe === "daily");
            const twoDaySignal = symbolSignals.find((s) => s.timeframe === "2day");

            return (
              <div key={symbol} className="glass-card p-4 border border-surface-700/50">
                {/* Symbol Header */}
                <div className="flex items-center gap-3 mb-3">
                  <span className="text-2xl">📈</span>
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <span className="text-base font-black text-surface-100">{mainSignal.symbol}</span>
                      <span className="text-xs text-surface-500">{mainSignal.name}</span>
                    </div>
                    <div className="flex items-center gap-2 mt-0.5">
                      <span className="text-xs font-mono text-surface-300">{fmtPrice(mainSignal.price)}</span>
                      <span className={`text-xs font-mono ${mainSignal.change_pct >= 0 ? "text-accent-emerald" : "text-accent-rose"}`}>
                        {fmtPct(mainSignal.change_pct)}
                      </span>
                    </div>
                  </div>
                </div>

                {/* Daily + 2-Day Signals Side by Side */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {/* Daily Signal */}
                  {daySignal && (
                    <div className="p-3 rounded-lg bg-surface-800/30 border border-surface-700/30">
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-[10px] px-1.5 py-0.5 rounded bg-primary-600/20 text-primary-300 font-bold">روزانه</span>
                        <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-medium ${
                          daySignal.direction === "buy" ? "bg-accent-emerald/15 text-accent-emerald" :
                          daySignal.direction === "sell" ? "bg-accent-rose/15 text-accent-rose" :
                          "bg-surface-600/30 text-surface-400"
                        }`}>
                          {daySignal.direction === "buy" ? "خرید" : daySignal.direction === "sell" ? "فروش" : "خنثی"}
                        </span>
                        {daySignal.decision_grade && (
                          <span className={`text-[10px] px-1 py-0.5 rounded border font-bold ${
                            daySignal.decision_grade === "A+" || daySignal.decision_grade === "A"
                              ? "border-accent-emerald/30 text-accent-emerald"
                              : "border-accent-amber/30 text-accent-amber"
                          }`}>{daySignal.decision_grade}</span>
                        )}
                      </div>
                      <div className="grid grid-cols-2 gap-2 text-[10px]">
                        <div>
                          <span className="text-surface-500">ورود: </span>
                          <span className="text-surface-200">{daySignal.entry_zone}</span>
                        </div>
                        <div>
                          <span className="text-surface-500">ضرر: </span>
                          <span className="text-accent-rose">{daySignal.stop_loss}</span>
                        </div>
                        <div className="col-span-2">
                          <span className="text-surface-500">اهداف: </span>
                          <span className="text-accent-emerald">{daySignal.targets}</span>
                        </div>
                        <div>
                          <span className="text-surface-500">R/R: </span>
                          <span className="text-primary-300 font-bold">{daySignal.risk_reward}</span>
                        </div>
                        <div>
                          <span className="text-surface-500">اطمینان: </span>
                          <span className="text-surface-200 font-mono">{(daySignal.confidence * 100).toFixed(0)}%</span>
                        </div>
                      </div>
                      <div className="mt-2 text-[10px] text-surface-400 truncate">{daySignal.reason}</div>
                    </div>
                  )}

                  {/* 2-Day Signal */}
                  {twoDaySignal && (
                    <div className="p-3 rounded-lg bg-surface-800/30 border border-surface-700/30">
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-[10px] px-1.5 py-0.5 rounded bg-accent-cyan/20 text-accent-cyan font-bold">۲ روزه</span>
                        <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-medium ${
                          twoDaySignal.direction === "buy" ? "bg-accent-emerald/15 text-accent-emerald" :
                          twoDaySignal.direction === "sell" ? "bg-accent-rose/15 text-accent-rose" :
                          "bg-surface-600/30 text-surface-400"
                        }`}>
                          {twoDaySignal.direction === "buy" ? "خرید" : twoDaySignal.direction === "sell" ? "فروش" : "خنثی"}
                        </span>
                        {twoDaySignal.decision_grade && (
                          <span className={`text-[10px] px-1 py-0.5 rounded border font-bold ${
                            twoDaySignal.decision_grade === "A+" || twoDaySignal.decision_grade === "A"
                              ? "border-accent-emerald/30 text-accent-emerald"
                              : "border-accent-amber/30 text-accent-amber"
                          }`}>{twoDaySignal.decision_grade}</span>
                        )}
                      </div>
                      <div className="grid grid-cols-2 gap-2 text-[10px]">
                        <div>
                          <span className="text-surface-500">ورود: </span>
                          <span className="text-surface-200">{twoDaySignal.entry_zone}</span>
                        </div>
                        <div>
                          <span className="text-surface-500">ضرر: </span>
                          <span className="text-accent-rose">{twoDaySignal.stop_loss}</span>
                        </div>
                        <div className="col-span-2">
                          <span className="text-surface-500">اهداف: </span>
                          <span className="text-accent-emerald">{twoDaySignal.targets}</span>
                        </div>
                        <div>
                          <span className="text-surface-500">R/R: </span>
                          <span className="text-primary-300 font-bold">{twoDaySignal.risk_reward}</span>
                        </div>
                        <div>
                          <span className="text-surface-500">اطمینان: </span>
                          <span className="text-surface-200 font-mono">{(twoDaySignal.confidence * 100).toFixed(0)}%</span>
                        </div>
                      </div>
                      <div className="mt-2 text-[10px] text-surface-400 truncate">{twoDaySignal.reason}</div>
                    </div>
                  )}

                  {/* If no daily/2day, show other timeframes */}
                  {!daySignal && !twoDaySignal && symbolSignals.slice(0, 2).map((s, i) => (
                    <div key={i} className="p-3 rounded-lg bg-surface-800/30 border border-surface-700/30">
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-[10px] px-1.5 py-0.5 rounded bg-surface-600/30 text-surface-400 font-bold">{s.timeframe}</span>
                        <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-medium ${
                          s.direction === "buy" ? "bg-accent-emerald/15 text-accent-emerald" :
                          s.direction === "sell" ? "bg-accent-rose/15 text-accent-rose" :
                          "bg-surface-600/30 text-surface-400"
                        }`}>
                          {s.direction === "buy" ? "خرید" : s.direction === "sell" ? "فروش" : "خنثی"}
                        </span>
                      </div>
                      <div className="text-[10px] text-surface-400">{s.reason}</div>
                    </div>
                  ))}
                </div>

                {/* Full Details Button */}
                <button
                  onClick={() => setSelectedSignal(mainSignal)}
                  className="mt-3 text-[10px] text-primary-400 hover:text-primary-300 transition-colors"
                >
                  مشاهده جزئیات کامل →
                </button>
              </div>
            );
          })}
        </div>
      )}

      {/* Detail Modal */}
      {selectedSignal && (
        <SignalDetailModal
          signal={selectedSignal}
          onClose={() => setSelectedSignal(null)}
        />
      )}
    </AppLayout>
  );
}

