        </div>
        <div className="h-2 rounded-full bg-surface-800 overflow-hidden">
          <div
            className="h-full rounded-full transition-all duration-700"
            style={{
              width: `${pct}%`,
              background: backfill.status === "running"
                ? "linear-gradient(90deg,#4f46e5,#818cf8)"
