          </div>

          {/* ── Strengths & Weaknesses ── */}
          <div className="grid grid-cols-2 gap-2">
            {analysis.strengths.length > 0 && (
              <div className="rounded-xl p-2.5 border border-accent-emerald/20 bg-accent-emerald/05">
