              <div className="flex justify-between">
                <span className="text-surface-500">NAV</span>
                <span className="font-mono text-surface-300">{fund.nav.toLocaleString("fa-IR")}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-surface-500">تغییرات</span>
                <span className={`font-mono ${fund.nav_change_pct >= 0 ? "text-accent-emerald" : "text-accent-rose"}`}>
                  {fund.nav_change_pct >= 0 ? "+" : ""}{fund.nav_change_pct?.toFixed(2)}%
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-surface-500">حجم</span>
                <span className="font-mono text-surface-300">{fund.trade_volume?.toLocaleString("fa-IR")}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-surface-500">ارزش</span>
                <span className="font-mono text-surface-300">{fund.trade_value?.toLocaleString("fa-IR")}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-surface-500">واحد</span>
                <span className="font-mono text-surface-300">{fund.shares_count?.toLocaleString("fa-IR")}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-surface-500">بازه</span>
                <span className="font-mono text-surface-300">{fund.price_min?.toLocaleString("fa-IR")} – {fund.price_max?.toLocaleString("fa-IR")}</span>
              </div>
            </div>
          </div>
        </div>

        {/* ── Footer ── */}
        <div className="sticky bottom-0 px-4 py-2.5 bg-surface-900/95 backdrop-blur border-t border-surface-800 rounded-b-2xl flex items-center justify-between">
          <span className="text-[8px] text-surface-600">
            تحلیل هوشمند بر اساس ۶ بعد مالی، نقدشوندگی، مدیریت، ریسک، هزینه، شفافیت
          </span>
          <button onClick={onClose} className="text-[10px] px-3 py-1.5 bg-surface-800 hover:bg-surface-700 text-surface-300 rounded-lg transition-all">
            بستن
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useMemo } from "react";
import FundNavMiniChart, { type FundNavPoint } from "./FundNavMiniChart";
import {
  detectFundGroup,
  detectFundSubgroup,
  getGroupDef,
  calcBubble,
  bubbleColor,
  type FundGroup,
} from "@/lib/fund-categories";
import { scoringEngine, type Fund } from "@/lib/fund-analysis";

// ── Helpers ──────────────────────────────────────────────────

function formatNum(v: number): string {
  if (!v) return "—";
  if (v >= 1_000_000_000_000) return (v / 1_000_000_000_000).toFixed(2) + "T";
  if (v >= 1_000_000_000) return (v / 1_000_000_000).toFixed(2) + "B";
  if (v >= 1_000_000) return (v / 1_000_000).toFixed(1) + "M";
  if (v >= 1_000) return (v / 1_000).toFixed(0) + "K";
  return v.toLocaleString("fa-IR");
}

function scoreColor(score: number): string {
  if (score >= 75) return "#10b981";
  if (score >= 60) return "#6366f1";
  if (score >= 45) return "#f59e0b";
  return "#ef4444";
}

function scoreLabel(score: number): string {
  if (score >= 75) return "عالی";
  if (score >= 60) return "خوب";
  if (score >= 45) return "متوسط";
  return "ضعیف";
}

// ── Score Gauge (Circular) ───────────────────────────────────

function ScoreGauge({ score, size = 36 }: { score: number; size?: number }) {
  const radius = (size - 4) / 2;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (score / 100) * circumference;
  const color = scoreColor(score);

  return (
    <div className="relative" style={{ width: size, height: size }}>
      <svg width={size} height={size} className="block -rotate-90">
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="currentColor"
          strokeWidth="2.5"
          className="text-surface-700/50"
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={color}
          strokeWidth="2.5"
          strokeLinecap="round"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          className="transition-all duration-700"
        />
      </svg>
      <div className="absolute inset-0 flex items-center justify-center">
        <span
          className="font-mono text-[9px] font-black"
          style={{ color }}
        >
          {score}
        </span>
      </div>
    </div>
  );
}

// ── P/NAV Bubble Badge ──────────────────────────────────────

function BubbleBadge({ price, nav }: { price: number; nav: number }) {
  const bubble = calcBubble(price, nav);
  if (bubble === null) return null;

  const color = bubbleColor(bubble);
  const isPositive = bubble > 0;

  return (
    <div
      className={`flex items-center gap-0.5 text-[9px] font-mono font-bold ${color}`}
      title={`حباب: ${bubble.toFixed(2)}% — قیمت: ${price.toLocaleString("fa-IR")} / NAV: ${nav.toLocaleString("fa-IR")}`}
    >
      <span>{isPositive ? "▲" : "▼"}</span>
      <span>{Math.abs(bubble).toFixed(1)}%</span>
    </div>
  );
}

// ── Fund Card Props ─────────────────────────────────────────

interface FundCardProps {
  fund: Fund;
  navPoints?: FundNavPoint[];
  isSelected?: boolean;
  onSelect?: (symbol: string) => void;
  view?: "grid" | "list";
}

// ── Main Component ──────────────────────────────────────────

export default function FundCard({
  fund,
  navPoints,
  isSelected = false,
  onSelect,
  view = "list",
}: FundCardProps) {
  const group = useMemo(() => detectFundGroup(fund.name, fund.fund_type), [fund.name, fund.fund_type]);
  const subgroup = useMemo(() => detectFundSubgroup(fund.name, group), [fund.name, group]);
  const groupDef = useMemo(() => getGroupDef(group), [group]);
  const scores = useMemo(() => scoringEngine(fund), [fund]);
  const isUp = fund.nav_change_pct >= 0;

  const bubble = calcBubble(fund.price_last, fund.nav);

  if (view === "grid") {
    return (
      <div
        className={`glass-card p-4 flex flex-col gap-3 transition-all group relative ${
          isSelected
            ? "border-primary-500/60 bg-primary-600/[0.06] ring-1 ring-primary-500/30"
