  const [overlay, setOverlay] = useState<OverlayIndicator>("none");
  const [subIndicator, setSubIndicator] = useState<SubIndicator>("none");
  const [hoverData, setHoverData] = useState<CandleDataPoint | null>(null);

  const filteredData = useMemo(() => filterByTimeframe(data, timeframe), [data, timeframe]);

  // True when the series is an intraday (2-min) realtime chart
  const isIntraday = useMemo(() => filteredData.some((d) => Boolean(d.time)), [filteredData]);

  // ``toTime`` already returns a numeric UTCTimestamp — compare the numbers
  // directly (re-parsing them through ``toUnix`` would zero them out and
  // drop every bar).
  const asUnix = (t: Time): number => (typeof t === "number" ? t : 0);

  const candles: CandlestickData[] = useMemo(
    () =>
      filteredData
        .map((d) => ({
          time: toTime(d.date || "", d.time),
          open: d.open,
          high: d.high,
          low: d.low,
          close: d.close,
        }))
        .filter((c) => asUnix(c.time) > 0)
        .sort((a, b) => asUnix(a.time) - asUnix(b.time)),
    [filteredData]
  );

  const volumes: HistogramData[] = useMemo(
    () =>
      filteredData
        .map((d) => ({
          time: toTime(d.date || "", d.time),
          value: d.volume,
          color: d.close >= d.open ? "rgba(0,209,175,0.35)" : "rgba(247,37,133,0.35)",
        }))
        .filter((v) => asUnix(v.time) > 0)
        .sort((a, b) => asUnix(a.time) - asUnix(b.time)),
    [filteredData]
  );

  const closes = useMemo(() => filteredData.map((d) => d.close), [filteredData]);

  // ── Cleanup helper ──────────────────────────────────────────────────────

  const cleanupSubChart = useCallback(() => {
    if (subChartRef.current) {
      subChartRef.current.remove();
      subChartRef.current = null;
    }
    if (subContainerRef.current) {
      subContainerRef.current.remove();
      subContainerRef.current = null;
    }
    subSeriesRef.current = [];
  }, []);

  // ── Create / Rebuild Chart ──────────────────────────────────────────────

  const buildChart = useCallback(() => {
    if (!chartContainerRef.current) return;

    // Cleanup previous
    if (chartRef.current) {
      chartRef.current.remove();
      chartRef.current = null;
    }
    cleanupSubChart();
    overlaySeriesRef.current = [];

    const container = chartContainerRef.current;
    const mainHeight = subIndicator !== "none" ? Math.floor(height * 0.7) : height;

    // ── Main Chart ──
    const chart = createChart(container, {
      width: container.clientWidth,
      height: mainHeight,
      layout: {
        background: { type: ColorType.Solid, color: "transparent" },
        textColor: "#9ca3af",
        fontFamily: "'Vazirmatn', 'Inter', sans-serif",
        fontSize: 11,
      },
      grid: {
        vertLines: { color: "rgba(128,128,128,0.06)" },
        horzLines: { color: "rgba(128,128,128,0.06)" },
      },
      crosshair: {
        mode: CrosshairMode.Normal,
        vertLine: {
          width: 1,
          color: "rgba(128,128,128,0.4)",
          style: LineStyle.Dashed,
          labelBackgroundColor: "#374151",
        },
        horzLine: {
          width: 1,
          color: "rgba(128,128,128,0.4)",
          style: LineStyle.Dashed,
          labelBackgroundColor: "#374151",
        },
      },
      rightPriceScale: {
        borderColor: "rgba(128,128,128,0.1)",
        scaleMargins: { top: 0.05, bottom: showVolume ? 0.25 : 0.05 },
      },
      timeScale: {
        borderColor: "rgba(128,128,128,0.1)",
        timeVisible: isIntraday,
        secondsVisible: false,
        rightOffset: 5,
        barSpacing: isIntraday ? 6 : 8,
        minBarSpacing: 3,
      },
      handleScroll: { vertTouchDrag: false },
    });
    chartRef.current = chart;

    // ── Candlestick Series ──
    const candleSeries = chart.addSeries(CandlestickSeries, {
      upColor: "#00d1af",
      downColor: "#f72585",
      borderUpColor: "#00d1af",
      borderDownColor: "#f72585",
      wickUpColor: "#00d1af",
      wickDownColor: "#f72585",
    });
    candleSeries.setData(candles);
    candleSeriesRef.current = candleSeries;

    // ── Volume Series ──
    if (showVolume) {
      const volumeSeries = chart.addSeries(HistogramSeries, {
        priceFormat: { type: "volume" },
        priceScaleId: "volume",
      });
      chart.priceScale("volume").applyOptions({
        scaleMargins: { top: 0.8, bottom: 0 },
      });
      volumeSeries.setData(volumes);
      volumeSeriesRef.current = volumeSeries;
    }

    // ── Crosshair data ──
    chart.subscribeCrosshairMove((param) => {
      if (!param.time || !param.seriesData) {
        setHoverData(null);
        return;
      }
      const cd = param.seriesData.get(candleSeries) as CandlestickData | undefined;
      if (cd) {
        const original = filteredData.find(
          (d) => toUnix(d.date || "", d.time) === asUnix(cd.time as Time)
        );
        setHoverData(original || null);
      }
    });

    // ── Responsive ──
    const ro = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const w = entry.contentRect.width;
        chart.applyOptions({ width: w });
      }
    });
    ro.observe(container);
    resizeObserverRef.current = ro;

    chart.timeScale().fitContent();
  }, [candles, volumes, height, showVolume, filteredData, subIndicator, isIntraday, cleanupSubChart]);

  useEffect(() => {
    buildChart();
    return () => {
      resizeObserverRef.current?.disconnect();
      chartRef.current?.remove();
      cleanupSubChart();
    };
  }, [buildChart]);

  // ── Overlay Indicators ──────────────────────────────────────────────────

  useEffect(() => {
    const chart = chartRef.current;
    if (!chart || !candleSeriesRef.current) return;

    // Remove old overlays
    overlaySeriesRef.current.forEach((s) => {
      try { chart.removeSeries(s); } catch {}
    });
    overlaySeriesRef.current = [];

    if (overlay === "none") return;

    const timeData = candles.map((c) => c.time);

    if (overlay === "SMA") {
      const sma = calcSMA(closes, 20);
      const lineData = sma
        .map((v, i) => (v !== null ? { time: timeData[i], value: v } : null))
        .filter(Boolean) as LineData[];
      if (lineData.length > 0) {
        const series = chart.addSeries(LineSeries, {
          color: "#3b82f6",
          lineWidth: 2,
          priceLineVisible: false,
          lastValueVisible: false,
          crosshairMarkerVisible: false,
        });
        series.setData(lineData);
        overlaySeriesRef.current.push(series);
      }
    } else if (overlay === "EMA") {
      const ema = calcEMA(closes, 20);
      const lineData = ema
        .map((v, i) => (v !== null ? { time: timeData[i], value: v } : null))
        .filter(Boolean) as LineData[];
      if (lineData.length > 0) {
        const series = chart.addSeries(LineSeries, {
          color: "#a855f7",
          lineWidth: 2,
          priceLineVisible: false,
          lastValueVisible: false,
          crosshairMarkerVisible: false,
        });
        series.setData(lineData);
        overlaySeriesRef.current.push(series);
      }
    } else if (overlay === "BB") {
      const bb = calcBB(closes, 20, 2);
      const colors = ["#f59e0b", "#f59e0b", "#f59e0b"];
      const widths: Array<1 | 2 | 3 | 4> = [1, 2, 1];
      const styles = [LineStyle.Dashed, LineStyle.Solid, LineStyle.Dashed];
      const bbLines = [bb.upper, bb.middle, bb.lower];
      for (let k = 0; k < 3; k++) {
        const ld = bbLines[k]
          .map((v, i) => (v !== null ? { time: timeData[i], value: v } : null))
          .filter(Boolean) as LineData[];
        if (ld.length > 0) {
          const series = chart.addSeries(LineSeries, {
            color: colors[k],
            lineWidth: widths[k],
            lineStyle: styles[k],
            priceLineVisible: false,
            lastValueVisible: false,
            crosshairMarkerVisible: false,
          });
          series.setData(ld);
          overlaySeriesRef.current.push(series);
        }
      }
    }
  }, [overlay, candles, closes]);

  // ── Sub Indicators (RSI / MACD) ────────────────────────────────────────

  useEffect(() => {
    if (subIndicator === "none") return;
    if (!chartContainerRef.current) return;

    const subContainer = document.createElement("div");
    subContainer.style.height = `${Math.floor(height * 0.28)}px`;
    subContainer.style.marginTop = "4px";
    chartContainerRef.current.parentElement?.appendChild(subContainer);
    subContainerRef.current = subContainer;

    const subChart = createChart(subContainer, {
      width: chartContainerRef.current.clientWidth,
      height: Math.floor(height * 0.28),
      layout: {
        background: { type: ColorType.Solid, color: "transparent" },
        textColor: "#9ca3af",
        fontFamily: "'Vazirmatn', 'Inter', sans-serif",
        fontSize: 10,
      },
      grid: {
        vertLines: { color: "rgba(128,128,128,0.04)" },
        horzLines: { color: "rgba(128,128,128,0.04)" },
      },
      crosshair: { mode: CrosshairMode.Normal },
      rightPriceScale: { borderColor: "rgba(128,128,128,0.1)" },
      timeScale: {
        borderColor: "rgba(128,128,128,0.1)",
        visible: true,
        timeVisible: false,
      },
      handleScroll: { vertTouchDrag: false },
    });

    // Sync time scale with main chart
    if (chartRef.current) {
      subChart.timeScale().subscribeVisibleLogicalRangeChange((range) => {
        if (range) chartRef.current?.timeScale().setVisibleLogicalRange(range);
      });
      chartRef.current.timeScale().subscribeVisibleLogicalRangeChange((range) => {
        if (range) subChart.timeScale().setVisibleLogicalRange(range);
      });
    }

    subChartRef.current = subChart;

    const timeData = candles.map((c) => c.time);

    if (subIndicator === "RSI") {
      const rsi = calcRSI(closes, 14);
      const series = subChart.addSeries(LineSeries, {
        color: "#a855f7",
        lineWidth: 2,
        priceLineVisible: false,
      });
      const rsiData = rsi
        .map((v, i) => (v !== null ? { time: timeData[i], value: v } : null))
        .filter(Boolean) as LineData[];
      series.setData(rsiData);

      // Overbought / Oversold lines
      if (timeData.length >= 2) {
        const obLine = subChart.addSeries(LineSeries, {
          color: "rgba(247,37,133,0.4)",
          lineWidth: 1,
          lineStyle: LineStyle.Dashed,
          priceLineVisible: false,
          lastValueVisible: false,
        });
        obLine.setData([
          { time: timeData[0], value: 70 },
          { time: timeData[timeData.length - 1], value: 70 },
        ]);

        const osLine = subChart.addSeries(LineSeries, {
          color: "rgba(0,209,175,0.4)",
          lineWidth: 1,
          lineStyle: LineStyle.Dashed,
          priceLineVisible: false,
          lastValueVisible: false,
        });
        osLine.setData([
          { time: timeData[0], value: 30 },
          { time: timeData[timeData.length - 1], value: 30 },
        ]);

        subSeriesRef.current = [series, obLine, osLine];
      } else {
        subSeriesRef.current = [series];
      }
    } else if (subIndicator === "MACD") {
      const macd = calcMACD(closes);
      const macdLineSeries = subChart.addSeries(LineSeries, {
        color: "#3b82f6",
        lineWidth: 2,
        priceLineVisible: false,
      });
      const signalLineSeries = subChart.addSeries(LineSeries, {
        color: "#f59e0b",
        lineWidth: 1,
        priceLineVisible: false,
      });
      const histSeries = subChart.addSeries(HistogramSeries, {
        priceLineVisible: false,
      });

      const macdData = macd.macd
        .map((v, i) => (v !== null ? { time: timeData[i], value: v } : null))
        .filter(Boolean) as LineData[];
      const signalData = macd.signal
        .map((v, i) => (v !== null ? { time: timeData[i], value: v } : null))
        .filter(Boolean) as LineData[];
      const histData = macd.histogram
        .map((v, i) =>
          v !== null
            ? { time: timeData[i], value: v, color: v >= 0 ? "rgba(0,209,175,0.6)" : "rgba(247,37,133,0.6)" }
            : null
        )
        .filter(Boolean) as HistogramData[];

      macdLineSeries.setData(macdData);
      signalLineSeries.setData(signalData);
      histSeries.setData(histData);
      subSeriesRef.current = [macdLineSeries, signalLineSeries, histSeries];
    }

    subChart.timeScale().fitContent();

    return () => {
      cleanupSubChart();
    };
  }, [subIndicator, candles, closes, height, cleanupSubChart]);

  // ── Helpers ─────────────────────────────────────────────────────────────

  const fmt = (v: number) => v.toLocaleString("fa-IR");
  const pct = (v: number) => `${v >= 0 ? "+" : ""}${v.toFixed(2)}%`;

  const lastPrice = filteredData.length > 0 ? filteredData[filteredData.length - 1].close : 0;
  const firstPrice = filteredData.length > 0 ? filteredData[0].close : 1;
  const changePct = ((lastPrice - firstPrice) / firstPrice) * 100;
  const highAll = filteredData.length > 0 ? Math.max(...filteredData.map((d) => d.high)) : 0;
  const lowAll = filteredData.length > 0 ? Math.min(...filteredData.map((d) => d.low)) : 0;
  const volAll = filteredData.reduce((s, d) => s + d.volume, 0);

  // ── Render ──────────────────────────────────────────────────────────────

  const TF_LABELS: Record<Timeframe, string> = {
    "1D": "۱ روز",
    "1W": "۱ هفته",
    "1M": "۱ ماه",
    "3M": "۳ ماه",
    "6M": "۶ ماه",
    "1Y": "۱ سال",
    ALL: "همه",
  };

  return (
    <Card
      title={title}
      actions={
        <div className="flex items-center gap-2 flex-wrap">
          {(Object.keys(TF_LABELS) as Timeframe[]).map((tf) => (
            <CardAction key={tf} active={timeframe === tf} onClick={() => setTimeframe(tf)}>
              {TF_LABELS[tf]}
            </CardAction>
          ))}
        </div>
      }
    >
      {/* ── Stats Bar ── */}
      <div className="flex flex-wrap items-center gap-4 mb-3 pb-3" style={{ borderBottom: "1px solid var(--glass-border)" }}>
        {symbol && (
          <div className="text-xs" style={{ color: "var(--text-secondary-light)" }}>
            {symbol}{" "}
            <span className="font-bold" style={{ color: "var(--text-primary-light)", fontFamily: "Inter" }}>
              {fmt(lastPrice)}
            </span>
            <span
              className="mr-2 font-bold"
              style={{ color: changePct >= 0 ? "var(--positive)" : "var(--negative)", fontFamily: "Inter" }}
            >
              {pct(changePct)}
            </span>
          </div>
        )}
        <div className="text-xs" style={{ color: "var(--text-secondary-light)" }}>
          بیشترین <span style={{ color: "var(--positive)", fontFamily: "Inter" }}>{fmt(highAll)}</span>
        </div>
        <div className="text-xs" style={{ color: "var(--text-secondary-light)" }}>
          کمترین <span style={{ color: "var(--negative)", fontFamily: "Inter" }}>{fmt(lowAll)}</span>
        </div>
        <div className="text-xs" style={{ color: "var(--text-secondary-light)" }}>
          حجم <span style={{ color: "var(--text-primary-light)", fontFamily: "Inter" }}>{(volAll / 1e6).toFixed(1)}M</span>
        </div>

        {/* Crosshair data */}
        {hoverData && (
          <div className="flex gap-3 mr-auto text-xs font-mono" style={{ direction: "ltr" }}>
            <span style={{ color: "var(--text-secondary-light)" }}>O <span style={{ color: "var(--text-primary-light)" }}>{fmt(hoverData.open)}</span></span>
            <span style={{ color: "var(--text-secondary-light)" }}>H <span style={{ color: "var(--positive)" }}>{fmt(hoverData.high)}</span></span>
            <span style={{ color: "var(--text-secondary-light)" }}>L <span style={{ color: "var(--negative)" }}>{fmt(hoverData.low)}</span></span>
            <span style={{ color: "var(--text-secondary-light)" }}>C <span style={{ color: "var(--text-primary-light)" }}>{fmt(hoverData.close)}</span></span>
            <span style={{ color: "var(--text-secondary-light)" }}>V <span style={{ color: "var(--text-primary-light)" }}>{fmt(hoverData.volume)}</span></span>
          </div>
        )}
      </div>

      {/* ── Indicator Toolbar ── */}
      <div className="flex items-center gap-3 mb-3 flex-wrap">
        <span className="text-xs" style={{ color: "var(--text-secondary-light)" }}>اندیکاتور روی نمودار:</span>
        {(["none", "SMA", "EMA", "BB"] as OverlayIndicator[]).map((ind) => (
          <button
            key={ind}
            onClick={() => setOverlay(ind)}
            className="text-xs px-2.5 py-1 rounded-md transition-all"
            style={{
              background: overlay === ind ? "var(--accent-primary)" : "var(--bg-surface)",
              color: overlay === ind ? "#fff" : "var(--text-secondary-light)",
            }}
          >
            {ind === "none" ? "بدون" : ind === "SMA" ? "SMA (20)" : ind === "EMA" ? "EMA (20)" : "Bollinger"}
          </button>
        ))}

        <span className="text-xs mr-3" style={{ color: "var(--text-secondary-light)" }}>پنل جدا:</span>
        {(["none", "RSI", "MACD"] as SubIndicator[]).map((ind) => (
          <button
            key={ind}
            onClick={() => setSubIndicator(ind)}
            className="text-xs px-2.5 py-1 rounded-md transition-all"
            style={{
              background: subIndicator === ind ? "var(--accent-secondary)" : "var(--bg-surface)",
              color: subIndicator === ind ? "#fff" : "var(--text-secondary-light)",
            }}
          >
            {ind === "none" ? "بدون" : ind}
          </button>
        ))}
      </div>

      {/* ── Chart Container ── */}
      <div ref={chartContainerRef} style={{ width: "100%" }} />
    </Card>
  );
}

"use client";

import { useEffect } from "react";

// Capacitor is an optional mobile-only integration. Keep imports opaque to
// Next's server/web bundler so the regular web build does not require the
// native plugin packages to be installed.
const loadOptional = <T,>(specifier: string): Promise<T> =>
  Function("s", "return import(s)")(specifier) as Promise<T>;

type CapacitorCore = {
  Capacitor: { isNativePlatform(): boolean; getPlatform(): string };
};
type StatusBarModule = {
  StatusBar: { setStyle(options: unknown): Promise<void>; setBackgroundColor(options: unknown): Promise<void> };
  Style: { Dark: unknown };
};
type SplashScreenModule = { SplashScreen: { hide(): Promise<void> } };
type KeyboardModule = { Keyboard: { setAccessoryBarVisible(options: unknown): Promise<void> } };
type HapticsModule = {
  Haptics: { impact(options: unknown): Promise<void> };
  ImpactStyle: { Light: unknown; Medium: unknown; Heavy: unknown };
};
type AppModule = { App: { getInfo(): Promise<{ version: string }> } };

/**
 * Bridge بین PWA و native Capacitor.
 * - در Web: noop
 * - در native: تنظیم status bar + haptics + splash screen + keyboard
 */
export function NativeBridge() {
  useEffect(() => {
    // فقط در سمت کلاینت اجرا شود
    if (typeof window === "undefined") return;

    const initNative = async () => {
      try {
        const { Capacitor } = await loadOptional<CapacitorCore>("@capacitor/core");
        const isNative = Capacitor.isNativePlatform();

        if (!isNative) return;

        // Status bar
        try {
          const { StatusBar, Style } = await loadOptional<StatusBarModule>("@capacitor/status-bar");
          await StatusBar.setStyle({ style: Style.Dark });
          await StatusBar.setBackgroundColor({ color: "#09090b" });
        } catch {
          /* noop */
        }

        // Splash screen
        try {
          const { SplashScreen } = await loadOptional<SplashScreenModule>("@capacitor/splash-screen");
          await SplashScreen.hide();
        } catch {
          /* noop */
        }

        // Keyboard
        try {
          const { Keyboard } = await loadOptional<KeyboardModule>("@capacitor/keyboard");
          await Keyboard.setAccessoryBarVisible({ isVisible: false });
        } catch {
          /* noop */
        }
      } catch (err) {
        // Capacitor not available (web)
      }
    };

    initNative();
  }, []);

  return null;
}

/**
 * Haptic feedback (فقط native).
 */
export async function hapticImpact(style: "light" | "medium" | "heavy" = "medium"): Promise<void> {
  if (typeof window === "undefined") return;
  try {
    const { Capacitor } = await loadOptional<CapacitorCore>("@capacitor/core");
    if (!Capacitor.isNativePlatform()) return;
    const { Haptics, ImpactStyle } = await loadOptional<HapticsModule>("@capacitor/haptics");
    const map = { light: ImpactStyle.Light, medium: ImpactStyle.Medium, heavy: ImpactStyle.Heavy };
    await Haptics.impact({ style: map[style] });
  } catch {
    /* noop */
  }
}

/**
 * App info.
 */
export async function getAppInfo(): Promise<{ version: string; platform: string } | null> {
  if (typeof window === "undefined") return null;
  try {
    const { Capacitor } = await loadOptional<CapacitorCore>("@capacitor/core");
    const info = await loadOptional<AppModule>("@capacitor/app").then((m) => m.App.getInfo());
    return { version: info.version, platform: Capacitor.getPlatform() };
  } catch {
    return null;
  }
}

import { useState, useEffect } from "react";

/**
 * Hook that initializes data client-side to prevent hydration mismatches.
 *
 * During SSR: returns `initialValue` (safe empty/default state).
 * After hydration: calls `generator` once and updates state with the result.
 *
 * The returned setter can be used to regenerate data (e.g., chart period switching).
 *
 * @example
 * ```tsx
 * // Simple usage (no setter needed)
 * const [cells] = useClientData(() => generateMockHeatmap(), [] as HeatmapCell[]);
 *
 * // With setter for data that can be regenerated
 * const [chartData, setChartData] = useClientData(() => generateIndexHistory(90), []);
 * ```
 */
export function useClientData<T>(
  generator: () => T,
  initialValue: T,
): [T, React.Dispatch<React.SetStateAction<T>>] {
  const [data, setData] = useState<T>(initialValue);

  useEffect(() => {
    // Intentional mount-only client-side initialization to avoid hydration mismatches.
     
    setData(generator());
  }, []);

  return [data, setData];
}

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || '/api/v1';
const REQUEST_TIMEOUT_MS = 60_000;
const LONG_TIMEOUT_MS = 600_000; // 10 minutes for heavy sync operations

// Consumers such as React Query use this event to drop user-scoped cache data
// whenever the in-memory session is cleared.
export const AUTH_STATE_CLEARED_EVENT = "auth:state-cleared";

// ── Auth token helpers (in-memory, XSS-safe) ────────────────────────
// The refresh token lives in an httpOnly cookie (set by the backend); the
// access token + user are kept in module memory only — never localStorage,
// so an XSS payload cannot exfiltrate them.

interface InMemoryAuth {
  access_token: string | null;
  user?: Record<string, unknown> | null;
}

let _memoryAuth: InMemoryAuth = { access_token: null, user: null };

function getStoredAccessToken(): string | null {
  return _memoryAuth.access_token;
}

function setAccessToken(token: string) {
  _memoryAuth.access_token = token;
}

function setAuthUser(user: Record<string, unknown> | null) {
  _memoryAuth.user = user;
}

function clearStoredAuth() {
  _memoryAuth = { access_token: null, user: null };
}

function writeStoredAuth(data: { access_token: string }) {
  _memoryAuth.access_token = data.access_token;
}

// Session restore after a page reload: the access token is gone from memory
// but the refresh cookie survives — exchange it for a fresh access token.
export async function hydrateSession(): Promise<InMemoryAuth> {
  try {
    const res = await fetch(`${API_BASE_URL}/auth/refresh`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      // The refresh token is read server-side from the httpOnly cookie.
      body: JSON.stringify({}),
      credentials: "include",
    });
    if (!res.ok) {
      clearStoredAuth();
      return _memoryAuth;
    }
    const json = await res.json();
    const data = json.data ?? json;
    if (data?.access_token) {
      _memoryAuth.access_token = data.access_token;
      if (data.user) _memoryAuth.user = data.user as Record<string, unknown>;
    } else {
      clearStoredAuth();
    }
  } catch {
    clearStoredAuth();
  }
  return _memoryAuth;
}

// ── Silent Token Refresh ────────────────────────────────────────

let _refreshPromise: Promise<string | null> | null = null;

async function _silentRefresh(): Promise<string | null> {
  // Deduplicate concurrent refresh attempts
  if (_refreshPromise) return _refreshPromise;

  _refreshPromise = (async () => {
    try {
      // The refresh token lives in an httpOnly cookie — the server reads it.
      const res = await fetch(`${API_BASE_URL}/auth/refresh`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({}),
        credentials: "include",
      });

      if (!res.ok) return null;

      const json = await res.json();
      const data = json.data ?? json;
      const newAccessToken = data.access_token;

      if (newAccessToken) {
        writeStoredAuth({ access_token: newAccessToken });
        if (data.user) _memoryAuth.user = data.user as Record<string, unknown>;
        return newAccessToken;
      }
      return null;
    } catch {
      return null;
    } finally {
      _refreshPromise = null;
    }
  })();

  return _refreshPromise;
}

// ── 401 Handler ─────────────────────────────────────────────────

function _handle401() {
  const accessToken = getStoredAccessToken();
  clearAuth();

  // A failed refresh must not leave the httpOnly cookie alive. JavaScript
  // cannot delete it directly, so expire it through the unauthenticated-safe
  // logout endpoint before redirecting to the login page.
  const headers: HeadersInit = {};
  if (accessToken) headers.Authorization = `Bearer ${accessToken}`;
  try {
    void Promise.resolve(
      fetch(`${API_BASE_URL}/auth/logout`, {
        method: "POST",
        headers,
        credentials: "include",
      }),
    ).catch(() => undefined);
  } catch {
    // A synchronous fetch failure must not mask the original 401 response.
  }

  if (typeof window !== "undefined") {
    const currentPath = window.location.pathname;
    if (!currentPath.startsWith("/auth/")) {
      window.location.href = `/auth/login?redirect=${encodeURIComponent(currentPath)}`;
    }
  }
}

// ── Helper: fetch with timeout ──────────────────────────────────


async function fetchWithTimeout(url: string, options: RequestInit, timeoutMs: number = REQUEST_TIMEOUT_MS): Promise<Response> {
  const timeoutController = new AbortController();
  const timer = setTimeout(() => timeoutController.abort(), timeoutMs);
  // Combine the caller's signal (e.g. React Query cancellation on symbol
  // switch) with the internal timeout signal. Previously options.signal was
  // unconditionally overwritten by the internal controller, so external
  // cancellation was silently ignored.
  const externalSignal = options.signal ?? null;
  let combined: AbortSignal = timeoutController.signal;
  let externalListener: (() => void) | null = null;
  if (externalSignal) {
    const anyFn = (AbortSignal as unknown as { any?: (signals: AbortSignal[]) => AbortSignal }).any;
    if (typeof anyFn === "function") {
      combined = anyFn([timeoutController.signal, externalSignal]);
    } else if (externalSignal.aborted) {
      timeoutController.abort();
    } else {
      externalListener = () => timeoutController.abort();
      externalSignal.addEventListener("abort", externalListener, { once: true });
    }
  }
  try {
    const response = await fetch(url, {
      ...options,
      signal: combined,
      credentials: "include",
    });
    return response;
  } catch (e) {
    // An externally aborted request must keep its AbortError identity so
    // React Query can distinguish cancellation from a real failure — do not
    // mask it as a timeout.
    if (externalSignal?.aborted) throw e;
    if (e instanceof DOMException && e.name === "AbortError") {
      throw new Error(`Request timeout after ${timeoutMs}ms: ${url}`);
    }
    throw e;
  } finally {
    clearTimeout(timer);
    if (externalListener && externalSignal) {
      externalSignal.removeEventListener("abort", externalListener);
    }
  }
}

// ── Core API Functions ──────────────────────────────────────────

async function apiRequest<T>(
  endpoint: string,
  init: RequestInit & { timeoutMs?: number },
  token?: string | null,
): Promise<T> {
  const headers: HeadersInit = { 'Content-Type': 'application/json', ...(init.headers as Record<string, string> | undefined) };
  const authToken = token ?? getStoredAccessToken();
  if (authToken) (headers as Record<string, string>).Authorization = `Bearer ${authToken}`;

  const timeoutMs = init.timeoutMs ?? REQUEST_TIMEOUT_MS;
  // eslint-disable-next-line @typescript-eslint/no-unused-vars -- timeoutMs is consumed, rest is fetch init
  const { timeoutMs: _t, ...fetchInit } = init as RequestInit & { timeoutMs?: number };

  let response = await fetchWithTimeout(`${API_BASE_URL}${endpoint}`, { ...fetchInit, headers }, timeoutMs);

  if (response.status === 401 && !endpoint.includes('/auth/')) {
    const newToken = await _silentRefresh();
    if (newToken) {
      (headers as Record<string, string>).Authorization = `Bearer ${newToken}`;
      response = await fetchWithTimeout(`${API_BASE_URL}${endpoint}`, { ...fetchInit, headers }, timeoutMs);
    }
  }

  if (response.status === 401) { _handle401(); }
  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`HTTP ${response.status}: ${errorText || response.statusText}`);
  }
  return response.json() as Promise<T>;
}

export async function apiGet<T>(endpoint: string, token?: string | null, signal?: AbortSignal): Promise<T> {
  return apiRequest<T>(endpoint, { headers: {}, signal: signal ?? undefined }, token);
}

export async function apiPost<T>(
  endpoint: string,
  data?: Record<string, unknown>,
  token?: string | null,
  timeoutMs?: number
): Promise<T> {
  const postTimeout = timeoutMs ?? (
    endpoint.includes('/backtests') || endpoint.includes('/ml/') || endpoint.includes('/brsapi') || endpoint.includes('/data-import') || endpoint.includes('/orchestrator') || endpoint.includes('/sync')
      ? LONG_TIMEOUT_MS : REQUEST_TIMEOUT_MS
  );
  return apiRequest<T>(endpoint, { method: 'POST', body: data ? JSON.stringify(data) : undefined, timeoutMs: postTimeout }, token);
}

export async function apiPut<T>(
  endpoint: string,
  data?: Record<string, unknown>,
  token?: string | null
): Promise<T> {
  return apiRequest<T>(endpoint, { method: 'PUT', body: data ? JSON.stringify(data) : undefined }, token);
}

export async function apiPatch<T>(
  endpoint: string,
  data?: Record<string, unknown>,
  token?: string | null
): Promise<T> {
  return apiRequest<T>(endpoint, { method: 'PATCH', body: data ? JSON.stringify(data) : undefined }, token);
}

export async function apiDelete<T>(endpoint: string, token?: string | null): Promise<T> {
  return apiRequest<T>(endpoint, { method: 'DELETE' }, token);
}

// ── Auth Helpers (legacy, kept for backward compatibility) ───────
// New code should use useAuth() hook from auth-context.tsx instead.

// Backward-compatible wrappers over the in-memory store (no localStorage).
export function getStoredAuth() {
  if (!_memoryAuth.access_token) return null;
  return {
    access_token: _memoryAuth.access_token,
    user: _memoryAuth.user,
  };
}

export function clearAuth() {
  clearStoredAuth();
  if (typeof window !== "undefined" && typeof window.dispatchEvent === "function") {
    window.dispatchEvent(new Event(AUTH_STATE_CLEARED_EVENT));
  }
}

export function storeAuth(data: { user: Record<string, unknown>; access_token: string }) {
  _memoryAuth.access_token = data.access_token;
  _memoryAuth.user = data.user ?? _memoryAuth.user;
  setAccessToken(data.access_token);
  setAuthUser(data.user ?? _memoryAuth.user);
}

// ------ Array Extraction (اصلاح‌شده) ------------------------------------------------------------------------------------------------------
export function extractArray<T = unknown>(response: unknown): T[] {
  if (Array.isArray(response)) return response as T[];

  if (response && typeof response === 'object') {
    const obj = response as Record<string, unknown>;
    for (const key of ['data', 'items', 'results', 'list', 'records', 'content', 'docs'] as const) {
      const val = obj[key];
      if (Array.isArray(val)) return val as T[];
      if (val && typeof val === 'object') {
        const nested = extractArray(val);
        if (nested.length > 0) return nested as T[];
      }
    }
    for (const val of Object.values(obj)) {
      if (Array.isArray(val)) return val as T[];
      if (val && typeof val === 'object') {
        const nested = extractArray(val);
        if (nested.length > 0) return nested as T[];
      }
    }
  }
  return [];
}

export function extractItems<T = unknown>(response: unknown): T[] {
  return extractArray<T>(response);
}

export function extractTotal(response: unknown): number {
  if (response && typeof response === 'object') {
    const obj = response as Record<string, unknown>;
    for (const key of ['total', 'totalCount', 'count', 'total_items', 'totalItems'] as const) {
      if (typeof obj[key] === 'number') return obj[key] as number;
      const data = obj['data'] as Record<string, unknown> | undefined;
      if (data && typeof data[key] === 'number') return data[key] as number;
    }
    const data = obj['data'] as Record<string, unknown> | undefined;
    if (data && typeof data === 'object') {
      for (const key of ['total', 'totalCount', 'count', 'total_items', 'totalItems'] as const) {
        if (typeof data[key] === 'number') return data[key] as number;
      }
    }
  }
  return 0;
}

export function safeExtractArray<T = unknown>(response: unknown, endpoint?: string): T[] {
  if (response && typeof response === "object") {
    const obj = response as Record<string, unknown>;
    if (obj.success === false || obj.error || obj.detail) {
      console.warn(`[safeExtractArray] backend error at ${endpoint ?? "?"}:`, obj.error ?? obj.detail ?? obj);
    }
  }
  return extractArray<T>(response);
}

